-- 芯之力知识库精华 v15（高相关 weak_text 继续 OCR 补强版）
BEGIN;

INSERT INTO rag_documents (id, title, content, tags, status, source, sort, update_time)
VALUES
(100001, '英雄之旅总览：把生命当作创造与疗愈的冒险', '英雄之旅不是追逐名利的个人奋斗剧本，而是一种把生命视为伟大冒险的意识训练：人被某种更深的力量触碰，离开惯性的生活方式，经历失联、磨难、失败、整合与疗愈，最后带着获得的礼物回到世界，贡献给他人。课程正文把这一主线放在当代处境中理解：人很容易陷入负面念头、焦虑、抑郁、过度分析和小我身份，因而失去与生命力、创造力、身体和世界的连接。所谓正能量人生，并不是永远顺利，而是能全身心参与生命，在困难中保持开放，把痛苦转化为更完整的人性。整个十二模块可视为一条路径：听见召唤，看见拒绝，找到向导，训练创造性心智，连接资源，召回温柔、勇猛、顽皮等原型能量，把障碍和恶魔转化为资源，再把礼物传给他人。英雄之旅的核心价值，是让个人从孤立的小我走向身心灵整合，再走向社群与世界的疗愈；每个人都携带一份独特礼物，旅程的意义在于听见它、训练自己承载它、并把它分享出去。它不是一次顿悟，也不是外部成就清单，而是持续的身心练习：安顿、呼吸、放下固化形式，重新选择如何回应生命。用于问答检索时，可对应生命意义、创造力低落、人生卡住、痛苦转化、如何贡献社会等问题。', '["英雄之旅", "创造力", "疗愈整合", "正能量人生", "生命礼物", "社群贡献"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 1, now()),
(100002, '聆听召唤：从童年火光到一生价值的辨认', '召唤不是头脑临时想出的目标，而是生命中反复触碰你的深层信号。它可能来自童年第一次被某个人、一本书、一首音乐、一个科学家或艺术家点亮的瞬间，也可能来自一次巨大的痛苦之后的重生，或来自想象临终回望时会让自己说出此生值得的价值。课程强调，人常被左脑的过度分析锁住，越努力想答案，越难听见召唤；所以练习不是思考清单，而是先安顿身体、呼吸、向天空伸展、向大地释放，再把问题像种子一样投入全身心，让画面、记忆和感受自然浮现。可反复询问：小时候谁启发了我，哪次挣扎让我更有生命力，哪个艺术作品打开过我，若生命将尽我希望完成什么。召唤常常短暂，却不会消失；它像内在已经存在的火，提醒你什么能让生命鲜活、快乐、神奇，也提醒你如何成为更好的自己并帮助别人。当出现多个答案时，不必急着选择哪一个正确，而是观察哪个让身体更放松、更有热、更多泪水或敬畏；这些生理反应常比逻辑判断更接近召唤。', '["召唤", "童年记忆", "生命使命", "身心练习", "价值澄清", "创造力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 2, now()),
(100003, '拒绝召唤与找到向导：把“不可能”转化为支持', '当一个人感到自己想创造某种生命、事业或关系时，拒绝召唤几乎会同步出现。它可能是父母、家庭、社会、性别角色、职业规划或内在批评者的声音，反复说你不能、你不该、那不现实。课程没有把这部分视为错误，而把它看成英雄之旅必经的张力：心中的渴望和头脑中的限制讯息同时存在，真正的成熟不是假装没有阻力，而是能与阻力同场工作。练习的关键，是先触碰心，说出我最想创造的是什么，并让身体做出代表梦想的动作；再走到另一边，进入批评者角色，用姿态和声音表达不允许，重复几次直到能看见它的能量模式；最后请出导师、祖先、榜样或灵性向导，走进他们的身体、眼神和神态，接收支持与许可。向导可以是现实老师、亲人、已故长辈、文学人物或内在智慧。这样做不是否认批评，而是让支持系统比批评更有能量，使人能在真实世界中带着勇气迈步。', '["拒绝召唤", "内在批评", "向导", "导师资源", "身体模型", "自我支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 3, now()),
(100004, '创造性心智：用游戏、幽默和多重视角重新连接生命', '创造性心智的核心是不被单一视角锁住。课程把右脑比作开放的海洋，能把任何事物连接到其他事物；左脑则像语言电脑，擅长代表、分析和控制，但如果成为唯一中心，就会让人困在机器世界，失去心灵、身体和奥秘感。创造性的人会移动、发散、玩耍、幽默，并能像孩子一样流动，同时保有成人的成熟。练习上，可以一天多次收回注意力、触碰心、打开全身通道，暂时放下固定身份，感受自己既是孩子、成年人、古老的生命、大树、动物，也是宇宙的一部分。通过身体动作、声音、笑和想象，人的小我身份会松动，生命意图便能从更广阔的创造意识中表达出来。这种玩耍不是逃避现实，而是让心智恢复灵活性。若发现自己僵硬、无趣、只能想出一种做法，正是需要进入创造性心智的信号。', '["创造性心智", "右脑连接", "左脑分析", "游戏精神", "多重身份", "身体觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 4, now()),
(100005, '三种心智与正念种子：静止、寂静、无边无际', '课程把更深的正念状态分为语言心智、身体心智和场域心智。语言心智容易担忧、解释和计划；身体心智若被紧绷占据，就会阻塞生命之气；场域心智则指人与家庭、城市、自然、社群及万有生命的连接。仅在头脑里设定目标，往往缺少直觉、自信和流动，因此需要把意图放入更精微的身心场域中。三颗种子的练习分别对应三个层面：把静止投入身体，让肌肉和姿态慢下来，像大树向下扎根又向天空打开；把寂静投入语言心智，让杂念在宽阔空间中休息，而不是用力驱赶；把无边无际投入场域心智，让涟漪从心和腹部扩散到周围一切人事物。等身体像光、头脑有寂静、场域能包容时，再说出我想在世界上创造的是什么，创造力会比紧张努力更稳定。', '["三种心智", "正念种子", "语言心智", "身体心智", "场域心智", "生命之气"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 5, now()),
(100006, '三个正向连接：意图、中心与资源圆环', '真正把召唤带到世界，不只是想清楚目标，而是同时建立三个正向连接。第一是简洁、正向、有共振的意图，例如我最想创造的是某种关系、疗愈、平静或贡献；第二是身体中心，可能在心口、腹部或其他最有能量感的地方，当压力、未知、速度过快或注意力涣散时，回到中心就等于回到根基；第三是资源圆环，包含导师、朋友、家人、自然地点、动物、祖先、灵性存有、社群或任何能支持你走路的人事物。练习时先安顿，下沉并打开；再看见未来时间线，一步步前进，每一步都重新感受意图、中心和资源。资源不是抽象安慰，而是一个可被身体感到的场：有人看见你、爱你、理解你、支持你继续。三连可作为任何计划前的微流程：先说清意图，再摸到中心，最后看见资源；三者同时在线时，行动更有弹性和耐力。', '["资源连接", "正向意图", "身体中心", "资源圆环", "时间线", "社群支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 6, now()),
(100007, '三种原型能量：温柔、勇猛与顽皮的整合', '为了让召唤能在沟通和行动中实现，课程提出三种普世原型能量：温柔、勇猛、顽皮。温柔让人先对自己良善，也能在紧张的人际氛围中建立信任和安全；但只有温柔会失去边界，所以需要勇猛的专注、火焰、决心和复原力。勇猛若脱离心灵，会变成暴力、批评或霸凌，因此必须回到人性的中心。顽皮则让人从过度严肃和僵硬中解放出来，带来笑、轻盈、好奇和创造性沟通。练习方式是为每种能量找到代表人物或榜样，进入他们的身体、眼神和姿态，再回到自己身上，用这股能量表达同一个生命意图。成熟表达是三者同时服务于心灵，而不是各自失控。冲突中若只有温柔，容易退让；只有勇猛，容易压迫；只有顽皮，容易逃避深度。', '["原型能量", "温柔", "勇猛", "顽皮", "沟通", "创造力训练"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 7, now()),
(100008, '用原型能量面对障碍：合气道式地欢迎与引导', '障碍在英雄之旅中被称为恶魔，可能是内在恐惧、批评、失联、羞耻，也可能是外在家人、机构、工作环境或不支持你的人。课程借用艾瑞克森取向和合气道精神：不要与阻碍硬碰硬，不要暴力消灭、逃离或控制，而是先与它相合，欢迎它，再把关系带向更好的方向。练习时先站在意图和中心里，看见未来道路，再让一个具体障碍出现在前方。用正向勇猛面对它时，感受边界、眼神、站立方式和可以说出的清晰话语；用顽皮面对它时，跳舞、转圈、笑，避免把力量交给障碍；用温柔面对它时，先支持自己的脆弱，再以成熟善意触碰阻碍背后的痛苦。障碍不是旅程失败的证据，而是提醒你回到中心并调用更完整的自己。', '["障碍转化", "恶魔", "合气道", "非暴力", "边界", "原型应用"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 8, now()),
(100009, '转化恶魔：从问题行为里识别正向需求', '问题、症状和成瘾行为表面上像敌人，深处常隐藏着尚未被看见的正向需求。课程用恶龙可能是等待被发现的礼物来说明这一点：如果只分析、压制、逃避或攻击问题，就会切断它携带的资源。更有效的方法是发展身体模型。选择一个反复让你挣扎的行为或情绪，例如焦虑、缺乏安全感、拖延、上瘾；不要急着解释，不要命令它停止，而是让身体自然做出一个姿态或重复动作，并以比平常慢数倍的节奏、温柔和好奇来体验它。然后在动作中询问：这个模式想为我创造什么，它想满足哪种正向需求。关键在于区分需求和策略：需求可能是安全、温暖、休息、连接或自由，旧策略可以被替换，但需求必须被尊重。', '["恶魔转化", "身体模型", "正向需求", "症状意义", "艾瑞克森", "成瘾疗愈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 9, now()),
(100010, '目标与障碍整合：让对立面成为同一支舞', '目标和障碍并不总是敌对关系，很多症状其实在尝试恢复平衡。一个人用紧绷、强硬和肌肉力量逼自己完成项目，结果拖延不断出现；拖延看似恶魔，深处却可能代表放松、休息、释放和阴性能量，提醒他不能只靠蛮力。整合练习先为目标建立身体模型，感受我真正想创造的是什么；再为每当我想创造它时被触发的那一面建立身体模型，如抑郁、自我批判、恐惧、愤怒或拖延。不要用对错评判两边，而是用缓慢、温柔、顽皮、好奇的动作欢迎每一面，倾听它各自代表的正向需求。整合后的行动不是折中妥协，而是让目标获得障碍所携带的智慧：努力获得休息，勇气获得柔软，前进获得节奏，因此更能长期持续。', '["目标整合", "障碍整合", "阴阳平衡", "拖延", "身体舞蹈", "创造性完整"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 10, now()),
(100011, '传递给他人：把获得的礼物变成世界的光', '英雄之旅最终不是把天分囤积起来，而是传递给他人。课程通过艾瑞克森对学生的教导指出，真正的回报方式是把有用的东西继续分享。一个人在年轻时需要专注自己的目标，但当能力和成功逐渐出现，如果只追逐名利、金钱和外在认可，创造力会再次收缩；若把天赋视为被托付的礼物，并用来帮助别人，生命会更快乐、更宽广。练习上，先放下比较、表演和赚钱的压力，进入让自己感到神圣、平静、合一的空间，感受内在不可摧毁的光。分享不是拯救姿态，也不是牺牲自我，而是让自己的觉醒映照并唤醒他人的觉醒。真正分享时必须先保持自己的光，不在关系中耗尽自己，而是从充满的中心去照亮。', '["传递给他人", "贡献", "礼物", "艾瑞克森", "慈悲练习", "社群疗愈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 11, now()),
(100012, '回顾整合：把每一天活成完整的英雄之旅', '最后的整合练习把十二个模块收束为日常道路：先安顿、下沉大地、向天空打开，让语言像音乐和梦一样流入全身；记得自己来到世界是为了给出一份礼物，也诚实看见曾经因为不被支持而转身拒绝。然后寻找榜样、向导和能让灵魂相触的人，学习把觉知中心从头脑转回身体、心灵和场域。日常行动中，要保留玩耍、温柔、勇猛、专注和严肃的混合状态；遇到障碍时，退后一步成为大树，回到静止、寂静和无边无际，再用身体模型、合气道式欢迎和创造性好奇把冲突转为合作。英雄之旅不是一次性完成的课程，而是每一天都能重新选择的活法：过好今天，享受这一刻，并支持他人也活出他们的旅程。', '["回顾整合", "每日练习", "感恩", "宽恕", "宇宙连接", "享受生命"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 12, now()),
(100013, '1号完美型：核心识别与成长建议', '1号的核心不是简单的爱挑剔，而是内在长期有一套高标准在审判：这件事对不对、够不够好、还能不能改进。他们把责任、秩序、原则和正确性放在快乐之前，擅长发现漏洞、维护规范、把事情做扎实。盲点是把应该当成唯一道路，把错误看成道德问题，把愤怒压成不满、讽刺、僵硬的礼貌或反复纠错。成长关键是从内在批评家退后一步，区分我想要和我应该，允许错误、风险和多种答案存在；把事实核对代替脑内定罪，把感谢与肯定说出口；给日程留白，练习享受、求助和适度妥协；把怒气视为被忽略需求的信号，用清楚、非控诉的语言表达边界。成熟的1号会把高标准转化为可靠、正直和持续改善，而不是让自己和他人永远不合格。', '["九型人格", "1号", "完美型", "完美主义者", "内在批评", "愤怒", "原则", "成长建议"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 13, now()),
(100014, '2号助人型：核心识别与成长建议', '2号的核心驱动力是通过被需要、被喜欢、被认可来确认自己的价值。他们能快速捕捉他人的情绪和需求，愿意支持、照顾、连接资源，也善于让别人感觉自己很重要。盲点是注意力长期放在他人身上，自己的真实需要会变得模糊，付出容易夹带期待：我这么懂你、帮你，你是否也会爱我、重视我？得不到回应时，2号可能受伤、抱怨、控制、吃醋。成长建议是停止用过度付出来换取关系安全，帮助前先问：这是对方真正需要，还是我想证明自己重要？把隐性期待改成直接请求，允许自己接受照顾；建立边界，不把拒绝理解为不爱。成熟的2号能温暖地滋养他人，也能诚实承认自己的欲望、脆弱和限度。', '["九型人格", "2号", "助人型", "给予者", "被需要", "认可", "边界", "关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 14, now()),
(100015, '3号成就型：核心识别与成长建议', '3号的核心关注是成功、效率、形象和可见成果：我怎样被尊敬、被认可、被证明有价值。他们行动快、目标感强、能读懂场域并切换角色，适合推动项目、包装想法、销售愿景、鼓舞团队。代价是把正在做什么误当成我是谁，把悲伤、恐惧、疲惫和亲密需求视为影响表现的干扰。成长方向是从表演自我回到诚实自我：定期停下问自己喜欢什么、不喜欢什么、身体感觉如何；把休息和情感觉察也放进日程，而非只安排产出；学习承认失败、困惑和普通时刻，不急着换项目或换形象。成熟的3号依然高效有感染力，但其价值不再完全依赖掌声。', '["九型人格", "3号", "成就型", "实干者", "形象", "成功", "工作狂", "诚实"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 15, now()),
(100016, '4号自我型：核心识别与成长建议', '4号的核心经验是强烈地感到我与别人不同，并在失落、渴望、独特性和真实表达中寻找自我。他们情感细腻，能进入他人的痛苦，富有审美、创造力和意义感。盲点是注意力容易停在缺失处：现实有什么不够，别人拥有什么而我没有，理想关系为何迟迟不到；情绪会被当成身份，嫉妒、忧郁、浪漫化和戏剧性表达会反复出现。成长建议是尊重情感但不被情感定义：把我感觉如此与事实必然如此分开；在普通日常中建立稳定行动；把嫉妒当成愿望线索，转化为可执行选择；亲密关系中直接表达需要，少用疏离、戏剧化或测试来证明爱。', '["九型人格", "4号", "自我型", "悲情浪漫者", "情绪", "嫉妒", "真实", "创造力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 16, now()),
(100017, '5号理智型：核心识别与成长建议', '5号的核心策略是用观察、知识和边界来保护时间、能量与内在空间。他们擅长客观分析、系统研究、保持冷静，常在独处后才重新接触情绪。压力点在于把外界需求体验成侵入，把亲密、承诺或即时回应视为资源消耗，于是退回头脑、分隔生活领域、少说少给；情绪可能不是没有，而是被推迟到安全独处时才浮现。成长建议不是强迫外向，而是让知识与生命重新连接：在尚未准备完美时也小步参与；用简短语言告诉别人自己需要多少时间和空间，而不是消失；练习在当下辨认身体和情绪，别只事后复盘。', '["九型人格", "5号", "理智型", "观察者", "边界", "知识", "抽离", "独处"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 17, now()),
(100018, '6号忠诚型：核心识别与成长建议', '6号的核心注意力在安全、信任、风险和权威：哪里会出问题，谁可靠，我的决定是否稳妥。他们能预演最坏情况，发现隐藏漏洞，对团队和承诺很忠诚。盲点是焦虑会让他们在顺从与挑战权威之间摆动，既想得到保护又担心被控制；他们可能怀疑他人动机、拖延决定、反复确认，或用反恐惧方式冲向危险来证明自己不怕。成长建议是发展内在权威：把事实、想象、直觉和投射分栏记录；为决策设定截止时间，允许足够好而非绝对安全；公开提出疑问，不在背后累积猜测；练习想象正面结果，让身体体验安全。', '["九型人格", "6号", "忠诚型", "怀疑论者", "安全", "信任", "权威", "焦虑"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 18, now()),
(100019, '7号快乐型：核心识别与成长建议', '7号的核心追求是可能性、自由、快乐和未来计划。他们乐观、点子多、反应快，能把不同事物连接成新方案，擅长带来兴奋感、创新气氛和对未来的信心。盲点是害怕被限制、无聊或痛苦困住，容易用新选择、合理化、玩笑和忙碌避开难受感；承诺后仍保留退路，兴趣下降就转向下一个刺激，未完成事项堆积。成长建议是把自由从永远有别的选择升级为能选择并完成：限制同时进行的项目，给承诺设置收尾标准；遇到痛苦时先停留、呼吸、命名感受，不急着转移；评估计划时同时看风险、资源和代价。', '["九型人格", "7号", "快乐型", "享乐主义者", "自由", "乐观", "选择", "逃避痛苦"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 19, now()),
(100020, '8号领袖型：核心识别与成长建议', '8号的核心关注是力量、控制、公正和真实。他们直接、有行动力，能在混乱中接管局面，保护弱者，讨厌虚伪、软弱和被蒙在鼓里。压力点在于把世界分成强者与弱者，隐藏脆弱，用愤怒、强势和报复来恢复控制，可能无意中让他人害怕或沉默。成长建议是把力量从压制转为承担：行动前先听完整信息，尤其欢迎坏消息；区分我在保护与我在控制；练习用较低强度表达需求，给别人反应时间；在可信对象面前承认害怕、在乎或受伤，不把柔软等同于失败；冲突中追求清楚和修复，而不只是胜利。', '["九型人格", "8号", "领袖型", "保护者", "控制", "正义", "愤怒", "脆弱"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 20, now()),
(100021, '9号和平型：核心识别与成长建议', '9号的核心策略是维持和谐、避免冲突，并把自己融入他人的节奏。他们能倾听多方、理解不同立场、提供稳定支持，是天然的调停者。盲点是忘记自己的优先级，把重要愿望让位给琐事、习惯或他人安排，表面顺从内心保留，压力下以拖延、麻木、被动抵抗表达愤怒。成长建议是把和平从没有冲突升级为真实参与：每天写下自己的一个偏好、一个不愿意、一个下一步行动；用期限和结构帮助聚焦，先做最重要的小步骤；练习直接表达不同意见，不用拖延让别人猜；把愤怒视为生命力和边界的信号。', '["九型人格", "9号", "和平型", "调停者", "和谐", "冲突回避", "惯性", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 21, now()),
(100022, '通用机制：注意力焦点、直觉与三大中心', '九型不是先看外在行为，而是看注意力被什么自动吸走。性格一旦形成，人会选择性搜集信息：1号看对错与改进，2号看别人是否需要和喜欢自己，3号看表现能否获得肯定，4号看缺失、独特和真实感，5号看边界与资源要求，6号看风险和隐藏意图，7号看快乐选择与未来可能，8号看失控、不公和力量对比，9号看他人安排与各方立场。身体中心8、9、1常通过腹部和本能感知环境；情感中心2、3、4通过关系、形象和情绪共鸣感知；精神中心5、6、7通过观察、预测和联想感知。成长入口是成为内心观察者：记录自己第一时间注意到什么、忽略什么；区分事实、解释、幻想和直觉。', '["九型人格", "通用机制", "注意力", "直觉", "三大中心", "身体中心", "情感中心", "精神中心"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 22, now()),
(100023, '通用机制：两翼、核心动机与同型差异', '两翼指某个型号相邻两侧型号对其表达方式的影响。它不是另一个核心类型，也不是简单的副人格，而是让同一型号呈现不同气质的调味层：偏5翼的4号可能更内收、理性和孤僻，偏3翼的4号可能更外显、形象化和有舞台感；偏8翼的9号更硬、更能顶住压力，偏1翼的9号更克制、更在意正确与秩序。使用两翼时要避免只凭风格判断，例如一个强势的9号不等于8号，一个外向的5号也不等于7号。先问核心动机：他是在维护和谐、保留资源，还是追求自由？再看两翼怎样改变表达。两翼解释差异，不替代访谈、情境和长期注意力观察。', '["九型人格", "通用机制", "两翼", "核心动机", "同型差异", "识别方法"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 23, now()),
(100024, '通用机制：压力线、安全线与状态变化', '每个型号不是静态标签，而是由日常主型、压力状态、安全状态共同构成。压力状态常沿箭头离开本型：1到4、2到8、3到9、4到2、5到7、6到3、7到1、8到5、9到6；安全状态常沿反向进入：1到7、2到4、3到6、4到1、5到8、6到9、7到5、8到2、9到3。使用时不要把安全线等同于一定健康、压力线等同于一定糟糕；安全也可能暴露阴影，压力也可能激发能力。关键是观察状态变化：在放松、受威胁、被爱、被批评时你变成什么样？成长不是迷恋安全态，而是能觉察三种状态、整合其正面资源，并在负面反应出现前暂停选择。', '["九型人格", "通用机制", "压力线", "安全线", "动态变化", "九角星", "状态识别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 24, now()),
(100025, '通用机制：关系与职场沟通的九型用法', '九型用于关系和职场时，重点不是给人分类，而是找到对方的原动力、焦虑点和沟通入口。1号需要尊重其标准，同时减少你错了的羞辱感；2号需要感谢但也要鼓励其说出真实需求；3号需要目标和认可，也要提醒其关注人和过程；4号需要真实与意义，反馈要避免轻率否定其感受；5号需要提前信息、边界和思考时间；6号需要透明、稳定承诺和可验证依据；7号需要空间与愿景，同时要明确收尾责任；8号需要直说、完整信息和可信赖的边界；9号需要清晰结构、温和追问和表达异议的安全感。成熟用法是用类型翻译彼此语言：把评判译成对质量的在乎，把控制译成对安全的需求，把拖延译成冲突恐惧，再讨论可执行请求。', '["九型人格", "关系", "职场", "沟通", "领导力", "反馈", "冲突", "团队管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 25, now()),
(100026, '关键对话：先恢复安全感，再讨论观点差异', '关键对话通常同时具备三个特征：观点不同、利害关系重大、情绪强烈。很多沟通失败不是因为道理不够，而是对话安全感已经破裂；一旦人感觉被攻击、羞辱或不被尊重，就会转入沉默或暴力：沉默包括回避、掩饰、退出，暴力包括控制、贴标签、攻击和打断。有效处理关键对话的第一步，不是立刻证明自己正确，而是观察气氛是否安全：对方是否还愿意说真话，自己是否还在听。若安全感下降，应先暂停内容争论，说明共同目的和尊重，例如“我不是要否定你，我想一起把问题解决”。然后再陈述事实、表达感受、解释自己的故事、询问对方看法。App 问答可用于伴侣冲突、上下级反馈、客户沟通和团队分歧。', '["关键对话", "沟通", "安全感", "冲突", "反馈", "沉默", "暴力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 26, now()),
(100027, '非暴力沟通四步：观察、感受、需要、请求', '非暴力沟通的核心，是把注意力从评判、指责、命令和辩解，转向人真实的观察、感受、需要和请求。第一步是观察：具体说发生了什么，避免“你总是”“你从来不”等概括性评价。第二步是感受：表达自己身体和情绪的真实状态，如失落、担心、疲惫、安心，而不是伪装成感受的指责。第三步是需要：为自己的感受负责，看到背后未被满足的需要，如尊重、休息、连接、自由、安全、理解。第四步是请求：提出具体、可执行、当下可回应的请求，而不是模糊期待或命令。它并非软弱妥协，而是让双方从敌对意识回到生命需要。适合回答亲密关系争吵、亲子沟通、职场表达、如何提出边界和如何道歉。', '["非暴力沟通", "观察", "感受", "需要", "请求", "同理心", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 27, now()),
(100028, '情绪急救：拒绝、孤独、失败和反刍需要及时处理', '日常心理伤害也需要像身体伤口一样做急救。拒绝会带来尖锐痛感，削弱自尊和归属感；孤独会让人更敏感、更防御，甚至把真正能靠近的人推开；失败容易让人把一次结果扩大成对自我的否定；反刍会让痛苦反复激活，形成焦虑和抑郁倾向。情绪急救的第一原则是尽早处理，而不是硬扛。可以先给情绪命名，承认痛苦真实存在；再把事件与自我价值拆开，避免“我被拒绝=我不值得”；随后做具体修复：联系安全的人、恢复日常行动、减少反复回放、写下可学习之处。若痛苦持续影响睡眠、工作、饮食、现实判断或有自伤风险，应寻求专业帮助。App 可用于被拒绝、失恋、孤独、失败、自卑和内耗等场景。', '["情绪急救", "拒绝", "孤独", "失败", "反刍", "自尊", "心理创伤"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 28, now()),
(100029, '自控力：先观察失控模式，再设计环境', '自控不是靠羞辱自己变强，而是成为自己的观察者，理解何时、何地、因为什么失控。很多人越相信自己意志坚定，越容易把自己暴露在诱惑中；一旦失败，又因为意外和羞耻而放弃。更有效的方法是像科学家一样收集数据：什么时候最容易拖延，什么情绪会触发消费或暴食，哪些人、地点、App 或疲劳状态会削弱自控。然后设计环境而不是只发誓：减少诱惑可见度，提前设定下一步动作，把长期目标和眼前选择连接起来，用小实验测试哪种方法有效。自控力还包含“我要做”“我不要”“我想要”三种力量：不仅要抵制诱惑，也要记得真正重要的目标。App 可用于拖延、成瘾、情绪性消费、减肥、学习和习惯改变。', '["自控力", "意志力", "拖延", "习惯改变", "观察者", "诱惑", "目标"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 29, now()),
(100030, '解决冲突：把冲突当作信息，而不是立即消灭', '冲突不可完全避免，重要的是把它当作信息入口，而不是马上逃跑、压制或赢过对方。高质量冲突处理从理解发生了什么开始：双方各自看到了什么事实，分别受到什么影响，各自真正关心什么。很多人一遇冲突就急着解决，反而没弄清原因；也有人任由敌意升级，错失修复机会。有效做法是先降低攻击性表达，帮助聆听和说话变得容易：少用指责，多用具体事件；少说“你就是”，多问“你当时看到的是什么”；承认对方处境，同时表达自己的边界和请求。冲突的目标不是双方都委屈地妥协，而是找到能照顾重要需要的新路径。App 可用于伴侣冷战、团队矛盾、朋友误会、谈判和家庭分歧。', '["解决冲突", "聆听", "对话", "边界", "关系修复", "谈判", "误会"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 30, now()),
(100031, '创伤反应：身体会记住未完成的危险', '创伤并不只是记忆里的一段故事，也会保存在身体、神经系统和关系反应中。经历过创伤的人可能明知现在安全，却在类似声音、气味、表情、距离或权威情境中突然紧绷、麻木、愤怒、逃离或讨好；这不是矫情，而是身体在用旧系统保护自己。疗愈的核心之一是重新建立安全与调节能力：先识别触发点和身体信号，再用呼吸、地面感、身体移动、稳定关系和可预测环境帮助神经系统回到当下。不要急着逼自己讲完所有创伤细节，身体安全比叙事完整更基础。关系中，创伤者需要被看见、被尊重节奏，而不是被催促“想开点”。App 可用于惊恐、麻木、过度警觉、亲密关系触发和创伤后自我理解。', '["创伤疗愈", "身体记忆", "安全感", "神经系统", "触发点", "情绪调节", "依恋"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 31, now()),
(100032, '回避型模式：逃避情绪会让关系和自我更空', '回避型或逃避型人格模式常见于对拒绝、失望、犯错和暴露脆弱高度敏感的人。为了不被伤害，他们会隐藏不安全感，努力保持理性、独立、无所谓，甚至把真实情绪像流感一样躲开。短期看，逃避能减少痛苦；长期看，它会让人失去与自己和他人的情绪连接，形成空虚、焦虑、亲密困难和自我价值感低落。成长不是一次性冲进情绪，而是安全地接触：当想逃跑、责备或麻木时，先停下，命名身体感受和脑中故事；区分真实事件与旧信念；用小剂量表达需要和脆弱，观察关系是否真的崩塌。App 可用于回避亲密、不敢表达、不安全依恋、内心空虚和情绪逃避。', '["回避型人格", "不安全依恋", "情绪逃避", "亲密关系", "脆弱", "自我价值", "焦虑"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 32, now()),
(100033, '边界表达：清楚说不，不等于伤害关系', '很多关系问题不是缺少爱，而是缺少清楚边界。没有边界的人容易讨好、压抑、拖延、爆发；边界过硬的人则可能控制、隔离、拒绝连接。健康边界是既承认关系重要，也承认自己的时间、身体、情绪和价值同样重要。表达边界时，先具体说明事实和影响，再表达自己的限制和可提供的替代方案，例如“我今晚需要休息，不能继续讨论；明天十点我可以认真听你说”。边界不是惩罚，也不是让对方猜，而是让关系可持续。若对方不适应你的新边界，不代表你错了；这只是关系系统在重新调整。App 可用于不会拒绝、被索取、关系内耗、职场加班、人情压力和亲密关系空间。', '["边界", "拒绝", "讨好", "关系内耗", "自我照顾", "沟通", "亲密关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 33, now()),
(100034, '行动改变：把大目标拆成可重复的小实验', '无论是九型成长、英雄之旅还是自控力训练，真正改变都需要从宏大愿望落到小实验。大目标容易激发热情，也容易引发压力、完美主义和拖延；小实验则让人用数据学习，而不是用自责消耗。设计实验时要明确：我要观察什么，下一步最小行动是什么，何时做，做完如何记录。比如想改善沟通，不是发誓以后不吵架，而是每次冲突前先说一个事实、一个感受、一个请求；想减少拖延，不是要求自己从此自律，而是先开始5分钟并记录触发点。失败不是人格失败，而是实验数据，提醒你调整环境、节奏、支持或目标。App 可用于习惯养成、学习计划、关系修复、情绪管理和职业目标推进。', '["行动改变", "小实验", "习惯养成", "拖延", "目标拆解", "复盘", "成长练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 34, now()),
(100035, '关系修复：先承认影响，再解释动机', '关系受伤后，很多人急着解释自己不是故意的，却忽略对方已经受到影响。修复对话应先承认事实和影响：我看到我刚才打断你，让你觉得不被尊重；再表达自己的感受和需要；最后提出可执行的修复请求或承诺。解释动机可以放在后面，因为如果先解释，容易被听成辩解。修复也包括聆听对方版本，不急着纠正其中每个细节。道歉不是自我贬低，而是对关系的负责；原谅也不是立刻恢复原状，而是双方重新建立安全感和边界。若伤害反复发生，修复需要具体行为变化，而不只是情绪表达。App 可用于道歉、冷战后复联、伴侣争吵、朋友误会、亲子冲突和职场关系恢复。', '["关系修复", "道歉", "影响", "安全感", "冷战", "亲密关系", "沟通模板"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 35, now()),
(100036, '福格行为模型：行为发生要同时具备动机、能力与提示', '当用户说“我知道该做但就是做不到”时，优先从行为设计入手。一个行为要发生，通常需要动机足够、能力门槛足够低、提示在正确时间出现。动机最不稳定，不能把改变押在热血上；更可靠的方式是把行为缩小到几乎不会失败，并绑定已有习惯。比如“刷牙后做一次深呼吸”“进门后先问一句今天怎么样”。先让行为发生，再让身份感和自信跟上。', '["行为改变", "福格模型", "微习惯", "动机", "提示", "自控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 36, now()),
(100037, '微习惯设计：小到不会失败，才容易长期坚持', '很多改变失败不是因为目标太小，而是第一步太大。微习惯的关键是把行动拆到两分钟内可完成，先追求“出现”而不是“完美”。用户想读书，可先设为“打开书读一段”；想运动，可先设为“穿上鞋出门站一分钟”。完成后及时给自己一个正向标记，让大脑把新行为和成就感连接起来。稳定后再自然加量，而不是一开始靠逼迫冲刺。', '["微习惯", "行动设计", "成长", "自我效能", "坚持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 37, now()),
(100038, '习惯回路：找出提示、惯常行为和奖励', '习惯不是单个动作，而是“提示—惯常行为—奖励”的回路。想改变坏习惯，先观察它通常在什么时候、什么情绪、什么地点、和谁在一起时发生，再识别真正奖励：是放松、逃避压力、获得刺激，还是寻求连接。不要只删除行为，而要保留奖励、替换动作。例如压力大就刷短视频，可能真正需要的是短暂恢复；可替换成五分钟散步、伸展或给朋友发一句话。', '["习惯回路", "行为改变", "奖励", "提示", "替代行为"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 38, now()),
(100039, '自控力不是硬扛，而是提前设计环境', '自控力资料的核心提醒是：越到诱惑现场才靠意志力，越容易失败。更有效的是提前改环境，让好行为更容易、坏行为更麻烦。想少刷手机，把手机放远、关通知、设置固定查看窗口；想控制饮食，不把高诱惑食物放在手边；想避免情绪化回复，先写草稿不发送。自控不是讨厌自己，而是承认人会受情境影响，然后温和地设计情境。', '["自控力", "环境设计", "意志力", "诱惑", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 39, now()),
(100040, '拖延的背后常是情绪调节，而不是懒', '拖延往往不是时间管理问题，而是情绪管理问题：任务让人感到羞耻、恐惧、无聊或无力，于是大脑选择短期缓解。处理拖延时，不要只问“怎么提高效率”，先问“我在回避哪种感受”。可把任务拆成下一步可见动作，并设置低压力开始仪式：只做五分钟、只写标题、只打开文件。开始后焦虑下降，行动会反过来带来掌控感。', '["拖延", "情绪调节", "行动", "自我效能", "任务拆解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 40, now()),
(100041, '认知觉醒：改变先从注意力回到当下开始', '成长不是一口气重塑人生，而是逐步看见自动反应。认知觉醒强调把注意力从模糊焦虑拉回具体事实：我现在在想什么、身体有什么感觉、下一步最小行动是什么。用户陷入“我不行、来不及、都完了”时，可先把大问题拆成可观察的场景和可执行的十分钟行动。觉察不是想明白一切，而是让自己从自动驾驶切回主动驾驶。', '["认知觉醒", "注意力", "自我改变", "行动", "觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 41, now()),
(100042, '成长型改变：先做实验，不急着定义自己', '当用户把一次失败解释成“我就是这种人”，改变会被身份标签锁死。更好的语言是实验：这次策略不适合我，下一次换一个提示、环境或支持方式。把改变当实验，可以降低羞耻感，也能保留复盘能力。每次只调整一个变量，例如时间、地点、同行者、任务大小或奖励方式。真正重要的不是一次做对，而是形成可迭代的自我更新系统。', '["成长", "实验思维", "复盘", "身份", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 42, now()),
(100043, '焦虑自助：先区分真实问题和假想灾难', '焦虑会把可能性伪装成确定性，让人提前生活在最坏结果里。处理时先写下担心内容，再分成两类：真实可行动的问题，和目前无法验证的灾难想象。前者列出下一步行动；后者练习延迟担心、回到身体和现实证据。不要和焦虑争辩“别想了”，而是问：我现在能做哪一个具体动作？如果不能行动，我能否先照顾身体，让神经系统降档？', '["焦虑", "认知行为", "担心", "情绪调节", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 43, now()),
(100044, '情绪粒度：说得越准确，越容易选对行动', '“我很烦”通常太粗糙，无法指导行动。情绪粒度训练是把模糊难受细分：委屈、羞耻、嫉妒、失望、担心、孤独、被忽视、无力、愤怒。不同情绪需要不同回应：失望需要调整期待，羞耻需要自我接纳，愤怒常提示边界，孤独提示连接需求。App 回答情绪问题时，应先帮用户命名感受，再从感受背后的需要进入行动建议。', '["情绪", "情绪粒度", "自我觉察", "需要", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 44, now()),
(100045, '情绪急救：心理小伤也要及时处理', '拒绝、孤独、失败、反刍和自责就像心理擦伤，如果不处理会扩大成长期痛苦。情绪急救的重点不是立刻积极，而是防止二次伤害：不要用一次拒绝证明自己不值得，不要让失败变成全面否定，不要在脑内反复播放羞辱场景。可用三步处理：承认受伤，给出多个解释，做一个能恢复自尊或连接的小行动。', '["情绪急救", "拒绝", "孤独", "失败", "自尊"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 45, now()),
(100046, '创伤反应：身体会先于理性进入防御', '创伤相关资料提醒，很多“反应过度”其实是身体把当下误判为过去的危险。用户突然僵住、爆发、逃离、麻木，并不一定是矫情，而可能是神经系统进入战斗、逃跑、冻结或讨好。支持方式不是逼自己马上讲道理，而是先恢复安全：看见周围环境、触碰稳定物体、慢慢呼气、让身体知道此刻已经不同于过去。稳定后再处理故事和意义。', '["创伤", "身体反应", "安全感", "神经系统", "疗愈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 46, now()),
(100047, '愤怒的积极功能：它常在提醒边界被侵犯', '愤怒并不总是坏情绪，它常提示某个边界、价值或需求被忽视。问题不在愤怒本身，而在表达方式。用户生气时可先问：我在保护什么？我希望对方停止什么、开始什么、理解什么？等身体降温后，用边界句表达：“当发生 X 时，我感到 Y，因为我需要 Z；下次请具体做 A。”这样既不压抑愤怒，也不让愤怒变成攻击。', '["愤怒", "边界", "情绪管理", "需求", "表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 47, now()),
(100048, '抑郁低谷：先恢复行动循环，再追求意义感', '抑郁状态会让人失去动力，而失去行动又会进一步降低情绪。支持用户时，不宜只说“想开点”。更实用的是行为激活：每天安排极小、可完成、可记录的行动，如洗澡、晒太阳、走五分钟、整理一小块桌面、联系一个安全的人。行动不是为了立刻开心，而是重建“我还能影响一点点生活”的证据。必要时建议寻求专业支持。', '["抑郁", "行为激活", "低谷", "行动", "支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 48, now()),
(100049, '反刍思维：把脑内复盘变成纸面问题', '反刍会让人以为自己在解决问题，实际是在重复痛苦。识别标志是：想了很久却没有新信息、没有行动、情绪更糟。可把脑内循环写成三个问题：我正在反复想哪句话？它对应的事实证据是什么？我能采取的最小行动是什么？如果没有行动，就给担心设置时间盒，转向身体活动或连接他人。把想法落到纸面，能把情绪风暴变成可处理对象。', '["反刍", "焦虑", "情绪急救", "书写", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 49, now()),
(100050, '存在焦虑：意义不是找到标准答案，而是承担选择', '存在主义心理治疗提醒，人的痛苦不只来自症状，也来自自由、孤独、死亡和意义感。用户问“我到底为什么活着”时，不必急着给鸡汤答案。可以引导其看见：意义往往不是被发现的固定物，而是在选择、关系、创造和承担中生成。先从一个愿意负责的小选择开始：今天我想怎样对待身体、关系、工作或某个重要价值？', '["存在主义", "意义感", "选择", "自由", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 50, now()),
(100051, '依恋系统：亲密关系里的追和躲都是求安全', '亲密关系中的“追问”和“冷处理”常不是单纯作或无情，而是两种安全策略。焦虑型通过靠近、确认、解释来降低不安；回避型通过拉开距离、沉默、强调独立来恢复掌控。若双方只攻击表层行为，就会形成越追越逃。修复时要翻译需求：追的一方需要可预期回应，躲的一方需要不被淹没的空间。先约定冷静时长和恢复沟通时间，比无限争对错更有效。', '["依恋", "亲密关系", "追逃循环", "安全感", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 51, now()),
(100052, '爱的五种语言：用对方能接收的方式表达爱', '很多关系并非没有爱，而是表达通道错位。爱的五种语言包括肯定的话语、高质量陪伴、接受礼物、服务行动和身体接触。用户可以观察伴侣最常抱怨什么、最常主动给出什么、最容易因什么感动，来判断主要爱语。关系经营不是只用自己喜欢的方式付出，而是学习对方能接收的方式，同时也清楚告诉对方自己需要什么。', '["亲密关系", "爱的五种语言", "伴侣", "表达爱", "需求"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 52, now()),
(100053, '伴侣冲突：先分清事实、解释和感受', '伴侣争吵常把事实、解释和感受混在一起：“你又不在乎我”其实可能包含事实“你迟到了三十分钟”、解释“你不重视我”、感受“我失望和不安”。修复时先拆开三层，事实越具体越少争议，解释越开放越能对话，感受越真诚越容易被听见。可以说：“你晚到三十分钟时，我脑中解释成自己不重要，所以很失落。我想知道实际发生了什么。”', '["伴侣沟通", "冲突修复", "事实", "感受", "解释"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 53, now()),
(100054, '亲子沟通：先连接，再纠正', '儿童沟通资料的一个关键原则是：孩子在被理解前很难真正听见道理。亲子冲突中，先描述孩子可能的感受和愿望，再谈规则与后果。比如“你很想继续玩，所以被叫停很生气”，比“别闹了”更能降低防御。连接不是纵容，而是先让孩子的大脑从对抗状态回到可学习状态。之后再给有限选择和清晰边界。', '["亲子沟通", "儿童心理", "连接", "边界", "情绪"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 54, now()),
(100055, '家庭关系中的边界：爱不是互相吞没', '家庭里常把“我都是为你好”当成越界理由。健康边界不是冷漠，而是区分谁的情绪、选择和后果由谁负责。用户面对父母、伴侣或孩子的压力时，可用三句式：我理解你的担心；这件事我会自己决定；我愿意在某个范围内和你讨论。边界需要温和重复，不必每次都证明自己有资格说不。', '["家庭关系", "边界", "自主", "沟通", "责任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 55, now()),
(100056, '人际游戏：反复上演的冲突通常有隐藏收益', '沟通分析资料强调，有些冲突像固定剧本：表面在解决问题，实际在重复熟悉角色，例如“你看我多可怜”“你总是错”“只有我能救你”。这些游戏会带来隐藏收益：避免真正亲密、证明旧信念、获得注意或逃避责任。识别方法是看结局是否总相似、情绪是否熟悉、双方是否越谈越远。退出游戏的第一步，是拒绝继续扮演被分配的角色。', '["沟通分析", "人际游戏", "关系模式", "责任", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 56, now()),
(100057, '讨好型关系：把“被喜欢”从生存需求降级为普通愿望', '讨好型模式会让人把别人的满意当作安全来源。用户需要练习把“希望被喜欢”与“必须被喜欢才能安全”分开。可以从低风险场景练习表达偏好：今天我想吃这个、这个时间我不方便、我需要考虑一下。每一次没有迎合却仍然安全，都会给神经系统新证据。边界不是突然强硬，而是逐步把自我带回关系中。', '["讨好型人格", "边界", "关系", "自我价值", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 57, now()),
(100058, '关键对话开场：用共同目的降低防御', '高风险对话开始前，先不要急着陈述立场，而要建立共同目的。共同目的回答的是：我们为什么值得继续谈？例如“我不是想追责，而是想让之后合作更顺”“我想谈这件事，是因为这段关系对我重要”。当对方感到你不是来羞辱或控制，才可能从防御转向合作。事实、感受和请求都应服务于共同目的。', '["关键对话", "共同目的", "安全感", "高难沟通", "合作"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 58, now()),
(100059, '非暴力沟通的难点：请求必须具体且可拒绝', '非暴力沟通不只是温柔说话。很多人把要求伪装成请求，例如“你能不能尊重我一点”。真正的请求要具体、当下、可执行、可拒绝，如“今晚十点前能否把行程告诉我”。如果对方不能拒绝，那更像控制；如果不够具体，对方不知道怎么做。清楚请求能让关系从猜测和指责转向协商。', '["非暴力沟通", "请求", "需要", "边界", "关系沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 59, now()),
(100060, '共情不是同意，而是准确理解对方的内在经验', '共情力的重点不是替对方辩护，也不是放弃自己的立场，而是先准确复述对方的感受、需要和处境。有效共情常包含三层：你经历了什么，你因此有什么感受，这背后什么对你重要。共情之后仍可以设边界。比如“我听见你很委屈，也很想被支持；同时我不能接受用吼叫继续谈。”这样既连接，也不纵容。', '["共情", "倾听", "边界", "沟通", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 60, now()),
(100061, 'NLP地图：人回应的是自己的解释系统', '沟通中，别人不是直接回应现实，而是回应自己脑中的地图：经验、信念、价值和语言习惯。同一句话可能被理解成建议、批评、控制或关心。遇到误解时，不要只重复原话，可换一种感官通道和框架：给画面、给步骤、给感受、给选择。先理解对方地图，再邀请对方更新地图，比强迫对方接受自己的版本更有效。', '["NLP", "地图不是疆域", "沟通", "信念", "换框"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 61, now()),
(100062, '语言风格会透露关系位置和情绪距离', '语言风格资料提醒，词语不只传递内容，也传递关系位置。频繁使用绝对化词汇会增加压迫感；大量“你总是、你从不”容易引发防御；只讲道理不说感受，会让亲密关系变冷；过度道歉可能暴露低位和讨好。App 在润色沟通话术时，应把攻击性判断改成具体事实，把绝对化改成当下情境，把隐藏需求说清楚。', '["语言风格", "沟通", "关系位置", "表达", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 62, now()),
(100063, '影响力原则：先建立可信度，再提出请求', '影响力不是操控，而是降低对方理解和决策成本。常见有效因素包括互惠、承诺一致、社会认同、喜好、权威和稀缺。但在关系和咨询场景中，最重要的是可信度与尊重。先说明共同利益、展示理解、给出选择，再提出具体请求。若只利用技巧压迫对方，即使短期有效，也会破坏信任。', '["影响力", "说服", "信任", "请求", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 63, now()),
(100064, '金字塔表达：先给结论，再给理由和行动', '用户需要向伴侣、客户或团队说明复杂问题时，可使用金字塔结构：先说核心结论，再给三到四个理由，最后给下一步行动。这样能减少对方在信息中的迷路感。情绪沟通也可借用：我的结论是我希望我们调整相处方式；理由是最近三次约定都失效、我感到不安、我仍重视关系；下一步是我们约定一个可执行规则。', '["金字塔原理", "表达结构", "沟通", "结论先行", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 64, now()),
(100065, '谈判不是压倒对方，而是扩大可交换资源', '谈判资料适合转化为关系协商建议：不要只盯一个立场，而要找背后的利益。双方争“谁对谁错”时，资源只有面子；转向“各自真正想保护什么”时，可能出现时间、方式、顺序、补偿、试行期等多个变量。好的谈判不是让一方认输，而是创造比僵持更好的交换方案。', '["谈判", "利益", "协商", "冲突解决", "双赢"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 65, now()),
(100066, '九型领导力：不同型号需要不同反馈方式', '九型用于管理和关系时，不是贴标签，而是调整沟通入口。1号重标准，反馈要具体且尊重其原则；2号重关系，先肯定付出再邀请表达需求；3号重成果，给清晰目标和真实反馈；4号重独特和意义，避免轻率否定感受；5号重边界，提前给信息；6号重安全，说明依据与风险；7号重自由，给选择；8号重直接，少绕弯；9号重和谐，要明确邀请其立场。', '["九型人格", "领导力", "反馈", "沟通", "团队"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 66, now()),
(100067, '人格识别：看注意力焦点，不只看外在行为', '同一种行为可能来自不同动机。努力工作可能是1号的责任、3号的成就、6号的安全、8号的掌控；照顾别人可能是2号的连接，也可能是9号避免冲突。识别九型时，应观察注意力自动被什么吸走：错误、需求、形象、缺失、边界、风险、可能性、力量还是和谐。动机比行为更稳定，也更适合给出成长建议。', '["九型人格", "识别方法", "动机", "注意力", "性格"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 67, now()),
(100068, '性格陷阱：早年适应策略长大后可能变成限制', '性格陷阱不是道德缺陷，而是曾经帮助人适应环境的策略在新场景中过度使用。比如过度警觉曾经保护自己，如今可能变成不信任；讨好曾经减少冲突，如今可能失去边界；控制曾经带来安全，如今可能压迫关系。成长不是否定过去的自己，而是感谢旧策略，再发展更多选择。', '["性格陷阱", "人格", "早年经验", "成长", "模式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 68, now()),
(100069, '回避型模式：真正需要的不是消失，而是安全距离', '回避型用户常在关系变近时想逃，因为亲密被体验为压力、要求或失控。修复不是强迫自己立刻完全开放，而是学会表达安全距离：“我需要半小时冷静，但我会回来继续谈。”这样既保护空间，也减少对方被抛弃感。回避的成长方向，是把消失变成可预期的暂停，把独立变成有连接的独立。', '["回避型人格", "依恋", "亲密关系", "边界", "安全距离"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 69, now()),
(100070, '人格障碍资料的启发：先看长期模式和功能损害', '面对“TA 是不是某种人格障碍”的问题，App 不应轻易诊断，而要引导用户观察长期模式：是否跨场景反复出现，是否导致关系、工作或自我功能受损，是否难以通过普通沟通调整。可提供非诊断性建议：保护边界、记录事实、减少被拉入极端互动，必要时寻求专业评估。知识库应避免给人贴病理标签。', '["人格", "边界", "关系风险", "非诊断", "心理健康"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 70, now()),
(100071, '系统思考：不要只盯事件，要看结构和反馈回路', '系统思考提醒，很多问题不是单次事件，而是结构持续制造同样结果。关系里反复争吵，可能有追逃反馈回路；工作中总拖延，可能有目标过大、反馈太慢、奖励缺失的结构。提问时从“谁错了”升级为“什么结构让这个结果反复发生”。找到反馈回路后，改变一个杠杆点，比反复责备更有效。', '["系统思考", "反馈回路", "关系模式", "行为改变", "结构"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 71, now()),
(100072, '批判性提问：先问证据，再问替代解释', '学会提问适合提升 App 回答的思辨质量。用户陷入单一解释时，可引导其问：我有什么证据？证据是否可靠？还有没有其他解释？这个结论有没有忽略例外？如果最好的朋友遇到同样情况，我会怎样判断？批判性思维不是否定一切，而是让情绪化判断多经过一道证据和替代解释的过滤。', '["批判性思维", "提问", "证据", "替代解释", "认知"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 72, now()),
(100073, '第三选择：从你赢我输转向共同创造', '冲突中的两难常被卡成“按你的”或“按我的”。第三选择思维要求先暂停立场竞争，进入理解和共创：我先真正理解你，你也理解我，然后我们一起找一个比双方原方案更好的方案。它特别适合亲密关系和团队冲突，因为关系质量本身也是结果的一部分。不是折中到双方都不满意，而是扩大问题框架。', '["第三选择", "冲突解决", "共创", "协作", "思维模型"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 73, now()),
(100074, '社会性动物：人会被情境和群体强烈影响', '社会心理学提醒，人的行为不只来自性格，也受情境、规范、群体认同和他人期待影响。用户评价自己或他人时，不要过早归因为“人品就是这样”。可问：当时的压力、群体氛围、权威暗示、奖励惩罚、旁观者反应是什么？理解情境不是推卸责任，而是找到更有效的改变入口。', '["社会心理学", "情境", "群体", "归因", "行为"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 74, now()),
(100075, '态度改变：先降低威胁，再提供新经验', '态度很少因为被强行说服而改变。直接否定对方常会激发防御，让其更坚持原观点。更有效的是先承认其关切，再提供小的新经验或证据，让对方保留自尊地更新。亲密关系中也是如此：如果一开口就是“你错了”，对方会保护自我；如果先说“我理解你担心的是 X，同时我想补充 Y”，才更可能产生移动。', '["态度改变", "社会影响", "说服", "防御", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 75, now()),
(100076, '心智模型：同一问题要用多个镜头看', '高质量思维不是掌握一个万能模型，而是能切换镜头。遇到关系问题，可用依恋看安全感，用系统思考看互动回路，用非暴力沟通看需要，用九型看注意力焦点。遇到行动问题，可用习惯回路、福格模型和自控环境设计。多模型能避免把复杂人生简化成一句标签。', '["思维模型", "多元视角", "决策", "关系", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 76, now()),
(100077, '高品质思维：先选模型，再处理问题', '《30个高品质思维模型》OCR 后可提炼为一个实用原则：不要把所有问题都当成情绪、性格或努力问题。遇到选择困难，用机会成本和长期收益看；遇到反复冲突，用系统回路看；遇到沟通卡住，用换位和利益结构看；遇到目标失控，用拆解和反馈看。模型不是答案，而是提问方式。App 回答时可以先判断问题类型，再选择适合的思维框架，避免给出泛泛建议。', '["思维模型", "问题拆解", "决策", "系统思考", "反馈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 77, now()),
(100078, '人际吸引和自尊：关系问题常牵动自我评价', '社会心理资料显示，人际反馈会强烈影响自我评价。用户被冷落或拒绝时，痛苦不只来自事件，也来自“我是不是不值得”的解释。支持时应把事件和价值拆开：一次回应慢，不等于你没有价值；一次关系失败，不等于你不适合被爱。先稳住自尊，再决定是否沟通、调整期待或离开。', '["自尊", "人际关系", "拒绝", "社会心理", "安全感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 78, now()),
(100079, '人生阶段：成长任务会随着年龄和角色改变', '成年发展心理学提醒，不同阶段的核心任务不同：建立身份、亲密关系、事业责任、照顾下一代、重新整合意义。用户的困惑不一定是退步，可能是旧阶段策略无法满足新阶段任务。App 回答时可问：你现在处在人生哪个转折？这个问题是在要求你发展什么新能力？这样能把焦虑转化为发展任务。', '["成年发展", "人生阶段", "成长任务", "身份", "意义"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 79, now()),
(100080, '人性的弱点：被重视感是沟通的底层需求', '人际沟通中，很多人首先需要感到被尊重、被看见、被认真对待。赞美、记住名字、真诚兴趣、少批评多理解，并不是讨好技巧，而是在满足基本的被重视需求。用于 App 建议时，应避免机械取悦，而是提醒用户：先让对方感到自己不是被审判的对象，再提出观点或请求。', '["人际沟通", "尊重", "被看见", "关系", "表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 80, now()),
(100081, 'NLP目标框架：把愿望改写成可执行结果', 'NLP 资料适合转化为 App 的目标澄清工具：不要只说“我不要焦虑、不要吵架、不要拖延”，而要改成正向、具体、可验证、由自己能启动的结果。例如“我想在冲突开始后先暂停三十秒，再用事实和需要表达”。一个好目标要能回答：我想要什么，何时何地发生，如何知道达成，它对我和关系是否生态，第一步由谁开始。这样能把模糊愿望转为行动脚本。', '["NLP", "目标设定", "行为改变", "可执行", "正向目标"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 81, now()),
(100082, 'NLP感知位置：从我、你、旁观者三角度重看冲突', '处理冲突时，可用 NLP 的感知位置练习。第一位置是我：我看见什么、感到什么、需要什么；第二位置是对方：如果我是 TA，可能害怕什么、想保护什么；第三位置是旁观者：一个中立的人会如何描述双方互动。用户卡在委屈或愤怒中时，不要求立刻原谅，而是先切换观察位置。位置切换能降低单一叙事的黏性，让沟通从控诉转向理解和选择。', '["NLP", "感知位置", "换位思考", "冲突修复", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 82, now()),
(100083, 'NLP逻辑层次：别在身份层攻击，只在行为层调整', '沟通中最容易伤人的错误，是把行为问题上升到身份否定：“你就是自私”“我就是没用”。NLP 的逻辑层次可帮助拆分：环境、行为、能力、信念价值、身份、使命。越高层越敏感，越低层越可改。反馈别人时，应尽量落在具体行为和影响上；鼓励自己时，可以把失败从身份层降回策略层：不是我不行，而是这个方法、环境或能力训练还需要调整。', '["NLP", "逻辑层次", "身份", "反馈", "自我价值"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 83, now()),
(100084, 'NLP亲和感：先校准对方状态，再推动观点', '高效沟通不是急着输出观点，而是先建立亲和感。亲和不等于讨好，而是观察对方的节奏、情绪、用词和关注点，让对方感到被接上。用户想说服或修复关系时，可先复述对方关键词，确认理解，再提出自己的需要。若对方在压力中，先降低语速、减少结论、给出选择；若对方重结果，就给结构和下一步。先连接频道，再传递内容。', '["NLP", "亲和感", "校准", "影响力", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 84, now()),
(100085, 'NLP换框：问题行为背后常有未被满足的正向意图', '换框不是强行积极，而是寻找行为背后的功能。拖延可能在保护人免于羞耻，冷处理可能在保护人免于被淹没，控制可能在追求安全。识别正向意图后，仍要评估旧策略是否有代价，再寻找更成熟的替代方式。这样既不纵容问题行为，也不把人简单定罪。App 在回答关系和成长问题时，可先问“这个反应原本想帮你避免什么”。', '["NLP", "换框", "正向意图", "行为模式", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 85, now()),
(100086, '语言风格：功能词比大道理更透露心理状态', '语言风格资料强调，真正透露心理状态的往往不是华丽内容词，而是人称、虚词、连接词、否定词、时态等小词。一个人频繁使用“我”可能处在自我关注或压力中；大量绝对化词汇会让表达更封闭；过多否定和转折可能显示防御或矛盾。用于 App 时，不应把单个词当诊断，而是把语言线索作为理解用户情绪、关系位置和注意力焦点的辅助证据。', '["语言风格", "功能词", "心理线索", "自我觉察", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 86, now()),
(100087, '人称代词：我、你、我们会改变关系气氛', '沟通话术里，人称代词会影响关系气氛。只说“你怎么总是”容易让对方感到被审判；只说“我都怪我”容易让自己陷入低位；适度使用“我们”能提示共同面对问题，但若用“我们”掩盖个人责任，也会显得逃避。更成熟的表达是：我为自己的感受和请求负责，你为你的选择负责，我们一起决定下一步规则。', '["人称代词", "关系沟通", "责任", "表达", "语言风格"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 87, now()),
(100088, '语言同步：相似的表达节奏能增加被理解感', '语言风格研究提示，人在连接顺畅时，表达节奏、词类和关注点会自然靠近。关系沟通中，可以有意识地先使用对方熟悉的词和框架，再提出新观点。比如对方重视效率，就先谈结果和步骤；对方重视感受，就先谈体验和影响。同步不是模仿操控，而是降低理解成本。同步之后再温和引入不同意见，通常比直接反驳更容易被听见。', '["语言同步", "沟通", "亲和感", "表达节奏", "理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 88, now()),
(100089, '从绝对化语言回到具体事实', '冲突中的“总是、从不、每次、所有人都”会迅速放大威胁，让对方进入辩解。语言风格资料可用于提醒用户把绝对化改成具体事实：把“你从来不关心我”改成“这周三次我提到难受时，你都没有继续问”；把“我永远做不好”改成“这次演示有两处没有准备充分”。事实越具体，越能讨论；标签越绝对，越容易卡住。', '["绝对化语言", "事实表达", "冲突降温", "沟通", "认知"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 89, now()),
(100090, '书写能帮助整理情绪叙事', '语言与心理研究显示，把混乱经历写出来，能帮助人把情绪、事实和意义重新组织。App 可以引导用户做三段式书写：发生了什么；我当时有哪些感受和身体反应；这件事触碰了我什么需要，以及下一步我能做什么。书写不是为了美化痛苦，而是把脑内反刍转为外部文本，使人更容易看见模式、选择行动。', '["书写疗愈", "情绪整理", "反刍", "语言", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 90, now()),
(100091, '九型发展层级：同一型号也有健康和失衡差异', '《九型人格2》强调，同一人格类型不是固定表现，而会随健康水平呈现不同层级。健康状态下，类型天赋会服务于生命：1号正直、2号慈悲、3号真实高效、4号创造、5号洞察、6号勇敢、7号喜悦、8号保护、9号安定。失衡时，同一能量会扭曲成批判、索取、表演、沉溺、抽离、怀疑、逃避、控制或麻木。因此 App 使用九型时，应同时判断主型和状态，而不是看到一个行为就定型。', '["九型人格", "发展层级", "健康状态", "失衡", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 91, now()),
(100092, '九型误判：理想自我不等于真实类型', '很多人测九型时会把“我想成为的人”误认为“我真实的自动策略”。例如想显得善良而选2号，想显得强大而选8号，想显得理性而选5号。更可靠的识别方式，是看压力下最自动的防御、反复出现的恐惧和注意力焦点。真正的类型常让人有一点被看穿，而不只是感觉很喜欢。App 解读时应提示用户：问卷只是入口，动机和长期模式更重要。', '["九型人格", "误判", "理想自我", "动机", "识别方法"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 92, now()),
(100093, '九型应用：不要用类型限制人，要用类型增加选择', '九型知识容易被误用成标签：“我是6号所以我就是焦虑”“他是8号所以没法沟通”。更成熟的用法是看见自动模式，然后增加选择。类型解释了为什么某些问题反复出现，但不决定人只能这样。App 回答应避免“你就是某型所以必然如何”，而应说“如果你有这种模式，可以尝试发展相反能力”。九型的目标是自由，不是把人关进九个盒子。', '["九型人格", "标签风险", "自由", "成长", "自我超越"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 93, now()),
(100094, '九型矛盾感：人会在不同场景表现出多个类型影子', '用户常问“为什么我像好几个型号”。九型人格2的一个实用提醒是：人会在不同关系、压力和角色中呈现多个类型的影子，但核心类型仍看最深层动机和防御。一个人可以既慷慨又自私，既温和又攻击，既理性又情绪化；这些矛盾不一定说明类型混乱，而可能是侧翼、压力线、安全线、健康层级和社会角色共同作用。识别时要看长期重复的主旋律。', '["九型人格", "侧翼", "压力线", "情境", "识别方法"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 94, now()),
(100095, '九型关系建议：先看对方害怕失去什么', '九型用于关系沟通时，可以先问“这个型号最怕失去什么”。1号怕失去正确和尊严，2号怕失去被需要，3号怕失去价值和认可，4号怕失去真实自我，5号怕失去空间和资源，6号怕失去安全和支持，7号怕失去自由和可能性，8号怕失去掌控和脆弱保护，9号怕失去和谐。理解恐惧后，沟通更容易避开对方防御，也更能提出对方听得进去的请求。', '["九型人格", "关系沟通", "核心恐惧", "防御", "理解他人"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 95, now()),
(100096, '情绪亲密：亲密关系的核心是能共同承受真实情绪', '情绪亲密不是两个人永远开心，而是双方能在恐惧、羞耻、愤怒、悲伤和脆弱出现时仍保持连接。很多关系疏远不是因为没有爱，而是情绪一强就进入攻击、退缩、讲道理或转移。App 回答亲密关系问题时，可以引导用户先说“我此刻真实感到什么”，再说“我需要怎样被回应”。能被安全表达和接住的情绪，会成为关系更深的入口。', '["情绪亲密", "亲密关系", "脆弱", "安全感", "真实表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 96, now()),
(100097, '适应性情绪与非适应性情绪要分开处理', '情绪资料区分适应性和非适应性情绪。适应性恐惧提醒真实风险，适应性愤怒保护边界，适应性羞耻帮助人回到关系伦理；非适应性情绪则常来自旧创伤、过度解释或环境误判，会让人反复陷入不合比例的反应。处理时不要笼统压制情绪，而要问：这份情绪在当下是否提供有效信息？如果是，转化为行动；如果不是，先安抚身体和旧经验。', '["情绪管理", "适应性情绪", "恐惧", "愤怒", "羞耻"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 97, now()),
(100098, '羞耻感的修复：从我不好回到我做了什么', '健康羞耻能提醒人尊重边界和关系，但有毒羞耻会把具体行为变成身份否定：“我错了”变成“我这个人很糟”。用户陷入羞耻时，应先把身份和行为分开：我做了某件需要承担的事，不等于我没有价值。修复顺序是承认影响、承担责任、表达歉意、做出补偿，同时停止用自我攻击替代真实改变。', '["羞耻", "自我价值", "修复", "责任", "情绪亲密"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 98, now()),
(100099, '悲伤不是软弱，它帮助人承认失去并重新连接', '悲伤常被误解为负能量，但它的功能是帮助人承认失去、放下无法挽回的部分，并重新寻找连接。用户失恋、关系破裂或人生阶段结束时，不必急着“振作”。可以允许悲伤有时间、身体感和表达出口：哭、写下失去、讲给安全的人听、为告别做一个仪式。悲伤被看见后，人才能把爱和意义带入下一阶段。', '["悲伤", "失去", "情绪疗愈", "亲密关系", "告别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 99, now()),
(100100, '情绪表达要同时包含感受、需要和边界', '只表达情绪而没有需要，容易变成宣泄；只有边界而没有感受，容易显得冷硬；只有需要而没有边界，容易陷入讨好。情绪亲密中的成熟表达可以是：“我感到害怕和失落，因为我需要稳定回应；如果你需要空间，请告诉我多久后回来谈。”这类表达既让对方知道你内在发生了什么，也给出可协商的行动方向。', '["情绪表达", "需要", "边界", "关系沟通", "亲密"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 100, now()),
(100101, '愤怒控制：先识别身体预警，而不是等爆发后补救', '愤怒很少突然出现，身体通常会先给信号：心跳加快、肩颈绷紧、脸热、拳头握紧、呼吸变浅、声音提高。控制愤怒的第一步不是讲道理，而是建立预警清单。一旦信号出现，就先暂停、离开刺激源、延长呼气、喝水或让身体移动。越早在低强度阶段介入，越不需要在高强度爆发后道歉和修复。', '["愤怒管理", "身体信号", "暂停", "情绪调节", "自控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 101, now()),
(100102, '愤怒情境记录：找出触发点、想法和后果', '控制愤怒需要记录模式。每次愤怒后可写四项：触发事件是什么；我当时脑中冒出的解释是什么；身体和行为如何反应；结果是解决了问题还是扩大了伤害。几次记录后，用户会看见常见触发点，如被否定、等待、失控、被催促或感到不公平。看见模式后，才能提前设计替代反应，而不是每次都以为只是对方惹我。', '["愤怒管理", "情境记录", "触发点", "认知", "复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 102, now()),
(100103, '破坏性愤怒与建设性边界要区分', '愤怒本身能提供边界信息，但破坏性愤怒会通过羞辱、威胁、冷暴力或攻击来伤害关系。建设性边界则把能量转成清楚要求：“这件事我不能接受”“我们暂停十分钟再谈”“下次请提前告诉我”。App 回答用户“我一生气就伤人”时，应同时承认愤怒背后的需求，并训练非伤害性的表达方式。目标不是没有愤怒，而是不让愤怒掌舵。', '["愤怒", "边界", "关系修复", "表达", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 103, now()),
(100104, '愤怒暂停协议：离开不是逃避，回来才是关键', '冲突升温时，暂停比继续争输赢更有用。但暂停必须有协议，否则会被体验成冷暴力或抛弃。可说：“我现在太激动，继续会伤人。我需要二十分钟冷静，八点二十回来继续谈。”暂停期间不反刍、不写攻击长文，而是降身体唤醒。关键是按约定回来，哪怕只先确认还愿意谈。这样既保护关系，也训练自我控制。', '["愤怒暂停", "冲突降温", "冷静期", "关系安全", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 104, now()),
(100105, '愤怒后的修复：不要只解释动机，要承认影响', '愤怒爆发后，很多人急着解释“我不是故意的”。但对方首先需要听见影响被承认。修复顺序可以是：我刚才提高音量/说了伤人的话；这让你感到害怕或受伤；这部分我负责；下次我会在身体信号出现时暂停；现在我想听听你的感受。解释动机可以放后面，不能替代承担影响。真正的道歉要带行为改变。', '["愤怒修复", "道歉", "影响", "责任", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 105, now()),
(100106, '抑郁康复：低谷中先建立支持网络，而不是独自硬扛', '抑郁相关案例资料提醒，走出低谷很少只靠一个人的意志力。用户陷入持续无力、绝望或自责时，应优先建立支持网络：可信任的亲友、专业咨询或医疗资源、规律作息、身体活动和危机联系人。支持不是替用户解决人生，而是在其能量最低时提供外部结构。App 回答时应鼓励用户把“我必须自己扛”改成“我可以借助系统恢复”。', '["抑郁", "支持系统", "康复", "心理健康", "低谷"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 106, now()),
(100107, '抑郁中的小行动：先恢复生活节律，再追求动力', '抑郁会让人等待“有动力再行动”，但恢复常常相反：先用极小行动恢复节律，再让动力慢慢回来。可从睡眠、饮食、晒光、洗漱、散步、联系一个安全的人开始，每天只记录是否完成，不用要求情绪立刻变好。小行动的作用不是证明自己强大，而是给大脑和身体重新建立可预测的安全感。', '["抑郁", "行为激活", "生活节律", "小行动", "恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 107, now()),
(100108, '双相和重度低谷：App 不做诊断，但要识别求助信号', '资料涉及抑郁和双相困境时，App 应保持非诊断原则：不根据聊天直接下诊断，但要识别风险信号。若用户出现持续失眠或嗜睡、明显功能下降、极端绝望、自伤念头、冲动高涨或情绪大幅波动，应建议尽快联系专业医生、咨询师或身边可信任的人。知识库给出的作用是陪伴、稳定和转介，不替代临床评估。', '["抑郁", "双相", "风险识别", "专业求助", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 108, now()),
(100109, '康复叙事：真实故事能给低谷者带来可恢复的证据', '抑郁康复案例的价值，不在于要求用户照搬别人的路径，而在于提供“人可以从深渊回来”的证据。App 回答低谷用户时，可以把康复描述为多因素过程：承认病痛、求助、调整环境、重建节律、学习情绪技能、逐步恢复关系和意义。避免把成功故事变成压力，而要把它变成希望：你不需要立刻好起来，只需要开始被支持。', '["康复故事", "希望感", "抑郁", "支持", "意义"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 109, now()),
(100110, '言语行为：一句话不仅传递信息，也在完成行动', '言语行为理论适合提升 App 的沟通建议：很多话不是单纯描述，而是在做事。道歉是在承担，承诺是在建立未来义务，请求是在邀请合作，指责是在分配责任，命令是在施加权力。因此沟通问题不能只看字面内容，还要看这句话完成了什么关系动作。用户想修复关系时，应选择能完成连接、澄清、承担和请求的语言，而不是无意识地完成攻击。', '["言语行为", "沟通", "道歉", "承诺", "关系动作"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 110, now()),
(100111, '承诺表达：说“我会”时要明确条件、时间和行动', '承诺是一种言语行为，会改变关系中的期待。模糊承诺如“我以后会改”容易让对方再次失望；有效承诺要包含具体行动、时间、条件和复盘方式。例如“下次争吵时我会先暂停十分钟，晚上九点回来继续谈”。App 给用户生成道歉或修复话术时，应避免空泛保证，改成可观察的承诺。', '["承诺", "言语行为", "关系修复", "道歉", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 111, now()),
(100112, '请求和要求：真正的请求允许对方回应和协商', '从言语行为角度看，请求、要求和命令会创造不同关系位置。请求承认对方有选择，要求带有更强压力，命令则假设权力差。亲密关系中很多“你能不能”其实是包装过的命令，难怪引发防御。更成熟的表达是说明需要、提出具体请求，并允许对方说明难处：“我希望今晚能聊十分钟，你现在方便吗？”', '["请求", "要求", "边界", "关系沟通", "协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 112, now()),
(100113, '亲子沟通：孩子行为背后常有能力缺口和情绪需求', '亲子资料提醒，孩子的问题行为不一定是故意作对，常常是情绪调节、表达能力、规则理解或连接需求不足。家长若只用批评和惩罚，短期可能压住行为，长期会削弱信任。更有效的是先翻译行为：孩子在保护什么、害怕什么、还不会什么？然后同时给连接和边界。App 回答亲子问题时，应避免把孩子标签化为懒、坏或不懂事。', '["亲子沟通", "儿童情绪", "行为背后", "连接", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 113, now()),
(100114, '亲子冲突：先处理情绪，再处理道理和规则', '孩子情绪上来时，大脑很难接收长篇道理。亲子冲突的顺序应是：先让孩子知道自己的感受被看见，再明确规则，再给选择和后果。例如“你很想继续玩，所以被叫停很生气；但睡觉时间到了。你可以现在收玩具，或我陪你收两分钟。”先连接不是纵容，而是让孩子从对抗状态回到可合作状态。', '["亲子冲突", "情绪处理", "规则", "选择", "合作"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 114, now()),
(100115, '家长权威：稳定、一致和尊重比吼叫更有力量', '有效家长权威不是声音大，而是规则稳定、边界一致、态度尊重。孩子需要知道什么可以协商，什么不能越界，以及越界后会发生什么。若家长情绪化地时松时紧，孩子会不断测试边界。App 可建议家长提前约定少量关键规则，用简短语言重复，并在执行时减少羞辱。温和和坚定可以同时存在。', '["亲子教育", "权威", "规则", "边界", "稳定"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 115, now()),
(100116, '培养孩子自我价值：多肯定努力、选择和品格', '亲子关系中，孩子不只需要被评价成绩，也需要确认自己作为人的价值。家长可以多肯定具体努力、选择、品格和成长：“你刚才虽然生气，但还是回来谈了”“你愿意尝试新方法”。这类反馈比泛泛说“你真棒”更能建立内在自我价值。App 回答亲子问题时，可把关注点从控制孩子转向发展孩子能力。', '["亲子关系", "自我价值", "肯定", "成长", "能力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 116, now()),
(100117, '情绪是一种语言：每种情绪都在传递信息', '《情绪的语言》可提炼为核心原则：情绪不是需要消灭的噪音，而是身体和心理的语言。恐惧提示风险，愤怒提示边界，悲伤提示失去，羞耻提示关系伦理，嫉妒提示渴望和比较。App 回答情绪问题时，不应只让用户“别想太多”，而要帮助翻译：这份情绪想告诉我什么？它指向什么需要？我能采取什么成熟行动？', '["情绪语言", "情绪管理", "需要", "边界", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 117, now()),
(100118, '恐惧的功能：不是阻止行动，而是要求检查安全', '恐惧的作用是提示风险和未知。健康恐惧会让人收集信息、设定边界、做好准备；失衡恐惧则会让人冻结、逃避或过度想象。用户害怕时，可以先感谢恐惧在保护自己，再问：我需要确认什么事实？需要什么支持？最小安全行动是什么？这样恐惧从敌人变成风险评估系统。', '["恐惧", "安全", "风险评估", "情绪语言", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 118, now()),
(100119, '嫉妒的信息：看见自己真正渴望什么', '嫉妒常被羞耻化，但它也能暴露真实渴望。看到别人拥有关系、成就、自由或关注时，用户可以问：我羡慕的到底是什么？这代表我也想发展哪种能力或生活？成熟处理嫉妒，不是贬低对方，也不是贬低自己，而是把比较转化为愿望和行动。嫉妒被翻译后，可能成为自我探索的入口。', '["嫉妒", "渴望", "比较", "情绪语言", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 119, now()),
(100120, '悲痛需要仪式和见证，而不是被催促放下', '悲痛是失去之后的深层情绪，它需要时间、仪式和见证。如果一个人被催促“别难过了”，悲痛可能转入麻木或长期反刍。App 支持悲痛用户时，可引导其说出失去了什么、这份关系或阶段曾代表什么、想如何纪念和告别。放下不是遗忘，而是让爱和意义找到新的位置。', '["悲痛", "失去", "仪式", "情绪疗愈", "告别"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 120, now()),
(100121, '简快疗法：改变不一定要长期分析全部过去', 'NLP 简快心理疗法强调，改变可以从当前资源、目标状态和可重复的新反应开始，而不一定要把所有过去细节分析完。App 可把它转化为实用问法：你想从现在的困境走向什么状态？你过去哪怕短暂体验过这种状态吗？当时有什么资源？下一次触发时，你能做哪个不同动作？这种取向适合把用户从反复解释带回行动练习。', '["NLP", "简快疗法", "资源", "目标状态", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 121, now()),
(100122, '资源取向：先找到用户已经拥有的例外经验', '当用户说“我从来做不到”时，简快疗法会寻找例外：有没有一次稍微好一点？有没有某个人、场景或状态下你能做到一点？例外不是否认问题，而是证明系统中已有资源。App 可以追问例外发生的条件，然后把它复制到新情境。比起只分析失败，寻找例外更能激活自我效能。', '["资源取向", "例外经验", "自我效能", "NLP", "改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 122, now()),
(100123, '次感元调整：改变内在画面会影响情绪强度', 'NLP 资料中常用内在表征理解情绪：同一记忆如果画面很大、很近、很亮、声音很强，情绪会更强；如果把画面拉远、变小、变暗，身体反应可能下降。App 可把这作为非临床的自我调节练习：当某个画面反复刺激你时，试着在想象中调节距离、大小和声音，同时回到呼吸和当下环境。', '["NLP", "次感元", "情绪调节", "想象", "自助练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 123, now()),
(100124, '信念松动：把绝对句改成可更新假设', '很多痛苦来自僵硬信念，如“我永远不被爱”“我一定会失败”。简快取向会把绝对信念改成可检验假设：在什么情境下它不完全成立？有没有反例？如果它只是旧保护策略，我现在能否更新它？App 回答时可帮助用户从身份化结论转向可调整信念，让改变有入口。', '["信念", "NLP", "认知调整", "绝对化", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 124, now()),
(100125, '沟通分析：关系互动中常有父母、成人、儿童三种自我状态', '沟通分析资料可转化为 App 的互动识别工具：人在交流时可能从父母自我状态说话，表现为批评、教导、保护；从成人自我状态说话，表现为事实、选择和协商；从儿童自我状态说话，表现为反抗、讨好、委屈或玩耍。冲突升级时，常是双方从成人状态滑入父母对儿童、儿童对父母。修复的关键是把话语拉回成人状态：讲事实、说感受、提请求、谈后果。', '["沟通分析", "自我状态", "成人状态", "关系沟通", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 125, now()),
(100126, '心理游戏：反复冲突背后常有熟悉但痛苦的脚本', '伯恩的人际游戏理论提醒，很多关系冲突表面在讨论事情，实际在重复固定脚本：受害者等待被拯救，拯救者过度负责后委屈，迫害者用指责获得控制。游戏的结局通常很熟悉：双方都证明了自己的旧信念。App 可帮助用户识别：这场争吵是不是又走到同一个结局？我正在扮演哪个角色？我能否退出脚本，改用成人状态表达需要和边界？', '["心理游戏", "沟通分析", "戏剧三角", "关系模式", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 126, now()),
(100127, '退出人际游戏：不接角色，回到真实请求', '退出心理游戏不是赢过对方，而是不再接下被分配的角色。对方指责时，不进入反击；对方求救但拒绝负责时，不急着拯救；自己想委屈控诉时，先问真正请求是什么。可用句式：“我愿意谈具体问题，但不接受互相羞辱。”“你希望我具体怎么帮？哪一步由你自己做？”把隐藏交易改成明说请求，游戏就失去动力。', '["人际游戏", "退出脚本", "真实请求", "边界", "沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 127, now()),
(100128, '亲密与自主：好的关系不是玩游戏，而是直接表达', '沟通分析的成长方向是从心理游戏走向自主和亲密。自主意味着能觉察自己的脚本，而不是自动重复；亲密意味着能直接表达真实感受和需要，而不是用拐弯、测试、讽刺或冷战获取回应。App 在关系咨询中可引导用户把“你猜我怎么了”换成“我现在需要被听见”，把测试对方换成清楚请求。', '["亲密关系", "自主", "沟通分析", "真实表达", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 128, now()),
(100129, '儿童心理：不要把成人逻辑直接套到孩子身上', '儿童心理学提醒，孩子不是缩小版成人。不同发展阶段的注意力、情绪调节、语言表达、因果理解和自我控制能力都不同。家长如果用成人标准要求孩子“马上懂事”，容易把能力不足误解成故意作对。App 回答亲子问题时，应先判断孩子可能处于什么发展阶段，再给出符合年龄的规则、选择和练习。', '["儿童心理", "发展阶段", "亲子教育", "情绪调节", "能力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 129, now()),
(100130, '儿童问题行为：先看发展任务，再看教育方法', '孩子的退缩、攻击、撒谎、拖延或哭闹，可能对应不同发展任务：争取自主、寻求连接、表达挫败、测试边界或回避羞耻。处理时先问这个行为在孩子的发展中服务什么，而不是直接贴坏习惯标签。家长需要同时提供安全关系和稳定边界，让孩子在可承受的范围里学习表达、等待、协商和承担后果。', '["儿童行为", "亲子关系", "发展任务", "边界", "情绪"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 130, now()),
(100131, '家长焦虑会进入孩子系统', '儿童心理资料强调，家长的焦虑、冲突和不稳定会影响孩子的安全感。孩子很多时候不是听家长说什么，而是感受家庭气氛。若父母长期紧张、指责或忽冷忽热，孩子可能用问题行为表达系统压力。App 可建议家长先调节自身情绪，再处理孩子行为：降低音量、明确规则、减少羞辱、保持可预测的回应。', '["家长焦虑", "儿童安全感", "家庭系统", "亲子沟通", "情绪"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 131, now()),
(100132, '拖延循环：短期逃避会强化长期焦虑', '拖延症资料指出，拖延的即时奖励是缓解不舒服：不用面对失败、评价、无聊或复杂任务。但短期舒服会带来长期焦虑，下一次更想逃。破循环的关键不是骂自己，而是识别“我正在用逃避换短暂轻松”。可以把任务拆到五分钟，先开始而不追求完成，并在开始后记录焦虑是否下降。行动会削弱拖延带来的假奖励。', '["拖延", "逃避", "焦虑", "行动", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 132, now()),
(100133, '拖延背后的完美主义：宁可不做也不愿做得不够好', '很多拖延来自完美主义：任务一旦开始，就可能暴露不足，所以大脑选择延后。用户可练习“低质量初稿”策略：先允许做出粗糙版本，再修改。把目标从一次做好改成先产生材料；把评价从结果改成是否开始。对完美型用户尤其重要：完成一个可改进的版本，比等待理想状态更接近真实成长。', '["拖延", "完美主义", "初稿", "行动", "自我接纳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 133, now()),
(100134, '反拖延计划：明确下一步、开始时间和障碍预案', '有效反拖延计划要具体到下一步，而不是写“我要努力”。格式可以是：在什么时间、什么地点、做哪一个动作、做多久、如果遇到阻碍怎么办。例如“晚饭后八点，在书桌前打开文档写标题十分钟；如果想刷手机，就把手机放到客厅”。计划越可执行，越不依赖临时情绪。', '["反拖延", "计划", "执行意图", "障碍预案", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 134, now()),
(100135, '人际沟通：先听懂，再回应，而不是准备反驳', '人际沟通技巧资料强调，倾听不是沉默等待自己发言，而是主动理解对方的事实、感受和需要。有效回应可以先复述：“我听到你在意的是……你感到……对吗？”这会降低防御，让对方感到被看见。App 在生成沟通建议时，应先给倾听句，再给表达句，避免用户一上来就输出立场。', '["人际沟通", "倾听", "复述", "理解", "关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 135, now()),
(100136, '表达感受时少用指责，多用我信息', '“你让我很痛苦”容易让对方防御；“我在这件事里感到难过和不安”更容易被听见。我信息不是只谈自己，而是把事实、感受、影响和请求组合起来：当发生 X 时，我感到 Y，因为它影响 Z；我希望下次 A。这样既表达真实，又减少攻击。App 可把用户的指责句自动改写为我信息。', '["我信息", "感受表达", "人际沟通", "冲突降温", "请求"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 136, now()),
(100137, '反馈技巧：具体行为比人格评价更有建设性', '给反馈时，评价人格会引发羞耻和抵抗；描述具体行为更可能带来改变。把“你不负责任”改成“这次约定的材料周三没有提交，导致项目延迟一天”。再说明影响、询问原因、共同制定下一步。无论亲密关系还是职场，反馈都应落在可观察行为上，而不是给人贴稳定标签。', '["反馈", "行为描述", "职场沟通", "关系沟通", "建设性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 137, now()),
(100138, '界限沟通：温和语气加清楚底线', '很多人以为有边界就必须强硬，其实边界可以温和但清楚。有效边界包含三部分：我理解你的处境；我能做的范围是；超出范围我不会做。比如“我知道你很急，我今晚可以帮你看十分钟，但不能替你完成全部。”温和让关系保持连接，清楚让对方知道规则。边界模糊才更容易积怨和爆发。', '["边界", "人际沟通", "底线", "温和坚定", "关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 138, now()),
(100139, '人格模式：先观察长期重复，而不是给人贴诊断', '人格障碍相关资料适合给 App 提供非诊断性框架：不要因为一次冲突就说某人是某种人格障碍，而要观察长期、跨场景、反复出现的模式，以及它是否造成关系、工作和自我功能受损。App 回答时应聚焦行为模式、边界和求助建议，而不是替用户给自己或他人下临床诊断。这样既能保护用户，也避免把复杂关系简化成标签。', '["人格模式", "非诊断", "关系风险", "边界", "心理健康"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 139, now()),
(100140, '人格障碍的认知视角：核心信念会驱动反复行为', '认知治疗资料强调，很多持久的人格模式背后有核心信念，例如“别人会伤害我”“我必须控制才安全”“我不值得被爱”“如果被拒绝就完了”。这些信念会让人选择性解读关系，并反复触发防御行为。App 可帮助用户把冲突从“我就是这样”拆成“我在什么信念下自动反应”，再寻找更平衡的新信念和行为实验。', '["认知治疗", "核心信念", "人格模式", "行为实验", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 140, now()),
(100141, '边缘化互动：强烈情绪下先稳定，再讨论关系结论', '人格障碍治疗资料中反复强调，强烈情绪会让关系判断变得极端：全好或全坏、亲密或抛弃、信任或背叛。App 不做诊断，但可给出稳定策略：当情绪强度过高时，先暂停关系结论，回到身体、事实和当下安全；等情绪降到可对话范围，再讨论事件、感受和请求。不要在情绪顶点做分手、拉黑、报复等重大决定。', '["强烈情绪", "关系判断", "稳定", "人格模式", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 141, now()),
(100142, '回避和依赖模式：一个怕靠近，一个怕分离', '人格相关资料可帮助理解两类关系困难：回避模式把亲密体验为压力和被吞没，因此倾向退缩；依赖模式把分离体验为危险，因此倾向黏附、确认和难以独立。App 回答关系问题时，可把表层行为翻译成安全需求，同时提醒用户发展相反能力：回避者练习可预期回应，依赖者练习自我安抚和独立选择。', '["回避", "依赖", "亲密关系", "安全感", "人格模式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 142, now()),
(100143, '人格改变：不是消灭自己，而是增加反应选择', '认知行为疗法看重具体练习：识别触发情境、自动想法、情绪强度、行为后果，再设计新反应。人格改变不是否定整个人，而是让原本单一的防御策略多出选择。用户若总是攻击、讨好、退缩或控制，可以先记录触发点，再练习一个更小的新动作：停顿、提问、表达需要、设边界或寻求支持。', '["人格改变", "认知行为", "触发点", "新反应", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 143, now()),
(100144, '需求层次：先满足基础安全，再谈自我实现', '动机与人格资料提醒，人的成长需要基础条件。若用户长期缺睡、缺安全、缺支持、经济或关系高度不稳，却要求自己立刻自我实现，容易变成自责。App 可先判断问题处在哪一层需求：生理、安全、归属、尊重还是自我实现。越底层的需求越需要具体支持和稳定结构；越高层的需求越适合谈意义、创造和潜能。', '["需求层次", "马斯洛", "安全感", "自我实现", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 144, now()),
(100145, '自我实现：不是完美成功，而是更真实地成为自己', '马斯洛的自我实现不是外界眼中的完美人生，而是人的潜能、价值和创造力逐渐被活出来。它通常伴随更真实的自我接纳、更少迎合、更能投入当下、更愿意服务超出小我的价值。App 回答人生意义问题时，可引导用户从“我应该成为什么样”转向“什么让我更真实、更有生命力、更愿意贡献”。', '["自我实现", "真实自我", "意义感", "潜能", "成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 145, now()),
(100146, '高峰体验：短暂的完整感可以成为人生方向线索', '动机与人格中提到的高峰体验，可用于帮助用户回忆生命中短暂但强烈的完整、清明、感动或创造时刻。这些时刻不一定频繁，却能提示人的核心价值和潜能方向。App 可引导用户回忆：什么时候我感到特别真实、自由、宁静或被点亮？那里可能藏着比外部评价更可靠的成长线索。', '["高峰体验", "价值澄清", "生命力", "自我实现", "意义"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 146, now()),
(100147, '缺失性需要与成长性需要要区分', '缺失性需要来自匮乏，如缺安全、缺爱、缺尊重；成长性需要来自生命扩展，如创造、学习、贡献和理解。两者都重要，但处理方式不同。用户若在匮乏中追求成长，可能越努力越焦虑；若基础需求已相对稳定，却仍只追求补偿，也会感到空。App 可帮助用户判断：此刻我是在补缺口，还是在响应成长召唤？', '["缺失性需要", "成长性需要", "动机", "自我觉察", "人生阶段"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 147, now()),
(100148, '走出抑郁：抑郁会影响动机、注意力、睡眠和身体', '抑郁不仅是心情不好，它会影响动机、注意力、精力、睡眠、食欲、身体感和对快乐的体验。用户在抑郁状态下做不到平时能做的事，不应简单解释为懒或脆弱。App 回答时应把抑郁视为身心系统整体低能量状态，建议从睡眠、饮食、活动、支持和专业求助等多点恢复，而不是只靠一句“想开点”。', '["抑郁", "身心状态", "动机", "睡眠", "恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 148, now()),
(100149, '抑郁中的自责会加重抑郁循环', '抑郁状态下，人容易把精力下降、兴趣丧失、拖延和社交退缩解释成“我没用”。这种自责会进一步消耗能量，形成恶性循环。更有效的是把症状和身份分开：我现在处在低能量状态，不等于我没有价值。先减少自责，再做微小行动，才能逐步恢复掌控感。App 应帮助用户识别自责语言并改写为支持性语言。', '["抑郁", "自责", "自我价值", "支持性语言", "恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 149, now()),
(100150, '抑郁恢复需要活动计划，而不是等待心情变好', '走出抑郁的行为思路是：先安排可完成的小活动，再等待情绪慢慢回应。活动计划不必宏大，可从起床、洗漱、晒太阳、五分钟走路、整理一个角落开始。关键是可执行、可记录、可重复。用户若说“我没有动力”，App 可以回应：先不追求动力，先做一个小到可以完成的动作，让身体重新接触生活。', '["抑郁恢复", "活动计划", "行为激活", "小行动", "生活节律"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 150, now()),
(100151, '儿童绘画：画面是儿童表达情绪和经验的一种语言', '儿童绘画与心理治疗资料提醒，孩子常常无法直接用语言说出复杂感受，但会通过画面、颜色、大小、位置、重复主题和讲述方式表达经验。App 在亲子问题中可建议家长不要急着解释画得好坏，而是温和询问：“这是谁？发生了什么？你画这里时想到什么？”重点是让孩子讲述，而不是成人单方面解读。', '["儿童绘画", "儿童心理", "情绪表达", "亲子沟通", "治疗"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 151, now()),
(100152, '解读儿童画：不能只凭单个符号下结论', '儿童画不能机械解码，例如黑色就代表抑郁、画怪物就代表创伤。更可靠的方式是结合孩子年龄、发展水平、生活事件、绘画过程和孩子自己的讲述。App 若涉及儿童画，应避免下诊断，只提供观察方向：主题是否反复出现，孩子讲述时情绪如何，画面与近期事件是否相关，是否需要专业儿童心理支持。', '["儿童画", "非诊断", "观察", "儿童心理", "亲子"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 152, now()),
(100153, '儿童创伤表达：重复主题可能是在寻求理解和整合', '在儿童绘画治疗中，反复出现的危险、分离、攻击、受伤或孤独主题，可能是在尝试表达尚未被整合的经验。家长不应立刻责备“别画这些”，也不应过度惊吓，而要提供安全的讲述空间。可说：“你愿意讲讲这幅画里的故事吗？”如果孩子持续痛苦、退缩或行为明显变化，应考虑专业评估和支持。', '["儿童创伤", "绘画表达", "安全讲述", "亲子支持", "心理治疗"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 153, now()),
(100154, 'NLP过滤机制：误解常来自删减、扭曲与类推', '人在沟通中并不是原样接收现实，而会自动经过三类过滤：删减让人只注意部分信息；扭曲让事实被解释成批评、威胁或否定；类推会把一次经验扩展成“总是、从不、一定”。App 处理冲突时，可引导用户先做三问：我漏掉了哪些信息？还有哪些同样合理的解释？有没有反例说明这不是普遍规律？这样能把“对方就是针对我”降级为“我现在有一个解释，需要验证”。', '["NLP", "沟通模型", "删减", "扭曲", "类推", "误解修复", "提问"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 154, now()),
(100155, 'NLP表象系统：用对方能接收的感官通道组织语言', '不同人理解信息时偏好的通道不同：有人重“看见画面”，有人重“听到逻辑”，有人重“感觉是否踏实”，也有人依赖内在自我对话。沟通时不要只用自己习惯的表达方式，而要把关键信息翻译成多通道：画面是什么、听起来怎么说、身体或情绪感受如何、下一步怎么做。对方常用“看起来、听起来、感觉、我想”等词，可作为选择表达入口的线索。', '["NLP", "表象系统", "共同语言", "亲和感", "沟通表达", "感官通道"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 155, now()),
(100156, '小词汇审计：但是、试着、不要会悄悄改变行动暗示', '微小词汇会改变听者接收到的关系和行动暗示。“但是”容易否定前半句，可改成“同时/而且”；“试着”暗示困难和不确定，可改为具体承诺；“不要担心”会先唤起担心，可改成“先放松、先做第一步”；“这是很难的”把困难绝对化，可改成“我还没找到容易的方法”。App 生成沟通话术时，可加入小词汇审计，减少无意中的否定、无力和反向暗示。', '["语言风格", "NLP", "小词汇", "暗示", "沟通润色", "行动指令"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 156, now()),
(100157, '元程序沟通：先识别对方的动机过滤器，再选择说服入口', '影响他人不是把同一套理由重复给所有人，而是识别对方的“过滤器”：TA 更关注获得好处还是避免风险？喜欢选择空间还是固定程序？依据内部标准还是外部认可？更关心人、地点、活动、时间还是信息？同一个建议，对风险型用户要说明安全和代价，对机会型用户要说明收益和可能；对程序型用户给步骤，对选择型用户给选项。匹配元程序能降低理解阻力，但不能替代真实尊重。', '["NLP", "元程序", "影响力", "说服", "价值观", "职场沟通", "动机"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 157, now()),
(100158, '决策策略：把一次好决定拆成可复用的内在流程', '所谓策略，可以理解为一个人达成某个结果时反复使用的内在流程。面对选择困难时，不必只问“哪个更好”，可以回忆一次自己很满意的决定：当时先看见什么、听见什么、比较了哪些标准、想象了什么后果、身体如何确认、最后如何行动。把成功决策拆成步骤后，可形成个人模板；理解他人的决策策略，也有助于销售、谈判和关系协商。', '["NLP", "决策策略", "模拟卓越", "自我效能", "选择困难", "行为复制"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 158, now()),
(100159, '表达性写作的四个语言信号：情绪、意义与视角切换', '有帮助的书写不是单纯宣泄，而是把经历组织成可理解的故事。可关注四个信号：适度承认负面情绪，而非压住；出现积极情绪或希望线索；因果、理解、意义等认知词逐渐增加；人称代词能在“我、他人、我们”之间切换。App 可把书写提示设计成：发生了什么、我有什么感受、别人可能经历了什么、这件事说明了什么、下一步我能做什么。视角弹性越高，越不容易困在单一受害叙事里。', '["语言风格", "表达性写作", "书写疗愈", "视角切换", "情绪整理", "LIWC"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 159, now()),
(100160, '言语行为适切条件：承诺、道歉和命令都要满足关系规则', '一句话是否有效，不只看字面是否好听，还要看它是否满足适切条件：说话者是否有资格这样说，听者是否能理解，内容是否具体，意图是否真诚，后续义务是否清楚。空泛的“我以后会改”不是好承诺；没有承担影响的“对不起”也难以完成修复。App 生成承诺、道歉、请求话术时，应检查：具体行动、时间条件、能力边界、责任承担和复盘方式是否齐全。', '["言语行为", "承诺", "道歉", "请求", "关系规则", "沟通质量"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 160, now()),
(100161, '制度性事实：语言能创造责任、身份和共同规则', '有些事实不是自然发生的，而是由共同规则承认后才成立：承诺、任命、约定、道歉、家庭协议都属于这类语言创造的关系事实。两个人说“我们约好了”，只有在双方都理解条款、承认规则、知道后果时才真正有约束力。App 可把关系协商从口头情绪升级为共同规则：谁参与、约定什么、何时执行、如何检查、违反后如何处理。', '["言语行为", "制度性事实", "规则", "责任", "家庭协议", "关系协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 161, now()),
(100162, '太空时间：亲子危机时先开辟无追责的连接窗口', '当亲子关系已经出现明显隔膜时，可预先约定“太空时间”：在这段时间里暂停算旧账、讲道理、谈判和追责，只表达关怀、支持、真实感受和连接需求。它最好在平时心情好时建立规则，危机时双方都可以提出启动，一般不少于 30 分钟。关键不是放弃规则，而是先防止关系断线；家长若继续批判、否定、居高临下，这个技巧会失效。', '["亲子沟通", "太空时间", "关系修复", "情绪安全", "家庭冲突", "连接"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 162, now()),
(100163, '家中规则合约：少量、明确、可复述，规则才有教育力', '孩子不守规则，常不是故意挑战，而是规则太多、太模糊、没有解释清楚，或家长自己执行不一致。有效规则应少量优先，可先限制在七条以内；用具体行为替代抽象要求，如“晚上 9 点前完成作业”比“早点做完”更清楚；让孩子复述规则，确认理解；家长也要遵守相同规则或解释例外。规则越清楚，惩罚越少；爱和规则需要同时存在。', '["亲子教育", "家庭规则", "边界", "一致性", "规则合约", "温和坚定"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 163, now()),
(100164, '家庭会议五步骤：把家庭问题从互相责怪变成共同解决', '家庭问题反复出现时，可用会议流程替代临场吵架：第一，用正面、简短、无责怪的语言确定问题；第二，先收集多个方案，不急着批评；第三，讨论每个方案的可行性和每个人的感受，选出都能接受的方案；第四，分配行动和支持方式；第五，约定复盘时间，检查满意度。家庭会议应在情绪平稳时练习，它不削弱家长权威，反而训练孩子的问题解决能力。', '["家庭会议", "亲子沟通", "共同解决问题", "家庭系统", "冲突修复", "协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 164, now()),
(100165, '检定语言模式：从表层话语追问出深层限制', '用户说出的只是表层结构，背后常有删减、模糊和限制性信念。比如“我希望会变好”可能隐藏无力感，“我应该”可能隐藏外部压力，“我不能”可能缺少具体障碍说明。App 不宜急着给建议，而应先检定：具体是谁、什么情境、怎么知道、什么阻止了你、有没有例外、你真正选择什么？把“希望、应该、不能”转成“我选择、我会、我能先做哪一步”，能恢复用户的行动感。', '["NLP", "检定语言模式", "深层结构", "提问", "信念松动", "沟通澄清"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 165, now()),
(100166, '添增力量：先找出问题行为提供了什么力量', '一些不良行为并不只是“坏习惯”，也可能在临时提供力量：愤怒给人支撑，成瘾给人镇定，暴食给人安全感，控制给人掌控感。若只要求停止，用户会失去原本借来的力量。更好的顺序是：识别行为满足的力量需求；寻找更低代价的替代资源；调用过去成功经验、榜样角色或新的支持性信念。改变不是拿走拐杖，而是先让人重新站稳。', '["NLP简快疗法", "资源取向", "自我价值", "问题行为", "正向功能", "行为替代"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 166, now()),
(100167, '倾听障碍清单：识别自己是在听，还是在准备反应', '很多“我在听”其实是假倾听：对比自己、猜测对方意图、在脑中演练反驳、只听想听的部分、急着评判、好为人师、争辩挖苦、转移话题或一味讨好。App 可在冲突建议中先做倾听检查：我能否复述对方事实？我是否听见了情绪？我是否已经在准备反击？在回应前先复述并确认，能显著降低防御。', '["人际沟通", "倾听障碍", "主动倾听", "共情", "冲突降温", "复述"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 167, now()),
(100168, '弦外之音：声调、语速和重音会泄露真实关系态度', '话语的伤害不总在字面，常在辅助语言里：音高、语速、音量、停顿、重音和语调会传递自信、轻蔑、不耐烦、犹豫或优越感。内容上说“我当然支持你”，如果重音和语气带着讽刺，听者接收到的可能是否定。App 生成沟通脚本时，除了文字，还应提示语气：慢一点、低一点、停顿确认、避免反讽重音；同时提醒用户检查自己的真实目的是否与表达一致。', '["人际沟通", "辅助语言", "弦外之音", "语气", "非语言沟通", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 168, now()),
(100169, '人格理解：同一个人可以被多个流派同时照亮', '人格心理学不只提供一种解释，而是用多镜头理解人：精神分析关注无意识、防御和早期经验；特质流派关注稳定差异；生物学流派关注遗传、气质和脑机制；人本主义关注价值、成长和真实自我；行为主义和社会学习关注环境、强化和观察学习；认知流派关注图式、解释和自我调节。App 回答人格问题时，不宜把用户归入单一标签，而应根据问题选择镜头：这是关系脚本、长期特质、情境学习、身体反应，还是信念解释在起作用？', '["人格心理学", "多流派", "特质", "认知", "人本主义", "行为学习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 169, now()),
(100170, '大五人格：用于描述倾向，不用于决定命运', '大五人格可以帮助用户描述自己在开放性、尽责性、外向性、宜人性和神经质等维度上的相对倾向，但它不是命运判决。高神经质不等于注定痛苦，低外向不等于社交失败；特质只是“更容易怎样反应”的概率，不等于“只能怎样生活”。App 使用人格维度时，应把结论转化为策略：高敏感者设计恢复空间，低尽责者使用外部结构，高外向者注意深度连接，低宜人者练习表达关心。', '["大五人格", "特质", "自我理解", "成长策略", "非标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 170, now()),
(100171, '特质与情境：解释行为要同时看人和场景', '人格讨论常陷入两种极端：一种认为行为全由性格决定，另一种认为人只是被环境推着走。更实用的理解是，行为来自特质与情境的互动：同一个谨慎的人在安全关系中会更开放，同一个外向的人在高风险场合也会沉默。App 分析用户或伴侣行为时，应追问：这是长期稳定倾向，还是某个场景触发？若换时间、关系、压力水平和奖惩环境，行为会不会变化？', '["特质情境", "行为解释", "人格", "关系分析", "情境触发"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 171, now()),
(100172, '自我效能感：改变从“我能做一点”开始', '社会认知理论强调，人对自己能否完成行动的判断，会影响是否开始、坚持多久以及遇到挫折后如何恢复。自我效能感不是空喊自信，而是来自可重复的小成功、榜样示范、他人支持和身体状态改善。App 处理拖延、焦虑或关系修复时，可把目标缩小到一个可完成动作，并记录成功证据；当用户说“我不行”，应帮助改写成“我现在能先完成哪一小步”。', '["自我效能", "社会认知", "小成功", "行为改变", "自我调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 172, now()),
(100173, '自我图式：人会用熟悉的自我故事筛选信息', '认知流派提醒，人不是被事件本身直接决定，而是会通过自我图式解释事件。若用户带着“我不被喜欢”的图式，普通延迟回复也可能被理解为拒绝；若带着“我必须完美”的图式，小失误也会变成自我否定。App 可引导用户把自我故事拿出来检验：我现在用的是什么标签？它让我忽略了哪些证据？有没有一个更宽的自我描述能容纳缺点、努力和变化？', '["自我图式", "认知流派", "自我故事", "关系误读", "信念检验"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 173, now()),
(100174, '主体间性：痛苦常在关系场中形成，也要在关系中被理解', '主体间性心理治疗把来访者和咨询师看作共同构成的关系系统。人的感受并非孤立存在，而是在特定关系、文化、历史和互动方式中被组织出来。App 回答关系创伤、亲密恐惧或咨询相关问题时，可避免把痛苦完全归因于个人缺陷，而是帮助用户看见：我在什么关系场里形成了这种反应？当前互动如何重新激活旧经验？新的关系经验如何支持我重新组织自我感？', '["主体间性", "关系系统", "心理治疗", "经验组织", "关系创伤"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 174, now()),
(100175, '情感协调：先让对方感到被理解，再推动改变', '主体间取向强调，情感协调不是简单复述，而是治疗师或倾听者努力贴近对方当下主观体验，并把理解以可接收的方式反馈出来。很多人并不缺道理，而是缺“我的感受被准确看见”的经验。App 生成安慰或咨询式回应时，应先命名可能的感受、承认其处境意义，再进入建议；过早分析、纠正或教育，会让对方更孤独。', '["情感协调", "共情", "倾听", "关系修复", "心理咨询"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 175, now()),
(100176, '共情内省式倾听：理解对方的内在逻辑，而不是抢着解释', '共情内省式倾听要求倾听者暂时放慢自己的理论、评判和解决冲动，进入对方经验内部，理解其感受怎样在对方世界里成立。对 App 来说，这意味着先问“在你的处境里，这为什么会这么痛？”而不是先问“你为什么不换个想法？”当用户情绪强烈时，优先输出理解、澄清和陪伴；当其稳定后，再提供解释、练习和行动建议。', '["共情内省", "倾听模式", "心理咨询", "情绪支持", "理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 176, now()),
(100177, '治疗关系修复：断裂本身也可以成为新的经验', '关系治疗中难免出现误解、失望、距离或冲突。主体间视角不把这些断裂只看作失败，而是把它们视为共同理解旧模式和创造新经验的机会。App 在关系修复建议中可引导用户：发生了什么断裂？各自怎样理解？它触发了什么旧感受？现在能否用更安全、更直接的方式谈论？修复不是证明谁对谁错，而是让关系有机会承载真实感受。', '["关系修复", "治疗关系", "主体间性", "断裂修复", "真实表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 177, now()),
(100178, '抑郁认知三元素：自己、世界和未来同时变暗', '贝克抑郁理论把抑郁中的认知核心概括为三类负性模式：用负性方式看自己，觉得自己无价值或有缺陷；用负性方式看世界，觉得环境充满剥夺、失败和阻碍；用负性方式看未来，觉得情况不会改善。App 遇到抑郁倾向表达时，可帮助用户把“事实”与“抑郁滤镜”区分开：这是我全部的人生，还是低落状态下被激活的一套解释？', '["抑郁", "贝克认知理论", "负性认知", "自我世界未来", "认知滤镜"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 178, now()),
(100179, '抑郁症状要分层看：情绪、认知、动机和身体会互相牵连', '抑郁不是单一情绪问题，常同时表现为情绪低落或空洞、负性自我评价、注意和思维迟缓、做事动力下降、回避、睡眠食欲和身体能量变化。App 回答时应避免把用户简单归为“懒、玻璃心、想太多”，而要提示这是一个身心系统状态。更有效的恢复路径通常需要多点介入：规律作息、微小活动、认知检验、关系支持和必要的专业帮助。', '["抑郁症状", "情绪", "认知", "动机", "身体反应", "恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 179, now()),
(100180, '抑郁图式：旧的负性模板会在压力下被重新激活', '抑郁易感性可以理解为某些负性图式在压力下被激活。平时用户可能还能维持功能，但在失恋、失败、丧失、冲突或长期压力下，旧模板会把事件解释成“我不够好、我会失去、未来没希望”。App 可帮助用户识别激活点：最近发生了什么压力？它碰到了哪种核心信念？有没有证据说明这只是旧模板，而不是全部现实？', '["抑郁图式", "压力触发", "核心信念", "认知易感性", "反刍"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 180, now()),
(100181, '反刍会放大抑郁：重复想不等于真正解决', '抑郁状态下，人容易反复咀嚼同一件事，以为想清楚才能行动，但反刍常让注意力越来越窄、情绪越来越重、行动越来越少。App 可以把反刍和问题解决区分开：反刍是循环问“为什么我这么糟”，问题解决是写下可验证事实、可影响部分、下一步行动和需要支持的人。若思考超过一定时间仍只增加痛苦，就应转向身体活动、外部支持或具体任务。', '["反刍", "抑郁", "问题解决", "注意力", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 181, now()),
(100182, '抑郁复发预防：恢复后仍要维护认知和生活系统', '抑郁好转不等于风险完全消失，维持治疗、认知练习和生活结构能降低复发概率。App 可把复发预防做成日常清单：睡眠和活动是否稳定？是否又开始孤立？是否出现“我没用、没希望”的自动解释？是否停止了有效练习？是否有可以提前联系的支持对象？重点是早识别、早调整，而不是等到完全崩溃才求助。', '["抑郁复发", "维持治疗", "认知疗法", "生活结构", "早期预警"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 182, now()),
(100183, '把信念当假设：用小实验替代空想式显化', '《能量》类资料适合被 App 转译成自我觉察练习：不要把“意念创造现实”理解成逃避现实责任，而是把信念当作可检验假设。若用户相信“没有机会”，可以设计一个 48 小时小实验：主动寻找三个机会线索、记录自己忽略了什么、采取一个微行动。这样把抽象信念落到注意力、选择和行动上，既保留积极探索，也避免陷入空想。', '["能量练习", "信念实验", "注意力", "积极心理", "行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 183, now()),
(100184, '注意力会筛选现实：你寻找什么，就更容易看见什么', '人每天接触的信息远远超过能处理的范围，因此注意力会像过滤器一样选择哪些线索进入意识。当用户长期只寻找威胁、缺失和失败，大脑会不断证明“世界就是这样”；当用户练习寻找资源、支持和可行动线索，也会更容易看见新的可能。App 可引导用户做注意力复盘：今天我自动看见了什么？我忽略了什么？如果我寻找一个微小资源，会在哪里？', '["注意力", "选择性知觉", "资源取向", "积极练习", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 184, now()),
(100185, '感恩不是否认问题，而是训练大脑看见已拥有的资源', '感恩练习的价值不在于粉饰困难，而在于让用户从“我只有缺口”的单一叙事中恢复平衡。有效感恩要具体：今天谁提供了支持？我完成了哪件小事？身体还在支持我什么？环境里有什么可用资源？App 在低落或匮乏感问题中，可建议用户每天记录三项具体资源，并配合一个现实行动，让感恩连接到力量，而不是变成压抑情绪的口号。', '["感恩", "资源觉察", "积极心理", "匮乏感", "低落恢复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 185, now()),
(100186, '疯传 STEPPS：传播不是运气，而是六类心理机制叠加', '《疯传》提出，内容和行为更容易传播，往往不是因为广告预算最大，而是触发了六类机制：社交货币让分享者显得有价值；诱因让人被环境反复提醒；情绪唤醒推动转发；公开可见让模仿更容易；实用价值让人愿意帮别人；故事把信息包装进可复述情节。App 可把这套框架用于课程、活动和内容传播诊断：缺哪一环，就补哪一环。', '["疯传", "STEPPS", "传播心理", "影响力", "内容策略", "社交货币"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 186, now()),
(100187, '社交货币：用户分享的不是内容，而是分享后的自我形象', '人们愿意分享能让自己显得聪明、有品位、有内部消息、乐于助人或与众不同的内容。传播设计不应只问“我们想说什么”，还要问“用户转发后会显得怎样”。App 可用于内容建议：给用户一个可展示的洞察、身份、成就或独特表达，让分享行为成为自我形象的一部分；但社交货币必须和真实价值相连，否则会变成噱头。', '["社交货币", "内容传播", "身份表达", "用户分享", "影响力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 187, now()),
(100188, '诱因：把想传播的行为绑定到高频场景', '好内容如果没有被想起的触发点，也容易沉下去。诱因的关键是把信息绑定到用户日常会频繁遇见的场景、词语、时间和动作上：一到周一想到复盘，一看到咖啡想到能量，一遇到冲突想到暂停三问。App 可帮助课程和产品设计触发器：用户什么时候最需要这条知识？现实中什么线索会提醒 TA？如何把提醒嵌入日常而不是只靠一次宣传？', '["诱因", "触发器", "习惯场景", "内容传播", "行为设计"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 188, now()),
(100189, '高唤醒情绪更容易推动传播，但要服务真实价值', '不是所有情绪都同样推动传播。高唤醒情绪，如惊讶、敬佩、愤怒、焦虑、兴奋，更容易促使人行动；低唤醒情绪，如满足或悲伤，未必带来同样的转发动力。App 生成传播建议时，可帮助用户寻找内容中的情绪核心：它让人惊讶在哪里？敬佩什么？担心什么？但情绪唤醒不等于煽动，最好让情绪服务于理解、行动和真实帮助。', '["情绪传播", "高唤醒", "内容策略", "影响力", "行动动力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 189, now()),
(100190, '实用价值：越具体、越省力、越能帮到别人，越容易被转发', '人们常分享有用信息，因为这让他们能帮助别人、维持关系并展示判断力。实用价值要具体：省多少钱、少踩什么坑、按哪几步做、适合谁、不适合谁。App 可把知识库内容改写成可传播建议：标题直接说用途，正文给步骤和场景，结尾给转发对象。抽象鸡汤不如一个清晰清单，模糊道理不如一个今天就能用的小工具。', '["实用价值", "清单化", "内容传播", "帮助他人", "行动步骤"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 190, now()),
(100191, '故事是信息的运输工具：让观点藏在可复述情节里', '故事能传播，是因为人们更愿意复述人物、冲突、转折和结果，而不是背诵抽象观点。一个好故事应让核心信息不能被轻易剥离：如果用户讲完故事却忘了产品、课程或方法，说明信息没有嵌入情节。App 可建议内容创作者用“人物遇到什么困境—尝试什么方法—发生什么转变—听众能带走什么行动”来组织表达，让知识随故事一起被记住。', '["故事传播", "叙事", "内容策略", "知识表达", "可复述"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 191, now()),
(100192, '人格测验的信度与效度：分数只能作线索，不能作判决', '人格测验要先问两件事：信度，即同一测验能否稳定、一致地测到某种倾向；效度，即它测到的东西是否真是想测的建构。高信度不等于高效度，一个量表可能稳定地测到“社会赞许倾向”而不是自尊。自陈量表还会受到伪装、敷衍答题、阅读理解、反应倾向和测评动机影响。App 解读测评结果时，应提醒：结果适合作为自我观察、讨论和后续行为验证的起点，不适合单凭一个分数判断人格、诊断障碍、录用或淘汰某人。更可靠的做法是结合长期行为、他人反馈、情境记录、功能损害和专业评估。', '["人格测验", "信度", "效度", "自陈量表", "测评解读"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 192, now()),
(100193, 'DSM-5替代性模型：人格障碍评估从类别转向功能画像', '人格障碍不宜只用“是不是某型”理解。维度化模型把重点放在两类信息：人格功能受损和病理性人格特质。人格功能包括身份认同、自我定向、共情、亲密等自我与人际能力；病理特质则描述消极情绪、疏离、对抗、脱抑制、精神质等方向的程度。这样能把人格问题放到连续体上看：普通人也会有某些特质，只是强度、僵化度、跨情境稳定性和功能损害不同。App 适合用作非诊断回答：先评估长期性、跨场景、功能损害、自我/人际能力，再讨论边界、求助和干预，而不是给用户或他人贴临床标签。', '["人格障碍", "DSM5", "维度模型", "人格功能", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 193, now()),
(100194, '图式—模式—策略：人格障碍的认知行为底层模型', '认知行为视角把人格障碍理解为“图式—模式—策略”的持续循环。图式是关于自我、他人和世界的深层信念；模式是某些图式在特定情境下被整体激活后的认知、情绪、动机和行为状态；策略原本有适应意义，如寻求安全、保持自主、争取认可、避免伤害，但当它过度发展、发展不足或僵化使用时，就会制造持久的人际和自我功能问题。干预不是简单纠正错误想法，而是先看策略保护了什么，再通过关系体验、行为实验、图式反馈、正念或角色扮演，让人发展更灵活的新策略。', '["人格障碍", "CBT", "图式", "模式", "行为策略", "个案概念化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 194, now()),
(100195, '人格障碍治疗联盟：关系本身就是行为实验室', '人格障碍干预比症状干预更依赖治疗联盟，因为改变慢、挫败多，且来访者的核心信念常会在治疗关系中被激活：害怕被拒绝、被控制、被羞辱、被利用，或觉得必须取悦/反抗治疗师。有效工作不是只讲技术，而是把关系困难纳入概念化：发生误解时及时标记，鼓励具体反馈，治疗师保持非防御态度，把会谈中的回避、顺从、攻击、理想化或贬低视为可观察材料。App 可借鉴这一点：面对高度敏感或长期模式用户，先建立可预测、尊重边界的互动，再引导事实记录、情绪稳定和小步实验。', '["治疗联盟", "人格障碍", "治疗关系", "CBT", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 195, now()),
(100196, '回避型人格模式：安全行为会短期降焦虑、长期困住自我', '回避型模式的核心不是“不想关系”，而是“渴望关系但预期羞辱、批评、拒绝”。回避、沉默、提前退出、不表达真实需求、只给正面反馈等安全行为，短期能降低焦虑，却让人失去验证新经验的机会，长期强化“我无法承受他人评价”的信念。认知行为干预强调：先建立足够安全的关系，再识别回避链条，逐步暴露于可承受的社交风险，练习自信表达、负面反馈、情绪耐受和行为实验。App 可把“逃开”翻译成保护策略，同时帮助用户设计低风险的接近练习。', '["回避型人格", "安全行为", "社交焦虑", "行为实验", "情绪耐受"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 196, now()),
(100197, '自恋型人格的认知理解：脆弱自尊与特权策略并存', '自恋模式不只是“自大”，更常是脆弱自尊与补偿性优越感的组合。个体可能把价值感建立在特殊、卓越、被认可之上，因此对批评、忽视、失败或地位受损高度敏感；当自尊受威胁时，容易使用贬低他人、要求特殊待遇、回避羞耻、争夺控制等策略。App 回答时不宜用“自恋”骂人，而应拆成可观察模式：是否需要持续赞美，是否难以承认影响，是否把普通反馈理解为羞辱，是否通过控制关系维持自尊。对当事人可引导区分真实自我价值与外部评价，练习承担影响而不崩塌。', '["自恋型人格", "自尊", "羞耻", "关系模式", "认知治疗"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 197, now()),
(100198, '偏执型人格模式：威胁扫描会把保护策略变成关系破坏', '偏执型模式可以理解为保护策略过度化：个体高度关注被伤害、被侵犯、被欺骗或被控制的可能，倾向把模糊信息解释成针对自己的威胁。它的短期功能是降低被动受害感，长期后果却是不断检查、质疑、反击和疏离，让他人更防御，反过来“证明”世界不可信。App 在关系咨询中可帮助用户把“对方一定有恶意”改写为可检验假设：事实是什么、还有哪些解释、若保持边界但暂缓攻击会怎样。面对他人的偏执化互动，则强调安全、边界、书面事实和避免陷入辩解循环。', '["偏执型人格", "威胁解释", "保护策略", "关系边界", "认知重评"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 198, now()),
(100199, '超越性动机与存在价值：成长后期需要比“我”更大的方向', '在基本需要相对稳定后，人仍可能感到空洞，因为动机不只包括补缺口和实现个人潜能，还包括对真、善、美、创造、意义、整体性、正义、卓越等存在价值的回应。马斯洛晚期把这类更高动机称为超越性动机或超越性需要：人需要献身于某种大于个人欲望的对象，突破只以自我利益为中心的生活。App 可在用户问“为什么条件不错仍空虚”时引导：先确认基础需求与心理困扰，再探索哪些价值让他愿意服务、学习、创造、守护或奉献。它不是道德绑架，而是成熟人格的方向感来源。', '["马斯洛", "超越性动机", "存在价值", "意义感", "成长需要"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 199, now()),
(100200, '九型心理缓冲带：防御机制会遮住类型真相', '九型资料把“心理缓冲带”理解为人为了维持自我形象而形成的防御系统。它会把性格中的负面特征、羞耻和矛盾挡在意识之外，使人只看到自己愿意相信的版本。不同类型常有不同防御倾向，如反向作用、压抑、认同、内投、分隔、投射、合理化、否定、麻醉等。RAG 中这比“测出我是几号”更有价值：识别类型时看一个人如何维护自我感、怎样解释冲突、哪些反馈最难听进去。成长不是撕掉防御，而是在安全和诚实中看见它保护的脆弱需要。', '["九型人格", "心理防御", "自我观察", "类型识别", "成长练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 200, now()),
(100201, '九型潜藏激情：类型背后的情绪习性比行为更关键', '九型人格的“激情”指反复劫持注意力的情绪习性，不是偶发情绪。它们可被看作早期适应留下的阴影：当某种情绪习惯被点燃，人会围绕它组织解释、关系和行动，并失去自我观察能力。判断类型时，不只看外在行为，而要看注意力最容易被什么情绪主题牵引：愤怒、骄傲、形象、嫉羡、匮乏、恐惧、贪多、控制、怠惰或麻木等。App 可引导用户记录“我在冲突中最自动的情绪剧本是什么”，再把激情当成返回真实需要和失落品质的线索。', '["九型人格", "潜藏激情", "注意力", "情绪习性", "类型成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 201, now()),
(100202, '情绪工作五项底层技能：接地、边界、引导、抱怨与复原', '强烈情绪不是只靠理解就能处理。先把自己带回身体和当下，再给内在体验划出边界，才更容易安全地翻译情绪。可作为五步框架：1）接地：借呼吸、身体感、脚下支撑，让情绪流过而不被淹没；2）定义边界：用愤怒、羞耻等信号辨认“我与他人”的界线；3）负责任地引导情绪：不压抑、不乱发泄，找安全容器表达；4）有意识地抱怨：把怨气从攻击变为看见未满足需要；5）恢复自我活力：情绪过后回到资源、节律和行动。适合回答“情绪上来怎么办”“如何不被情绪吞没”。', '["情绪语言", "情绪调节", "接地", "边界", "身体觉察", "自我复原", "强烈情绪"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 202, now()),
(100203, '情绪亲密的三层共情：感觉到、同情、同感都需要边界', '与人共情不是越融合越好。情绪亲密可分三层：感觉到，是用身体临在、表情、语调和细节读取对方状态；同情，是在心的层面与对方相连，让对方感到安全和被理解；同感，是双方在共享情绪中并肩共振。风险也随层级增加：只“感觉到”可能变成旁观或操控；“同情”过度会吸收太多、丢失自己；“同感”失衡会形成封闭的“我们”而拒绝反馈。健康共情=连接+自主+可质疑，适合亲密关系、咨询倾听和团队情绪支持。', '["情绪亲密", "共情", "同情", "同感", "边界", "倾听", "关系安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 203, now()),
(100204, '愤怒两步公式：痛苦或压力遇到触发思维才会点燃', '愤怒常由两部分组成：先有身体或情感上的痛苦/压力，如疲劳、头痛、被拒绝、需要受阻；随后出现触发思维，把情境解释为“对方故意伤害我、冒犯我、应该受惩罚”。痛苦像燃料，触发思维像火柴；任一部分被看见，愤怒链条就有机会中断。RAG 可用于生成愤怒日志字段：压力源、客观事件、触发解释、愤怒强度、实际行为、对自己后果、对他人后果。干预重点是同时降低生理唤醒和替换指责、灾难化、支配性想法。', '["愤怒管理", "触发思维", "压力", "认知扭曲", "愤怒日志", "身体唤醒"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 204, now()),
(100205, '愤怒的隐藏奖赏：短期奏效会强化爆发', '有些愤怒难改，不是因为当事人不知道它伤人，而是因为它短期内“有用”：别人退让、停止要求、改变安排，自己获得控制感和释放感。这种奖赏会把愤怒训练成默认工具，即使长期代价是关系疏远、抵抗升级和自责。反愤怒方案要问三件事：这次爆发带来了什么积极结果？我真正想保护的需要是什么？有没有不破坏关系也能达成同样结果的方式，如坚定表达、协商、设置容忍度、独立制定计划。适合处理“我知道发火不好但忍不住”。', '["愤怒强化", "控制感", "边界表达", "替代行为", "协商", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 205, now()),
(100206, '抑郁中的自我批评：评估行为，不审判整个人', '自我批评在抑郁中常从“我这件事没做好”滑向“我这个人不行”。把成绩、考试、家务、工作等结果绑定到“我”的价值，会让失败变成自我攻击。更有帮助的区分是：行为可以复盘，结果可以失望，策略可以调整，但人的基本价值不随一次成败升降。走出抑郁需要两种思维协作：理性思维像侦探，检查证据、寻找多种解释、做小实验；同情性思维像可靠照护者，用友好、支持、宽恕和修复取代威胁惩罚。适合自责、羞耻、完美主义引发的抑郁检索。', '["抑郁", "自我批评", "自我价值", "同情性思维", "理性思维", "羞耻"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 206, now()),
(100207, '抑郁康复的共同照护：研究自己的模式并预设求助信号', '康复故事反复指向一个实用原则：来访者不是被动等待治疗，而要逐渐成为自己康复系统的共同管理者。做法包括：记录自己的发作模式和季节/生活事件触发点；观察睡眠、饮食、精力、语速、退缩、冲动等早期信号；把有效疗法、药物、运动、互助、日记、光照、饮食等整理成个人方案；提前授权可信亲友在发现异常时联系医生或治疗师。它不是“靠自己硬扛”，而是把自我觉察、专业支持和社会支持制度化，让低谷时仍有人能拉响警报。', '["抑郁康复", "自我监测", "支持系统", "早期信号", "治疗合作", "生活方式"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 207, now()),
(100208, '拖延三管齐下：改写思维、锻炼情绪肌肉、用五分钟启动', '拖延不是单纯懒惰，而是认知、情绪、行为连锁：任务出现负面看法，引发焦虑、厌恶或压力，再用低压力活动替代，获得即时放松，拖延因此被强化。反拖延可三管齐下：认知上识别“以后再做、准备好再开始、失败就完了”等拖延思维，把计划看成可检验假说而非人格审判；情绪上练“情绪肌肉”，接纳不适、观察身体紧张，放弃短期逃避换长期收益；行为上用五分钟计划，先承诺开始五分钟，再决定下一个五分钟。适合任务启动困难和压力型拖延。', '["拖延", "三管齐下", "情绪肌肉", "五分钟计划", "认知改写", "行动启动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 208, now()),
(100209, 'TA 的认可饥渴：人际游戏常在替代真实亲密', '沟通分析把人际互动看成满足三种基本渴望的方式：刺激渴望、认可渴望和结构渴望。婴儿需要身体抚触，成人也需要象征性“安抚”，如问候、微笑、回应和被看见；但仅有问候不够，人还需要安排清醒时间，于是活动、仪式、消遣、游戏、亲密成为不同层级的时间结构。心理游戏之所以顽固，是因为它既提供认可和时间结构，又避免真实亲密的脆弱。App 可据此区分：用户是在寻求真实请求、普通消遣，还是通过反复冲突获取安抚。', '["沟通分析", "认可饥渴", "安抚", "时间结构", "心理游戏", "亲密"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 209, now()),
(100210, 'TA 三类沟通：互补维持互动，交错制造中断，隐藏形成游戏', '在沟通分析中，一次沟通不只看说了什么，还看由哪个自我状态发出、邀请对方哪个自我状态回应。互补沟通指刺激和回应方向匹配，互动能顺利继续；交错沟通指回应来自意料之外的自我状态，谈话容易卡住、冲突或转向；隐藏沟通则同时存在社交层和心理层，表面像理性对话，底层却在交换依赖、控制、惩罚、讨好或逃避。心理游戏常是隐藏沟通反复运行并导向可预测结局。适合解析“明明只是小事却总吵起来”的对话结构。', '["沟通分析", "互补沟通", "交错沟通", "隐藏沟通", "自我状态", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 210, now()),
(100211, '人际游戏公式：骗局、弱点、回应、转换和结局', '心理游戏不是简单“耍心机”，而是习以为常但功能不良的安抚方式。G 公式可作为识别模板：一方抛出看似合理的刺激或骗局；对方的弱点被勾住并回应；随后发起者或参与者自我状态转换；最后出现熟悉的情绪结局，如正义愤怒、委屈、被踢、无助。戏剧三角补充说明角色会在受害者、拯救者、迫害者之间快速互换。退出游戏的关键不是争输赢，而是识别隐蔽动机、拒绝接预设角色、把沟通拉回真实请求和可协商边界。', '["人际游戏", "G公式", "戏剧三角", "受害者", "拯救者", "迫害者", "沟通分析"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 211, now()),
(100212, '主体间场：治疗师不是旁观者，而是共同创造治疗环境的人', '主体间心理治疗把咨访关系看成由两个主体共同形成的系统。治疗师对来访者主观经验的理解，会受到治疗师自身主体性、理论假设、文化背景、情绪反应和经验组织方式影响；这些影响不是要被假装消除，而是要被敏感地觉察和使用。治疗环境也不是固定容器，而由场所、共情倾听、互动关系以及不可预知的双方经历共同创造。RAG 可用于提醒咨询师：解释来自关系背景，任何“客观看法”都要检查自己在主体间场中的贡献。', '["主体间场", "咨访关系", "治疗师主体性", "共同创造", "反思", "心理治疗"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 212, now()),
(100213, '情感协调的治疗力：破裂—修复和特殊情感时刻会重组经验', '主体间治疗强调经验围绕情感组织，因此改变情感体验会为新的经验组织打开机会。婴儿研究提供了三个关键原则：互动中的持续调节、破坏与修复、特殊情感时刻。迁移到心理治疗中，来访者与治疗师会共同期待、误会、调整和修复；当某一刻来访者真实感到“我的体验被另一个人感受到并适当回应”，就可能扩大自我调节范围，形成新的共享情感经验。它解释了为什么一次真诚的理解、一次关系裂痕后的修复，有时比完美解释更有治疗作用。', '["情感协调", "破裂修复", "特殊情感时刻", "自我调节", "主体间性", "治疗关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 213, now()),
(100214, '霍妮三种人际移动：亲近、对抗、疏远都是求安全', '霍妮把许多内心冲突理解为三种人际方向的拉扯：亲近他人时，用户可能用讨好、依赖、牺牲来换安全；对抗他人时，可能用控制、竞争、证明自己来避免被伤害；疏远他人时，可能用冷淡、消失、自给自足来保住自主。App 端回答时，不宜只把这些反应评价为“太软弱”“太强势”或“太冷漠”，而要追问：我此刻在防什么危险？我最怕失去的是爱、价值、尊严还是自由？成熟不是固定选择某一种策略，而是在不同关系里能更有弹性地靠近、设限或退后。', '["霍妮", "内心冲突", "人际模式", "讨好", "对抗", "疏远", "安全感", "关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 214, now()),
(100215, '理想化自我与外化：假和谐会把冲突推远', '内在冲突常会被两种方式暂时盖住：一是制造一个“我应该永远优秀、正确、被喜欢”的理想化形象；二是在理想化破裂后，把痛苦完全外化为“都怪别人/环境”。前者让人不断羞耻和自责，后者让人短期舒服却远离可改变的部分。App 可帮助用户区分愿景与苛刻形象：我要求自己必须成为什么样才配被接纳？现实中哪一小部分是我能承担和调整的？哪一部分确实属于外部限制，需要边界、协商或资源支持？', '["霍妮", "理想化自我", "外化", "内耗", "羞耻", "责任", "自我接纳", "冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 215, now()),
(100216, '每日情绪日志：焦虑要写成可检验的想法', '焦虑自助不只是让用户“别想太多”，而是把脑内灾难化写成可检查的材料。可引导用户用每日情绪日志记录：触发事件是什么；焦虑、羞耻、愤怒等情绪各有多强；脑中自动想法是什么；其中有哪些放大、读心、非黑即白、应该化等认知扭曲；更平衡的回应是什么；重新评分后情绪是否下降。这样做的重点不是强迫积极，而是把“我完了”变成“这是一个想法，我能找证据、找替代解释、做小实验”。', '["焦虑", "认知疗法", "每日情绪日志", "认知扭曲", "自助", "想法检验", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 216, now()),
(100217, '暴露与行为实验：停止用回避喂养恐惧', '许多焦虑之所以持续，是因为回避让大脑一直没有机会更新：“我不去，所以没出事”会被误解为“幸好我不去，否则一定完蛋”。暴露不是鲁莽硬闯，而是把害怕情境拆成可承受的小阶梯：先写下预测的最坏结果和概率，再设计一次安全、具体、可停止的小实验，记录真实发生了什么。用于社交焦虑、羞怯、反复担忧时，App 可建议用户减少一个安全行为、完成一次低风险接触，再用结果修正旧信念。', '["焦虑", "暴露法", "行为实验", "回避", "安全行为", "社交焦虑", "信念更新"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 217, now()),
(100218, '认知不协调：改变观点常从小行为和自我辩解开始', '人做了与自我形象不一致的事，会产生不舒服的认知不协调，并倾向于通过改变态度或编理由来恢复一致感。关系沟通和行为改变中，与其强迫对方承认“你错了”，不如邀请一个低压力、可自愿的小行动，再让对方从行动经验中更新看法。反过来，用户也要警惕自己被承诺、沉没成本和公开表态绑住：我现在坚持，是因为证据更充分，还是因为不想承认之前的选择可能有问题？', '["认知不协调", "态度改变", "自我辩解", "承诺", "行为改变", "沟通", "社会影响"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 218, now()),
(100219, '社会学习：榜样、强化和环境比说教更能改行为', '社会学习视角提醒，行为常由观察、模仿、奖惩和自我期待共同塑造。亲子、伴侣或团队场景里，单纯说教和羞辱往往不如清楚示范、即时反馈和环境设计有效。App 可把建议落到三个问题：谁正在示范这种行为？这个行为之后立刻得到了什么奖励或代价？环境里哪些提示在鼓励旧模式？想培养新行为，就要让新行为更容易被看见、被做到、被肯定，而不是只要求对方“自觉一点”。', '["社会学习", "榜样", "强化", "环境设计", "行为改变", "亲子沟通", "团队管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 219, now()),
(100220, '旁观者效应：责任不明确时，善意会被群体稀释', '社会心理学中的旁观者研究显示，人越处在一群人中，越可能等待别人先行动；这不一定是冷漠，而常是责任扩散、彼此观望和误判情境造成的。App 在危机求助、团队协作或家庭分工中，可建议把“有没有人帮我”改成命名、限时、具体的请求：请 A 现在打电话，请 B 陪我去医院，请 C 今天 18 点前确认方案。明确责任能把模糊善意转化为行动，也能减少用户把无人响应解释成“我不值得被帮”。', '["旁观者效应", "责任扩散", "求助", "群体影响", "具体请求", "危机沟通", "社会心理学"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 220, now()),
(100221, '少数意见的价值：不同声音能防止群体迷思', '群体决策中，表面一致并不总是健康；少数意见会迫使群体更仔细检查证据，激发发散思维和创造力。若为了和气、效率或权威而压制异议，团队容易进入群体迷思：没人敢说风险，最后一起做出差判断。App 可建议家庭或团队设置“反方角色”：先收集不同意见，再决定；先讨论证据，再投票；特别询问沉默者看见了什么。关系质量不是没有分歧，而是分歧能被安全表达。', '["群体迷思", "少数意见", "团队决策", "发散思维", "异议", "心理安全", "社会心理学"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 221, now()),
(100222, '心理标签效应：诊断词会改变我们看见一个人的方式', '经典实验提醒，一旦给人贴上心理或人格标签，后续普通行为也容易被解释成标签证据。App 端应避免把“抑郁型人格、回避型、病态、自恋”等词当作判决书；更适合把标签降级为线索，并回到可观察事实：这种行为出现多久？在什么场景出现？带来什么功能损害？对方是否也有例外表现？对自我标签同样如此，“我就是废物/拖延人格”要改写为“我在某些任务前会回避，但可以观察触发点并练习下一步”。', '["心理标签", "诊断谨慎", "人格", "自我标签", "观察事实", "污名化", "心理实验"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 222, now()),
(100223, '思维定势与功能固着：换问题框架才能产生新选择', '人解决问题时常被既有用法和第一反应锁住，以为某个物品、角色或关系“只能这样”。思维定势会让用户在冲突中反复问“谁对谁错”，却忘了还可以问“我们真正要达成什么功能”。App 可引导用户拆框：我默认了哪些必须？这个资源除了原用途还能支持什么？如果目标不变、路径换三种，会有哪些选择？在亲密关系、职场沟通和自我改变中，创造力往往不是更用力，而是先松开旧框架。', '["思维定势", "功能固着", "创造力", "问题重构", "决策", "沟通", "心理实验"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 223, now()),
(100224, '社会建构视角：别把所有痛苦都解释成个人性格', '社会学视角强调，个人行为背后常有角色、规范、制度和文化脚本。用户把一切痛苦归因为“我太脆弱、我不够努力”时，App 可补问：这个家庭/单位/群体期待你扮演什么角色？哪些奖励和惩罚在维持当前模式？有没有阶层、性别、年龄、职业规则让选择变窄？这不是否认个人责任，而是避免把结构性压力伪装成性格缺陷。有效改变有时不是再逼自己，而是调整规则、边界、资源和支持网络。', '["社会学", "社会建构", "角色", "规范", "制度", "结构性压力", "自责", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 224, now()),
(100225, '成年发展的生态视角：人生危机常是角色与环境重组', '成年发展不是一条直线，也不只由年龄数字决定。人的困境会受实足年龄、生理年龄、心理年龄、社会年龄，以及时代、家庭、工作、健康和突发事件共同影响。App 回答“我这个年纪还这样是不是失败”时，可把羞耻改写为发展评估：我正在经历哪种角色转换？这个压力来自年龄常规事件、时代变化，还是非常规打击？我需要学习的新能力、支持系统和身份叙事是什么？这样能把危机从自我否定转为角色与环境重组。', '["成年发展", "生态视角", "人生阶段", "角色转换", "年龄", "身份", "支持系统"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 225, now()),
(100226, '改变难以坚持：洞见之后要搭建维持系统', '重大改变很少只靠一次顿悟完成。危机、故事、支持、治疗、旅行、意义感都可能触发改变，但旧环境和旧奖励会把人拉回原模式。App 在用户“我终于想通了”之后，应继续追问维持系统：未来最可能复发的场景是什么？谁能在我退回旧模式前提醒我？我要改变哪些环境提示？每周用什么仪式复盘？如果跌回去，最小恢复动作是什么？真正的改变不是永不反复，而是反复时有回到轨道的方法。', '["改变心理学", "复发预防", "维持系统", "洞见", "支持网络", "习惯保持", "行动计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 226, now()),
(100227, '影响力防身清单：好感、权威、稀缺和社会认同都要慢下来', '影响力原则既能帮助沟通，也可能劫持判断。用户在冲动购买、仓促承诺、关系让步或群体跟风前，可做防身清单：我是否因为别人先给了好处而急着回报？是否因为已公开承诺而不愿调整？是否因为大家都这样做就停止思考？是否把头衔、专业感或自信语气误当证据？是否被“最后机会、限量、错过就没了”推着走？健康的影响力应允许对方慢下来、看证据、保留拒绝权。', '["影响力", "互惠", "承诺一致", "社会认同", "权威", "稀缺", "决策", "防操控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 227, now()),
(100228, '情感隐藏模型：焦虑有时是在替未表达的情绪站岗', '有些焦虑不只来自认知扭曲，也可能在保护某些“不方便表达”的情绪：不敢承认愤怒，于是变成担心；不敢说需要，于是变成反复控制；不敢面对悲伤，于是忙着焦虑未来。App 不应把所有焦虑都机械套入“想法错了”，也可以温和询问：如果焦虑暂时停下，底下最可能浮现什么感受？我有什么请求、边界或哀伤一直没被说出口？当隐藏情绪被安全表达，焦虑有时会自然下降。', '["焦虑", "情感隐藏", "情绪表达", "需要", "边界", "认知疗法", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 228, now()),
(100229, '确认性偏见：主动寻找反证，才能突破自我证明循环', '确认性偏见会让人更容易看见支持自己观点的信息，并忽略挑战自己信念的证据。关系冲突中，用户若先认定“TA 不在乎我”“我一定会失败”，后续所有细节都可能被筛选成证据。App 可引导用户做反证练习：如果我的判断错了，会有哪些迹象？有哪些事实同时支持另一种解释？我能不能问一个开放问题，而不是继续搜集控诉材料？真正的理性不是永远相信自己，而是愿意让信念接受检验。', '["确认性偏见", "反证", "认知偏差", "关系误读", "自我觉察", "开放问题"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 229, now()),
(100230, '后知之明偏见：复盘时不要把结果倒推成“早就知道”', '事情发生后，人很容易觉得结果本来就显而易见，并低估当时的不确定性。后知之明偏见会让复盘变成责备：你明明早该看出来、我怎么这么笨、早知道就好了。App 可把复盘改成过程复盘：当时我掌握了哪些信息？哪些风险是真能看见的，哪些是事后才知道的？下一次可设置什么预警信号？这样既保留学习，又避免用结果惩罚过去的自己。', '["后知之明偏见", "复盘", "自责", "决策", "不确定性", "预警信号"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 230, now()),
(100231, '双曲线折扣：拖延和冲动都在高估眼前、低估未来', '双曲线折扣描述了人更重视眼前收益、低估未来代价的倾向。它会让用户今天刷手机、明天补救；今天冲动消费、未来焦虑；今天逃避对话、未来关系更僵。App 可把长期目标改造成近端约束：提前设截止日期、把任务拆成今天能完成的最小动作、让未来代价现在可见、把承诺告诉可信的人。不要只靠意志力和未来的自己，未来的自己通常也会遇到同样的诱惑。', '["双曲线折扣", "拖延", "冲动", "未来自我", "承诺", "行动设计"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 231, now()),
(100232, '邓宁—克鲁格效应：越不熟练，越需要外部反馈校准', '人在能力不足时，常因为缺少判断标准而高估自己；能力提升后，反而更能看见复杂性和不足。App 可在学习、关系修复或自我成长问题中提醒：自信不等于熟练，挫败也不等于没天赋。更可靠的校准方式是外部反馈、可量化结果、刻意练习和复盘证据。用户若觉得“我已经很会沟通/我很懂自己”，可以追问：别人体验是否一致？有没有反复出现的失败模式？我是否请过可靠的人指出盲点？', '["邓宁克鲁格效应", "自我评估", "反馈", "刻意练习", "盲点", "学习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 232, now()),
(100233, '基本归因错误：先看情境压力，再判断人格问题', '基本归因错误让人解释他人行为时过度强调性格，低估情境压力；解释自己行为时却更容易强调处境。伴侣迟到不一定是不在乎，员工沉默不一定是没责任，孩子顶嘴也不一定是品格差。App 可在评价他人前加入情境检查：当时 TA 面临什么压力、信息、角色和资源限制？类似情境下别人会怎样？有没有稳定的跨场景模式？先看情境，不等于纵容伤害，而是让判断更准确，边界更有针对性。', '["基本归因错误", "情境", "人格判断", "关系冲突", "社会心理学", "非标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 233, now()),
(100234, '边际效用递减：同一种满足会越用越不灵', '戈森第一定律提醒，连续满足同一种享受时，新增快乐通常会递减。它可转译为生活建议：重复刷短视频、购物、甜食、被认可或工作成就，一开始有效，后来可能越来越麻木，还需要更高剂量。App 可帮助用户区分“我真的需要更多”还是“同一种满足已经递减”。恢复活力常需要多元满足：身体休息、关系连接、创造、学习、贡献和意义，而不是把所有情绪都压到同一个出口。', '["边际效用递减", "行为经济学", "享受", "成瘾风险", "生活平衡", "多元满足"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 234, now()),
(100235, '享受均等：时间和精力要分配给真正有价值的需要', '戈森第二定律强调，要让整体享受更大，不能把全部资源投入单一需要，而要在多种需要之间分配，直到继续投入的边际收益大致相当。App 可把它用于时间管理和身心平衡：工作、亲密、健康、学习、休息、意义都需要一定投入；某一项过度挤占其他项，短期可能看似高效，长期会造成失衡。用户做选择时可问：我继续把时间投在这里，新增收益还高吗？是否有另一个被忽视的需要，投入一点就能明显改善生活质量？', '["享受均等", "资源分配", "时间管理", "生活平衡", "需要", "行为经济学"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 235, now()),
(100236, '交换不是占便宜：稳定合作要让双方都看见收益', '交换关系能持续，不是因为一方永远赢，而是双方都认为交换后的处境比交换前更好。无论是亲密关系、家庭分工、团队协作还是商业谈判，如果长期只有一方付出、另一方享受，关系就会累积怨气。App 可把协商建议从“谁该听谁”改成“双方各自得到什么、付出什么、风险是什么、如何复盘”。好的交换不是冷冰冰算计，而是让贡献、需要和回报被看见，减少隐性账本和情绪爆发。', '["交换规律", "合作", "互惠", "关系协商", "家庭分工", "谈判"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 236, now()),
(100237, '未知水域导航：把恐惧转成地图而不是灾难', '适用场景：用户面对关系变化、家庭冲突、分离风险或无法解释的不安时，容易把未知等同于灾难。
核心观点：恐惧并不只是要被消除的情绪，它常在提醒：当前信息不足、仪器失灵、旧办法不够用。把未知想象成“危险水域”有其价值，但如果只停留在惊慌或怨恨里，就会错过真正的航线。咨询中更有用的方向，是把恐惧转译成一张临时地图。
操作步骤：1）命名未知：我究竟不知道什么，是对方意图、关系结果、财务后果，还是自己的承受力？2）区分事实与解释：事实是发生过的行为，解释是我给它加上的意义。3）检查仪器：睡眠、情绪、支持系统、信息来源是否可靠。4）做小型探测：选择一个低风险行动，例如一次具体沟通、一次边界表达、一次独处复盘。5）观察—行动—复盘—校准：行动后记录什么有效、什么无效、下一步改变什么。
提醒：不要用“没事的”快速安抚用户，也不要把恐惧升级成灾难预言。更好的回应是：这里确实有不确定性，我们先画出可观察信号和可执行预案。恐惧被转成地图后，用户会更有控制感。
App 端提示：可把用户叙述转成一张“航海卡”：危险信号、缺失信息、可求助对象、下一步小实验、复盘时间。这样既承认风险，又避免让用户沉溺于想象中的恶龙。特别适合搭配情绪强度评分使用：恐惧越高，越要把任务拆到当天能完成的一步。', '["恐惧识别", "未知恐惧", "风险评估", "行动校准", "OODA", "自我负责"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 237, now()),
(100238, '不被视为理所当然：价值感来自稳定边界与可见投入', '适用场景：用户长期觉得自己在关系、家庭或团队中被消耗、被默认付出，却又不敢减少投入。
核心观点：不被视为理所当然，不是制造恐吓，也不是要求别人立刻感恩，而是重新让自己的时间、注意力、照顾、承诺和能力变得有边界。一个人越把重要资源无限免费化，越容易在表面“善良”下积累怨气；而怨气爆发后，又会被对方体验为攻击。
可转化为三类问题：1）我正在提供什么价值？包括情绪劳动、经济支持、家务、陪伴、专业能力、稳定性。2）我期待怎样的回应？回应要具体，例如尊重时间、共同分担、停止羞辱、愿意修复，而不是抽象地“对我好”。3）如果长期没有回应，我会如何保护自己？边界必须包含后果，否则只是抱怨。
行动建议：先停止把牺牲包装成爱。把“我都为你做了这么多”改成“这件事我愿意做到哪里，超过哪里我会停下”。把“你应该珍惜我”改成“当出现这些行为时，我会减少投入/暂停讨论/重新评估关系”。价值感不是靠证明自己不可替代，而是靠稳定地尊重自己。
App 端提示：当用户说“我不想再付出了”时，先不要劝其立刻切断，而是帮助他盘点哪些付出是自愿、哪些是讨好、哪些已经越过边界；再把每项付出配上清晰条件。若用户处在高风险关系中，边界不应只靠个人硬扛，而要同步考虑朋友、家人、专业服务或法律资源。', '["边界", "自我价值", "被重视", "期望管理", "关系成长", "行动改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 238, now()),
(100239, '记分牌模型：先看互动回路，再决定是否还要记分', '适用场景：用户在关系中反复计算“我做了多少、对方欠我多少、为什么总是我输”，陷入委屈与攻击循环。
核心观点：记分牌不是用来证明谁坏，而是用来观察互动如何一步步失衡。很多关系不是突然崩坏，而是在无数次让步、回避冲突、奖励破坏性行为、压抑真实需要中逐渐形成“我怎么做都不对”的感受。
使用方式：第一阶段，把分数写出来：哪些场景让我觉得自己永远输？我为了避免冲突做了哪些让步？我是否用沉默、讨好、补偿来换短暂平静？第二阶段，停止只围着对方反应转，改用自己的标准行动：我希望自己在这类场景中成为什么样的人？下次最小的不同回应是什么？第三阶段，评估是否还需要记分：当边界清楚、行为稳定、双方能协作时，记分牌应被放下；若仍只有单方努力，则它提示关系可能需要更大调整。
咨询提醒：不要让用户沉迷“翻旧账”。每一笔分数都要转成一个可观察行为、一个可改变动作、一个复盘日期。真正目标不是赢过对方，而是从输赢框架转向自我负责、协作或清醒退出。
App 端提示：可引导用户做七天互动记录，只写行为和后果，不写人格评价。记录后再问：哪些分数其实是我自己在继续记，哪些是真实需要被处理的关系问题。若记录显示双方都在记分，可进一步引导共同目标；若只有单方持续承担，则进入关系风险评估。', '["关系模式", "互动复盘", "权力动态", "责任", "冲突降温", "系统思考"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 239, now()),
(100240, '技能鸿沟：看见问题不等于会回应问题', '适用场景：用户能准确说出关系里的模式，却一到现场就变成指责、辩论、冷战或最后通牒。
核心观点：洞察和能力之间存在鸿沟。一个人可能已经看见“对方在转移话题”“我又被激怒了”“这段沟通在重复旧剧本”，但如果没有新的回应技能，洞察只会变成优越感或控诉。原材料中的“技能鸿沟”可以转化为：观察能力已经上线，行为能力还没跟上。
练习路径：1）先暂停而不是讲道理。高唤醒时，解释越多越像攻击。2）写“现场报告”：触发事件、我的身体反应、我脑中的解释、我做了什么、结果怎样。3）找出缺失技能：是不会拒绝、不会提请求、不会结束争吵、不会表达失望，还是不会承受对方不满？4）设计一句替代回应，例如“我现在听不进去，20分钟后回来继续”“这件事我不同意，但我会按这个时间处理”。5）复盘一次只改一个点。
咨询目标：把“我知道问题在哪”推进到“我下次可以做什么”。用户不需要一次变成熟，只要从自动反应前移半秒，就已经在跨越技能鸿沟。
App 端提示：当用户已经很会分析他人，却没有可执行动作时，回复重点应从“你看得很准”转向“下一次你准备停在哪里、说哪一句、做哪个动作”。这个条目也能降低自责：不会回应不是人格失败，而是技能尚未练熟，可以通过脚本和复盘训练。', '["行为复盘", "技能鸿沟", "沟通暂停", "冲突处理", "刻意练习", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 240, now()),
(100241, '先行动后解释：语言要由一致行为托底', '适用场景：用户总想通过一次长谈让对方理解自己、停止某种行为或承认错误，但现实中越解释越失效。
核心观点：语言不是没用，而是没有行为托底的语言很容易变成辩解、求认可或控制。关系中的信任通常不是被一句话建立，而是被一段时间的一致行动建立。只有当对方已经看见行为变化，语言才适合用来澄清“我现在为什么这样做、我的期待是什么、边界在哪里”。
实践顺序：1）先做可见改变，例如按承诺处理家务、准时离开争吵现场、稳定执行自己的作息和计划。2）减少解释欲，不在情绪最高点讲原则。3）当行为持续一段时间后，再用短句表达：“我最近在调整自己的生活方式；这件事我会按这个时间做；如果继续辱骂，我会暂停对话。”4）语言只服务于清晰，不服务于证明自己正确。
边界提醒：这不是冷暴力，也不是故意隐瞒重要事实。涉及安全、财务、亲密同意、重大关系决策时仍要明确沟通。此条的重点是：不要把还没被自己活出来的价值观，急着变成说服别人的演讲。
App 端提示：适合在用户准备摊牌前使用。先请用户列出过去两周自己已经稳定做到的三件事；如果列不出，说明谈话可能还缺少行为基础，需要先补行动。若用户把少说话理解为消失，需要补一句：暂停前说明回来时间，回来后完成沟通，这是安全感的一部分。', '["沟通", "一致性", "非语言信号", "边界表达", "行动承诺", "信任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 241, now()),
(100242, '相互依赖警报：牺牲换认可会把照顾变成怨恨', '适用场景：用户习惯过度负责、害怕冲突、隐藏需求，并期待别人自动理解自己的付出。
核心观点：相互依赖并不是“太爱别人”，而是把自我价值绑在被需要、被认可、被留下上。它常表现为：替别人承担本该由对方承担的责任；嘴上说“我没关系”，心里记账；害怕提出要求会被抛弃；用照顾换亲密；冲突前先撒谎、隐瞒或讨好。长期看，这会让照顾者觉得自己被利用，也让被照顾者感到被控制。
识别问题：当我说“都是为了你”时，里面是否藏着“所以你必须按我期待回应”？当我不表达需要时，是否仍期待对方读懂？当对方没有感恩时，我是否爆发怨恨？
替代策略：1）把隐性契约改成明示请求：我希望你本周承担两次接送，而不是我默默做完再生气。2）把拯救改成尊重责任：对方能做的事，让对方做。3）把害怕冲突改成可承受分歧：不同意不等于被抛弃。4）建立外部支持系统，不把伴侣、孩子或同事变成唯一情绪出口。真正的亲密不是无限牺牲，而是双方都能带着边界靠近。
App 端提示：可用“付出—期待—没说出口—怨恨”四列表帮助用户拆解隐性契约。只要期待无法被对方明确听见，就先不把对方未满足期待解释成恶意。在成长型咨询里，这类用户尤其需要练习“直接要”和“允许对方拒绝”，否则照顾会继续变形。', '["相互依赖", "隐性契约", "讨好", "认可需求", "边界", "自我照顾"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 242, now()),
(100243, '容忍即强化：用奖励回路看待反复伤人的行为', '适用场景：用户抱怨某种行为反复出现，如冷嘲热讽、失约、甩锅、越界、情绪勒索，却每次都用退让换短暂平静。
核心观点：反复行为通常被某种奖励维持。奖励不一定是夸奖，也可能是关注、让步、补偿、替对方收拾残局、降低标准，或用沉默让事情过去。与其只问“对方为什么这么糟糕”，更有建设性的问题是：这个行为之后，系统给了它什么好处？
操作步骤：1）列出一个具体行为，不做人格审判。2）记录它发生后的常见结果：谁退让、谁获得控制、谁免于承担责任。3）停止奖励破坏性行为：不在辱骂中继续解释，不替长期失责者兜底，不用亲密或资源换和平。4）奖励修复行为：对方愿意承担、道歉、补偿、稳定改变时，给予合作与肯定。5）设置可执行后果：例如暂停讨论、重新分工、引入第三方、调整关系距离。
重要提醒：此模型不是让用户责怪自己“都是我纵容的”。在暴力、胁迫或严重风险中，优先安全与外部支持。它适用于有行动空间的关系复盘：看清奖励回路，才能改变回路。
App 端提示：适合处理反复冲突。让用户选一个最小边界做实验，例如“不在辱骂中继续解释”。实验目标不是让对方立刻改变，而是验证回路是否开始松动。当边界执行后对方短暂升级反应，不要立刻判定失败；先观察自己是否又用旧奖励把循环接回去了。', '["行为强化", "边界", "关系风险", "反馈回路", "冲突解决", "责任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 243, now()),
(100244, '关系中的领导力：不是获得授权，而是先管理自己', '适用场景：用户觉得“对方不配合，所以我没法改变关系”，或者把领导力误解为命令、控制和压倒。
核心观点：可迁移的精华是：领导首先是自我管理，不是等别人授权。一个人若无法管理自己的时间、情绪、承诺、标准和愿景，就很难让家庭、团队或关系信任他的方向。真正的领导不是争论“你应该听我的”，而是持续做该做的事，让愿景变得可见。
行动化：1）先定义愿景：我希望这个家/关系/项目更稳定、更健康、更自由，具体表现是什么？2）定义自己的责任：哪些事无论别人怎样我都要做好？3）用标准和时间表行动：我会在周六上午处理这件事；这不是我现在的优先级；如果你想按另一标准完成，可以由你负责。4）从小计划练习执行，例如一次家庭活动、一次预算整理、一次固定运动。5）出错后修正，不抱怨追随者。
边界：领导不等于支配别人，也不等于把对方贬低成下属。它是承担自己选择的后果，并邀请能认同愿景的人协作。若长期无人愿意协作，得到的也是重要信息。
App 端提示：如果用户把领导力说成“为什么 TA 不听我的”，可把问题转回“你自己的标准、计划和后果是什么”。领导力先看可执行承诺，而不是对方服从程度。此条也适用于职场和亲子：先把自己可控范围做清楚，再讨论他人是否愿意合作。', '["领导力", "愿景", "责任", "家庭协作", "执行力", "决策"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 244, now()),
(100245, '定义价值与底线：先问“我想要什么”', '适用场景：用户在关系里只问“怎样才能让对方改变”，却说不清自己真正想要怎样的生活。
核心观点：很多痛苦来自目标不清。长久不等于幸福，经济稳定不等于满意，外人眼中的体面也不等于内在满足。若一个人无法定义自己珍视什么，就容易用社会剧本、沉没成本或他人期待替自己做决定。
澄清问题：1）如果不考虑面子，我为这段关系感到骄傲吗？2）我是否经常感到满足、轻松、被尊重？3）对方是否为我的生活增加价值，还是主要消耗？4）哪些是必须存在的：尊重、忠诚、亲密、共同育儿、财务透明、情绪安全、成长空间？5）哪些可以协商，哪些是底线？6）如果五年后仍是现在这样，我会感谢今天的自己留下，还是怨恨自己逃避？
咨询应用：把“我不知道要不要继续”拆成指标，而不是逼用户立刻选择。定义价值不是把自己的价值观强加给别人，而是知道自己愿意为什么投入、愿意为哪些缺失承担代价，以及什么情况下要改变距离。
App 端提示：可生成一张关系价值清单，让用户按“必须有、希望有、可协商、不能接受”分类。分类后再讨论选择，通常比直接问分不分更稳定。若用户暂时答不上来，可以先从身体反应入手：想到留下或离开时，哪里放松，哪里收紧。这个过程也能减少把责任全推给对方的冲动。', '["价值澄清", "目标设定", "底线", "关系决策", "自我诚实", "选择"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 245, now()),
(100246, '焦虑需要出口：改变关系时别制造无路可走的压力', '适用场景：用户开始设边界或自我提升后，对方变得焦虑、试探、黏人、指责或退缩，用户不知道该安抚还是硬扛。
核心观点：关系系统改变时，焦虑会升高。若焦虑没有清晰出口，人可能会用旧方式求安全：争吵、控制、讨好、突然亲近、突然退出、破坏进展。原材料中的“仓鼠迷宫”可中性化为：当一个人不知道怎样才能重新获得连接和安全感时，他会在脑内反复转圈。
健康做法不是操纵不确定性，而是给出可实践的出口。出口包括：明确哪些行为会增加亲近，哪些会降低亲近；明确冲突后如何修复；明确表达“我在改变自己，不是在惩罚你”；明确安全底线，如不羞辱、不威胁、不越界。
示例句：我愿意更靠近，但需要我们说话时不攻击人格；如果你愿意一起制定分工，我会投入；如果你只是用指责逼我回到旧模式，我会暂停。
咨询提醒：模糊和忽冷忽热也许能短期制造反应，但会损害安全感。真正可持续的关系改变，需要让双方知道怎样做会走向更好，而不是只知道自己正在失去什么。
App 端提示：当用户的改变引发对方焦虑时，不建议用“让 TA 着急一下”作为策略。更适合帮助用户同时表达稳定性和边界：我不会惩罚你，但我也不会回到旧模式。出口越具体，越不容易变成威胁；例如“周日晚一起复盘分工”比“你要更在乎我”更可执行。', '["焦虑", "关系修复", "安全出口", "情绪调节", "沟通设计", "支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 246, now()),
(100247, '自我提升后的拖绳效应：给关系追赶期，也保留选择权', '适用场景：用户开始健身、学习、稳定情绪、减少讨好后，发现伴侣、家人或朋友没有同步改变，于是产生怨恨或想立刻切断。
核心观点：自我提升常有“拖绳效应”：一开始你在自己的方向上前进，关系系统还没感觉到；等改变足够明显，绳子被拉直，对方才突然意识到你已经走远。此时常出现两种误判：用户觉得“你早干嘛去了”，对方觉得“你怎么突然变了”。
处理方式：1）承认不同步是正常现象。你是在自己的时间线上成长，对方不是你脑内计划的参与者。2）看见怨恨来源：对方可能像一面镜子，照出你过去放弃自己、纵容失衡的旧样子。3）给一个追赶期：在行为稳定后说明愿景、邀请协作、提供具体路径。4）设复盘点：例如三个月后看是否有真实行动，而不只看承诺。5）保留选择权：追赶期不是无限等待；若对方持续拉你回旧模式，你可以调整距离。
此模型帮助用户避免两种极端：一是报复性切断，二是为了照顾所有人而放弃自己的新航线。成熟做法是深呼吸、继续引领、观察对方是否愿意同行。
App 端提示：可让用户设置“追赶期复盘表”：我会继续做什么、我邀请对方做什么、我观察哪些行为、到期后如何决定。这样能把耐心和底线同时保住。追赶期结束后，不用急着审判对方好坏，只需看双方生活方向是否仍能相容。', '["自我提升", "关系过渡", "耐心", "结果独立", "复盘", "边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 247, now()),
(100248, '改变不是小把戏：避免“好转—退回—再好转”的过山车', '适用场景：用户学到某个沟通技巧或边界技巧后短期有效，一旦关系缓和就恢复旧模式，随后问题复发。
核心观点：如果改变只是策略表演，对方会逐渐不信任；如果改变被内化为新的生活方式，关系才会稳定。很多人把边界、冷静、健身、独立、减少讨好当作“让对方回心转意”的工具。短期好转后，他们立刻退回过度付出、求认可、无标准的旧状态，于是形成过山车：危机—改变—好转—松懈—复发—更大危机。每循环一次，信任都会被侵蚀。
维持方式：1）把技巧写成身份承诺：我不是为了换取某次回应才睡好、运动、守边界；这是我想成为的人。2）把好转视为反馈，不视为终点。3）当对方出现积极回应时，不用“奖励”自己放弃标准。4）建立复发预警：开始翻旧账、停止自我照顾、重新讨好、把边界变成威胁，都是退回信号。5）每月复盘一次：哪些行为已经自然化，哪些还靠愤怒撑着？
咨询中要强调：真正改变看起来不戏剧化，而是稳定、可预测、可持续。有效的事要继续做，不是等关系好一点就停止。
App 端提示：适合在用户短期好转后推送。提醒用户把新行为写进日程、环境和支持系统，而不是只靠愤怒或危机驱动；危机退去后仍能执行，才算内化。如果用户依赖对方反应来维持改变，可提醒他把改变连接到自尊、健康、孩子、职业等更稳定价值。', '["改变维持", "信任", "复发预防", "习惯保持", "关系模式", "内化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 248, now()),
(100249, '五种结果思维：关系选择不是只有修复或失败', '适用场景：用户把关系问题简化成“要么挽回成功，要么人生失败”，因此迟迟不敢看清现实。
核心观点：成熟决策需要把可能结果全部摊开，而不是只盯着最想要的一个结果。原材料把关系走向整理成多种结果，其可迁移价值在于：留下、离开、重建、接受现状、改变关系结构，都不是抽象口号，而是不同成本、风险和代价的组合。用户越能看见选项，越少被恐惧和沉没成本绑架。
咨询步骤：1）写出理想结果：我最希望怎样？2）写出现实可接受结果：如果理想达不到，什么仍可被我接受？3）写出不可接受结果：哪些状态继续一年会伤害我？4）为每个选项列成本：孩子、财务、身体、社交、心理、价值观、法律和安全。5）为留下和离开都做计划：留下需要哪些边界和复盘点；离开需要哪些资源和支持。
关键提醒：选择不是为了证明谁对谁错，而是为了让生活对自己有效。一个清醒选择的结果，即使不完美，也比在默认剧本里长期消耗更能恢复自主性。
App 端提示：可把五种结果简化为“修复、重谈、暂时接受、拉开距离、结束关系”五栏。每栏都写收益、代价、所需资源和最坏情况预案。此表也能帮助用户识别逃避：若每个选项都不愿承担成本，真正议题可能是害怕选择本身。先做预案，再做决定，能降低冲动选择。', '["关系决策", "风险评估", "选择成本", "自主性", "预案", "目标澄清"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 249, now()),
(100250, '安全基地：人只有感觉被接住，才有力气探索', '依恋并不是儿童才有的依赖，而是贯穿一生的安全调节系统。一个人感到安全时，会自然去探索、学习、工作和建立关系；感到危险、分离或失控时，会本能地寻找一个“更强、更智慧、可回应”的对象作为安全港。对 App 端知识库来说，这个概念可以转化为一条关系成长原则：先建立可获得性，再谈改变。可获得性不只是人在场，更是情绪上能回应、能看见、能稳定。咨询、伴侣沟通或亲子互动中，如果一方已经处于威胁感里，直接讲道理、催独立、要求改变，往往会让探索系统关闭。更有效的顺序是：先确认“我在这里、我听见你、这件事可以慢慢说”，再邀请对方看见选择和行动。安全基地的目标不是让人黏住关系，而是帮助人能在连接和自主之间灵活往返：难过时可以回来被安抚，恢复后又能重新走向世界。产品化时可做成“安全基地自检”：我现在是在探索模式还是求安全模式？我需要的是建议、陪伴、确认，还是实际保护？对支持者也可给出提醒：不要把依赖需求简单评价为不成熟，也不要把独立要求包装成冷漠；成熟关系是在需要时可求助，在稳定后能放手。若用户暂时没有可靠他人，也可引导建立微型安全基地，如稳定呼吸、身体接地、联系一位可信任的人、写下此刻可控的下一步。', '["依恋", "安全基地", "安全港", "亲密关系", "心理咨询", "情绪调节", "可获得性", "自主探索"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 250, now()),
(100251, '调谐沟通：一方发信号，另一方用行动回答', '安全型依恋的核心不是完美照顾，而是“信号—回应”的调谐循环：孩子清楚表达需要，照顾者读懂线索并做出相称回应，孩子被安抚后又能继续探索。迁移到成人关系与咨询场景，沟通质量不只看说了什么，还要看对方的信号是否被准确接住。一个人流泪、沉默、退缩、提高音量或反复追问，背后常有“我需要被看见、被安抚、被确认边界”的信号。有效回应不是把自己的节奏强加给对方，而是先校准：我听见你现在很紧，我猜这不是要吵赢，而是需要确定我没有离开；你希望我先陪你平静，还是一起想办法？调谐还包括及时放手：当对方已经恢复，不继续包办、不以关心之名控制。知识库可将其写成四步：识别信号、命名需要、给出相称回应、回头确认是否真的有帮助。这条知识也适合转成对话质量评分：对方的情绪有没有被命名？请求有没有被具体化？回应是否与需要相称？例如伴侣说“你根本不在乎我”时，表层像指责，底层可能是“我需要确认你还在乎”。如果直接辩解“我怎么不在乎”，互动会升级；若先回应“你现在像是很孤单，也很想确定我在”，才可能让对方的防御下降。调谐不是读心术，猜错也可以修正，关键是持续询问和校准。', '["调谐", "依恋沟通", "共情", "情绪信号", "关系修复", "亲子沟通", "伴侣沟通", "咨询技术"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 251, now()),
(100252, '回避与焦虑不是性格缺陷，而是早年求安全的策略', '回避型和焦虑/矛盾型依恋常被误解为“冷漠”或“太黏”，但依恋视角提醒我们：它们首先是适应策略。回避者曾学到表达需要可能得不到回应，甚至会被拒绝，于是降低痛苦外显，把注意力转向任务、理性或独处；表面平静不等于没有压力。焦虑者曾经历回应不可预测，于是放大信号、持续监测对方行踪和承诺，试图用高强度表达换取稳定。App 在给建议时应避免贴标签和责备，而要帮助用户识别策略背后的安全功能：我这样做是在保护什么？代价是什么？对回避倾向的人，可用低压、具体、可选择的邀请，尊重其自主；对焦虑倾向的人，要增加可预期性，如明确回复时间、说清边界，并同时练习自我安抚。目标不是消灭策略，而是让旧策略在新关系中有机会被更新。这能帮助知识库避免“你太回避”“你太焦虑”的二次伤害。更好的语言是：你的系统曾经学会用撤退/追问来减少危险，现在我们尝试更低成本的新方法。给回避者的练习可以是说出一个小需要，而不是一次性暴露全部脆弱；给焦虑者的练习可以是延迟一次确认冲动，同时用日程、承诺和自我安抚增强可预测性。双方都需要看见：策略背后有爱和恐惧，改变要靠安全经验累积，而不是靠羞耻驱动。', '["回避型依恋", "焦虑型依恋", "矛盾型依恋", "安全策略", "亲密关系", "自我保护", "关系模式", "情绪需求"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 252, now()),
(100253, '内部工作模型：亲密关系里运行的是“注意力规则”', '内部工作模型不只是“我对父母的记忆”，更像一套自动运行的注意力、记忆和解释规则：哪些信号会被看见，哪些感受会被允许，哪些证据会被忽略，哪些行为会被认为最能保住关系。安全型模型较开放，能随着新经验调整；不安全模型更容易把新关系硬塞进旧预期，例如把治疗师的短暂沉默理解为拒绝，把伴侣的迟回复解释为抛弃。知识库可将这一点转化为一种自助提问：此刻我最先注意到什么？我自动忽略了什么？我正在用哪条旧规则保护自己？这条规则当年可能有用，如今还准确吗？咨询中的改变往往不是给用户一个新道理，而是帮助他看见旧规则如何筛选现实，再通过小的安全例外让模型松动。关系成长的关键，是把“我就是这样”改写为“我学会过这样保护自己，现在可以多一个选择”。可将其设计为“旧规则捕捉卡”：触发事件是什么？我脑中立刻出现的解释是什么？它让我看见哪些证据、忽略哪些证据？如果把这条规则当作旧时的保护者，它当年在保护我免于什么？今天我能不能做一个小实验，收集相反证据？这种写法适合咨询作业、关系复盘和情绪日志。它也提醒支持者，不要急着要求用户相信新解释；旧模型之所以黏着，是因为它曾经维持过生存和亲近，必须在被理解后才可能更新。', '["内部工作模型", "依恋规则", "注意力", "认知模式", "关系误读", "心理咨询", "行为实验", "安全例外"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 253, now()),
(100254, '元认知安全：把感受当信号，不当最后判决', '依恋安全不仅体现在关系里，也体现在一个人能否对自己的心理状态保持反思。元认知能力让人知道：我现在的想法、感受和记忆是真实体验，但未必就是事实全貌；我的信念会变化，别人对同一件事也可能有不同而真实的感受。缺少这种能力时，人容易把一瞬间的情绪当作最终判决，比如“我感觉被抛弃，所以他一定不爱我”“我觉得自己很差，所以我就是失败者”。App 可以把它做成情绪急救句式：我注意到自己正在产生一个强烈解释；这个解释可能在保护我；我可以先不按它行动；我需要再收集三个事实。咨询师和支持者也要用元认知姿态回应，而不是急着反驳：你此刻的感觉很强，我们先尊重它，同时也给它一点空间，看看还有没有其他可能。这样的空间，常常就是从反射反应走向关系修复的入口。在产品中，这条可作为“情绪与事实分离”模块：先允许情绪存在，再把解释放在括号里。例句是：我很难过，这是事实；“他一定故意伤害我”是一个解释；我可以先照顾难过，再决定是否验证解释。它也适合帮助用户从关系绝望中退一步：此刻的我处在恐惧状态，所以世界看起来很窄；等身体平静后，我可能会看见更多信息。元认知不是冷冰冰地分析自己，而是用温柔的观察者位置，让情绪不必靠冲动行动来证明自己。', '["元认知", "反思功能", "情绪调节", "依恋安全", "关系误读", "认知松动", "自我觉察", "心理弹性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 254, now()),
(100255, '语言虐待的第一线索：不是脏话，而是持续让人失去现实感', '语言虐待常常不是一句明显的脏话，而是隐藏在反问、讽刺、否定、威胁、敌意和模棱两可信息里的攻击。它的伤害之一，是让受害者越来越不相信自己的感受：明明谈话后痛苦、困惑、失去方向，却又说不出“到底哪里不对”；明明被贬低、被忽视、被误导，却被对方说成太敏感、小题大做或没有幽默感。知识库在处理这类主题时，应把“感受”视为重要证据，而不是附属情绪。可提示用户记录三类线索：对方说了什么和做了什么；谈话后我的身体与情绪反应是什么；这种模式是否重复出现并让我更怀疑自己。识别语言虐待不需要等施虐者承认，也不需要旁观者完全理解。若一段关系持续让人失去现实感、自尊和表达能力，就需要把它从“沟通不好”升级为“可能存在伤害性权力模式”来评估。不建议让用户一开始就去搜集“对方是不是坏人”的结论，而是先保护现实感：把具体语句写下来，标注发生场景、是否有旁人在场、对方事后是否否认、自己是否反复想解释清楚。若记录显示同类互动反复发生，尤其总在私下发生、总让你怀疑自己、总把问题推回你身上，就要提高风险等级。知识库还应提醒：困惑本身就是线索，因为健康沟通即使有冲突，也不会长期让一方失去判断力和表达能力。', '["语言虐待", "现实感", "情绪证据", "关系伤害", "煤气灯效应", "自我怀疑", "识别红旗", "心理安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 255, now()),
(100256, '支配权力与个人权力：分清控制关系和合作关系', '语言虐待背后常有两种关系观的冲突：支配权力把关系看成输赢、上下和控制，个人权力把关系看成相互依存、共同发展和彼此尊重。前者需要通过压倒别人来获得安全感，后者允许双方都有感受、边界、请求和拒绝。这个区分很适合迁移到 App 的关系评估：一段关系是否允许共同制定目标？双方是否都能表达观点并被听见？拒绝是否会被尊重？成功是否会被祝福而不是被打压？如果每次沟通都变成谁对谁错、谁服从谁、谁证明自己没有错，用户就不应只从“我怎么解释得更清楚”入手，而要看见权力结构本身。对咨询和自助内容而言，关键不是鼓励用户赢回争论，而是恢复个人权力：知道自己的感受有价值，能清楚表达，能说不，也能在不被尊重时暂停或退出对话。当用户问“是不是我太敏感、太不懂沟通”时，这个框架能把焦点从个人缺陷转向关系结构。可以给出对照表：支配关系关心服从、面子和胜负；合作关系关心事实、感受和共同方案。支配关系里，解释越多，越可能被当作新的把柄；合作关系里，解释会带来更多理解和调整。若用户发现自己总在证明自己没有错、没有恶意、没有不合作，就需要暂停说服对方，先恢复个人权力：我能描述事实，我能保留感受，我能提出条件，我能选择离开。', '["支配权力", "个人权力", "合作关系", "控制", "边界", "伴侣关系", "自尊", "关系评估"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 256, now()),
(100257, '面对否认与讽刺：边界从“我知道自己感受是真的”开始', '在语言虐待关系中，受害者常试图用更多解释换来理解，但对方可能持续否认、嘲弄、假装道歉，或把伤害说成玩笑。此时最容易发生的陷阱，是把目标设成“让对方承认我的感受有道理”。更稳的边界起点是：我不需要先赢得对方批准，才能确认自己受到了伤害。App 可提供一个不争辩动机的表达模板：刚才你用嘲讽/吼叫/贬低的方式说话，我感到受伤和不安全；我愿意讨论事情本身，但不接受这种方式；如果继续这样说，我会暂停谈话，等双方能尊重地说话再继续。这个模板的重点是行为、影响和后果，而不是证明对方“故意伤害”。如果对方继续否认，用户要把它当作边界信息，而不是继续解释自己的纯真。边界不是让对方立刻改变，而是让自己不再被迫留在伤害性互动里。边界表达要短，因为长篇解释容易被对方带入新一轮否认。App 可建议用户提前写好三句：第一句描述行为，第二句说明影响，第三句给出后果。比如“你刚才用讽刺评价我的能力；我感到被贬低，也无法继续好好听；如果继续这样说，我会离开房间，晚些再谈。”之后要把注意力放在执行，而不是让对方承认。若对方愿意修复，再进入具体议题；若对方继续嘲讽、追击或倒打一耙，边界的意义就是帮助用户结束现场伤害。', '["边界表达", "语言虐待", "否认", "讽刺", "自我确认", "关系安全", "停止争辩", "沟通模板"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 257, now()),
(100258, '虐待型沟通的三组红旗：竞争、操纵、亲密关闭', '虐待型伴侣关系往往缺少显眼标志，因为施虐者可能在外人面前表现良好，甚至以关心的语气发出控制信息。可迁移的识别方法，是看三组互动红旗。第一，竞争取代合作：你的成绩、学习、工作或快乐被对方体验为威胁，谈话变成谁更高、谁更有理。第二，操纵取代交流：对方打断、转移、假装不懂、事后否认约定，或只在需要你帮忙时友善。第三，亲密被关闭：你们无法共同制定计划、无法平等交换意见，也很难分享真实情绪；每次你想澄清问题，最后都变成你反省自己哪里做错。知识库可将这三组红旗用于关系自检：如果长期不能共同讨论目标、不能安全表达感受、不能在外人不在时被尊重，那么问题不只是沟通技巧不足，而可能是权力和敌意正在破坏亲密。下一步应优先做支持系统、记录证据和边界计划，而不是继续单方面优化说法。该条可用于 App 的关系风险分层：偶发冲突看修复能力，长期红旗看结构稳定性。若一次争吵后双方能道歉、复盘、调整，那是普通冲突；若每次都由一方承担全部责任，另一方从不承认影响，且你的行动空间越来越小，就更接近伤害性模式。对这类用户，内容不宜只推“如何温柔表达需求”，还要提供外部支持、财务和居住安全、可信联系人、必要时的专业或法律资源等下一步清单。因为在权力失衡关系里，单纯提升沟通技巧可能让用户继续留在危险循环中。', '["关系红旗", "操纵", "竞争", "亲密关闭", "语言虐待", "伴侣关系", "权力模式", "安全计划"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 258, now()),
(100259, '高难沟通顺序：先安抚本能脑，再触达情绪，最后讲逻辑', '《感召力》把说服和领导力语言拆成三个层面：本能脑先判断安全与威胁，情感脑决定是否有动力，逻辑脑最后才处理理由。把这个模型迁移到心理咨询、伴侣冲突和亲子沟通中，一个常见错误是从逻辑开始：我为什么这么做、你为什么不该生气、事实其实是怎样。对方若已经感到被攻击，逻辑只会被当成辩解。更稳的顺序是先降低威胁：放慢语速、降低音量、说明共同目的、给出选择感；再触达情绪：命名对方的失望、害怕、委屈或愤怒；最后才进入事实、限制和下一步。可用一句话开场：“我不是来赢你，我想先确认你哪里受伤了，然后我们再一起看怎么办。”这不是讨好，而是尊重大脑处理信息的顺序。安全感不够时，道理很难进入；安全感恢复后，逻辑才有被听见的机会。产品化时可把它做成“冲突开场检查”：我的语气会不会让对方更紧？我有没有先说明不是来惩罚或否定？我有没有先听见情绪，再讲事实？它也能指导 AI 回复：先承接用户处境和身体感受，再帮用户整理情绪，最后提供结构化建议。对于咨询师或陪伴者，这个顺序能防止过早教育化。许多用户不是不知道道理，而是神经系统还处在警报中；当警报没有被看见，越正确的建议越像压力。', '["高难沟通", "本能脑", "情感脑", "逻辑脑", "安全感", "冲突降温", "伴侣沟通", "亲子沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 259, now()),
(100260, '移情—价值观—平衡：回应愤怒时的三段式', '当对方愤怒或失望时，直接解释政策、规则或现实限制，很容易被听成冷漠。《感召力》中处理棘手问题的序列可迁移为咨询和关系沟通模板：先移情，再价值观，最后平衡。移情不是同意对方所有判断，而是承认其情绪经验：“我理解你为什么会生气，这件事让你觉得被忽视。”价值观是找到双方仍然共享的方向：“我们都希望这段关系里能被尊重，也能把事情说清楚。”平衡才是补充现实：“同时，我不能在被吼叫时继续讨论；我们可以暂停十分钟再回来。”这个结构比“但是你也有问题”更容易保留连接，因为它先让对方感到被看见，再把边界和限制放进共同目标里。用于 App 时，要提醒用户避免假共情：如果移情只是铺垫反驳，对方会更防御；真正有效的是先认真进入对方视角，再温和而清楚地带入自己的立场。这个三段式还可以用于道歉和拒绝。道歉时：先承认“这让你很受伤”，再指出“我也重视信任”，最后说“我会怎样补救”。拒绝时：先承认“你很希望我现在答应”，再连接“我也希望我们关系里能诚实”，最后表达“但我这周做不到，我能提供另一个时间”。价值观部分尤其重要，它把双方从敌对位置拉回同一边；平衡部分则避免为了共情而牺牲边界。若只移情没有边界，会变成讨好；若只有边界没有移情，会像冷冰冰的判决。', '["移情", "价值观", "平衡", "冲突回应", "共情", "边界", "沟通模板", "高难对话"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 260, now()),
(100261, '隐喻、故事与成三：让表达被记住而不操控', '沟通不只是传递信息，也在塑造对方脑中的画面。《感召力》提醒，隐喻会悄悄分配角色：如果把组织比作机器或汽车，领导者像驾驶员，其他人就容易被放进零件位置；如果把改变比作种植、旅程或共同建造，听众更容易感到自己是有生命、有选择的参与者。心理咨询和关系成长内容尤其要谨慎选择隐喻：把用户称为“坏掉的人”会制造羞耻，把他称为“正在修复地图的人”“重新学习安全的人”则更有行动空间。故事也是人类默认的交流方式，它比抽象建议更能承载情绪和记忆；而三点式结构能让复杂建议变得完整、可执行。App 输出建议时，可把观点组织为一个温和隐喻、一个贴近日常的小故事、三个可实践动作。这样表达既容易被记住，又不靠恐吓或操控推动改变。在心理健康内容里，隐喻尤其影响用户身份感。说“你要战胜自己的脆弱”可能强化内在战争；说“你在学习和脆弱合作”会降低内耗。故事也不必宏大，可以是一个常见生活片段：一次迟回复、一次争吵后的沉默、一次敢于说不的练习。三点式则帮助用户把复杂情绪落地，如“先停下、再命名、后选择”。这条的伦理重点是：表达结构服务于理解和自主，而不是为了让用户被说服。好的心理教育让人更能做自己的决定，而不是更容易被话术牵着走。', '["隐喻", "故事", "成三原则", "表达结构", "心理教育", "沟通设计", "关系成长", "去羞耻"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 261, now()),
(100262, '成熟从停止“改变和指责模式”开始', '关系出问题时，人常在两端摇摆：把原因全放在对方身上，幻想“只要 TA 改变就好了”；或把别人的痛苦全揽成自己的失败，觉得“都是我不够好”。两者都看似有解释力，却把复杂互动简化成某个人的错，反而让成长停住。更成熟的入口不是替自己辩护，也不是自责，而是把注意力转回：我在这个循环里做了什么？我能负责什么？我如何在压力下不再自动反应？在咨询/自助场景中，可引导用户先描述互动链条：对方做了什么，我如何解读，我的身体和情绪如何升高，我采取了沉默、讨好、指责、拯救还是逃离，结果又怎样影响对方。这样，问题从“谁坏/谁对”变成“这个系统如何运转”。成熟不是自我抬高，而是在关系中承担自己那一份，减少无效反应，为他人也腾出成长空间。可迁移练习：冲突后写三栏——事实、我的反应、下一次我愿意做的一个更成人的动作。暂时少写“对方应该怎样”，除非它能转化为一个清楚、可商量、可被拒绝的请求。它还能防止咨询对话滑向审判：来访者既不需要被要求原谅，也不需要被鼓励继续控诉，而是被邀请看见自己仍有选择权。对高情绪用户，可先做稳定和安抚，再进入责任梳理；责任不是罪责，而是可改变的位置。', '["心智成熟", "关系模式", "责任边界", "自我觉察", "冲突修复", "情绪管理", "家庭系统", "咨询提示"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 262, now()),
(100263, '自我分化：在亲密联结中保持独立思考', '自我分化可以作为关系成长的核心能力：一个人既能和重要他人保持情感联结，又不把自己的立场、情绪和价值完全交给关系气氛决定。低分化时，人容易在两种反应间摆动：为了和谐而融合，压下真实想法；或为了保住自我而切断关系，表面独立、内心仍被对方牵动。较成熟的做法不是冷漠，也不是强硬，而是在紧张场景里继续表达自己，并允许对方不同意。App 可以把它拆成三个提醒：第一，先把“我真正相信什么、我想怎样做人”写清楚；第二，用平静语气表达立场，而不是用批评逼对方认同；第三，在分歧后仍维持基本联系，避免用消失、冷战或过度解释来缓解焦虑。自我分化特别适用于亲子、伴侣、职场和友谊冲突：用户需要的不是立刻赢得对方，而是在关系压力下不失去自己。分化越高，越能把“我爱你/我在乎你”和“我有不同选择”同时放在关系里。这一能力也能降低“边界=疏远”的误解。分化不是把别人推出去，而是让关系容得下两个真实的人。练习时可以从低风险关系开始：先表达一个小偏好，观察自己是否会因对方失望而过度补偿，逐步训练承受分歧的肌肉。最终评估标准不是对方是否满意，而是自己是否更清楚、更稳定、更少被卷入旧循环。', '["自我分化", "亲密关系", "独立思考", "情感联结", "边界", "原生家庭", "冲突沟通", "成熟人格"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 263, now()),
(100264, '辨认真成熟与假成熟：认同和反叛都可能是在借用自我', '假成熟常常很像能力：会照顾人、会讲道理、能在公共场合表现出色、能赢得赞许，甚至能以叛逆姿态显得很有个性。但如果这种成熟依赖他人的认同，或依赖与某个人、某个群体对着干，它就不是稳定的内在立场，而是“借来的成熟”。一旦关系不稳定、弱点被看见、期待落空，个体就可能迅速讨好、疏远、愤怒或崩溃。真成熟的检验不在顺境，而在紧张和无人喝彩的场合：能否继续按价值观行动，能否清楚表达而不专横，能否忍受自己和他人的不适，能否反思自己的部分而不把责任全推给别人。App 可用此条帮助用户识别“我是在做自己，还是在维持人设”。提示问题包括：这个决定如果没人夸我，我还会做吗？如果对方不赞成，我是否立刻改变或故意反着来？我现在的强势/脆弱，是事实，还是为了影响别人？成熟不是表现得完美，而是在不同关系场景里越来越一致地承担责任。这条尤其适合成就型、讨好型或长期被比较的用户：他们可能非常能干，却在亲密关系中失去方向。后台可将“假成熟”识别为一种压力反应，而非人格缺陷；目标不是拆穿用户，而是帮助其把外部评价转回内在原则。它也能提醒内容生成避免用“强大人设”替代真实成长。', '["假成熟", "真自我", "人设", "认同需求", "反叛", "价值观", "自我一致性", "关系压力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 264, now()),
(100265, '三角关系：别把两个人的紧张交给第三方解决', '当两个人之间的紧张难以承受时，最容易出现第三方：向朋友抱怨伴侣、让孩子承接夫妻焦虑、让父母或同事替自己站队、把症状或问题行为变成家庭共同关注的焦点。第三方能短暂降压，却常让真正的关系问题停留在原处，还把负担转移给无关者。识别三角关系的信号包括：我是否不断向不在场的人诉苦，却不和当事人谈？我是否成了调解者、拯救者、盟友或替罪羊？两个人是否因为共同担心我而避免面对彼此？更成熟的方向不是突然断开第三方，而是把谈话带回该发生的关系中：与当事人直接、具体、温和地沟通；向第三方倾诉时少寻求站边，多整理自己的反应；如果自己被卷入别人冲突，先问“这件事谁才是应该直接面对的人”。在家庭、伴侣和职场中，退出三角关系能减少误解，也能让每个人重新承担自己的那一份成熟任务。在 App 场景里，它可作为“倾诉后的下一步”提示：倾诉可以帮助降温，但如果只停留在倾诉，会让问题固定。更有建设性的倾诉，是请第三方帮助自己准备一次直接沟通，而不是请第三方证明自己完全正确。若直接沟通暂时不安全，也可以先做计划、求专业支持，而不是让无关者长期承压。', '["三角关系", "家庭系统", "伴侣冲突", "亲子关系", "站边", "拯救者", "关系边界", "直接沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 265, now()),
(100266, '离家独立不是逃离或依赖，而是带着真实保持联结', '成年后的独立不只是搬出去、经济自理，或减少联系。若一个人仍无法在父母面前表达不同意见，仍靠报喜不报忧维持认可，或只用义务式探望维持表面和平，他在情感上可能仍停留在未完成的离家阶段。另一端是“逃离”：把父母贴上不可理喻的标签，用疏远证明自己独立，却在相似亲密关系中继续被旧反应触发。更成熟的离家，是在联结和自主之间建立新平衡：能关心父母，但不替他们生活；能听取意见，但不把选择权交出去；能说出真实感受，但不用攻击来宣告边界。App 可把这一条用于成年亲子关系：当用户想断联、爆发或继续讨好时，引导其区分“关心”和“照顾/拯救”，写下自己愿意做与不愿意做的范围，再用尊重但清晰的语言表达。真实比表面和谐更重要，因为一个人若能在原生家庭的强情绪场中保持稳定，通常也更能在伴侣、亲子和职场关系中保持成人姿态。这也能帮助父母端用户：孩子独立不是对爱的否定，父母需要管理自己的失落和担忧，而不是用建议、金钱或内疚维持控制。成熟的亲子关系会从“谁听谁的”转向“两个成年人如何相互尊重”。它也承认某些家庭需要安全距离；成熟的重点是清醒选择，而不是被恐惧或义务自动推动。', '["离家独立", "成年亲子", "原生家庭", "真实表达", "情感联结", "责任范围", "边界", "自主"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 266, now()),
(100267, '单身期是内在安定训练场，而不是等待被拯救的空档', '单身并不等于缺少关系价值，它提供了练习自我安定、责任和方向感的窗口。若一个人把恋爱、社交媒体、购物、酒精、暧昧或被关注感当作主要镇静剂，亲密关系就会掩盖尚未发展的内在能力：独处时无法放松，焦虑时必须有人回应，人生选择被“是否有人爱我”左右。更成熟的单身期，是学习用自己的身体和理性资源管理不确定：呼吸、运动、规律作息、财务整理、职业探索、友谊经营、价值澄清，以及区分已知风险和未知恐惧。App 可将“扫描—诊断—解决”的焦虑循环转化为觉察工具：我是在处理已经发生的问题，还是在寻找未来灾难的证据？我现在想联系某个人，是为了真实交流，还是为了让自己立刻安心？这一条也适用于离婚、丧偶、空窗期和关系冷静期。单身阶段的目标不是变得不需要任何人，而是在进入亲密关系前，先不把自己的稳定完全外包给别人。它也能减少对单身用户的隐性羞辱：单身不是失败状态，而是一个可主动使用的发展阶段。若用户渴望关系，可把重点放在“我想带着怎样的自己进入关系”，而不是“谁能让我不再焦虑”。这样的表达能同时支持渴望亲密和练习独立，避免把二者对立起来。', '["单身成长", "自我安定", "焦虑管理", "亲密依赖", "内在资源", "关系选择", "自我负责", "价值澄清"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 267, now()),
(100268, '伴侣关系的成熟悖论：少改造关系，多承担自己的部分', '很多伴侣以为关系改善的关键是“让对方终于明白”。但亲密关系里最有转化力的起点，往往是停止把全部精力放在伴侣身上，转而整理自己在循环里的贡献。常见弯路有三条：冲突与疏远的舞蹈，用争吵获得联结、再用冷淡获得距离；跷跷板模式，一方过度掌控，另一方逐渐无力；三角关系，把孩子、父母、朋友或外遇卷进两人的紧张中。成熟不是忍耐一切，也不是强势纠正，而是能说“我累了，需要十五分钟恢复，之后我来处理厨房”，能减少替对方做决定，能不让孩子成为夫妻矛盾的缓冲垫。App 可在伴侣冲突后引导用户识别：我是在攻击、退缩、支配、迁就，还是求第三方站队？我下一步能承担哪一个具体责任？当一方稳定地改变自己的反应，关系环境就会改变，另一方也会被迫重新调整。亲密不是没有差异，而是两个不完美的人都愿意在差异中更负责任地做自己。这条不意味着把关系问题都归给自己，也不要求留在伤害性关系中。它强调在安全前提下寻找自己的可行动点：停止升级冲突、明确分工、减少讽刺、按时回来沟通、直接提出需要。成熟改变通常细小、重复、可观察。因此，后台知识可优先生成“我能做什么”的句式，而不是“如何让对方改变”的控制脚本。', '["伴侣关系", "婚姻成长", "冲突循环", "跷跷板模式", "三角关系", "责任分担", "亲密与自主", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 268, now()),
(100269, '成长型助人：陪伴痛苦，但不接管对方的人生功能', '无效帮助常披着善意外衣：急着给建议、替对方分析所有人、站在 TA 这边批评不在场的人、帮 TA 消除痛苦，或把自己变成修复者。短期内，这会让受助者感到被理解，也让助人者感到重要；长期看，却可能加深依赖、制造三角关系，并剥夺对方练习解决问题的机会。成长型助人的关键，是既不逃避痛苦，也不过度接管。助人者可以稳定陪伴、认真倾听、询问过程，而不是急于下结论：问题从什么时候开始？涉及谁？你当时怎么回应？对方又怎么回应？哪些做法短期有用、长期无用？你能负责的下一步是什么？这种“研究者立场”能帮助对方从抱怨内容转向关系模式，看到自己可行动的位置。App 端可用于咨询师提示、朋友倾诉、父母支持孩子、管理者带团队：真正的支持不是让对方永远需要你，而是尊重其能力，留出空间，让对方在关系中恢复思考、选择和承担。对普通用户，它也能修正“我必须给出答案才算有用”的压力。很多时候，稳定地在场、问好问题、相信对方有能力，比立刻提供方案更有帮助。助人者若感到疲惫或怨恨，常是已经越过了自己的功能边界。这能保护双方：受助者保有主体性，助人者也不把价值感绑在拯救成功上。', '["助人者", "咨询关系", "不过度帮助", "依赖", "倾听", "研究者立场", "关系模式", "支持系统"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 269, now()),
(100270, '习惯是神经路径：重复会保存我们的反应方式', '詹姆斯把习惯理解为可塑性留下的路径：水流反复经过会加深沟渠，纸折过一次再折更容易，神经系统也会因重复而更容易走旧路。对自我发展而言，这意味着“我就是这样的人”常常不是本质判决，而是长期重复后的省力路径。抱怨、拖延、讨好、睡前刷手机、冲突时沉默或爆发，都可能因一次次被使用而变得自动；同时，运动、写情绪记录、暂停十分钟、清楚表达请求，也能因重复而变得省力。App 可把此条转化为温和但有力量的提示：每一次反应都在训练下一次更容易发生的自己。改变不是靠一次顿悟，而是通过新的微小通道反复被使用，逐渐让旧通道阻力变大、新通道阻力变小。它也提醒用户不要轻视“偶尔一次”：在脆弱时重走旧路会强化旧模式，而在小事上练习新回应，会给重大压力时的自己预先铺路。这条可作为复盘语言，帮助用户从羞耻中出来：旧习惯之所以强，不是因为你坏，而是因为它被训练得太熟；新习惯之所以难，也不是因为你没救，而是因为路径还浅。把改变看作铺路，会比把改变看作意志审判更可持续。因此，知识库应把“下一次更容易”作为习惯反馈的核心语言。而且越早练习越省力。', '["习惯", "神经可塑性", "行为改变", "自动反应", "微行动", "情绪调节", "自我训练", "复发预防"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 270, now()),
(100271, '改变习惯的四个抓手：强开端、不断链、立刻行动、每日小训练', '关于习惯改变，詹姆斯给出一组非常适合应用化的原则。第一，新习惯开始时要让动机尽量强：安排环境、公开承诺、减少诱惑，让第一步有足够推力。第二，在新习惯稳固前不要轻易重返旧习惯；每一次“破例”都像把卷好的线球松开，会削弱之前积累的神经优势。第三，决心必须尽快落到行动，否则情绪和愿望只在内心消散，反而训练出“想很多但不做”的习惯。第四，每天在小事上练一点自我管理：做一件不太想做但有益的事，拒绝一个不必要的冲动，保持一次专注。它们像给未来的压力买保险。App 可把这四点设计成习惯卡：今天的承诺是什么？我如何让环境支持它？我是否避免了最小破例？我有没有在 2 分钟内做出实际动作？这种方法不鼓励苛责，而强调连续、可执行和及时反馈。长期来看，性格不是空洞标签，而是被无数小行动塑造出来的行动倾向。当用户失败时，也可以用这四点定位问题：是开端动机不够强，环境仍在诱发旧习惯，还是决心没有转化为动作？修正设计比责骂自己更重要。所谓自律，是把有益行动训练到不必每天重新谈判。这也适合做成复盘模板，而不是只做打卡提醒。', '["习惯改变", "行为设计", "承诺", "不断链", "立即行动", "自律", "小训练", "行动倾向"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 271, now()),
(100272, '注意力选择塑造经验：发生过不等于真正进入生命', '詹姆斯强调，经验并不是外界原样进入心灵；感官和注意力会不断选择、强调、排除。一个事物可能出现一千次，如果从未被注意，它就很难成为个人经验；同一趟旅行，不同人会记住风景、价格、社交活动或自己的情绪，因为他们的兴趣不同。对心理成长而言，这能解释为什么一个长期关注威胁的人会觉得世界充满危险，一个总扫描缺点的人会在关系里不断找到证据，一个练习感恩和资源觉察的人更容易看见支持。App 可将此条用于焦虑、抑郁和关系误读：不是要求用户“积极思考”，而是邀请其检查注意力的取样方式。今天我自动寻找了什么证据？有没有被我忽略但同样真实的线索？我是否把单一刺激提升成了全部现实？注意力不是单纯的聚焦工具，它会参与建构用户的世界。训练注意力，就是训练一个人能从同一处现实中看见更多维度，从而拥有更多行动选择。这也解释了为什么同一段关系中，双方会拥有不同“事实感”。他们并非必然有人撒谎，而是注意力长期选择了不同线索。沟通时若能交换“我注意到了什么、我忽略了什么”，就比争夺唯一真相更容易靠近彼此。因此，注意力训练本质上也是关系训练和情绪训练。', '["注意力", "选择性知觉", "经验建构", "焦虑", "认知偏差", "资源觉察", "关系误读", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 272, now()),
(100273, '意识流：当下体验不是固定事实，而是不断变化的整体', '“我现在就是这样想的”并不等于一个永恒事实。詹姆斯反对把意识切成一个个静止颗粒，指出思想更像连续流动的河：同一对象在不同时间、身体状态、情绪背景和过往经验中，会被体验为不同的东西。困倦、饥饿、疲惫、低落、刚经历冲突或刚获得支持，都会改变我们对同一句话、同一个人、同一件事的感受。对 App 来说，这一条可用于降低情绪结论的绝对性：当用户说“我彻底完了”“TA 一定不在乎我”“我永远做不到”时，可以提醒这可能是此刻意识流中的高峰，而不是最终判决。更有效的提问是：此刻的身体状态是什么？这个想法带着哪些刚刚发生的背景？如果睡一觉、吃点东西、和可信的人聊过，再看它会不会不同？意识流也意味着改变有入口：不是强行否认感受，而是承认感受会流动，并通过休息、行动、书写、对话和环境改变，为下一段意识提供不同条件。它还适合危机降温：先不急着解决人生，只处理这一段意识流的条件。喝水、离开刺激源、放慢呼吸、写下想法、延迟重大决定，都是给下一段体验创造不同入口。等浪头过去，再讨论价值、边界和行动。这能把用户从绝对化判断中带回可观察的当下。', '["意识流", "情绪流动", "认知解离", "情绪管理", "身体状态", "自我观察", "危机降温", "心理弹性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 273, now()),
(100274, '情绪评分先行：先把低落从一团雾变成可追踪数据', '伯恩斯的认知疗法入口不是立刻讲大道理，而是先把情绪变成可观察数据。App 端可引导用户用 0-100 分记录低落、焦虑、愤怒、羞耻、内疚、无望等强度，并标注过去几天的变化、睡眠、活动、社交和压力事件。这样做有三个价值：第一，用户会发现情绪不是永久身份，而是会波动的状态；第二，后续练习能比较前后分数，避免只凭“我还是很糟”否定进步；第三，当分数长期很高、出现明显功能受损或危机信号时，系统能把自助建议升级为更稳妥的支持路径。评分不是诊断，而是让 App 回答从泛泛安慰转为“当前强度—触发因素—可做小步骤—复盘效果”的闭环。', '["伯恩斯", "情绪评分", "认知疗法", "自我监测", "情绪管理", "低落", "复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 274, now()),
(100275, '感觉不是事实：先找自动想法，再处理情绪', '当用户说“我感觉自己没价值”“我感觉对方一定讨厌我”时，App 不应直接把感觉当事实，也不应粗暴否定。更好的处理是把“感觉—想法—事实”拆开：我现在的身体和情绪感觉是什么；脑中自动冒出的句子是什么；可观察事实支持什么；有哪些事实并不支持；如果朋友遇到同样处境，我会怎样解释。伯恩斯反复强调，情绪常由我们对事件的解释触发，改变解释不是装作没事，而是把“我感觉如此”改写成“我正在产生一个想法，它需要证据检验”。这能帮助用户从被情绪裹挟，转向拥有一点观察距离。', '["自动想法", "感觉不是事实", "认知重评", "事实核对", "情绪调节", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 275, now()),
(100276, '十类认知扭曲：把“我完了”拆成可检验偏差', '强烈低落时，用户的语言常会出现固定偏差：非黑即白、以偏概全、心理过滤、否定积极、跳结论、放大缩小、情绪化推理、应该化、贴标签、个人化。App 可以把这些作为识别模板，而不是评判用户“想错了”。例如“我一次失败，所以我永远不行”包含以偏概全；“对方没回消息，所以一定不在乎我”包含读心和跳结论；“我必须让所有人满意”包含应该化。提炼的方向是：先标出偏差类型，再问证据、反例、替代解释和下一步实验。认知扭曲清单的价值在于降低羞耻：问题不是“我这个人坏”，而是“我的大脑在压力下用了过度简化的解释”。', '["认知扭曲", "非黑即白", "以偏概全", "读心", "贴标签", "个人化", "认知疗法"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 276, now()),
(100277, '消极思维日志：把脑内缠斗搬到纸上处理', '消极念头在脑内转动时会显得很有力量，因为它们速度快、彼此勾连、带着情绪。伯恩斯建议把它写下来：触发事件是什么；自动想法原句是什么；对应情绪强度多少；这句话包含哪些认知扭曲；更平衡的回应是什么；重新评分后情绪是否下降。App 可把它做成问答模板，尤其适合反复自责、拖延、社交挫败、关系误读。关键要求是写“原句”，不要只写概括；回应也不能强行积极，而要可相信、可检验、可行动。这样用户不再和一团情绪搏斗，而是在纸面上逐条拆解：哪些是事实，哪些是推断，哪些是旧信念。', '["消极思维日志", "自动想法", "认知扭曲", "理性回应", "情绪记录", "书写练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 277, now()),
(100278, '每日活动计划：低动力时先恢复掌控与休闲比例', '低落和无力会让人等待“有心情再行动”，但长期等待会让生活越来越窄。每日活动计划把一天按小时拆开，先写目标，晚上写实际结果，并给每项活动标注掌控感 M 与愉悦感 P。它的重点不是逼用户完美执行，而是恢复两类体验：我还能完成一点事；我仍可以安排一点滋养。App 可建议用户先安排极小任务，如起床、洗漱、下楼、整理桌面、给朋友发一条消息，同时加入休闲和恢复，而不是把计划表变成新的自责工具。复盘时看趋势：哪些活动略微提升分数，哪些过度消耗，明天如何调整。', '["行为激活", "每日活动计划", "掌控感", "愉悦感", "低动力", "抑郁自助", "复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 278, now()),
(100279, '反拖延表：用预测—行动—实测打破“太难没用”', '拖延常被两种预测喂养：任务会很难；做了也没满足感。反拖延表要求用户先把任务拆成 15 分钟以内的小步骤，再分别预测难度和满足程度，完成后记录实际难度和实际满足程度。很多人会发现，大脑在开始前高估痛苦、低估回报。App 可把这个模型用于求职、学习、整理、沟通准备和健康行动：不是问“你为什么这么懒”，而是问“你预测它有多难？先做哪一步？做完实际多少分？”当数据反复证明预测不准，行动阻力会下降，自信来自证据而不是鸡血。', '["拖延", "反拖延表", "行为实验", "任务拆分", "难度预测", "满足感", "行动启动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 279, now()),
(100280, '快乐预测表：用实验松动“独处一定痛苦”', '许多关系低谷中的用户会相信：一个人做什么都没有意义，只有被爱、被陪伴、被关注才会快乐。快乐预测表把这个信念变成实验：列出可能带来成就感或愉悦的活动，标注独自完成或与他人完成，先预测快乐分数，做完后记录实际分数。它不是鼓励孤立，而是帮助用户发现快乐来源不只依附于某个人。App 可在失恋、孤独、周末低落、依赖关系中使用：安排 2-3 周小实验，比较独处和共处的真实体验，再据此规划生活。这样自尊会从“对方有没有选择我”逐步转向“我能不能照顾自己的生活”。', '["快乐预测表", "独处", "依赖", "行为实验", "自我照顾", "失恋修复", "愉悦感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 280, now()),
(100281, '语言柔道：面对自我批评，先移情再反馈协商', '伯恩斯把应对批评比作“语言柔道”：不硬碰硬反击，也不全盘吞下。App 可把它转成三步：第一，移情，先准确复述批评里可能合理的部分，让对方感觉被听见；第二，反馈，说出自己的事实、感受和边界；第三，协商，提出下一步如何修正、核对或合作。这个结构同样可用于自我批评：当内在声音说“你真没用”，先承认“我确实没完成这件事”，再反馈“这不等于我整个人没价值”，最后协商“下一步只做 10 分钟”。它能把羞耻和防御，转为具体修复。', '["语言柔道", "批评应对", "移情", "反馈", "协商", "自我批评", "冲突修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 281, now()),
(100282, '愤怒规则重写：减少“应该”，才能降温关系冲突', '愤怒常来自内心规则被违反，例如“对方应该立刻理解我”“我付出就必须被同等回报”“家人就应该按我的方式爱我”。这些规则有时听起来合理，却会把关系变成高压控制。伯恩斯建议冷却愤怒想法、重写规则、减少“应该”，把绝对命令改成现实期待：我希望对方这样做；我可以清楚请求；对方不配合时我仍能保护自己；改变自己反应通常比控制他人更可行。App 可在伴侣、亲子、职场冲突中引导：这条规则是否现实？是否可协商？如果对方不满足，我能做什么边界行动，而不是只靠怒火施压？', '["愤怒管理", "应该化", "规则重写", "边界", "关系冲突", "认知重评", "谈判"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 282, now()),
(100283, '明智控制：少惩罚，多奖励可观察的合作行为', '在关系里，人们常用冷战、指责、讽刺、撤回亲密来“让对方改变”，但惩罚容易制造怨恨和防御。伯恩斯引用行为改变思路，强调用可观察记录和奖励机制影响互动：先确定自己真正想增加的行为，例如主动沟通、按时分担、尊重边界；再在对方出现目标行为时给予明确肯定；对破坏性行为减少奖赏、保持边界，而不是升级惩罚。App 应避免把这写成操控技巧，而要强调合作、透明和自我负责：我能改变的是自己的反馈模式，不能保证控制对方。关系改变要看数据：目标行为频率是否增加，双方是否更愿意协商。', '["行为强化", "关系改变", "奖励机制", "冲突降温", "合作", "边界", "反馈回路"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 283, now()),
(100284, '垂直箭头法：从表层想法挖到真正卡住人的隐性假设', '表层想法常只是入口，例如“这次没做好”。垂直箭头法继续追问：如果这是真的，为什么那么糟？它说明我是什么样的人？我最怕出现什么后果？连续追问后，隐藏信念会浮现，如“我必须完美才有价值”“别人不认可我就说明我不值得爱”“失败一次就没有未来”。App 可用这种方法做深层概念化：不要急着安慰表层事件，而是找出反复制造痛苦的假设。找到后再做两件事：评估这个假设的代价与功能；设计一个更灵活的新信念和小实验。这样用户处理的不只是一次情绪，而是长期脚本。', '["垂直箭头法", "隐性假设", "核心信念", "自我价值", "认知疗法", "深层信念"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 284, now()),
(100285, '认同上瘾：把自尊从别人评价里慢慢收回来', '认同需求本身正常，但当用户必须持续获得赞同才觉得安全，就会形成“认同上瘾”：一个眼神、一句批评、一次拒绝就足以摧毁情绪。伯恩斯提醒，别人的评价只有在用户自己先相信时，才会真正定义自我价值。App 可帮助用户区分三层：别人说了什么；这句话是否有事实依据；我是否把它上升成“我整个人没价值”。练习方向不是变得不需要任何人，而是发展独立自尊：可以听取反馈、修正行为，同时不把人格价值交给他人投票。对讨好、回避冲突、关系依赖的用户，这是一条关键成长线。', '["认同上瘾", "自尊", "他人评价", "讨好", "独立自尊", "关系依赖", "批评应对"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 285, now()),
(100286, '工作不等于价值：把自尊从单一成就指标中解套', '许多用户把工作、收入、头衔、效率和社会认可等同于个人价值，因此一旦失业、被批评、晋升失败或产能下降，就会迅速陷入羞耻。伯恩斯把“工作是否等于价值”单独成章，适合提炼为 App 知识：成就是重要生活领域，但不是价值的全部来源。用户可以建立四类支点：稳定行为，如守信、学习、照顾身体；关系贡献，如真诚、支持、边界；内在品质，如好奇、勇气、善意；成长过程，如从错误中修正。这样工作挫败仍然痛，但不会直接导向“我这个人失败”。App 回答时要把职业复盘和人格价值分开。', '["自尊", "工作价值", "成就焦虑", "职业挫败", "羞耻", "价值澄清", "人格价值"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 286, now()),
(100287, '完美主义处理：允许平凡，减少非此即彼的自我评价', '完美主义表面上追求高标准，内核常是恐惧：只要不完美就没有价值。它会让用户拖延、过度准备、害怕暴露、无法享受成果，也会把普通错误解释成失败人格。伯恩斯的处理方向不是劝用户“随便做”，而是把标准改成现实、渐进、可修正：给任务设最低可交付版本；把错误当数据；允许 70 分先行动；用“进步、学习、影响”替代“完美、证明、赢”。App 可提醒用户识别非此即彼语言：必须、永远、彻底、完蛋、毫无意义。成熟的高标准应服务生活，而不是把人困在自责和停滞中。', '["完美主义", "非黑即白", "行动启动", "自责", "高标准", "自我接纳", "拖延"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 287, now()),
(100288, '绝望时的保护流程：先评估冲动，再扩大连接与时间窗口', '当用户表达“活不下去”“没有意义”“想消失”时，App 不能只做认知重评，应先进入保护流程。伯恩斯在绝望章节中把“选择活下来”和评估冲动作为单独主题。可迁移为四步：第一，询问冲动强度、计划具体性、可获得手段和是否独处；第二，立刻扩大连接，联系可信任的人、专业支持或当地紧急资源；第三，把时间窗口缩短到“先安全度过接下来 10 分钟/1 小时/今晚”；第四，再处理绝望想法，如“痛苦会永远持续”“没有任何人能帮我”“我只会拖累别人”。危机知识库的重点不是替代专业干预，而是让 App 在高风险信号下优先稳定、连接和升级。', '["危机支持", "绝望", "自杀冲动评估", "安全计划", "连接支持", "认知疗法", "情绪急救"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 288, now()),
(100289, '谈判前先画局势地图：目标、底线、路径与预案', '核心意思：重要沟通不要从“我要怎么说”开始，而要先把局势画成一张可执行地图。先确认自己究竟要达成什么结果：是拿到信息、建立信任、争取资源、确认合作，还是决定退出；再写清楚成功标准、时间节点、可让步范围和不可突破的底线。
使用方法：1）列出现状、目标状态、关键利益相关方与决策链条；2）区分核心利益、可交换条件、情绪诉求和表面立场；3）标出信息缺口，例如对方真实预算、风险顾虑、授权边界、时间压力；4）预设 A 路径与 B 方案，包含关键节点、可能阻力、第一步动作、责任人和复盘时间；5）提前设计退出机制，避免在现场被情绪或沉没成本绑架。
App 端可做成“沟通前卡片”：我想要的结果是什么？最低可接受结果是什么？哪些信息必须确认？如果对方拒绝，我的替代方案是什么？这张卡片会把模糊焦虑转成可检查项目。边界提醒：规划不是为了控制别人，也不是追求百分百确定。它的作用是在信息不完整时减少误判，让你知道哪些地方可以灵活，哪些地方必须守住。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["谈判准备", "信息结构", "目标设定", "底线", "风险预案", "决策"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 289, now()),
(100290, '开合节奏：该透露的信息先开，该保护的底线及时合', '核心意思：有效沟通不是“全说”或“不说”，而是管理信息释放的节奏。“开”是释放足够信息，让对方愿意表达、愿意合作；“合”是收束边界，把讨论聚焦到当前最重要的问题，避免过早暴露底牌或让话题失控。
使用方法：开局时先释放低风险信息，例如自己的基本关注点、合作意愿、可讨论范围，常用句式是“我想先了解你的真实关注点”“我们先确认彼此期待”。观察对方反应后，再决定是否深入。收束时把范围限定到少数核心议题，例如“先把讨论聚焦在预算和交付两个问题上”“具体条款我们内部评估后再确认”。
判断标准：如果对方愿意补充细节、提出条件或追问下一步，可以适度继续“开”；如果对方开始回避、泛泛表态或情绪紧绷，要及时“合”，减少信息密度并确认边界。适用场景包括会议发言、商务谈判、新关系建立、亲密关系中的边界协商。边界提醒：开合不是故弄玄虚，也不是诱导对方入套，而是在透明与谨慎之间找到合适比例，让信息流动服务于共同判断。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["沟通节奏", "信息释放", "边界", "谈判开局", "职场沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 290, now()),
(100291, '留白观察：用反应窗口获得比追问更多的信息', '核心意思：很多关键信息不是从对方的答案里直接出现，而是出现在停顿、补充、回避、反问、情绪变化和回应速度里。留白不是被动沉默，而是有目标地创造观察窗口：先看对方怎么动，再决定自己怎么回应。
使用方法：1）提出轻量问题后暂停，不急着解释或补充；2）观察回应速度、语气、用词、表情、身体姿态，以及对方是否主动追问细节；3）把反应分为三类：真实兴趣（主动追问、提出具体场景、分享经验）、礼貌回应（泛泛认可但不深入）、隐性抗拒（长时间沉默、转移话题、顾虑过多）；4）根据状态调整：积极就推进，谨慎就降低压力，抗拒就暂时撤退。
练习方式：在一次重要对话里，刻意把自己的第一反应延后 2-3 秒，记录对方是否补充新信息。复盘时不要只看“说了什么”，还要看“什么时候说、用什么语气说、说完后是否继续投入”。边界提醒：留白必须有时间限度和判断目标，不能变成冷处理。它的价值是帮助你降低误判，而不是用沉默惩罚对方。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["倾听", "观察反馈", "提问", "低压力沟通", "情绪信号"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 291, now()),
(100292, '轻问题试探：把“我再考虑”拆成可验证的真实顾虑', '核心意思：对方说“我再考虑一下”时，不要立刻理解为拒绝，也不要继续硬推。它可能代表价格阻碍、风险担忧、信任不足、授权不够或决策链条未清。更稳妥的做法是把模糊话语拆成几个可验证假设，再用轻问题逐一测试。
使用方法：先记录对方的具体用词、停顿、语气和反复提到的主题；再提出假设性问题降低压力，例如“如果预算控制在这个范围，哪个环节你最担心？”“假设我们先从小项目开始，你们团队配合度如何？”“如果时间调整到 X，你的接受度会怎样？”观察对方是给出具体顾虑、继续回避，还是开始谈条件。
判断线索：反复谈预算，多半是价格或价值感问题；询问保障、失败案例和试用，多半是风险顾虑；要求资质、客户反馈或更高层背书，常与信任不足有关。边界提醒：试探不是审问，不连续追问同一话题，不触碰隐私底线，也不把获得的信息用于要挟。好的试探是轻触即止：得到足够信号后及时收束，再决定推进、降压或退出。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["提问", "意图识别", "顾虑验证", "谈判中场", "低成本试探"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 292, now()),
(100293, '从意向到承诺：把模糊好感锁定为下一步行动', '核心意思：沟通推进的关键不是让对方说“不错”“可以考虑”，而是把模糊意向转化为可执行动作。真正的推进包含五个台阶：初步认可、价值确认、明确承诺、条件锁定、实际动作。每一步都需要验证对方真实状态，不能跳级催促。
使用方法：先确认共识：“我理解你的核心关注是 X 和 Y，我们在这个方向上一致吗？”再锁定下一步：“具体来说，下一个动作是什么？谁负责？”最后给时间锚：“我们什么时候再确认进展？如果遇到阻碍如何调整？”在项目、合同、关系升级中，都要把“以后聊”“原则上同意”改写成“下周三前给答复”“周五确认条款”“每月固定复盘”。
App 端可以提示用户把每次对话后的成果写成三行：已达成的共识、下一步行动、复盘时间。若三行写不出来，说明只是情绪上变近了，尚未形成行动承诺。边界提醒：推进不是逼定。只有在信任基础、价值交换和风险说明足够时，行动承诺才稳定。若对方仍有核心顾虑，先回到验证和消除风险，而不是施压。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["承诺", "行动锚点", "推进节奏", "关系协商", "时间节点"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 293, now()),
(100294, '价值交换与影响力：先证明真实价值，再谈深度绑定', '核心意思：稳定影响力来自真实价值交换，而不是控制、讨好或制造依赖。先让对方看见你能解决什么具体问题，再通过持续兑现价值建立信任，最后才谈长期合作、资源投入或更深层关系绑定。
使用方法：先做吸引点自查：我的核心价值是什么？我能为对方解决什么具体问题？对方现在最需要什么？我的资源、专业、经验或性格优势是否能精准匹配？随后检查关系升级条件：对方是否主动回应、是否认可价值、是否愿意投入时间或资源、是否出现共同成长的可能。团队领导、商业伙伴、内容获客、亲密关系都适用。
阶段判断：价值吸引解决“为什么要接近你”，情绪连接解决“跟你合作是否舒服”，利益绑定解决“双方是否都愿意投入”，深度影响解决“能否持续共创”。任何阶段都不能倒置。边界提醒：对方应当随时可以选择离开。健康绑定建立在互惠、共同目标和自主选择上；如果靠恐惧、不安全感、单方面索取或信息不对称让对方留下，这不是影响力，而是关系风险。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["利益交换", "影响力", "互惠", "合作关系", "价值匹配"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 294, now()),
(100295, '关系筛选与退出：用结构匹配替代情绪判断', '核心意思：合作关系、职场关系和亲密关系都不能只看一时好感，也不能因为已经投入就无限坚持。更可靠的判断标准是结构匹配：价值观、节奏、利益、沟通方式和风险承受能力是否长期兼容。
使用方法：用五维检查表复盘：1）价值观是否一致，成功定义是否接近；2）决策速度、沟通频率、执行风格是否同步；3）短期目标和长期愿景是否能共赢；4）表达方式、反馈接受度、冲突处理风格是否舒适；5）风险承担意愿和止损边界是否清晰。三个维度以上长期不匹配，可视为结构性不合；两个维度不匹配，先尝试协商；一个维度不适，继续观察。
退出前做三项验证：问题是否持续足够久、双方是否尝试调整、继续投入的代价是否超过收益。这样可以避免一次争吵后的情绪化退出，也避免完美主义式筛选。边界提醒：退出时保持尊重和边界，说明事实、影响和决定，不把离开包装成惩罚，为未来可能的重新合作留下空间。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["关系协商", "合作筛选", "退出机制", "匹配度", "沉没成本"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 295, now()),
(100296, '局势变化时的策略重构：目标固定，路径灵活', '核心意思：沟通和谈判常常不是线性推进，而是在新信息、新角色、新压力下不断变化。成熟的应对不是固守原方案，也不是随风倒，而是在核心目标和底线不变的前提下，重新评估局势并调整路径。
使用方法：先识别“裂缝”：信息不对称、时间节奏错位、信任破损、利益分配失衡、资源配置矛盾、关键人员态度转向。再问三件事：变的是什么？外部环境、内部资源、目标优先级还是关系角色；为什么原策略不再适用？是执行不到位，还是假设条件已改变；什么必须改，什么可以保持？核心原则不变，具体策略、信息颗粒度和推进节奏可以调整。
行动上，可以先做小幅微调；若关键假设已失效，就重设路径、资源和时间窗口；若窗口正在关闭，则进入决断。边界提醒：权变不是放弃原则，也不是机会主义。它的价值是提前看见结构性失衡，用建设性介入、风险预警和路径重构避免更大损失。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["权变", "局势判断", "风险识别", "策略调整", "谈判决策"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 296, now()),
(100297, '可信表达与说服：说服力来自事实、身份、时机和兑现能力', '核心意思：真正有力量的表达不靠华丽包装，而靠可验证事实、合适身份、恰当时机和可兑现承诺。说服不是把话说满，而是让对方相信这句话经得起检查，并且你能为后果负责。
使用方法：表达前做四维自检：1）事实是否真实，是否存在夸大、模糊或偷换概念；2）身份是否匹配，是否超出权限或关系阶段；3）时机是否合适，对方当前状态是否适合接收，会不会干扰既定节奏；4）可信度是否足够，对方会质疑什么，我能否提供证据、案例、数据或行动记录。商务承诺中宁可保守承诺、透明说明风险，再用稳定交付增加信用。
在职场汇报里，要让数据和结论一致；在公开表达里，只讲自己能承担的经验；在商务承诺里，让资源、时间和执行力匹配。边界提醒：言过其实的代价会从短期失去主导权，发展到中期透支信用、长期重建信任困难。可信表达也是冲突降温工具：先确认事实和责任，再表达态度，比急着辩解更有说服力。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["说服", "可信表达", "承诺管理", "事实核对", "信任"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 297, now()),
(100298, '冲突降温：先收束范围，再回到共同问题', '核心意思：冲突升温时，最常见的错误是急着证明自己对，结果让对方更防御。更有效的顺序是：暂停输出，观察反应，收束议题，退回共同利益，再提出可讨论的小问题。这样既不逃避冲突，也不让冲突扩散成关系攻击。
使用方法：第一步，停顿并观察对方是沉默、抗拒、转移话题还是情绪上扬；第二步，把讨论范围从“你总是/你从来”收束到一个可处理事实，例如“我们先只看交付时间和职责分配”；第三步，用低压力提问寻找障碍：“这个安排里你最担心的是什么？”“如果先从小范围试行，阻力在哪里？”第四步，用共同目标承接：“我们都希望这件事能推进，所以先确认下一步。”
如果对方仍然抗拒，先降低信息密度，不继续追加论点；如果对方开始说出具体担忧，再共同设计一个小范围、可验证的调整。边界提醒：降温不是让步到底，也不是压抑真实需求。需要同时保留底线与尊重：不审问、不讽刺、不威胁，必要时暂停并约定回来继续谈。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。
自测提示：把这个模型用于最近一次真实对话，写下一个可观察信号、一个可调整动作和一个必须守住的边界，避免只停留在理解概念。', '["冲突降温", "共同利益", "边界", "提问", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 298, now()),
(100299, '观察是线索假设，不是读心或操控', '核心观点：人类行为观察的价值，不在于把某个表情、姿势或动作翻译成确定的内心答案，而在于把日常互动中的细节变成可检验的线索。书中导言把观察者比作实地考察者：车站、商店、机场、聚会和街道都是观察场，但观察的目的应是更深入地理解人与人的交往，而不是探知隐秘思想、控制他人。
使用方法：看到异常动作时，先记录事实，如“他说到这个话题时两次移开目光、手指反复摩擦杯沿”，再生成低强度假设，如“可能紧张、犹豫或需要更多时间”，最后用开放式沟通核对：“这个话题是不是让你有点为难？”
边界提醒：单个动作只能提示可能性，不能作为人格、动机或道德判决。越是觉得自己“看穿了”，越要回到事实、情境和对方确认。真正成熟的观察会增加宽容：理解行为背后的处境与压力，而不是强化攻击、操控或贴标签。
App 落地：可做成“观察—假设—核对”三栏卡片。观察栏只填可拍摄、可复述的事实；假设栏最多列三种可能，不允许写“就是”；核对栏给出一句尊重式提问。这样用户既能提升敏感度，也不会把非语言知识用成审判工具。
限制提醒：若对方明确解释了原因，应优先尊重其自述；观察只能补充理解，不能替代当事人的说明。', '["行为观察", "避免读心", "事实解释分离", "核对沟通", "非语言线索", "观察伦理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 299, now()),
(100300, '先记录动作模式，再解释心理含义', '核心观点：人的动作并非杂乱无章，而是由大量重复的姿势、运动和事件片段构成。书中以“十指交叉时总是同一个拇指在上”为例说明，许多身体习惯稳定到本人也不自知。对 App 知识库来说，这意味着观察应从“模式”入手，而不是被一次偶发动作牵着走。
操作框架：第一步，只写可见事实：动作是什么、何时出现、持续多久、在谁面前出现。第二步，看基线：这个人平时是否也这样，还是只在某类话题、某类对象、某种压力下出现。第三步，看组合：语言内容、语气、身体方向、手脚动作和场景要求是否一致。第四步，再提出假设：这是习惯动作、礼貌动作、紧张释放，还是某种关系信号？
判断原则：一次皱眉不等于反感，一次沉默不等于冷暴力，一次热情也不等于真诚。长期、重复、跨场景仍稳定出现的模式，才比单点行为更值得讨论；即使如此，也仍需要与当事人核对。
App 落地：建议用户建立“同一个人、同一类情境、连续多次”的观察笔记，例如会议、约会、争执、沉默后修复。系统可提示用户比较平时基线与本次偏离：是偶发疲劳、环境限制，还是重复出现的互动模式。模式越稳定，假设才越值得拿出来讨论。', '["长期模式识别", "行为基线", "动作模式", "事实记录", "情境判断", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 300, now()),
(100301, '动作来源四分法：先天、发现、同化、训练与混合', '核心观点：同一个动作看起来像“性格”，实际可能来自不同来源。书中把动作来源区分为先天动作、个人发现动作、同化动作、有意训练动作，并强调成年人的许多动作是混合形成的。这个框架能帮助我们避免把文化差异、职业训练或个人习惯误解成动机。
观察应用：若某个动作在不同文化、不同年龄段都常见，可先把它当作可能的基础反应；若它与身体结构和个人习惯有关，如抱臂、站姿、手势偏向，则要看个人长期基线；若它在某个群体中特别常见，如同一地区的招呼方式、同一团队的表达习惯，可能是同化来的；若它只在特定职业或训练场景中出现，如舞台、服务、军队或仪式动作，则可能是被教出来的。
沟通提醒：不要问“你为什么用这个动作针对我”，可改为“我注意到你在这个场合会这样表达，这对你来说是习惯、礼貌，还是当时有别的感受？”这样既保留线索，又减少误判。
App 落地：可把每次观察后的解释拆成四个来源选项：身体自然反应、个人旧习惯、群体/文化学习、职业或礼仪训练。用户若无法判断，就选择“未知来源”。这个步骤能把“他故意这样”降级为“这个动作可能有多种形成路径”。', '["动作来源", "文化差异", "习得行为", "个人习惯", "情境与动机区分", "沟通核对"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 301, now()),
(100302, '姿势不是字典：同一动作会随文化、职业和场景变义', '核心观点：手势、点头、招呼和象征姿势不能当成固定词典。书中反复说明，区域信号会因地理和文化而变，技术姿势只在专业领域内有效，密码姿势则需要系统规则才有意义；同一姿势还可能在不同国家表达相反或无关的意思。
应用方式：当看到对方点头、摇头、挥手、比手势、抱臂或身体后撤时，先问三类背景：一是文化背景，这个动作在对方成长环境中是否有特殊含义；二是场景背景，它是礼仪、职业规范、社交习惯，还是当下情绪；三是互动背景，动作是否引发对方接近、远离、解释或修正。
避免误判：不要说“他抱臂就是防备”“她不看我就是撒谎”。更稳妥的表述是：“这个动作可能提示距离、思考或不适，但也可能只是习惯或文化表达；需要结合上下文，再用温和提问确认。”对跨文化沟通尤其要降低确定性。
App 落地：在手势和姿势内容旁加入“文化校准”提醒：这个动作在你的文化里可能代表 A，在对方文化里可能代表 B，也可能什么都不代表。系统可要求用户补充对方成长环境、职业场景和当时任务，再生成低确定性的沟通建议。
限制提醒：若没有共同文化背景，就把结论写成“我不确定这个动作代表什么”，再邀请对方解释。', '["手势解读", "跨文化沟通", "区域信号", "技术姿势", "避免绝对化", "情境线索"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 302, now()),
(100303, '目光线索：直视、移开与扫视要看节奏和关系任务', '核心观点：目光不是简单的“看=真诚、不看=心虚”。书中《视觉行为》指出，两个人相遇时会在想看与想移开之间保持微妙平衡；凝视可表示关注、亲密、威胁、支配，也可表示恐惧中的警觉；移开目光可表示服从、思考、回避压力或降低冲突。
观察维度：看方向——对方是看人、看物、看出口，还是看地面；看节奏——目光接触是自然来回、过短、过长，还是突然中断；看关系——上级、下属、陌生人、朋友、伴侣之间的目光规则不同；看话题——谈事实、谈情绪、谈请求时，目光负荷也不同。
沟通用法：若目光让你不安，不要直接指责“你不敢看我”。可以说：“我注意到说到这里时我们目光都变少了，我担心这个话题有压力，要不要放慢一点？”这样把目光当作互动温度计，而不是测谎仪。
App 落地：可设计“目光不适检查表”：我是否把对方的不看解释成否定？当时话题是否困难？对方是否在思考、羞怯、服从、害怕冲突或受文化规则影响？完成检查后再决定是继续谈、暂停，还是询问对方是否需要时间。
限制提醒：目光线索尤其受羞怯、神经多样性、权力距离和疲劳影响，不能单独用于判断诚实。', '["视觉行为", "目光接触", "沟通判断", "关系互动", "压力线索", "核对沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 303, now()),
(100304, '致意仪式：迎接、告别与身份变化的关系重置', '核心观点：问候、告别、祝贺和仪式性寒暄，不只是礼貌外壳，也是在标记关系状态。书中《致意表现》把“你好”“再见”、欢迎、告别、庆祝看作关系债务的偿还和关系秩序的重建：有人到来、离开，或社会地位发生变化时，人们会通过拥抱、握手、微笑、寒暄、祝贺等动作确认“我们如何相处”。
观察应用：关系中的不适有时发生在致意环节，而不是正文内容。比如对方进门时是否被看见，离开时是否被送别，成就是否被祝贺，失落是否被承认。过度简化的致意可能让人感觉被忽视，过度隆重的致意也可能带来压力。
沟通建议：不要仅凭问候热情判断真心。先看双方共同的礼仪期待，再看长期稳定性。如果感到被冷落，可表达影响：“刚才我进来时没有被回应，我有点失落；你当时是在忙，还是没注意到？”把仪式差异转成可讨论的关系需求。
App 落地：适合用于关系修复提醒。系统可提示用户回顾冲突并不只看争论内容，也看开头和结尾：有没有打招呼、有没有解释离开、有没有感谢、有没有在重要变化后重新确认关系。很多关系紧张来自仪式性承认缺失。
限制提醒：有些人因家庭、文化或社交焦虑不擅长仪式表达，关系判断应看后续行动是否稳定。', '["致意表现", "关系互动", "仪式感", "告别", "问候", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 304, now()),
(100305, '姿势对应：身体同步提示亲和或地位协调', '核心观点：当两个朋友地位相近、态度相似、互动顺畅时，他们常会无意识地出现姿势对应：相似坐姿、相似倾斜角度、相近点头节奏、同步的身体细微动作。书中把它视为友好交往中的自然身体表示，传递“我和你在同一边”的无声信息。
观察重点：同步要看是否自然、双方是否舒适、是否长期在类似关系中出现。朋友间的姿势对应常让人觉得“对劲”；治疗、咨询、服务或高难沟通中，适度降低姿态差异也可能带来安抚。但地位不对称时，机械模仿可能被体验为冒犯；下属过度复制上司的放松姿势，反而可能破坏关系边界。
使用边界：不要把同步当作“喜欢我”的铁证，也不要用刻意模仿操控亲和。更好的方式是校准对方节奏：若对方紧绷，先放慢语速、降低压迫感；若对方放松，再自然靠近。观察同步的目的，是判断互动是否安全，而不是制造假亲密。
App 落地：可在对话训练中把“同步”定义为跟随节奏而非复制动作。用户练习的是音量、距离、停顿、身体朝向的温和调整；一旦对方后撤、僵住或不自在，就停止靠近。同步的目标是降低威胁，不是让对方失去边界。
限制提醒：真正的同步通常轻微、自然、可退出；一旦需要用力维持，就应回到真实表达。', '["姿势对应", "身体同步", "亲和感", "地位关系", "沟通节奏", "关系安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 305, now()),
(100306, '关系符号：距离、并行、触摸和公开性构成互动证据', '核心观点：关系不是只靠语言声明，也会通过空间距离、同行方式、身体接近、挽手、拥抱、接吻、扶持、触摸部位和公开程度被他人读出。书中《关系符号》和《身体接触关系符号》提醒，旁观者会从细微动作判断两人是否有私人关系以及关系性质，但这些线索必须排除拥挤、礼仪、救助和临时任务。
观察框架：先看“是否自愿接近”——拥挤车厢里的近距离不等于亲密；再看“谁主动、谁回应”——单方面触摸与双方自然靠近不同；再看“部位和时长”——手、肩、背、头部的亲密等级不同；最后看“公开性”——私下与公开场合的动作可能承担不同关系声明。
沟通提醒：关系线索最容易被投射和误读。比起断言“你们关系不正常”，更稳妥的是表达事实与感受：“我看到你们在聚会上长时间挽手，我有些不安；这在你们之间代表什么？”让关系定义回到双方可确认的语言。
App 落地：对伴侣、亲子、同事场景都可做“关系符号复盘”：我看到了什么动作？这个动作在这个场景是否有礼仪或任务解释？对方是否愿意、放松、回应？我真正担心的关系需求是什么？最后再转成一句可验证的问题。', '["关系符号", "身体接触", "边界", "亲密关系", "事实解释分离", "公开性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 306, now()),
(100307, '非语言泄漏与矛盾信号：按可控性排序，而非直接定罪', '核心观点：当语言、表情、手脚、姿势和生理反应不一致时，确实可能出现非语言泄漏；但泄漏显示的是“内外不协调、压力或未说出的内容”，不等于必然撒谎。书中明确指出，摸鼻子、手对脸接触、手势减少等线索不能直接证明欺骗，只能提示有些东西无法顺畅表达。
判断方法：先区分两难信号和矛盾信号。两难信号可能来自真实混合情绪，如既想靠近又害怕；矛盾信号才更像外在表演与内在感受冲突。再按可控性排序：生理自发反应、腿脚和躯干动作通常比刻意语言和脸部表情更难控制，但也只是在强情绪时更有价值。
沟通用法：把“你在撒谎”改成“我听到你说没事，但你的手一直抓紧，看起来这件事可能有压力；你愿意多说一点吗？”这样既尊重线索，也给对方澄清、保留隐私或调整表达的空间。
App 落地：可作为“误判减速器”。当用户输入某个可疑动作时，系统先返回至少三个替代解释：压力、礼貌表演、混合情绪、认知负荷、隐私保护或文化差异。只有在长期一致、线索组合强、对方又拒绝澄清时，才提示用户关注边界和风险。
限制提醒：识别矛盾后先处理安全和信任，过早审问只会增加对方防御，使线索更混乱。', '["非语言泄漏", "矛盾信号", "测谎误区", "压力线索", "沟通判断", "事实核对"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 307, now()),
(100308, '短缺与过度信号：不自然强度常提示表演压力', '核心观点：有些非语言线索不是内容错，而是强度、时长或节奏不合适。书中把强度不足称为短缺信号，如闪电式微笑、凝固式微笑、过短目光接触；把强度过大称为过度信号，如笑得太久、动作太夸张、热情超过场景需要。两者都可能来自真实心境与社会表现之间的冲突。
观察维度：看强度是否匹配事件大小，看时间是否过短或拖长，看出现和消失是否自然，看是否只在特定对象或压力话题前后发生。还要排除文化风格：外露型文化本来动作更大，保守型文化本来表情更克制；跨文化互动中，短缺或过度可能只是彼此规则不同。
应用提醒：短缺和过度只提示“这里可能有表演、礼貌、紧张、困惑或文化差异”，不能直接推出恶意。适合的核对句是：“我感觉刚才这个回应有点勉强/用力，是不是这个场合让你难办？”把判断落在互动体验，而非人格指控。
App 落地：可帮助用户处理“感觉怪怪的”场景。系统让用户分别标注表情强度、持续时间、出现/消失速度、话题前后变化和文化背景，再给出“可能勉强、可能礼貌、可能不熟悉规则”的假设，而不是直接判定虚伪。
限制提醒：强度失配也可能来自紧张、笨拙或不熟练，不宜直接上升到人品评价。', '["短缺信号", "过度信号", "表演压力", "文化风格", "情绪识别", "核对沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 308, now()),
(100309, '领域、阻挡与防御：个人空间是安全感语言', '核心观点：人会把部落、家庭和个人空间当成需要防卫的领域，也会在压力中寻找屏障。书中《领域行为》讨论人对“自己的地方”的安全感，《阻挡信号》描述儿童躲在母亲或家具后、成人用桌子、杯子、包、手臂等建立缓冲；《防御行为》则呈现遇到危险时保护头部、躯干和脆弱部位的反应。
观察应用：对方后退、转身、把物品放在中间、抱紧身体、靠墙坐、选择能看见出口的位置，可能是在调节安全距离，而不是一定讨厌你。相反，突然闯入对方个人空间、堵住出口、隔着桌子逼问，都可能增加防御。
沟通建议：若对方出现阻挡或防御，先降低刺激：后退半步、放慢语速、给选择权、允许暂停。可说：“我注意到这个距离可能有点紧，我们可以坐远一点或晚点再谈。”尊重空间，往往比继续追问更能恢复关系安全。
App 落地：适合在高难沟通前做环境调整建议：不要堵门，不隔着屏幕逼问，不在公众场合追问私密问题；给对方水、座位、退路和暂停权。空间先安全，语言才更可能被听见。观察到阻挡时，优先降低压迫感。
限制提醒：对创伤、社交焦虑或高敏感者，空间线索可能更明显，沟通时更要给选择权。', '["领域行为", "个人空间", "阻挡信号", "防御行为", "安全感", "关系边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 309, now()),
(100310, '自发与瞳孔信号：生理唤醒只说明被触动，不等于动机', '核心观点：出汗、脸色变化、呼吸改变、瞳孔扩大或收缩等自发信号，受自发神经系统影响，通常比语言和脸部表情更难刻意控制。书中因此把它们放在较可信的位置；《瞳孔信号》还指出，在光线稳定时，瞳孔变化会随情绪刺激而变化，并且常在当事人无意识中影响互动。
使用边界：生理线索的可信，不等于含义单一。心跳加快可能是喜欢、害怕、羞耻、愤怒、兴奋、咖啡因、疲劳或环境热；瞳孔扩大可能来自兴趣，也可能来自光线、药物或一般唤醒。观察者只能说“身体被激活了”，不能直接翻译成“他喜欢我”或“她心虚”。
沟通建议：把生理观察用于自我调节和温和关心。对自己，可说“我现在身体被激活，需要暂停”；对他人，可说“我感觉这个话题让你有点紧绷，要不要喝水或休息一下？”生理信号最好服务于照顾和核对，而不是推断控制。
App 落地：可用于自我觉察而不是侦测他人。系统可提醒用户记录自己的身体唤醒：脸热、手汗、呼吸急、瞳孔或视野变化，然后问“我被什么触动了，需要安全、休息、靠近还是澄清？”对他人则只做关心式询问。
限制提醒：若涉及持续惊恐、失眠或强烈躯体不适，应把它视为需要照顾的身心信号。', '["自发信号", "瞳孔信号", "生理唤醒", "非语言线索", "避免读心", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 310, now()),
(100311, '身份、衣着与身体修饰：外观信号先问角色和场域', '核心观点：服装、发型、化妆、饰品、制服、随行人员和身体修饰都在传递社会信号。书中《身份显示》讨论权威如何通过外部形式呈现，《衣着信号》指出“穿上衣服而不发出社会信号是不可能的”，《身体修饰》则把化妆、发型、饰物、香水等视为地位、角色、性别、年龄、职业、游戏心态或群体归属的显示方式。
观察框架：先看场域——工作、约会、仪式、休闲和反叛场景对外观期待不同；再看角色——制服、礼服、低调穿着、刻意随便都可能在表达身份；再看变化——一个人突然改变穿着或修饰，可能是角色转换、关系需求、情绪状态、群体归属或审美尝试。
避免误判：外观不是人格判决。不要把“穿得随便”直接等于不尊重，也不要把“精心打扮”直接等于虚荣或勾引。更好的说法是：“我注意到你今天和以往风格不同，是有什么特别场合或心情吗？”让外观成为理解入口，而不是评价武器。
App 落地：适合用于减少外貌评价和标签化。系统可把“他穿成这样说明什么”改写为“这个外观可能在当前场域表达何种角色、归属或心情”。若涉及关系影响，再引导用户表达自己的感受与期待，而不是评价对方品味或道德。', '["身份显示", "衣着信号", "身体修饰", "角色表达", "社会信号", "非标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 311, now()),
(100312, '社会直觉很快，但需要“事实—解释—行动”三步校准', '核心观点：迈尔斯反复提醒，社会直觉是人类在复杂环境中快速生存的工具，却不是天然可靠的裁判。我们会迅速判断一个人是否可信、一次拒绝是否代表讨厌、一段沉默是否意味着关系破裂；这些判断常常足够快，却会被过度自信、验证性偏见、可得性线索、情绪状态和信念固着放大。App 端不应简单告诉用户“别想太多”，而应帮助用户把直觉降级为假设。

使用方法：当用户说“TA 肯定不在乎我”“同事就是针对我”时，先让用户写下可观察事实：对方具体说了什么、做了什么、发生在什么情境。第二步列出至少三种解释：人格动机、情境压力、沟通误差、自己当前情绪。第三步再选择低风险行动：核对、等待更多信息、提出请求或调整边界。

沟通价值：这种做法保留直觉的提醒功能，也避免让直觉直接升级为攻击、冷战或自责。知识库可将其做成“事实不是解释，解释不是结论，结论先接受检验”的提示模板。尤其适用于亲密关系误读、职场冲突、社交焦虑、用户复盘重大决定。

落地提醒：这条适合做成误读急救流程。系统先承认直觉的保护意图，再邀请用户补证据；语气要像“我们一起核对”，而不是“你想错了”。', '["社会认知", "直觉判断", "认知偏见", "事实解释分离", "关系误读", "App问答模板"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 312, now()),
(100313, '归因三问：判断人格之前，先检查共同性、区别性和一致性', '核心观点：关系里的许多伤害，来自把对方的一次行为过快解释成人格缺陷。迈尔斯在归因章节中区分内部归因与情境归因，并介绍凯利的三个线索：共同性、区别性、一致性。一个人迟到，可能是“不重视我”，也可能是今天交通异常；一个孩子成绩下降，可能是动机问题，也可能是课程难度、老师互动、家庭压力共同作用。基本归因错误让我们高估人格、低估情境，尤其在生气或受伤时更明显。

App 可把归因三问做成冲突降温卡：第一，共同性：别人遇到同一情境也会这样吗？第二，区别性：TA 只在这件事上这样，还是所有场景都这样？第三，一致性：TA 是否长期重复同一模式？只有三个问题都指向稳定模式时，才更适合讨论边界和责任；若线索不足，先用核对式语言：“我注意到这次你没有回应，我脑中有个解释，但我想先了解发生了什么。”

应用边界：校准归因不是替伤害开脱，而是避免把可修复事件直接变成人格审判。对伴侣、亲子、上下级沟通来说，先查情境能减少羞辱和防御，让后续请求更具体。

落地提醒：当确有长期伤害模式时，归因三问的结论可以转向边界和保护；它不是让用户无限理解对方，而是让判断更有证据。', '["归因理论", "基本归因错误", "情境压力", "冲突降温", "沟通核对", "非标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 313, now()),
(100314, '期望会制造互动现实：把预言改成可检验的邀请', '核心观点：迈尔斯把社会信念写得很有应用价值：我们不只是观察关系，也会用期待塑造关系。若我预期对方冷漠，我可能先退缩、语气变硬或减少解释；对方感到被排斥后真的冷淡，于是我的预期看似被证明。教师对学生的期待、伴侣对伴侣的解释、面试者对求职者的态度，都可能进入这种自我实现预言。

App 端可引导用户区分“预测”与“邀请”。预测式反应是：反正 TA 不会听，我也懒得说；邀请式反应是：我担心你可能不愿意听，但这件事对我重要，我想用十分钟讲清楚。预测把未来提前封死，邀请给对方一个不同反应的机会。

练习模板：写下我对 TA 的负面预期；写下我可能因此做出的防御动作；写下一个不牺牲边界、但能给关系创造新证据的小行动。比如从“他一定会否定我”改为“我先只说一个事实和一个请求，看他是否愿意回应”。

适用场景：关系复联、亲子期望、团队管理、用户担心被拒绝。知识库应强调：改变期待不是天真相信对方，而是减少由自己防御动作制造的坏结果。

落地提醒：系统可在用户准备放弃沟通前，生成一句低防御开场白，并要求只观察一次回应，不用立刻判定整段关系。', '["自我实现预言", "期待效应", "关系互动", "教师期望", "沟通邀请", "行为实验"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 314, now()),
(100315, '态度预测行为有条件：越具体、越自觉、越少外压，越可靠', '核心观点：用户常问“为什么我明明知道该沟通，还是逃避？”迈尔斯对态度与行为的总结能避免道德化指责：态度会影响行为，但只有在态度与行为足够具体、外部压力较小、个体能觉察自身态度时，预测力才更强。笼统地说“我重视健康”不一定能预测今晚是否运动；但“我认为饭后散步十分钟对我有帮助，并且我已经安排好时间”，就更接近行为。

App 落地：把“价值宣言”翻译成“具体态度”。不要只问用户“你想改善关系吗”，而要问：你是否愿意在今晚 21:00 前给对方发一句事实和请求？你认为这样做的好处、代价和阻碍是什么？如果用户行为不一致，也先查外部因素：是否太疲惫、害怕冲突、缺少脚本、环境诱惑太强，而不是直接贴上“不自律”。

咨询/成长价值：这条可用于习惯改变、亲密沟通、戒烟戒酒、学习计划和职场执行。它提醒知识库：改变不靠重复正确道理，而要让态度与场景、动作、时间和社会压力对齐。越是具体可执行，态度才越可能变成下一步行动。

落地提醒：如果用户连续失败，优先检查目标是否过于抽象、场景是否未安排、外部阻力是否被低估；修正设计比加强自责更有效。', '["态度与行为", "具体化目标", "行为设计", "自我觉察", "外部压力", "行动改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 315, now()),
(100316, '先做后信：小承诺、角色和不协调会悄悄改写自我', '核心观点：迈尔斯系统呈现了“行为也会塑造态度”。人会逐步相信自己公开说过、主动选择过、承担过责任的事。角色扮演会让最初陌生的身份变得自然；登门槛现象说明，一个自愿的小承诺会提高后续更大承诺的概率；认知不协调则解释了为什么当行为与原有信念冲突、且外在理由不足时，人会调整态度来减少心理紧张。

App 可双向使用这条知识。成长设计上，把改变做小：先表达一次感谢、先发一次清晰请求、先完成五分钟练习，让“我是能沟通/能行动的人”通过行为积累。防操控上，提醒用户识别小承诺链：免费试用、先签名、先答应一个无害请求、先公开表态，都可能让后续拒绝更难。

咨询提示：当用户说“我没有信心，所以做不到”，可温和改写为“信心有时来自做过一次”。但也要强调自愿和可选择性：被强迫的行为不易内化，反而激起抵抗。最适合的改变，是足够小、能主动选择、能看见积极后果，并与用户自己的价值一致。

落地提醒：知识库应同时提醒“微行动”与“微同意”的区别。前者服务用户价值，后者可能服务他人操控；关键看选择权和透明度。 并保留退出通道。', '["行为改变态度", "小承诺", "登门槛效应", "认知不协调", "角色扮演", "防操控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 316, now()),
(100317, '从众的两种力量：想被接纳，也想判断正确', '核心观点：从众并不只是软弱。迈尔斯把从众拆成顺从、服从和接纳，也区分了规范影响与信息影响。规范影响来自归属压力：人害怕被嘲笑、排斥、惩罚，于是公开附和。信息影响来自不确定：情境模糊、任务困难、自己没把握时，别人就像现实线索，我们更容易相信群体是对的。理解这两种力量，能让 App 帮用户从“我怎么这么没主见”的羞耻里出来。

使用方法：面对人情压力、团队意见、家庭催促或社交媒体风向时，先问两句：我是在怕被拒绝，还是在借别人判断事实？如果是规范压力，需要边界脚本和支持者；如果是信息压力，需要补充证据、咨询专业意见、延迟决定。公开回应会增强从众，事先承诺会增强独立，因此可在进入高压场景前写下底线：“如果被劝酒，我只说一次不喝，并把杯子换成水。”

沟通价值：这条不鼓励盲目反群体。成熟的独立是在重要价值上能站稳，也能在证据不足时向群体学习。App 可用于拒绝、消费决策、职场会议、亲友压力和网络舆论自保。

落地提醒：当用户需要拒绝群体压力时，先帮其找到至少一个现实或想象中的支持者。独立并不等于孤立，支持能降低规范压力。', '["从众", "规范影响", "信息影响", "顺从与接纳", "边界脚本", "社会压力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 317, now()),
(100318, '说服双路径：重要决定走中心路线，日常诱惑常走外周线索', '核心观点：迈尔斯对说服的中心途径和外周途径特别适合做 App 决策提醒。中心途径发生在用户有动机、有能力认真思考时，重点看论据质量；外周途径发生在注意力不足或议题不重要时，人更受吸引力、权威感、熟悉度、情绪图像、群体热度等线索影响。很多营销、PUA 式沟通和冲动消费，并不是用更好的理由打动人，而是绕过深思。

App 可给用户一张“说服体检表”：第一，我是在看证据，还是被人设、颜值、专家头衔、恐惧画面带着走？第二，这件事对我重要吗？重要就延迟决定，主动找反方资料。第三，对方是否让我来不及想、来不及问、来不及比较？越急越要慢。第四，我是否已经公开承诺，因面子而难以退出？

态度免疫：迈尔斯还提到，温和预警和角色扮演能增强抵抗力。App 可让用户提前演练拒绝句：“我需要 24 小时考虑”“请把依据发给我”“我不在情绪强烈时下决定”。这样既能提升沟通清醒度，也避免把所有说服都妖魔化；好的说服应让人更理解事实，而不是更失去自主。

落地提醒：系统可以在用户情绪高涨、限时优惠、关系施压时触发“慢决策”提示：先睡一晚、列证据、问一个反方问题。', '["说服", "中心途径", "外周途径", "态度免疫", "消费决策", "防操控"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 318, now()),
(100319, '群体场会放大反应：有人看见时更用力，没人认领时更偷懒', '核心观点：迈尔斯的群体影响章节能帮助用户理解团队与家庭系统。社会助长显示，他人在场会提高唤起水平，使优势反应更强：熟练任务可能表现更好，不熟练或困难任务可能更容易出错。社会懈怠则显示，当个人贡献无法被识别、责任被平均摊薄时，人会不自觉少出力。去个体化进一步说明，在匿名、群体唤起和责任扩散结合时，道德约束会下降，行为可能偏离平日自我。

App 落地：团队协作不要只喊“大家一起努力”，而要让责任可见、贡献可追踪、目标有挑战且有意义。亲密关系和家庭分工中，也要避免“谁有空谁做”的模糊结构，因为模糊最容易制造搭便车和怨气。对于用户在群聊、网络骂战或集体情绪中失控，可提示：匿名感和群体情绪正在降低你的自我监控，先退出场域再判断。

使用建议：把任务按人、时间、完成标准拆开；公开表扬具体贡献；对困难任务先练习再上场；对高唤起场景设置暂停按钮。群体不是必然让人变坏，也不是天然更高效；关键是评价、责任和规范如何被设计。

落地提醒：在关系咨询中，这条可解释“不是只有我不负责，而是我们没有把责任说清”。解释系统问题后，再回到个人可承担的一步。', '["群体影响", "社会助长", "社会懈怠", "去个体化", "团队协作", "责任可见化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 319, now()),
(100320, '群体极化与群体思维：高凝聚团队更要制度化异议', '核心观点：群体讨论不一定让观点更平衡，常会把成员原有倾向推向更极端。迈尔斯用群体极化解释同温层、网络社区和团队会议中“越聊越确信”的现象：成员反复听到支持性论点，并通过社会比较确认自己属于正确阵营。群体思维则发生在高凝聚、追求一致、隔绝异议的团队中，成员为了维护团结压下疑虑，最终做出糟糕决策。

App 端可服务团队管理和关系沟通：如果一个家庭、伴侣或团队总说“我们都这么认为”，要检查是否有人不敢表达不同意见。设计异议流程比期待某个人勇敢更可靠：先匿名收集风险点；会议中指定“反方角色”；领导最后发言；把“提出坏消息”定义为贡献；重大决定前安排冷静期和外部视角。

个人使用：当用户沉浸在只支持自己的社群里，可提醒其主动寻找一个高质量反对意见，而不是刷更多同类证据。亲密冲突中，也要避免找一圈只会站队的朋友，把委屈推向极端。真正可靠的支持系统，不只安慰你，也帮你看见盲点、代价和替代方案。

落地提醒：App 若用于团队复盘，可固定加入“我可能忽略了什么”“谁会不同意我们”的问题，避免只收集让团队舒服的信息。', '["群体极化", "群体思维", "团队决策", "异议机制", "同温层", "心理安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 320, now()),
(100321, '偏见不是单一恶意，而是身份、分类和公正世界共同运作', '核心观点：迈尔斯对偏见的处理比简单“不要歧视”更可用。偏见包含情感、行为倾向和信念，常由社会身份、资源竞争、社会化、制度支持、类别化和动机性解释共同维持。人会偏爱“我们”，把外群体看得更相似；会把少数群体的突出事件记得更牢；也会借“公正世界”信念责备受害者，好让自己相信世界仍然可控。

App 可用于减少关系中的标签化和群体敌意。第一步，把群体标签改回具体的人：这个人做了什么，而不是“他们都怎样”。第二步，检查是否存在内群体偏差：我们犯错是情境所迫，他们犯错就是本性。第三步，警惕责备受害者：对方遭遇不幸，不等于其应得。第四步，增加真实、平等、有共同目标的接触，而不是只在竞争和刻板叙事里认识对方。

咨询价值：用户在家庭、职场或亲密关系中也会制造小型“内外群体”：我家/你家、老员工/新人、理性的人/情绪化的人。知识库可引导其把阵营语言转成具体事实、共同需要和可协商边界。

落地提醒：在用户表达强烈群体厌恶时，先不贴“你有偏见”，而是引导其回到具体个体、具体行为和具体需求，降低防御。 再讨论公平。', '["偏见", "社会认同", "类别化", "公正世界信念", "责备受害者", "群际关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 321, now()),
(100322, '刻板印象威胁：身份标签会占用表现能量，需要高期待与高支持', '核心观点：刻板印象不只影响旁观者怎么看人，也会影响当事人如何表现。迈尔斯引用斯蒂尔等人的研究说明，当一个人担心自己会被负面刻板印象评价时，这种担心本身会占用工作记忆、提高生理唤起、增加出错恐惧，进而拉低表现。它不是能力不足，而是身份威胁正在进入任务系统。

App 端可把这条用于考试焦虑、职场表现、亲密关系中的自我怀疑。用户说“我果然不适合”“我们这种人就是不行”时，不急着灌鸡汤，而是帮他识别：当前任务里是否有标签压力？是否担心代表整个群体？是否在证明自己而不是完成任务？

干预语言：高支持不是降低标准，而是“我相信你能达到更高标准，所以给你具体反馈”。避免说“你们这类人也可以”，这会强化标签；改说“这项能力可以通过策略和练习提升，你这次主要卡在步骤二”。同时减少身份显著性，强调共同身份、任务策略和可控变量。对 App 来说，它能让鼓励从泛泛肯定变成既有要求又有安全感的反馈。

落地提醒：对青少年、女性、少数群体、转岗新人尤其要避免“你能做到已经很不错”式低期待安慰；更好的支持是具体策略和明确信任。', '["刻板印象威胁", "表现焦虑", "身份安全", "高期待高支持", "考试焦虑", "职场成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 322, now()),
(100323, '亲密不是神秘缘分：接近、相似、被喜欢和逐步表露共同塑造关系', '核心观点：迈尔斯把喜欢和爱情从“命中注定”拉回可观察机制。友谊和吸引常由接近性开始：更容易遇见、互动和熟悉的人更可能成为朋友。曝光效应让熟悉感增加好感；相似的态度、价值和生活方式会让人感到被确认；知道对方喜欢自己，也会增强喜欢的回路。激情之爱常带有强唤起和解释，而长期亲密更依赖伴侣之爱：平等、信任、自我表露和共同承担。

App 可用于关系成长，而不是教用户操控吸引。建议把“如何让 TA 爱我”改成“如何创造安全、真实、可持续的互动”。具体做法：增加低压力、高质量的共同时间；从低风险话题逐渐表露真实感受；用倾听回应对方表露，而不是立刻评价；检查双方付出与回报是否长期失衡；把新鲜活动作为补充，而不是用刺激掩盖关系问题。

关系修复提示：激情下降不等于爱消失，可能是关系从高唤起转向稳定依恋。真正需要警惕的是冷漠、轻蔑、长期不回应和无助感。成熟的爱情不是一直强烈，而是双方能反复理解、创建和重建关系。

落地提醒：这条可避免把亲密成长包装成技巧控制。App 应强调共同意愿、节奏同意和边界尊重，任何表露都应允许对方不回应。', '["亲密关系", "吸引", "接近性", "相似性", "自我表露", "伴侣之爱"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 323, now()),
(100324, '利他不是只靠善良：清晰事件、具体责任和时间余量会显著提高帮助', '核心观点：迈尔斯把帮助行为拆成社会交换、社会规范、进化解释和共情利他，也特别强调情境条件。旁观者效应不是说明人冷漠，而是说明模糊情境中，人会先看别人反应；别人都没动，就容易出现多元无知。人越多，责任越分散；时间越紧，越可能跨过需要帮助的人；事件越清晰、求助越具体、有人率先行动，帮助越容易发生。

App 可把这条改写为求助和助人模板。求助时不要只说“有没有人能帮我”，而要具体点名：“小王，请你现在帮我打电话；小李，请你陪我去门口。”描述事实、需要、时间和行动。助人时，看到异常先不要用“别人会处理”安慰自己，先问三个问题：是否有人受伤？我是否能做一个低风险动作？我能否指定或带动其他人？

咨询/沟通价值：它也适合朋友倾诉。很多人不是不愿帮，而是不知道怎样帮。App 可引导用户把模糊期待翻译成具体请求：今晚陪我散步二十分钟、帮我看一遍简历、提醒我明天预约咨询。善意需要结构，结构会让善意更容易发生。

落地提醒：当用户是求助者，系统可直接生成“点名—事实—请求—时限”四段式消息；当用户是旁观者，提示先做最小安全行动。', '["利他", "旁观者效应", "责任扩散", "具体求助", "共情", "助人行为"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 324, now()),
(100325, '冲突常由社会困境启动：把“各自合理”改造成“共同有利”', '核心观点：迈尔斯在冲突章节中把许多矛盾解释为社会困境：每个人的短期选择看似合理，叠加后却伤害共同利益。公共地悲剧、囚徒困境、家庭分工、团队资源、伴侣冷战都类似：我多占一点、多防一点、少承担一点，短期保护自己，长期却让系统恶化。冲突还会让人把自己的行为解释为外界压力，把对方解释为贪婪、不可靠或恶意。

App 落地：先把争执从“谁坏”改写成“这个系统怎样奖励了坏结果”。家庭中，如果谁先做谁吃亏，就要重设分工和可见回报；团队中，如果合作没有奖励、搭便车没有成本，就会不断消耗积极者。亲密关系中，若道歉者总被继续追打，沉默者总能逃过责任，系统也在强化失衡。

可用工具：缩小责任单位、增加面对面沟通、让贡献可见、改变激励、建立共同规范、强调共同身份和长期利益。知识库可用一句话提示用户：不要只问“对方为什么这样”，也要问“我们当前规则让哪种行为更容易发生”。改变结构，常比责骂人格更有效。

落地提醒：这条尤其适合反复争吵的伴侣或团队。不要只追问谁先错，而要画出循环：谁做了什么、短期收益是什么、长期代价是什么。', '["冲突", "社会困境", "公共地悲剧", "合作机制", "家庭分工", "系统思考"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 325, now()),
(100326, '和解不是一次道歉：接触、共同目标、建设性沟通和 GRIT 逐步降温', '核心观点：迈尔斯把和平写成一套过程，而不是一句“别吵了”。单纯接触不一定消除敌意，尤其在地位不平等、竞争和刻板印象仍在时；更有效的是平等接触、共同目标、合作任务、建设性沟通和逐步互惠的降温行动。GRIT 策略强调：一方先公开表达降低紧张的意图，再做一个小而可验证、不会危及自身安全的善意行动，并邀请对方回报；若对方合作，就继续升级信任，若对方攻击，也保持边界。

App 可用于伴侣冷战、家庭长期矛盾、团队对立。先不要要求巨大让步，而是设计低风险修复动作：暂停讽刺三天、按时回复一个必要信息、归还一个资源、承认一个具体影响、共同完成一件小任务。每个动作前都说明意图：“我想让我们不再升级，所以先做这一步。”

沟通模板：少用旧账攻击、读心和威胁；多用事实、感受、需要、反馈、提问和双方都能接受的建议。若直接谈判困难，可引入第三方调解，帮助双方从“非赢即输”转向“共同有利”。和解的关键不是立刻信任，而是用连续、可验证的小行动重新制造信任。

落地提醒：GRIT 不适用于要求用户在危险关系中单方面忍让。若存在持续威胁、暴力或严重操控，优先做安全边界，再谈互惠降温。', '["和解", "GRIT", "建设性沟通", "共同目标", "关系修复", "调解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 326, now()),
(100327, '见证与承认：创伤复原从“不再孤立”开始', '核心理解：创伤不只是个人内部的痛苦，也会发生在关系与社群的断裂中。当一个人经历了不可承受的伤害，最折磨人的往往不只是事件本身，还有之后被怀疑、被责备、被要求沉默，或被旁观者劝说“算了、忘了吧”。温和的支持不是急着追问细节，也不是替对方决定该怎么处理，而是先承认：你经历的事重要，你的反应有意义，你不必独自承担。
用于 App 端沟通时，可把“见证”拆成三步：第一，稳定地在场，用简单语言表达相信与关心；第二，保护当事人的选择权，询问她现在需要安静、陪伴、实际协助还是转介资源；第三，避免站到加害或压力系统一边，例如质疑“为什么不早说”“为什么不离开”。对关系成长而言，真正的支持是一种行动：愿意记得、愿意保护、愿意和当事人一起面对现实后果。承认与弥补无法抹去过去，却能帮助人重新相信世界仍有秩序和正义。
适用场景包括：用户不确定是否该说出经历、亲友不知道如何回应、伴侣想修复信任。回答时要把“相信与保护”放在“分析原因”之前，并提醒支持者少说评判，多提供可被拒绝的具体帮助，例如陪同、记录、寻找资源或只是安静在场。', '["创伤支持", "见证", "去孤立", "社群承认", "安全沟通", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 327, now()),
(100328, '创伤反应：不是“太敏感”，而是保护系统仍在工作', '核心理解：创伤反应可以被理解为自我保护系统在极端处境后仍保持高负荷运行。危险发生时，身体会动员逃跑、抵抗、警觉、忽略疼痛等能力；当抵抗或逃离都无效时，这套系统可能变得混乱，并在危险过去后仍无法自动复位。于是，一个人可能出现三类常见体验：过度警觉，像随时预期危险再来；记忆侵扰，某些画面、梦、气味或声音突然把人带回过去；禁闭退缩，表现为麻木、空白、隔离、失去兴趣或对未来不敢想象。
App 端表达时，应避免把这些反应道德化为“脆弱”“矫情”“故意作”。更稳妥的说法是：这是身心在努力保护你，只是保护方式已经不再适合现在。第一步不是马上挑战记忆，而是帮助用户辨认“此刻我在哪里、周围是否安全、我能做一个小选择吗”。当反应被命名，它就不再只是莫名其妙的失控，而能成为可观察、可调节、可被支持的信号。
适用场景包括：用户说自己突然暴躁、惊醒、发呆、对小事反应很大。回答时可先正常化这些反应，再邀请她观察强度和触发线索。避免要求她证明自己受过伤，也避免把麻木解释成冷漠；麻木有时也是身体在省电和自保。也可提醒用户：反应强弱会波动，波动不等于失败。', '["创伤反应", "过度警觉", "记忆侵扰", "麻木退缩", "身心保护", "情绪调节"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 328, now()),
(100329, '身体记忆与触发：先回到现在，再理解过去', '核心理解：创伤记忆常不像普通回忆那样有清楚的时间顺序和语言说明，而更像感官碎片：身体紧绷、心跳加快、胃部不适、某个气味或声音、一个姿势、一个梦。人可能理性上知道危险已经过去，身体却像仍在当时。这不是“想太多”，而是记忆、情绪、知觉和身体感受在创伤时没有被整合。
因此，App 端不宜引导用户强行回想细节，也不宜使用高强度暴露式练习。更合适的顺序是：先安全定位，再身体安顿，最后才是意义理解。可以邀请用户用低刺激方式描述当前状态，例如“我注意到胸口紧”“我在房间里，脚踩在地上”“我现在可以选择暂停”。当用户已经稳定，再帮助她区分：这是过去留下的身体警报，不等于现在一定有危险。关系沟通中，亲友也可学习把触发看作身心信号，而不是争吵中的故意攻击；先降速、减少刺激、确认边界，再谈发生了什么。
适用场景包括：用户被某句话、气味、亲密接触或冲突瞬间带回旧感受。回答时可提供“现在—过去”区分句式：我正在经历一个旧警报，但我可以先确认当下环境。若用户仍处在危险关系中，应优先谈现实安全和可用支持，而不是记忆解释。', '["身体记忆", "触发点", "当下定位", "稳定化", "感官碎片", "低刺激支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 329, now()),
(100330, '亲近者的回应：真实评价能减轻羞耻和自责', '核心理解：创伤之后，亲近者的反应会深刻影响复原。支持、保护和真实评价，可以减轻创伤冲击；敌意、怀疑、轻描淡写或盲目接受，则可能加深羞耻、自责和孤立。所谓真实评价，不是替当事人制造虚假安慰，而是同时看见三件事：事件确实严重；人在危险中选择极其有限；许多看似“奇怪”的反应其实是正常的创伤反应。
在 App 端的沟通建议中，可以把亲友回应设计成“确认—归责—选择”三步：确认感受和经历，不急着追问证据；把责任放回伤害行为和不安全环境，而不是放到受害者的性格上；把下一步交还给当事人选择。尤其在性侵、家庭暴力、长期控制等情境中，要避免问“你为什么不反抗、为什么不离开”。更有帮助的问题是：“现在怎样会让你安全一点？”“你希望我陪你做哪一件小事？”这种回应能帮助人从被评判的位置回到有尊严的位置。
适用场景包括：亲友、伴侣、咨询助理需要回应披露。可建议使用短句：“我相信这对你很难”“谢谢你告诉我”“你希望我现在怎么陪你”。如果不知道该说什么，承认不知道也比仓促解释更好。支持的目标不是立刻让对方好起来，而是减少二次受伤。', '["关系支持", "羞耻", "自责", "亲友沟通", "真实评价", "去责备"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 330, now()),
(100331, '长期控制的影响：复原要把选择权一点点拿回来', '核心理解：长期创伤常不只是单次暴力，而是一套持续削弱自主的控制系统：制造恐惧、反复无常地惩罚、偶尔给予小恩小惠、隔绝外界支持、监控身体和日常生活、要求保密或忠诚。人在这样的环境中可能变得顺服、迟疑、依赖、难以判断危险，并不是因为“愿意受苦”，而是因为自主感被长期破坏，求生策略被固定下来。
App 端要避免用简单口号要求用户“立刻勇敢”“马上切断关系”。更稳态的方向是帮助她重新体验可控的小选择：今天要不要回复消息；是否需要找一个可信的人保存重要信息；身体需要睡眠、饮食、医疗还是安静；哪些物品、联系人、地点能支持安全感。复原不是一次夺回全部力量，而是把身体、时间、金钱、社交、表达和行动的主导权一点点收回。关系成长中，尊重边界尤其重要：任何打着关心名义的强迫，都可能复制控制；真正的帮助应增加选择，而不是替代选择。
适用场景包括：用户明知关系伤害自己却难以离开、难以拒绝、反复回到控制者身边。回答时应把重点放在控制机制和资源缺口，而不是羞辱她“不清醒”。可以帮助她建立外部连接清单、证件和财务安全意识、危机联系人，但所有建议都要允许用户按自己的节奏选择。', '["长期控制", "自主权", "安全计划", "边界", "家庭暴力理解", "小选择"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 331, now()),
(100332, '童年创伤的适应：先理解求生策略，再谈改变', '核心理解：童年长期受虐时，孩子必须在不安全的人际环境里维持依恋、寻找意义和保留希望。她可能否认、淡化或合理化伤害，可能发展出过度警觉、讨好、隐藏、解离、完美表现，或把责任揽到自己身上。许多策略在成人看来像“矛盾”或“问题行为”，但在当时可能是孩子能想到的唯一求生方式。
用于 App 端时，重点不是给用户贴上人格标签，而是帮助她把模式还原到历史背景中：当年这样做，可能是为了少受伤、保住关系、让世界看起来仍有一点希望；现在如果这些策略让关系、身体或生活受限，可以在安全前提下逐步更新。比如，把“我总是讨好”改写为“我曾学会通过顺从换取安全，现在我可以练习小范围表达不同意见”；把“我太坏了”改写为“自责曾让我以为自己还有控制感，但责任并不在孩子身上”。理解不是纵容伤害，而是让改变从羞耻中释放出来。
适用场景包括：用户把自己描述成“太会讨好、太矛盾、太假、没有自我”。回答时可把这些模式翻译成过去的保护性能力，再讨论今天的代价。这样既能减少羞耻，也能打开改变空间：不是把旧策略一刀切掉，而是在更安全的关系里练习新的反应。', '["童年创伤", "求生策略", "讨好反应", "解离", "自我理解", "去标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 332, now()),
(100333, '把责任放回正确的位置：反对“责备受害者”', '核心理解：长期创伤最容易被误解的地方，是旁观者常用正常环境里的标准评判极端处境中的选择。人们会问为什么不逃、为什么顺从、为什么沉默，甚至把反应解释成性格缺陷。这样的评判忽略了长期恐惧、隔离、依赖和控制会改变人的判断与行动范围，也会让受害者承担比加害者更严厉的道德审判。
App 端知识库应坚持“情境化理解”：先看处境、权力差和可用资源，再看行为。用户如果反复自责，可以引导她区分三类责任：伤害行为的责任属于加害者；当时有限选择下的求生反应不等于同意；现在可以承担的是照顾自己、寻找支持和逐步修复的责任。这样既避免把用户固定在无助位置，也避免把不属于她的罪责继续压在她身上。对咨询和沟通来说，去责备不是否认复杂性，而是给人一个更公平的起点，让她能在不被羞辱的环境中重新审视自己的边界、需要和未来行动。
适用场景包括：用户反复说“是不是我也有问题”“我当时为什么那样”。回答时可温和地区分“反思”和“自我定罪”：反思是为了现在更自由，自我定罪会继续替加害系统工作。若需要讨论自己的脆弱点，也必须在责任已经归位、情绪相对稳定之后进行。', '["责备受害者", "归因", "羞耻修复", "责任区分", "创伤理解", "去污名"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 333, now()),
(100334, '赋权式支持：帮助可以给建议，但不能替用户复原', '核心理解：创伤的核心伤害之一，是自主权被夺走和人与人的联系被切断。因此，复原关系的首要原则是恢复自主权。支持者、咨询师或亲友可以提供信息、陪伴、建议、照顾和资源，但不能代替当事人决定什么才是“正确复原”。即使出于善意的强行安排，也可能让人再次体验失控。
App 端的咨询话术可以遵循赋权原则：先询问许可，再提供选项；把建议说成“你可以考虑”，而不是“你必须”；允许用户暂停、拒绝、修改目标；把进展定义为她更能做选择，而不是她更听话。关系中的界限也属于赋权：清楚的时间、频率、联系规则和紧急处理方式，不是冷漠，而是创造安全领域。支持者也需要自己的支持系统，因为没有人能单独承受创伤带来的强烈情绪。真正稳固的帮助关系，是既可靠又有边界，既愿意靠近，又不控制对方。
适用场景包括：咨询对话、AI 陪伴和亲友支持。系统应优先使用选择题和开放许可，例如“要不要先停一下”“你想听建议还是只想被陪伴”。当用户拒绝建议时，不把拒绝视为阻抗，而视为自主权正在恢复；这本身就是复原的一部分。这种尊重会降低防御，让合作更可能发生。', '["赋权", "自主权", "支持关系", "治疗契约", "边界", "选择权"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 334, now()),
(100335, '复原三阶段：安全、回顾与哀悼、重建联系', '核心理解：复原常可概括为三个阶段：第一是建立安全，第二是回顾与哀悼，第三是重新连接生活。这个顺序不是僵硬流程，而是提醒我们：没有足够安全时，不宜贸然深入创伤细节；只停留在安全管理中，也可能让生命长期收缩；当故事逐渐被整合，人才有力量回到关系、工作、愿望和未来。复原也不是直线，旧问题会在新的人生节点返回，需要重新照顾。
App 端可把三阶段转化为温和导航：如果用户正在高激活或现实不安全，重点是稳定身体、环境和支持网络；如果用户已有一定资源，才进入叙事整理、意义理解和哀悼失去；如果用户开始关心未来，则支持她建立边界、选择信任的人、恢复兴趣和行动。每个阶段都要保留自主权：用户可以慢，可以绕路，可以暂停。所谓完成，并不是再也没有痛苦，而是症状可管理、记忆可承受、自尊和关系逐渐恢复，创伤成为生命故事的一部分，而不是全部。
适用场景包括：用户问“我是不是退步了”“为什么好一阵又被触发”。回答时可说明阶段会往复，复发不等于失败。不同阶段适合不同帮助：高压时做稳定和现实支持；较稳时做故事整合；有余力时做关系、边界和未来规划。', '["复原阶段", "安全优先", "回顾与哀悼", "重建联系", "长期修复", "阶段性支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 335, now()),
(100336, '安全优先：从身体掌控扩展到环境和支持网络', '核心理解：安全不是一句“别怕”，而是具体、分层、可执行的生活条件。书中把第一阶段的安全工作从身体开始，再扩展到环境和关系：身体层面包括睡眠、饮食、运动、医疗照顾、过度警觉和侵扰反应的管理；环境层面包括安全住所、经济和行动能力、日常自保计划；关系层面包括筛选可信的人、动员支持系统、必要时连接社会服务或司法资源。
App 端应把安全问题放在任何深入练习之前。可以设计低负荷问题：“我现在的身体最需要什么？”“我在哪里会更安全一点？”“谁能提供具体帮助？”“今天只做哪一个小步骤？”对长期受控的人，小任务尤其重要，因为它能重新训练计划、判断和主动性。安全计划不应制造恐慌，也不应替用户做决定，而是帮她把模糊的危险感拆成可观察的现实因素。稳定化的目标，是让用户逐渐体验：我能照顾身体，我能选择环境，我能联系可靠的人，我可以在现实世界里增加一点安全。
适用场景包括：用户情绪很高、睡眠饮食混乱、关系中仍有现实威胁。回答应先聚焦今天和本周，而不是人生大目标。可以把计划做得很小：喝水、开灯、联系一个人、把危险物移远、确定今晚在哪里睡。小而可完成的行动能积累主导感。', '["安全计划", "稳定化", "身体照顾", "环境安全", "支持网络", "自我照顾"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 336, now()),
(100337, '创伤叙事要有节奏：讲述是整合，不是强迫暴露', '核心理解：当安全基础足够后，讲述创伤故事可以帮助记忆从静止、碎片和沉默，逐渐变成可被理解的生命叙事。但讲述不是越快越好，也不是越详细越有效。过度回避会让复原停滞，过早或过猛地接近记忆，则可能让人再次被淹没。关键是在“安定的现在”和“痛苦的过去”之间来回移动，让人知道自己此刻有人陪伴、有选择、有暂停权。
App 端不应提供强刺激回忆任务，而应强调节奏和许可：用户先确认现实安全和身体承受度，再选择是否整理片段；可以从事件前后的生活背景、当时的资源、重要关系和现在的理解开始，而不是直接进入最痛苦画面；若出现明显失控、麻木、惊恐或生活功能下降，应放慢并回到稳定。讲述的目标也不是侦查事实、逼出“唯一真相”，而是让用户逐渐找到语言、情感和意义，把“发生在我身上的事”放回生命脉络中，并在尊严感中重新选择下一步。
适用场景包括：用户想整理过去，但又害怕被记忆淹没。回答可建议先建立“暂停词”“结束仪式”和事后照顾，而不是直接书写最痛苦细节。若对话中出现明显失控，应停止追问故事，转向当下感官、呼吸节奏、环境确认和可信陪伴。', '["创伤叙事", "节奏", "见证", "稳定优先", "记忆整合", "温和回顾"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 337, now()),
(100338, '哀悼不是沉溺：承认失去，释放“不必宽恕”的压力', '核心理解：创伤会带来真实的失去：失去安全感、身体边界、童年、信任、家庭幻想、旧的自我和某些未来可能。复原中的哀悼，是承认这些损失曾经发生，并允许悲伤、愤怒、失望和空白有位置。哀悼不是沉溺过去，而是让人停止用否认或自责维持旧秩序，开始为新的生活腾出空间。
这一条对 App 端尤其重要：不要把“宽恕加害者”设为疗愈任务。用户不需要等加害者认错、悔改或获得宽恕，才能开始复原。更温和的方向是发现生活中仍存在的爱、支持、价值和选择，让注意力从加害者身上逐步回到自己身上。可以引导用户区分：我可以不再被他定义，但这不等于我必须原谅；我可以哀悼损失，同时保护边界；我可以承认愤怒，而不让愤怒控制全部生活。真正的释放，常常不是替伤害找理由，而是发现自己仍有爱与被爱的能力，仍能与人建立新的联系。
适用场景包括：用户被他人劝“放下”“原谅才算好了”。回答时可明确区分放下控制权和宽恕加害者：前者是为了自己，后者不是义务。哀悼允许反复出现，也允许轻松和快乐回来；快乐不是背叛过去，而是生命力仍在。允许不原谅，也允许慢慢重新生活。', '["哀悼", "不强求宽恕", "失去", "愤怒", "自我释放", "爱的能力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 338, now()),
(100339, '重建联系与使命：边界、信任和普通生活都是复原', '核心理解：复原后期不是把创伤故事讲完就结束，而是重新进入生活。人会开始学习：哪些人值得信任，哪些人需要保持距离；怎样在亲密中保留自由意志；怎样表达需要、拒绝不合适的要求、保护下一代；怎样恢复愿望、兴趣、工作、友谊和普通日子。创伤曾让人孤立，重建联系则让人重新体验“我属于人群，也拥有自己”。
App 端可支持用户把复原落到关系和行动中：练习清晰边界，选择可靠联盟，发展同辈互助，逐步面对家庭秘密或社会压力，但所有公开表达都应有准备、有时机、有安全计划。对一些人而言，社会行动、帮助同类、教育倡导或追求正义，会把个人痛苦转化为对他人的礼物；对另一些人而言，能安稳工作、恋爱、养育、玩耍、享受生活，也同样是胜利。团体支持很有力量，但必须安全、结构清楚、适合阶段；早期以教育和自我照顾为主，深入分享应在稳定之后。长期修复的标志，是创伤仍被记得，却不再垄断人生。
适用场景包括：用户开始想恋爱、工作、公开发声、帮助别人或加入团体。回答时应提醒：使命感需要建立在自我照顾之上，不能用拯救他人来替代照顾自己。团体、倡导和正义行动都应有边界、有同伴、有退出机制；普通生活同样值得被肯定。', '["重建联系", "边界", "信任", "使命感", "团体支持", "长期修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 339, now()),
(100340, '倾听的核心：把治疗师的内在反应转化为临床信息', '《心理治疗实战录》反复提醒，治疗师并不是没有感受的“空白屏幕”。在倾听时被激发出的怜悯、愤怒、厌倦、好奇、无助、想营救、想讨好或想赶快结束等反应，本身就是理解来访者的重要线索。尤其当来访者叙述的字面内容与治疗师内心反应不一致时，常提示有未被说出的情绪、被防御遮住的关系模式，或来访者惯常激发他人回应的方式。用于 App 知识库时，可转化为咨询辅助提示：先标记“我此刻被激发了什么”，再区分这是治疗师个人议题、情境压力，还是来访者互动方式带来的信息；把感受当作待检验假设，而非事实判决。这样既能避免把反移情直接行动化，也能避免因追求中立而变得冷硬、机械、无回应。对用户端心理教育而言，这一条也可表达为：有效倾听不是没有反应，而是能觉察反应、暂缓反应，并把反应用于更准确地理解对方。在产品化时，这一条不宜被写成“凭感觉判断用户”，而应写成一套审慎流程：记录反应、命名反应、寻找触发点、回到用户原话和互动情境中验证。若系统用于辅助咨询师，可提示“此处可能需要督导或自我照顾”；若用于普通用户心理教育，则可转译为“你在关系中激发他人的感受，也可能是理解关系循环的线索”。', '["咨询倾听", "反移情觉察", "治疗师回应", "情绪承接", "临床假设", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 340, now()),
(100341, '初访不是套病史：先熟悉这个人并建立合作框架', '初始访谈的首要任务不是尽快收集完整病史、给出人格模型或套用诊断标签，而是让治疗师与来访者彼此熟悉，初步判断是否适合心理治疗，并为后续合作定下基调。书中强调，除非存在自杀风险、精神病性状态、中毒、器质性损伤或独立社会功能明显受损等紧急情况，否则初访不宜过早围绕症状清单和成长史做“搜集式审问”。治疗师可以用礼貌、真实、安定的方式开场，核对姓名和联系方式，帮助来访者适应环境；随后用开放问题邀请其说明来访理由。症状当然重要，但症状细节最好在治疗过程中、伴随具体情境自然浮现，因为其出现的情境本身就是理解症状意义的线索。App 可将这一条设计为初访清单：先做风险筛查，再确认来访者关心什么、愿不愿合作、能否理解会谈规则；不要把一次初访包装成完整诊断或治疗承诺。这也能避免 App 端常见的“问卷化冷感”：用户刚进入支持场景时，若被连续追问童年、症状频率和人格原因，可能更紧张或更自责。更合适的知识库表达是：先说明会谈/对话的目的、保密和限制，先陪用户把当前困扰说清楚，再逐步扩展到生活背景。只有当安全风险或医疗风险出现时，才把流程转向紧急求助、精神科或线下支持。', '["初始访谈", "咨询框架", "风险筛查", "合作关系", "非诊断", "咨询边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 341, now()),
(100342, '问题澄清：从概括抱怨拉回最近一次具体情境', 'Arianes 因胃痛和婚姻争吵来访时，最初只说“结了婚的人不都成天吵吗”。书中示范了几种会把会谈带进死胡同的回应：追问“总还有些可说的吧”、抽象追问“受不了是什么意思”、质疑其概括，或在初访中用沉默让来访者独自承受焦虑。更有效的做法是承认自己需要来访者协助，并把问题拉回到最近一次具体争吵：什么时候、在哪里、谁在场、发生了什么、是瞪眼、吼叫还是动手。治疗师还要解释为什么需要细节——不是审讯，而是为了确认自己真的听懂。具体化能把“我就是很痛苦”转化为可共同观察的事件，让来访者从模糊、封闭、情绪化的印象中退一步，看见事情的现实结构。App 可把它转化为问题澄清模板：先共情，再询问最近一次场景、可观察行为、身体反应、对方回应和未说出口的需要。这一条尤其适合做成 App 的追问策略：当用户使用“总是、从来、所有人、没办法”等概括词时，系统不急着反驳，而是邀请其选择一个最近、最清楚、强度适中的片段。随后再整理“事件—解释—情绪—身体—行动—后果”的链条。这样既能降低用户被评判感，也能把抽象痛苦变成可复盘、可调整的小单元。', '["问题澄清", "具体化提问", "咨询对话结构", "治疗师回应", "婚姻冲突", "身体化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 342, now()),
(100343, '直接探引遗漏部分：被回避的内容不会自动浮现', '书中反对一种常见误解：只要治疗师足够耐心，来访者没有说出的内容就会自然浮现。事实上，许多重要材料必须靠治疗师直接、适度地探引。来访者旧有的适应方式常会让他在不同情境中重复症状言行，继续归因于他人或环境，却看不见自己“此时此刻做了什么、没有做什么”。治疗师既要认真倾听以熟悉防御，也要在会谈失焦时重新抓住主诉的核心。例如 Arianes 谈花园时，花园作为减压资源值得注意，但若任由话题无边际漫谈，治疗会失去焦点；治疗师于是把话题拉回婚姻关系变化。App 可把这一条做成会谈导航：当用户叙述开始绕开核心痛点时，不急于打断，也不无限放任，而是温和标记“这里好像有个重要部分还没说清”，再邀请其回到具体行为、未表达需要和关系后果。这一策略的难点在于尺度：过早追逼会让用户感到被审问，完全等待又会让对话空转。知识库可提示助人者先确认用户是否有足够安全感，再用“我注意到这里好像停住了”“我们是否可以回到刚才那一点”之类语言邀请，而不是用“你在逃避”贴标签。它也适合辅助识别阻抗：绕开、讲道理、讲别人、讲无关细节，都可能是在保护某个尚难承受的情绪。', '["阻抗防御", "直接探引", "会谈聚焦", "此时此刻", "咨询动力", "复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 343, now()),
(100344, '治疗师犯错后的修复：一次会谈不必完美也能具有治疗性', 'Arianes 在自由联想尝试中变得焦虑，治疗师意识到推进太快，于是退回一步，换成更可承受的探索角度；后来临近结束时，治疗师也承认自己没有把固定会谈安排说清楚。书中由此提出一个重要原则：心理治疗复杂到很少有“完美开局、完美过程、完美结束”的会谈。治疗师必须习惯非完美，愿意把误解、莽撞、时间处理不佳或提问失准，转化为后续工作的材料。关键不是永不犯错，而是在发现来访者焦虑、困惑或关系断裂时，能以就事论事且不防御的方式修复。对于 App 咨询辅助，可设置会谈后复盘四问：我在哪一刻推进太快或退得太远？来访者的身体和情绪信号是什么？我如何澄清、道歉或重设框架？下次如何把这次断裂变成理解来访者模式的入口？这种复盘能帮助助人者减少“怕错而不作为”的僵硬。对 App 后台而言，这一条可转化为“断裂—修复”知识：当用户反馈“你没懂我”“这个建议没用”“我更乱了”时，系统不应急着辩解或继续给建议，而要先承认影响、询问哪里不贴合、重述用户关切，再调整方向。它也提醒真人咨询师：复盘不是自责，而是把技术失误、节奏失衡、边界不清转化为更准确的下一步。修复本身往往比完美回应更能建立可信关系。', '["关系修复", "治疗师复盘", "咨询误差", "会谈结束", "情绪承接", "督导训练"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 344, now()),
(100345, '个案概念化：把当前互动、童年经验和自我实现预言连起来', 'Arianes 的婚姻痛苦不只是“妻子不体贴”，而是他期待妻子像理想化母亲一样无需说明就懂自己；当这种期待落空时，他便退回到九岁受伤男孩的位置，预期亲近女性会忽视自己的需要。治疗师没有把童年创伤当作标签，而是在当前婚姻互动、来访者对妻子的期待、童年向母亲求助被责骂的记忆之间，提出一个可探索的假设：他把早年形成的态度带进成年亲密关系，进而以不表达需要、带着拒绝预期靠近妻子的方式，制造了自我实现预言。App 可将这条转化为个案概念化框架：当前触发事件是什么？来访者自动期待什么？这种期待像哪段早年关系？它如何影响来访者的表达、回避或攻击？当下有没有新的回应可能？内容需以假设方式呈现，不宣称已解释全部人格，也不替代专业治疗。这一条也提醒 App 不要把“原生家庭”作为万能解释。早年经验只有在它能解释当下可观察的互动循环时，才适合进入概念化；否则容易让用户停在责怪过去或把自己固定成受害者。较好的呈现方式是：过去形成了某种保护性预期，这个预期曾经有用，但现在可能让用户少表达、先防御、误读他人，从而重复旧结局。目标不是追责，而是增加新的选择。', '["个案概念化", "早年经验", "亲密关系", "自我实现预言", "防御模式", "治疗性假设"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 345, now()),
(100346, '移情是工作材料：直接处理来访者对治疗师的担心与贬低', 'Arianes 在会谈中批评治疗师办公室“很差劲”，进而把治疗师看成“失败者”。治疗师没有急着解释房子不是自己的、也没有回避这个议题，而是把它当作移情关系的材料：来访者似乎需要把治疗师看成像父亲一样软弱、失职、终将让自己失望的人。书中强调，移情不是只在精神分析中才出现的危险物，也不是一出现就会打开“潘多拉之盒”；在一般心理治疗中，来访者对治疗师的担心、欣赏、失望或攻击，常是理解其旧关系模板的关键。治疗师越能直接而不防御地处理这些感受，越能让来访者体验到：负面想法可以被说出来，关系不会因此崩塌。App 可提供移情观察提示：来访者是否把治疗师/平台/建议者想象成会批判、抛弃、失败或控制自己的人？这与其现实关系中哪些期待相似？此刻是否适合温和澄清，还是先承接情绪？用于 App 时，不宜把普通用户对平台或建议的不满都解释成移情；更稳妥的是把它作为关系线索：用户是否在期待“你也会像别人一样不可靠/批评我/控制我”？如果是，回应要先承认这种担心的现实感，再说明当前对话能做什么、不能做什么。对咨询师辅助场景，则可提示：不要急于证明自己无辜，也不要把来访者的贬低当成人身攻击；先看它在关系中承担什么功能。', '["移情关系", "治疗师回应", "负面情绪", "关系模板", "动力取向", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 346, now()),
(100347, '负向移情与攻击：先代谢治疗师自己的受伤，再形成可检验假设', 'Banks 初访时质疑治疗师年轻、男性、未必有能力，还用专业术语和前任治疗师压迫新治疗师。书中列出多种无效回应：被激怒后冷漠拒绝、用专业地位反击、急着证明自己没有性别偏见、过早指出“你在贬低我”。更有效的路径是：治疗师先觉察自己被伤害、焦虑、愤怒的感受，暂缓防御反击，再把这些反应转化为假设——如果她也这样对待潜在男性伴侣，关系会怎样？她的攻击是否在保护自己免于再次失望？随后治疗师忽略挑衅，转而询问她现实中的亲密关系。负向移情不是要被纵容，也不是治疗师必须无条件忍受辱骂；只有当这些言行能被带回会谈、促进来访者理解自身模式时，才具有治疗价值。App 可把它转化为“被攻击时三步”：稳定自己、识别关系功能、选择是否把攻击变成可讨论材料。这一条可用于训练“不过度个人化”的临床思维。来访者的尖锐语言会真实地伤到治疗师，否认这一点反而容易在后续以冷淡、讽刺或撤退表现出来。较好的做法是先在内心承认受伤，再问：这个攻击是否在测试我会不会报复？是否在迫使我离开以证明旧信念？是否在转移丧失和羞耻？只有当治疗师能稳住自己，才可能既设边界，又不放弃理解。', '["负向移情", "阻抗防御", "治疗联盟", "治疗师反应", "攻击性", "咨询边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 347, now()),
(100348, '治疗联盟不是互相喜欢：能在攻击和不信任中继续工作才是联盟', '书中对“治疗联盟”提出了一个很务实的理解：它并不等同于来访者喜欢治疗师、治疗师也喜欢来访者，更不是双方从一开始就有清晰一致的共同目标。许多来访者因为害怕亲密、预期被伤害或羞耻，会把自己表现得很不讨喜；如果治疗师把“建立亲善关系”当成首要目标，就容易被迫讨好、解释、证明自己。Banks 反复怀疑治疗师是否会发火、是否能理解她，治疗师没有急着证明“我很好”，而是把无法信任本身作为问题来探索：你想象我会做什么？这让怀疑变成可理解、可检验的材料。对 App 咨询辅助而言，这一条可用于提醒助人者：关系质量不只看互动是否温和，也看双方能否承受不信任、失望、愤怒和尴尬；治疗师要能稳定地喜欢自己的专业姿态，才能不被来访者的喜欢或不喜欢牵着走。这对 App 的启发是，支持性语言不能只追求“让用户舒服”。有时用户需要的不是被赞同，而是有人能稳定地承接其怀疑，并把怀疑拆成可讨论的问题。知识库可提供两类回应：一类用于先安定关系，如“你担心我也会误解你”；一类用于推进探索，如“如果我真的会让你失望，你最担心发生什么”。这种设计能避免系统一味讨好，也避免在用户攻击时机械地结束支持。', '["治疗联盟", "不信任", "关系承受力", "治疗师稳定性", "防御", "咨询关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 348, now()),
(100349, '诊断与治疗目标：不要只看症状标签，要看关系能力和情境功能', '书中通过 Clark、Billy、Frank、Delmore、Elbogen 和 Banks 等案例说明，临床判断不是把症状逐条套进标签，而是在具体情境中观察一个人如何生活、如何与治疗师互动、能否使用关系来反思自己。Billy 有视听体验，但与人交流的方式不像精神分裂症患儿，最终需考虑神经科因素；Clark 的丧偶抑郁要放在其长期依赖妻子维持功能的背景中理解；Delmore 与 Elbogen 都有异性关系困难，但前者能自我检视、信任治疗，后者则广泛外归因、难以把治疗师当作情感对象。治疗计划也因此不同。App 端知识库可将其表述为：心理教育内容不做诊断判决，而帮助用户区分症状、功能、关系能力、风险信号和求助路径。真正有意义的问题不是“这是什么标签”，而是“这个人在什么情境下失去秩序感？他能否借助关系恢复反思与行动？”在知识库落地时，这一条应明确区分“心理教育解释”和“临床诊断”。App 可以帮助用户理解焦虑、抑郁、创伤、人格模式等概念，但不应根据几句描述判定人格障碍或精神疾病。更有帮助的是引导用户观察：症状何时出现、是否影响睡眠饮食工作、人际中是否重复同一循环、是否能求助和反思、是否存在自伤或精神病性风险。这样既能减少标签化，也能提高转介判断质量。', '["鉴别诊断", "非标签化", "治疗目标", "功能评估", "移情关系", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 349, now()),
(100350, '青少年与抑郁初访：先评估安全和边界，再把症状放回发展任务', 'George 退学后出现失眠、食欲下降、无意义感和对“会不会发疯”的恐惧。治疗师没有立刻把会谈变成症状清单，而是先做必须的安全评估：直接询问是否想过自杀、是否曾行动、现在是否仍有冲动，同时在合适时机询问药物、酒精、毒品和自伤风险。书中强调，谈自杀时态度比措辞更重要；实事求是的提问通常能让来访者感到痛苦被认真对待。随后，治疗师清楚说明保密边界：父母付费不等于可以知道治疗细节，但若来访者无法保证不伤害自己，治疗师会采取必要保护措施，可能包括通知父母。对抑郁的理解也不以“消除症状”为唯一目标，而是帮助来访者重建自我方向、行为能力和成长任务。App 可据此设计青少年心理教育：安全筛查、隐私说明、支持网络和专业转介优先，内容只作为辅助，不替代危机干预或治疗。对 App 而言，青少年场景还需要特别处理家长角色：既要尊重青少年的隐私和主体性，也要在安全风险、虐待风险或严重功能受损时启动成人支持和线下资源。知识库可给出边界话术：哪些内容会保密，哪些情况必须寻求帮助，为什么这不是背叛而是保护。随后再帮助用户探索失恋、离家、学业、身份选择等发展任务，避免把一切简化成“情绪不好”。', '["青少年抑郁", "危机评估", "保密边界", "自杀风险", "发展任务", "专业求助"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 350, now()),
(100351, '适度自我披露：只有服务治疗目标时才进入会谈', '书中批评把治疗师“匿名状态”绝对化的教条。治疗师个人生活不应随意敞开，但这并不意味着治疗师必须永远像无名机器。George 问自己为什么没有接受更深入的精神分析时，治疗师不仅解释当前治疗形式为何适合，还说自己若在 18 岁时能坐在 George 的位置上，或许能避免许多不幸。作者说明，这种披露不是满足治疗师表达欲，而是为了让 George 认同一个曾在青春期探索、并非全知全能的现实导师，从而推动理想化移情走向更成熟的方向，而不是把治疗师幻想成“治疗师上帝”。App 可把它转化为助人者提示：自我披露前先问三件事——它服务谁的需要？是否帮助来访者理解自己或关系？披露后是否仍能回到来访者经验？若答案不清楚，就应保持节制。这一条也适用于 App 人设设计：系统可以有温度，但不应编造个人经历来获取信任；真人助人者可以适度分享，但必须可追溯到来访者利益。判断标准包括：披露是否简短、是否与当前主题直接相关、是否帮助用户减少孤立或形成新视角、是否会把注意力转移到助人者身上。若披露后用户开始照顾助人者、比较谁更痛苦，或偏离自己的体验，就需要及时收回焦点。', '["自我披露", "咨询边界", "理想化移情", "治疗师真实", "青少年咨询", "专业节制"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 351, now()),
(100352, '治疗终结与复盘：结束不是完结，而是把功能还给来访者', 'Arianes 治疗后期提出“还需要来多久”，治疗师没有替他做终止决定，而是把结束治疗本身作为一次成长任务：问题不在于是否必须继续来，而在于来访者是否已经完成了想通过治疗为自己做的事。书中提醒，终结常会激活两类反应：担心治疗师不满自己的独立，或回避与治疗师分离的失落。因此治疗师既不应匆忙结束，也不应为了自己的失落延长治疗，而要帮助来访者讨论决定、检验联想、确认新的功能是否已经能在生活中运作。Arianes 最终把对父亲式照顾的需要转化为对侄子 Bobby 的照顾，并保留必要时再联系的通道。App 可将其设计为阶段复盘：我现在能独立处理什么？哪些旧防御还会出现？我如何把治疗中的理解迁移到现实关系？需要怎样的后续支持？终结不是治疗神话的圆满，而是把选择权与责任逐步还给来访者。这一条也可用于 App 的阶段性结案或低频随访设计：当用户状态好转时，不必制造依赖或继续挖掘所有问题，而应帮助其命名已经学会的能力、预判复发信号、确认现实支持者、约定需要时如何重新求助。复盘问题可以包括：我现在怎样理解最初的困扰？我学会了哪些不同回应？哪些情境仍容易把我带回旧模式？如果旧模式出现，我第一步能做什么？', '["治疗终结", "复盘", "自主性", "分离议题", "关系修复", "后续支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 352, now()),
(100353, '四类治疗功能：安抚、整合、恰当觉醒与诠释', '结论章将治疗师在移情关系中的功能概括为四类，可作为 App 咨询辅助的后台分类。第一是安抚：治疗师暂时承接来访者过强的正向或负向情感，不以惩罚回应挑衅，让情绪不至于压垮来访者。第二是整合：当来访者失去秩序感时，治疗师通过倾听、整理和连接，暂时帮助其恢复组织经验的能力。第三是恰当觉醒：当来访者的性格要素导致误解或伤害他人时，治疗师在时机成熟时温和面质，使其看到自己不愿承认的部分。第四是诠释：把当下行为与过去或当前关系的意义连接起来，让来访者用新的眼光理解自己。书中也提醒，这些技术没有固定层级，不能机械匹配某个诊断；同一个来访者在不同会谈中所需功能会变化。App 可据此给回复打标签：当前更需要承接、整理、面质还是解释？先判断来访者可承受度，再选择回应深度。这四类功能还能帮助避免“所有问题都用同一种语气回应”。例如用户情绪爆表时先安抚，叙述混乱时先整合，反复合理化伤人行为时才考虑恰当觉醒，已经具备反思能力时再做诠释。若顺序错了，深度解释可能变成压力，过度安抚可能固化回避，过早面质可能造成关系断裂。因此后台知识库可把每条回复先标注主要功能，再生成与用户承受度匹配的语言。', '["治疗干预", "情绪承接", "整合", "面质", "诠释", "咨询辅助"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 353, now()),
(100354, '团体疗效因子地图：把关系改变看成多机制叠加', '【核心观点】团体之所以能促进关系成长，不是因为某一种神奇技术，而是多个疗效因子在同一场域中叠加：希望、普遍性、信息传递、利他、原生家庭关系的矫正性重现、社交技能、模仿、人际学习、凝聚力、情绪宣泄和存在性反思。把这些因子当作“地图”而不是清单，App 端就能避免把社群运营简化成打卡、倾诉或知识灌输。
【产品转化】设计社群或小组课时，可让每个环节对应一种机制：开场提供希望和共同语言；互动环节促进普遍性与互助；反馈环节让成员看见自己的影响；复盘环节把体验转为可迁移的行动。
【运营提醒】不同用户受益点不同：有人需要先被接纳，有人需要清晰反馈，有人需要在帮助别人时恢复价值感。知识库可提示运营者观察“哪些因子在这个群里被激活，哪些被忽略”，而不是只追求热闹或情绪释放。
【内容落点】适合做成后台的“机制标签”或运营检查表：本周内容是否只在传递知识，是否也创造了互相回应；用户是否只有表达出口，还是能收到反馈并尝试新行动；群体是否只是陪伴，还是逐渐形成规范和凝聚力。这样可以把心理教育从单篇文章升级为一套可观察、可迭代的关系场域设计。', '["团体疗效因子", "团体心理教育", "关系成长", "社群运营", "心理机制", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 354, now()),
(100355, '希望感来自可见的进步：让新成员看到“有人已经走过”', '【核心观点】希望不是空泛鼓励，而是“我也可能改变”的可见证据。团体中的成员处在不同阶段：有人刚加入、有人正在挣扎、有人已经走过一段路。新成员看到相似处境的人发生了真实进步，会比单纯听带领者解释更容易产生信心。带领者自身对团体有效性的稳定信念，也会影响成员是否愿意投入。
【产品转化】App 社群可以设计“进步证据墙”“阶段故事”“老成员给新成员的一句话”等轻量机制，展示具体、可信、非夸张的变化：学会求助、能表达感受、敢参加线下活动、减少回避。
【边界提醒】希望感不是承诺疗效，也不是制造励志压力。更适合表达为：有人曾经也困惑、羞耻、孤独，但通过持续参与、被支持和练习，获得了新的关系经验。对新用户而言，看到可达成的小变化，往往比听宏大口号更有力量。
【内容落点】希望还可以来自时间维度：提醒用户回看自己几周前与现在的差别，或让老成员讲述“我当时也不信这个练习有用，但后来发现自己能多停留十分钟”。这些细小证据比宏大成功故事更适合心理教育产品，因为它降低比较压力，同时提升自我效能。尤其要让故事保留普通人的犹豫和反复，避免把进步包装成线性胜利。', '["希望感", "同伴榜样", "康复叙事", "新成员引导", "社群氛围", "关系成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 355, now()),
(100356, '普遍性：从“只有我这样”回到“我属于人类”', '【核心观点】许多关系困扰会被孤立感放大：用户以为只有自己有羞耻、嫉妒、攻击性、依赖、疏离或奇怪幻想，于是更加不敢说。团体中的普遍性体验能把“我是坏的/怪的”松动为“这也是人类经验的一部分”。当成员听见他人也有相似担忧，并在安全氛围里被接纳，羞耻感会下降，连接感会提升。
【产品转化】App 端适合用匿名问题箱、相似经历投票、主题共鸣卡、去羞耻化文章来激活普遍性。例如：“你是否也会在关系里既渴望靠近又想逃？”让用户看到分布，而不是暴露个人隐私。
【运营提醒】普遍性不等于抹平差异。文化、性别、年龄、身份背景会影响成员能否感到“被包括”。因此，社群话术要同时呈现共同人性和差异尊重：不是“大家都一样”，而是“你的经验有其独特处，也并不使你孤立于人类之外”。
【内容落点】这一条尤其适合做成“你不是一个人”系列，但要避免把痛苦浪漫化。可用方式包括：展示匿名高频困扰、提供温和命名、邀请用户把秘密拆成“事实—感受—需要”三部分。目标不是让用户立刻公开最深秘密，而是让他们先获得一点点可说、可被理解的空间。这种呈现能同时降低羞耻并保护个人节奏。', '["普遍性", "去羞耻化", "孤独感", "匿名表达", "多元文化", "社群安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 356, now()),
(100357, '利他主义：帮助别人也是重建自我价值', '【核心观点】团体中，成员不仅通过被帮助而受益，也会通过帮助别人而恢复价值感。很多人进入关系成长场景时带着“我没有什么可提供”的自我评价；当他们的倾听、提醒、经验或一句真诚反馈真的帮到了别人，自尊和意义感会被重新点亮。利他的关键不是拯救，而是在接受帮助和提供帮助之间灵活切换。
【产品转化】社群可以设计互助型角色：欢迎新成员、经验回应、复盘伙伴、资源整理、情绪陪跑提醒等，让用户以小剂量贡献参与共同体。App 内容可强调“你不需要成为专家才可以有价值”，只要表达真实经验、提出一个好问题、见证别人，都可能成为支持。
【运营提醒】利他要避免滑向过度助人或抢救。好的互助结构应鼓励成员先照顾自己的边界，再提供有限、具体、可拒绝的帮助；同时让被帮助者也有机会回馈，避免固定的拯救者—受助者等级。
【内容落点】后台可为不同活跃度用户设计不同贡献入口：只点赞也算见证，回复一句“我懂”是陪伴，整理资源是服务，分享复盘是经验传递。贡献等级不应制造排名，而应帮助用户发现“我在关系里有影响力”。当用户长期只求被照顾，也可以温和邀请其尝试一次小回馈。', '["利他主义", "互助社群", "自我价值", "意义感", "助人边界", "同伴支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 357, now()),
(100358, '团体凝聚力：安全归属是改变的土壤，不是讨好式和谐', '【核心观点】团体凝聚力是成员对团体、带领者和彼此关系的吸引与信任：我被看见、被重视、被接纳，也愿意重视这个团体。它既本身有疗愈作用，也是其他机制发生的前提。没有足够归属感，成员很难冒险自我暴露、表达愤怒、接受反馈或尝试新行为。
【产品转化】App 社群的凝聚力可通过稳定节奏、清晰规则、可靠回应、共同语言和小组身份来建立。指标不应只看发言量，还要看成员是否愿意回来、是否提及具体成员、是否能在被触动后继续留在关系里。
【重要区分】凝聚力不是永远温暖、夸夸群或零冲突。真正有凝聚力的团体能容纳不同意见，并在冲突后继续沟通。过度追求表面和谐，可能压抑敌意，让关系停滞；过早、过猛的冲突，又可能在凝聚力尚未形成时撕裂团体。运营者要把握节奏：先稳住归属，再邀请真实。
【内容落点】凝聚力可被拆成四个可运营信号：成员是否愿意准时出现，是否愿意回应他人而不只发自己的内容，是否能在不舒服后回来说明，是否开始使用“我们”的语言。若群内只有热情欢迎却没有真实反馈，凝聚力可能停留在表层；若冲突频繁但无人离开并能复盘，反而可能是更成熟的连接。', '["团体凝聚力", "归属感", "心理安全", "冲突容纳", "社群留存", "关系氛围"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 358, now()),
(100359, '人际学习：看见意图与影响之间的差距', '【核心观点】关系成长的关键，不只是理解“我为什么这样”，还包括看见“我的行为在别人那里造成了什么影响”。团体像一个社会缩影：成员平时在外部关系里反复出现的互动循环，会在小组中重演，并被多人观察到。一个人可能主观上想靠近，却因为抢话、冷漠、讽刺、分析过度或退缩，让别人感到距离和压力。
【产品转化】App 可把人际学习转化为可练习的问题：我刚才的表达让你更想靠近还是远离？我以为自己在帮忙，你实际感到被支持还是被控制？当我沉默时，你会怎么理解我？这些问题帮助用户从“自我解释”进入“关系影响”。
【运营提醒】人际学习需要多个视角，而不是单一评判。不同成员对同一事件的感受可能不同，正是这些差异让用户看见他人的内在世界。社群内容应鼓励具体观察、感受和影响，而非人格标签。
【内容落点】后台可以给 AI 助手配置“意图—影响”提示：当用户解释自己动机时，追问别人可能收到什么；当用户抱怨别人反应时，邀请他回看自己前一步行为。这个机制也适合关系课程作业：记录一次互动中“我想传达什么、对方可能感到什么、我下次要怎样验证”。', '["人际学习", "社会缩影", "意图与影响", "关系反馈", "自我觉察", "社交技能"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 359, now()),
(100360, '此时此地：把当场发生的互动变成可迁移的学习', '【核心观点】“此时此地”不是只聊当下情绪，而是把团体现场正在发生的关系过程拿来观察、体验和理解。它有两个层面：第一，成员真实地在现场产生感受、靠近、回避、愤怒、羡慕或关心；第二，团体回看刚刚发生了什么，理解互动模式及其意义。只有体验没有反思，容易变成短暂强烈的情绪事件；只有反思没有体验，又会变成枯燥分析。
【产品转化】在社群运营中，当成员把话题转向外部人物时，可以温和拉回：“当你这样说时，群里的人有什么感受？”“你刚才选择沉默，和你在线下关系里的沉默像吗？”“这一次我们能不能试着不猜外部那个人，而是看看你和大家之间发生了什么？”
【使用边界】此时此地需要安全和节奏。它不是逼问隐私，而是帮助用户在真实互动中生成可迁移的学习：我如何表达、别人如何接收、我如何修复。
【内容落点】此时此地也能用于线上群：谁被频繁忽略，谁总在解释外部人物，谁只在别人痛苦时给建议，谁在被回应后消失。运营者不必把所有话题都拉回现场，但当外部故事反复出现且无法推进时，现场互动就是更好的材料。关键是用邀请式语言，而非审问式语言。', '["此时此地", "进程觉察", "体验与反思", "关系实验室", "小组复盘", "社群互动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 360, now()),
(100361, '反馈文化：具体、真诚、可承受地说出彼此影响', '【核心观点】有效反馈的目标，是让对方看见自己的行为如何影响关系，而不是给人格下判决。反馈太模糊，如“你挺好的”，难以促进改变；反馈太羞辱，如全面否定一个人，又会让对方防御或崩溃。更有用的表达是：描述具体行为、说出自己的感受、连接对方目标，并留下继续探索和修复的空间。
【产品转化】App 可提供反馈模板：①当你做/说……；②我感到……或我更想靠近/远离；③我猜这可能与你想要的关系目标相反；④你愿意听听大家怎么看吗？同时鼓励提问具体化：“我哪里让你难以靠近？”比“你喜欢我吗？”更可操作。
【运营提醒】反馈应随信任程度递进。早期先从观察和自我感受开始，少推测动机；只有在关系足够稳固时，才进入更深层模式。带领者要示范共情式反馈，并及时阻止嘲讽、标签化和堆积后的爆发式攻击。
【内容落点】反馈文化需要配套接收训练：用户不仅学习怎么说，也学习听到反馈时先复述、确认、暂停防御，再决定是否采纳。App 可提供“反馈后自我稳定”小工具，如呼吸、写下事实、区分行为和人格、选择一个可尝试的调整点。这样反馈才不会变成互相伤害。', '["反馈", "共情式反馈", "行为描述", "关系影响", "非标签化", "沟通模板"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 361, now()),
(100362, '带领者的三项任务：维系结构、塑造文化、启动成员互动', '【核心观点】团体带领者不是每个问题的直接解答者，更像乐队指挥：知道何时发声、何时退后，帮助成员之间产生有效互动。其基本任务包括：创立并维系团体结构，建立适合成长的团体文化，推动疗效因子在成员互动中发生。带领者的态度比技巧更底层：关心、真诚、共情、文化调谐和稳定投入，是挑战能够被接收的前提。
【产品转化】App 端的社群运营者、课程带教或 AI 助手可被设计成“容器维护者”：提醒规则、照顾新成员融入、观察沉默者和垄断者、把外部故事转化为现场互动、鼓励成员互相回应，而不是所有人都只对管理员发言。
【行为准则】带领者无法“不影响”规范：迟到、忽略、过度主导、只回应某类表达，都会塑造文化。优秀带领者会有意识地强化自我暴露、直接沟通、尊重差异、互助和复盘，同时保护团体完整性。
【内容落点】在产品里，带领者任务可部分由规则、流程和 AI 提示承担：自动欢迎新成员，提醒匿名和保密，提示成员互相回应，识别连续沉默或过度发言。但核心判断仍需要人来把握：什么时候保护个体，什么时候保护团体；什么时候给建议，什么时候让成员之间生成答案。', '["带领者任务", "团体文化", "社群主持", "规范塑造", "互动设计", "心理安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 362, now()),
(100363, '规范与边界：保密、出勤、外部联系和同意是安全容器', '【核心观点】团体越鼓励真实表达，越需要清晰边界。很多新成员害怕被嘲笑、被迫暴露、隐私外泄，或在群体中失去自我。准备阶段需要提前解释：团体目的、参与方式、出勤期待、保密原则、外部联系、亚团体、危机例外和知情同意。边界的价值不是控制成员，而是让他们知道“这里发生什么、不会发生什么、例外如何处理”。
【产品转化】App 社群应有易懂的入群说明：不转述他人故事；只分享自己的体验；截图、私聊拉帮、二次传播需要明确禁止或说明；线下/私下联系要回到群内透明讨论；涉及身体接触、深度练习或敏感信息时需获得明确同意。
【运营提醒】单纯命令“不能做”效果有限。更好的方式是解释某行为为何损害共同目标：秘密联盟会让成员无法坦诚，隐私外泄会破坏安全，缺席会影响整个小组。规则越能连接到成长目标，越容易被内化。
【内容落点】可沉淀成入群前的“共同契约”：我可以选择分享多少；我不会截图传播他人的故事；我会尽量按约出现；我若与成员私下联系，会尊重对方并在必要时回到群内讨论影响。契约最好用问答和场景题呈现，而不是长篇制度，让用户知道规则在保护他们的表达自由。', '["边界", "保密", "知情同意", "社群规则", "入组准备", "外部联系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 363, now()),
(100364, '自我暴露与透明度：开放要服务关系成长，不是倾倒隐私', '【核心观点】自我暴露有治疗性，也有风险。成员的适度开放能带来普遍性、凝聚力和反馈机会；带领者的透明也能示范真实、正常化感受、拉近关系。但开放并不等于越多越好。判断标准始终是：这次暴露是否服务成员成长、关系真实和团体任务，还是在满足表达者的宣泄、控制、求关注或越界需求。
【产品转化】App 可把自我暴露设计成分层：轻度事实、当下感受、关系影响、深层脆弱。用户不应被要求一开始就说最隐私的内容；可以先从“我愿意分享的部分”开始。运营者或 AI 助手若进行自我揭示，应短、准、为用户服务，例如：“我注意到听到这里我有些担心，想确认你是否需要更多支持。”
【边界提醒】透明度要和保密、同意、角色清晰配套。带领者要等情绪平稳后再暴露，避免把未经处理的个人反应倾倒给成员；不确定是否合适时，应回到目标、影响和边界来判断。
【内容落点】知识库可给用户一套判断问题：我现在分享，是为了更真实地连接，还是为了获得即时安慰、证明自己、压倒别人？我分享后愿意听反馈吗？我是否尊重听众的承受度？对带领者则可提示：每次自我暴露后观察成员是否更能工作，而不是更关注带领者本人。', '["自我暴露", "透明度", "真实表达", "角色边界", "脆弱表达", "社群安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 364, now()),
(100365, '冲突处理：不急着灭火，把冲突转化为现实检验与修复', '【核心观点】冲突不是团体失败的证据，常常是关系学习的入口。有凝聚力的团体会鼓励成员在支持之外表达不同意见和不满；如果敌意被压下去，它会以冷漠、缺席、替罪羊或背后结盟的形式出现。真正关键的是：冲突中沟通不能中断，成员要为自己的表达负责，并在风暴之后继续保留关系。
【产品转化】App 社群遇到冲突时，不必立刻删除一切负面情绪，也不应放任羞辱。可引导四步：①暂停人格攻击；②请双方描述具体行为和影响；③询问各自真正重视什么；④把冲突连接到共同目标，如“我们如何既保留真实，又让这里可继续参与？”
【进阶提醒】有些冲突表面在争内容，深层可能是权力、被看见、被忽略、与带领者的不满，或偏离主要任务的次级满足。带领者要问：这个冲突让团体回避了什么？它是否能帮助成员看见自己的关系模式？
【内容落点】冲突后需要有“修通脚手架”：复述对方真正听到的影响，承认自己表达中的可负责部分，说明仍想留在关系中的意愿，商量下一次更好的提醒方式。对社群来说，最有价值的不是证明谁对谁错，而是让成员体验到：关系可以出现裂缝，也可以通过诚实、边界和责任被修复。', '["冲突处理", "关系修复", "现实检验", "替罪羊", "主要任务", "社群治理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 365, now()),
(100366, '支持与挑战平衡：先有接纳，再推动冒险与新行为', '【核心观点】支持和挑战不是对立面。没有接纳，挑战会被体验成羞辱或控制；没有挑战，支持会停留在安慰，无法推动新行为。团体工作的艺术在于：先让成员感到被关心、被理解、可留下，再邀请其面对回避、尝试表达、承受反馈、修复冲突。早期凝聚力越稳，后续越能进行更困难的人际工作。
【产品转化】App 端可用“支持—挑战双轨”设计：每次困难分享后，先有共情回应，再有一个可选择的小挑战。例如：“听起来你很受伤；如果你愿意，我们也可以一起看看，你沉默时别人可能怎么理解你。”对积极参与但回避冒险的用户，可逐步邀请更具体的表达；对按时出现但情感缺席的用户，可邀请描述此刻身体和关系感受。
【运营提醒】挑战要个性化、可拒绝、可复盘。面对高防御、羞耻重或文化上不习惯公开表达的人，节奏要慢；面对反复垄断、攻击或回避者，带领者要更清晰地把反馈连接到其目标。
【内容落点】后台可以把回应分成三档：稳定型回应用于情绪高峰，探索型回应用于用户开始好奇，挑战型回应用于关系足够稳且目标清晰时。比如同样面对“我不想说话”，早期可以接纳沉默，中期可以询问沉默的保护作用，后期可以邀请用户尝试说出一句真实感受。', '["支持与挑战", "心理安全", "冒险尝试", "新行为", "情绪承受", "小组带领"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 366, now()),
(100367, '会谈摘要与反馈监测：让团体学习有连续性', '【核心观点】团体中的重要体验常常太强烈，成员当下只能防御或生存，过后才有能力理解。会谈摘要能帮助成员重新看见关键互动，把“发生过的事”转化为可学习、可保存、可迁移的经验。持续反馈监测则让带领者不只依赖直觉，而能及时发现谁正在掉队、谁参与但不冒险、谁出席却情感缺席。
【产品转化】App 可以在小组课后生成隐私保护的复盘卡：本次主题、重要互动、可复习的关系观察、成员可自选的下一步练习。对个人层面，可提供轻量问卷追踪归属感、表达度、被理解感、冲突压力和行动尝试。对团体层面，可观察群内回应是否集中在少数人、是否出现沉默、是否有成员边缘化。
【边界提醒】摘要不是裁判判词，也不应泄露隐私。应避免姓氏和敏感身份信息，使用成员同意的安全传送系统；收集反馈后必须被使用，否则会削弱用户继续反馈的意愿。
【内容落点】摘要还可服务长期成长档案：用户能看到自己从“只讲事件”到“能讲感受”，从“听到反馈就退缩”到“能回来澄清”的变化。反馈监测则可帮助运营者发现隐性风险：高频发言者不一定参与深入，沉默者不一定没有收获，满意度高也不等于有挑战。数据要回到对话中使用。', '["会谈摘要", "反馈监测", "复盘", "连续性学习", "隐私保护", "实践证据"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 367, now()),
(100368, '类型不是判词：把它当成观察注意力流向的语言', '核心观点：心理类型更适合被理解为一套观察语言，而不是给人定终身的标签。OCR 第十章把类型分成两层：一层是一般态度，即注意力和心理能量更习惯流向客体，还是更习惯回到主体；另一层是功能类型，即一个人更常用思维、情感、感觉或直觉来适应生活。它描述的是“我通常怎样定向、怎样取样、怎样做判断”，不是“我本质上只能成为什么人”。

App 落地时，应把类型表达为倾向和假设：此刻我更被外界事实、关系反馈、机会和评价牵引，还是更被内在意义、个人原则、想象和安全感牵引？我正在用逻辑、价值、身体事实还是可能性来理解事件？这样，类型帮助用户看见自己的默认路线，而不是把选择权交给测验分数。

关系价值：当用户说“我就是这样的人”“TA 就是这种类型”时，可以引导他们改写为“我在这个场景里常这样反应”。类型越被当成观察镜头，越能增加选择；越被当成身份判决，越容易变成借口、审判或自我设限。

应用边界：如果后续要接入测评结果，建议始终用“可能更倾向于”而不是“你就是”。系统可以把类型结论和具体场景绑定，例如“在冲突中你更常先退回内在判断”，并要求用户举出反例。能找到反例，恰好说明类型没有夺走人的自由。', '["心理类型", "非标签化", "自我理解", "注意力流向", "人格成长", "App知识库"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 368, now()),
(100369, '外倾的礼物与风险：会顺应世界，也要把自己带回来', '核心观点：外倾不是“爱社交”的同义词，而是一种把兴趣、判断和行动优先连到客体与客观事实上的态度。它的礼物是现实适应力：能迅速读到环境需要，跟随机会、规则、他人反应和外部条件调整自己；在团队、市场、社交、执行场景中，这种能力很有价值。

风险在于，外倾若过度，会把“外面正在发生什么”当成唯一真实的东西。OCR 第十章提到，外倾者可能连身体状态和内在需要这种最直接的主观事实都忽视，直到疲惫、症状或亲近者的反馈出现，才发现心理已经失衡。关系中也容易出现一种误会：外倾者以为自己只是在回应现实，伴侣或朋友却感到 TA 总是被工作、社群、机会和他人评价带走。

App 可以给外倾倾向用户三个回收问题：第一，外界要我做什么？第二，我的身体和情绪正在说什么？第三，如果不急着适应别人，我真正想保留什么？这样既不否定外倾的行动力，也防止用户把自我照顾误认为自私或低效。

应用边界：外倾成长的重点不是减少关系或机会，而是在行动前后留出一个回到主体的停顿。系统可在用户连续加班、频繁社交、强烈追逐反馈时提醒：今天有没有一个决定不是为了回应外界，而是为了照顾真实需要？', '["外倾", "客体定向", "自我照顾", "身体觉察", "关系平衡", "过度适应"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 369, now()),
(100370, '内倾的礼物与风险：能守住主体，也要检验外界反馈', '核心观点：内倾不是“孤僻”或“不合群”，而是心理能量从客体退回主体，先由内在立场、意义、想象、原则或感受来决定反应。它的礼物是独立、深度和不轻易被环境裹挟：当外界声音很大时，内倾能保护个人判断，保留对复杂内在经验的敏感。

风险在于，内倾若过度，客体容易被体验成压力、干扰或威胁。第十章讲到，内倾类型面对客体时常有自我坚守与防御倾向，外在表达也可能显得冷漠、隐秘、犹豫或不易理解。关系中，这常被误读成“不在乎”“不信任”“高冷”；而内倾者本人可能只是还没有把内在过程翻译成别人能听懂的语言。

App 可以把内倾成长设计成双向练习：一边允许用户先安静、书写、整理自己的主观事实；一边提醒用户把一个内在结论拿到外界小范围验证。可用句式是：“我需要一点时间整理，但我会回来告诉你我的想法。”这能同时保护主体空间和关系连接。

应用边界：内倾成长的重点不是强迫自己外向，而是把内在经验做成可沟通的材料。系统可鼓励用户先用笔记保存复杂想法，再选择一句最重要的话说给对方听。只要关系能收到信号，沉默就不必被误解为拒绝。', '["内倾", "主体定向", "表达练习", "关系误读", "心理边界", "自我验证"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 370, now()),
(100371, '四种功能：思维、情感、感觉、直觉是四种取样方式', '核心观点：功能偏好不是智商、道德或能力等级，而是人理解世界时常用的取样方式。思维关心概念、因果、原则和一致性；情感关心价值、喜欢/不喜欢、关系意义和重要性排序；感觉关心当下事实、身体刺激、细节和可观察材料；直觉关心可能性、趋势、象征和尚未展开的图景。每种功能都可能以外倾或内倾方式出现，所以不能把“思维=内倾”“情感=外倾”简单等同。

App 端可以把功能用于冲突复盘：我现在的证据主要来自哪一种功能？我是在讲道理，还是在讲重要性？我是在抓事实，还是在追可能性？被我忽略的功能会提出什么问题？例如，思维强的人在伴侣沟通中可能需要补一句“这件事对你意味着什么”；情感强的人在决策中可能需要补一栏“可验证事实是什么”。

关系价值：功能语言能把“你太冷血/你太情绪化/你太死板/你想太多”翻译成“我们正在用不同通道取样”。这种翻译能降低羞辱感，让对话从人格攻击转向信息互补。

应用边界：功能识别不应变成新的优劣排序。每一种功能在压力下都会失真：思维可能变成冷酷辩护，情感可能变成迎合或审判，感觉可能变成短视，直觉可能变成空想。知识库要强调“补信息”，而不是给某种功能封王。', '["功能偏好", "思维", "情感", "感觉", "直觉", "冲突复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 371, now()),
(100372, '优势功能不是全人格：专长带来适应，也会制造盲点', '核心观点：人会把最顺手、最被奖励的功能发展成优势功能。它让我们在社会中获得位置：有人靠清晰思维解决问题，有人靠情感判断维系关系，有人靠感觉细节稳住现实，有人靠直觉发现机会。问题在于，当一个人把自己完全等同于优势功能，就会把其他部分看成麻烦、低效或不成熟。

OCR 第二章借席勒讨论“功能分化”的代价：为了发展某种能力，其他功能可能被压低；这种片面性对集体有用，却可能让个体变得贫乏。第七章也指出，与主导功能完全一致会帮助人满足集体期待，但也可能带来个体退化。

App 可把这条做成“我被奖励的那部分不是全部的我”提示。用户在职业、亲密关系或自我评价中，如果长期只用一种能力证明价值，就需要问：我最骄傲的能力正在排斥什么？我是否把休息、依赖、情绪、想象或身体感受看成没用？成长不是否定优势，而是让优势不再垄断人格。

应用边界：这条特别适合职业倦怠和亲密关系失衡。用户常把最能带来成就的能力当成唯一身份，久而久之就无法承认自己也需要被照顾、需要不确定、需要玩耍或需要停下。系统可邀请用户每周练一次“不被绩效奖励但能恢复完整感”的小行动。', '["优势功能", "人格完整", "职业压力", "自我价值", "功能分化", "整体性"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 372, now()),
(100373, '劣势功能会粗糙地回来：别只靠更用力的优势功能', '核心观点：被长期压抑、未分化的功能不会消失，只会以更原始、笨拙或失控的方式回来。一个高度理性的人可能在亲密关系里突然被情绪淹没；一个习惯照顾感受的人可能在事实和边界面前混乱；一个追逐可能性的人可能忽视身体和日程；一个依赖感觉事实的人可能害怕抽象意义或未来变化。

OCR 第七章谈到，心理能量越集中在主导功能，其他功能获得的能量越少，久而久之会沉入无意识并产生反抗；第十章也描述无意识功能具有更古老、更原始的特征。App 不应把这种反弹解释成“人格崩坏”，而应解释为被冷落的功能在要求被看见。

落地练习：当用户反复在同一处失控时，不急着让 TA 更努力使用优势功能，而是询问“这里缺少哪种功能的帮助？”理性用户可练习命名感受，情感用户可写事实清单，直觉用户可做身体扫描，感觉用户可列三种未来可能。

应用边界：劣势功能训练要小剂量、低羞耻、可重复。不要要求一个长期压抑感受的人一次说清全部创伤，也不要要求一个现实感薄弱的人立刻制定完美计划。更有效的是给一个可完成的微练习，让被冷落的功能逐渐进入意识。', '["劣势功能", "未发展功能", "无意识补偿", "情绪失控", "自我调节", "人格发展"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 373, now()),
(100374, '辅助功能是安全通道：成长不必直冲最脆弱处', '核心观点：人格成长不是把人一下推到最不擅长、最痛苦的功能里。OCR 第十章在“主要功能和从属功能”中指出，实际生活里除主导功能外，常有相对无意识的辅助功能；发展可以经由第二功能来保护意识立足点，再逐步接近更深的无意识内容。

这对 App 很实用：如果用户是理性型，不一定一开始就要求 TA 大量暴露情绪，可以先用感觉或直觉作为桥梁——记录身体信号、画出情境图、列出可能性，再慢慢进入感受和需要。如果用户是非理性型，也不必立刻否定 TA 的体验，而可训练更稳定的理性辅助功能：给体验命名、排序、核对证据、做小计划。

关系价值：伴侣或咨询式对话中，不要用“你为什么不能直接表达感受/直接讲逻辑”逼迫对方跳到最弱处。更好的提问是：你比较容易从哪个入口靠近这件事？事实、价值、身体、可能性，哪一个现在最安全？这样成长更温和，也更可持续。

应用边界：辅助功能也能帮助 App 控制干预强度。面对高压用户，系统先寻找最安全的入口，而不是直接追问最痛点。这样可以减少防御和依赖，把成长保持在用户仍能自我承载的范围内，避免把“洞察”变成新的压迫。', '["辅助功能", "成长路径", "心理安全", "咨询提示", "功能训练", "温和改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 374, now()),
(100375, '投射：关系里的“我看见你”常混有“我放到你身上的东西”', '核心观点：投射可以理解为把主观内容放进客体，于是我们以为自己只是在看见对方，实际上也在看见自己尚未承认的情绪、愿望、恐惧或价值。OCR 第十一章定义投射时指出，主观内容离开主体并被具体化到客体中，可能是痛苦和不相容的内容，也可能是正面价值；第一章也谈到集体态度会借投射来思考和感受，从而妨碍客观看见个体差异。

App 端可用于关系误读：当用户反复说“TA 一定看不起我”“所有人都在控制我”“这个人完美无缺”时，不急着否定，而是温和拆分三层：可观察事实是什么？我赋予它的意义是什么？这个意义是否也反映了我自己的恐惧、渴望或自卑？

关系价值：识别投射不是把责任全拉回自己，也不是替对方开脱。它只是让用户在行动前多一个校准步骤：我看到的对方，有多少来自对方实际行为，有多少来自我内在尚未被安放的内容？这样能减少读心、理想化、妖魔化和过度防御。

应用边界：投射校准要保持双重视角。系统既要帮助用户收回可能属于自己的内容，也要允许对方确实有伤害行为。可用提示语：“我们先核对我加上的解释，同时也保留对事实和边界的尊重。”这样不把自我反思变成自我否定。', '["投射", "关系误读", "读心校准", "理想化", "妖魔化", "自我觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 375, now()),
(100376, '类型冲突：双方看到的常是彼此最不利的外观', '核心观点：类型差异常让人误以为对方“不讲理”。外倾更容易相信客观事实、环境要求和外部反馈；内倾更容易相信主体立场、内在图像和个人意义。第十章外倾/内倾的描述，以及对外倾思维与主观思维冲突的讨论，都显示：两种定向一旦互相评判，常会把对方看成入侵者或偏执者。

App 可把冲突翻译成两个问题：第一，对方正在服务哪一种现实——外部事实、他人期待、共同规则，还是内在原则、个人意义、长期图景？第二，我是否只看见了对方类型的低级表现，而忽略了它保护的价值？例如，外倾者催促行动，可能是在保护现实进度；内倾者要求暂停，可能是在保护判断质量。

沟通模板：不要说“你太外向/太内向”，而说“我听见你很重视外部反馈；我这边需要一点时间确认内在判断”。类型冲突的修复，不是证明谁更正常，而是让两种现实都获得位置。

应用边界：类型冲突最适合做成对话前的翻译器。系统可分别生成两种语言：给外倾者的是“请留一点空间给对方整理内在判断”；给内倾者的是“请给对方一个可见的时间点和外部信号”。双方都不必放弃自己，只需增加可理解性。', '["类型冲突", "内外倾", "关系沟通", "观点差异", "冲突翻译", "非人格攻击"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 376, now()),
(100377, '对立形态：越片面，越容易被相反面夺回方向盘', '核心观点：“对立形态”可用于解释很多自我管理失败：当意识生命长期被一种极端、片面的倾向支配时，被排除的对立面会在某个时刻变得有力量，反过来抑制甚至打破原有控制。它不需要被神秘化，可以理解为心理系统的补偿和反弹。

App 中常见例子包括：长期讨好的人突然爆发；长期理性控制的人在压力下迷信直觉或陷入灾难想象；长期独立的人在亲密关系中出现强烈依赖；长期追求自由的人被生活细节拖垮。问题不在于这些人“变了一个人”，而在于被排除的需要、情绪或功能积累到必须出现。

落地提醒：当用户说“我怎么会做出完全相反的事”，可以引导 TA 回看最近一直在压下什么：愤怒、疲惫、依赖、秩序、身体、意义、关系需要。越早承认对立面，越不需要等它以失控方式出现。成长不是永远站在一边，而是学习在张力中保持可调节。

应用边界：对立形态适合做早期预警，而不是事后责备。系统可让用户定期填写“我最近最不允许自己体验什么”，并把答案当作需要照顾的信号。越能在小幅度时承认对立面，越不容易等到关系破裂或身体耗竭才被迫转向。 先照顾小信号。', '["对立形态", "心理补偿", "片面性", "反弹", "自我调节", "人格整合"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 377, now()),
(100378, '阴影与自身：成长不是美化自我，而是看见被排除的我', '核心观点：OCR 第十一章区分自我与自身：自我是意识领域中心，自身则包含更广阔的心理整体，包括无意识。文本还提到阴影作为被自身发现的部分。对 App 来说，这一观点可以转化为非神秘化的成长语言：我并不等于我愿意承认的那一小块；那些被我排除、否认、讨厌或投给别人的部分，也可能属于我的心理整体。

阴影不必被解释成“邪恶人格”，更适合看作未被承认的能力、欲望、脆弱、攻击性、依赖、嫉妒、野心或创造力。它们被压下去时，常在关系里以强烈反感、过度理想化、失控爆发或重复吸引的形式出现。

App 练习可以是：我最受不了别人哪一点？这点是否也提醒我某种被禁止的自己？如果把它从道德审判改写为一种能量，它原本想保护什么？这种练习不是纵容伤害行为，而是让用户把被排除的心理材料带回可观察、可选择、可负责的位置。

应用边界：阴影工作需要温和语言。知识库不宜说“你其实也很坏”，而应说“你强烈排斥的东西可能携带某种被禁止的生命力”。当用户能把阴影从羞耻对象改写为可负责的能量，就更容易同时保持边界和自我接纳。 练习要慢。', '["阴影", "自身", "自我", "无意识", "人格整合", "自我接纳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 378, now()),
(100379, '人格发展：从同一化到分化，再到更有弹性的整合', '核心观点：第十一章把分化解释为把某种功能从混合状态中分离出来，使它能够独立、清晰地运作。没有分化，人会把感觉、情感、思维、直觉混成一团：感受像事实，想象像证据，价值判断像客观规律。分化让人先看清“这是情绪、这是事实、这是推论、这是直觉”。

但分化不是终点。第二章和第七章提醒，过度分化会把人变成单一功能的代表：会思考却不会感受，会照顾却不会判断，会执行却不会想象，会预感却不会落地。健康发展更像两步：先分清功能，减少混乱；再让不同功能重新合作，恢复整体性。

App 可把它做成“先分栏，再整合”的工具。面对一件关系事件，用户先分别写：事实/身体感觉/情绪价值/想法推论/未来可能；然后再问：如果这些信息都是真的一部分，我下一步最小、最负责任的行动是什么？这种练习既避免情绪和事实混淆，也避免用冷冰冰的分析切断生命经验。

应用边界：这条可与情绪日志、冲突复盘、认知重评联动。不同之处在于，它不仅问“想法是否准确”，还问“哪一种心理功能正在说话，哪一种没有被邀请”。当不同功能都获得位置，行动往往更稳，也更有人味。', '["分化", "人格发展", "功能整合", "事实感受分离", "自我观察", "成长练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 379, now()),
(100380, '类型语言的边界：服务关系成长，不服务诊断和宿命', '核心观点：心理类型进入 App 知识库时，最重要的边界是“用于观察，不用于审判”。它可以帮助用户发现自己的定向、功能偏好、投射、劣势功能和关系误读，却不应被包装成命运说明书、灵魂等级或诊断标签。OCR 第十章已经多次提示，纯粹类型只是概括出来的典型图像，现实个体常有主导、辅助、意识和无意识功能的复杂组合。

App 的回应可采用四步：一，先描述情境中的反应，不急着命名类型；二，询问注意力流向外界还是内在；三，识别主要使用的功能和缺席的信息；四，把结论落到一个可练习动作，例如核对事实、表达感受、补充边界、休息、行动或等待。

这样做能避免和 v10 中已有的“人格测验只能作线索”“不要用类型限制人”等主题重复成空泛提醒，而是提供荣格类型独有的操作框架：态度—功能—投射—劣势功能—整合。类型的价值不在于更快定义人，而在于让人更慢、更准确、更温柔地理解自己和他人。

应用边界：最终呈现时可把“类型”放在二级解释，而不是首屏结论。先回应用户的具体困扰，再提供类型视角作为可选镜头。这样既能利用荣格类型的解释力，又避免用户把复杂人生缩减成四个字母或一个标签。', '["类型应用", "非诊断", "App问答模板", "关系成长", "人格测评边界", "荣格类型"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 380, now()),
(100381, '内疚与羞耻：从“我是坏人”回到“我做错了什么”', '核心观念：健康的后悔关注行为和修复，破坏性的内疚/羞耻则把行为扩展成身份判决。伯恩斯指出，典型链条是：我做了不符合标准的事 → 这证明我是坏人/无价值的人 → 如果被发现别人会鄙视我 → 我很危险或该受惩罚。App 可引导用户把这条链拆开：事实是什么？我真正需要负责的部分是什么？有没有放大、乱贴标签、罪责归己或过度“应该”？如果我关心的是价值和关系，下一步可做的修复行为是什么？例如道歉、补偿、解释、学习新技能、设提醒、请求反馈。练习中要保留责任感，但移除人格审判：用户可以承认行为造成影响，也可以不把自己定义成坏人。这样，内疚从瘫痪性的自我惩罚转为有方向的修复行动。

使用建议：App 可把内疚处理分成“责任澄清”和“修复计划”两个页面。责任澄清包括：我是否真的违反了自己的价值？伤害的具体影响是什么？哪些后果是我造成的，哪些属于他人解释或环境限制？修复计划包括：我能否承认影响、道歉、补偿、改变流程或学习新能力？如果用户只停留在“我活该难受”，系统可提醒：惩罚自己并不等于负责，真正的负责是减少再次伤害的概率。对于羞耻强烈的用户，还要把“别人可能怎么看我”与“我实际能做什么”分开，避免读心和灾难化让修复停摆。', '["内疚", "羞耻", "后悔", "责任边界", "修复行动", "自我宽恕"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 381, now()),
(100382, '复发预防：把工具箱留在情绪变好之后', '核心观念：情绪好转后，最容易把练习丢掉；而伯恩斯反复强调，认知工具之所以能维持效果，是因为人学会了在下一次波动时处理想法、活动和关系。App 的复发预防条目可做成一页“个人情绪维护计划”：1）早期信号：情绪评分连续上升、活动M/P下降、睡眠紊乱、开始孤立、频繁出现应该/标签/灾难化；2）高风险场景：被批评、任务拖延、关系拒绝、工作比较、独处周末；3）首选工具：三栏日志、活动计划、反拖延实验、语言柔道、愤怒预演、垂直箭头；4）支持清单：可联系的人、咨询资源、需要暂停或减负的事务；5）复盘问题：这次旧规则又是什么？我下次怎样更早发现？它应被表述为维护系统，而不是“保证永不低落”。真正的预防，是在平稳期也保留观察、记录、行动和求助的通道。

使用建议：维护计划可设置为每月一次轻复盘，而不是等到危机时才启动。复盘问题包括：最近哪个旧规则最活跃？我是否减少了让我有掌控感或愉悦感的活动？我是否又开始用“总是、必须、完了、没救了”这类绝对语言？我是否停止联系支持者？App 可根据用户历史记录推荐最有效的三项工具，例如某人对三栏法反应最好，另一个人对活动计划更敏感。复发预防还应允许“部分复原”：即使只完成一个小行动、写下一条自动想法、联系一个人，也是在打断下滑链条，而不是非要一次恢复到最佳状态。', '["复发预防", "维护计划", "早期信号", "工具箱", "情绪监测", "支持系统"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 382, now()),
(100383, '心理学不是常识包装：先用科学态度校准直觉', '核心观点：迈尔斯在第1章把心理学入门放在“批判性思考”上，而不是先给一堆结论。人的直觉有价值，但容易受后见之明和过度自信影响：事情发生后，我们能为相反结果都编出“早就知道”的解释；在判断自己知道多少、看人多准、预测多稳时，也常比证据更自信。

App落地：当用户提出“我就是知道TA在骗我”“我早就看出自己会失败”这类判断时，知识库可以提醒系统先把直觉降级为假设：1）我看到了什么可观察事实；2）还有哪些替代解释；3）什么证据能支持或推翻我的判断；4）若要行动，最小可逆步骤是什么。

使用边界：批判性思维不是否定感受，也不是把用户变成冷冰冰的数据机器，而是帮助用户在感受强烈时不急着下终局判决。尤其适合关系误读、职场评价、自我否定、网络心理测试和“玄学式人格判断”的场景。

后台提示：这条可作为所有问答的“证据闸门”。当用户要求人格判断、关系判断或原因归因时，先输出低威胁问题，而不是直接反驳。推荐句式是：“这个直觉值得听见，我们也把它放进待验证区。”这样既保护用户体验，又减少把常识、热门说法或心理测试结果当作事实。', '["心理学基础", "科学态度", "批判性思维", "后见之明偏差", "过度自信", "事实核对", "App问答模板"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 383, now()),
(100384, '天性与教养共舞：遗传倾向不是命运判决', '核心观点：第4章反复校准“基因还是环境”的二分法。基因提供生物蓝图，解释人类共同性与部分个体差异；环境、文化、父母、同伴和当前情境则不断参与塑造。更准确的说法不是“人格百分之多少来自基因、百分之多少来自环境”，而是基因会影响我们进入何种环境、别人如何回应我们，而环境又会放大、缓冲或改写遗传倾向。

App落地：当用户说“我天生就是焦虑/懒/不会社交，所以没办法”时，可回应为：你可能有某些较敏感的气质或反应阈值，但这不是固定剧本。下一步不是否认先天差异，而是设计更适配的环境：减少高触发场景、选择更支持的人际反馈、用小步练习建立新的经验。

避免误用：不要把遗传解释成宿命，也不要把环境解释成“只要努力就能变成任何样子”。知识库可保留一句后台原则：天性通过教养实现，教养也总是作用在具体天性之上。

后台提示：适合用于气质、亲子、人格和情绪敏感度解释。系统可以把“我改不了”翻译成“我需要更合适的改变路径”。例如高敏感用户不必追求变得迟钝，而是学习提前识别刺激、恢复能量、选择低消耗社交和逐步扩大容忍窗口。', '["天性与教养", "行为遗传学", "基因环境互作", "气质", "人格发展", "非宿命", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 384, now()),
(100385, '选择性注意：你没看到，不等于它不存在', '核心观点：第3章和第6章提醒，意识注意像一束光，只能照亮体验中的有限部分。大量感觉信息在意识外被加工；当我们专注某个任务时，会忽略旁边显眼的变化，甚至对“换人”“换物”视而不见。第6章进一步说明，觉察微弱信号不只取决于刺激强度，也取决于期望、动机、警觉水平和当下任务。

App落地：在用户复盘冲突或自责时，系统可提示“注意力截图不是全景图”。可引导用户补三类漏看信息：当时我正在专注什么？我可能忽略了哪些环境线索？我现在的期待是否让我更容易只看见威胁、拒绝或失败？这能降低读心、灾难化和选择性证据收集。

应用价值：这条适合接入焦虑、亲密关系和学习效率场景。对焦虑者，可解释为什么人会过度扫描危险；对学习者，可提醒多任务会降低反应；对关系误解者，可提示“我当时没有注意到”比“它一定没发生”更准确。

后台提示：这条也能支持“记录而非争辩”的产品交互。系统可鼓励用户在情绪过后补写第二版复盘：第一版记录当时注意到的东西，第二版加入旁观者、时间线和环境信息。两版并列能让用户看见注意力如何被任务和情绪收窄。', '["注意力", "选择性注意", "信号检测论", "变化盲视", "知觉定势", "焦虑校准", "关系误读"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 385, now()),
(100386, '毕生发展视角：别用成人逻辑要求每个年龄段', '核心观点：第5章把发展心理学定义为研究从婴儿到老年生理、心理和社会性变化的学科，并提出三组核心问题：天性与教养、连续性与阶段性、稳定性与变化性。儿童不是缩小版成人：认知、依恋、同伴关系、身份探索和成年任务都会随年龄改变。皮亚杰的阶段理论虽被修正，但“儿童通过与世界互动建构知识”的洞见仍有价值。

App落地：亲子和自我成长问答中，不宜把所有问题都解释成“性格不好”或“道理没讲透”。儿童行为常与发展能力有关，青少年冲突常夹杂身份探索和同伴认同，成年焦虑常与亲密、工作、贡献和独立任务有关。系统可先问：这个人处在人生哪个阶段？此阶段的能力、任务和压力是什么？

提醒：发展视角不是纵容伤害行为，而是把“能不能做到”和“愿不愿意做到”分开。对于教育、亲子沟通、成年转型、自我接纳场景，它能让建议更符合年龄任务。

后台提示：这条可成为亲子模块的基础校准。面对“孩子故意气我”“青春期就是叛逆”等表达，系统先不急着给管教技巧，而是提醒用户检查能力成熟度、依恋需要、同伴压力和自主任务，再把规则设计成清晰、稳定、可执行的下一步。', '["发展心理学", "毕生发展", "儿童心理", "依恋", "青春期", "身份发展", "亲子沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 386, now()),
(100387, '学习三通道：行为改变不只靠意志，还靠联结、结果和榜样', '核心观点：第7章把学习定义为经验导致的相对持久行为变化，并概括三类主要学习：经典性条件作用、操作性条件作用和观察学习。经典条件让人把两个刺激联结起来，形成自动反应；操作条件让人把行为与结果联结起来，重复被强化的行为、减少受惩罚的行为；观察学习让人通过榜样和模仿习得新行为。

App落地：用户想改变拖延、暴食、回避、冲动消费或关系反应时，不要只说“坚持”。可从三问拆解：1）什么刺激自动触发了情绪或欲望？2）这个行为获得了什么即时奖励或逃避了什么不适？3）我身边或屏幕上有哪些榜样正在教我这样反应？然后设计替代刺激、替代奖励和可模仿的微榜样。

特别价值：这条能把行为改变从道德评价转为机制分析。它也适合解释创伤触发、恐惧泛化、坏习惯维持、亲子模仿和媒体影响，但输出时要避免把复杂问题简化成单一条件反射。

后台提示：在生成行动方案时，可把每个建议都标注属于哪类学习机制：替换触发是经典条件思路，重新安排奖励是操作条件思路，找可模仿对象是观察学习思路。这样能让用户明白“改变环境”不是偷懒，而是直接作用于学习机制。', '["学习理论", "经典条件作用", "操作性条件作用", "观察学习", "行为改变", "榜样", "习惯机制"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 387, now()),
(100388, '强化塑造行为：奖励具体进步，比空泛批评更能改变', '核心观点：第7章的操作性条件作用为App端行为改变提供了底层语言。行为会受结果塑造；强化不是“奖品”本身，而是任何能增加某行为出现频率的后果。塑造复杂行为时，应从接近目标的小步开始强化；间歇强化会让行为更难消退，这解释了赌博、刷手机、偶尔被回应的关系依赖为什么特别顽固。

App落地：目标设计可遵循四步：把目标改成可观察行为；记录行为出现的条件；对期望行为给出及时、具体、低成本强化；当行为稳定后，逐渐从外部奖励转向内在奖励。对亲子和团队反馈，可把“你怎么这么懒”改成“你今天按时开始了10分钟，这一步值得保留”。

边界：惩罚能暂时压制行为，却未必教会替代行为，还可能带来恐惧、逃避或无助。知识库可提示：如果必须设后果，也要同时强化想要的行为；否则用户只知道“不要做什么”，不知道“该怎样做”。

后台提示：适合做成习惯追踪、亲子反馈和职场管理的统一规则。奖励要具体、及时、贴近行为，而不是评价整个人。系统可自动把人格评价改写为行为反馈，如把“你太拖延”改为“你在19:30打开文档并写了第一段，这是可复制的启动动作”。', '["强化", "行为塑造", "操作性条件作用", "间歇强化", "自我管理", "亲子教育", "反馈"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 388, now()),
(100389, '记忆不是录像：它会编码、提取，也会建构和改写', '核心观点：第8章用信息加工模型说明，记忆包含编码、存储和提取三个过程；当代研究还强调工作记忆的主动加工。记忆不是把现实逐帧录下再原样播放，而是在旧信息、当前线索、情绪状态和他人提示参与下重新建构。错误信息、想象和来源混淆，都可能让人真诚地相信并未发生或已经变形的细节。

App落地：当用户反复复盘“当时到底是不是这样”或在人际争执中坚持“我记得很清楚”时，可提醒：真诚不等于完全准确。建议先记录原始记忆，再区分亲眼所见、别人告诉我的、我后来推断的、我在情绪中想象的。对重要冲突，可使用“事实时间线”而不是“谁记得更对”的争夺。

敏感场景：涉及创伤、儿童经历、法律指控或严重伤害时，App不应诱导用户“恢复记忆”或替用户断定真伪，只能做稳定、记录、求助和证据边界提示。

后台提示：这条可服务“冲突复盘”和“创伤叙事”两类场景。对普通冲突，鼓励尽早写下原始记忆并保留不确定性；对创伤相关内容，避免追问细节和暗示性问题，优先稳定当下、尊重用户节奏，并提醒必要时找专业人员陪伴整理。', '["记忆", "工作记忆", "记忆建构", "错误信息效应", "源头遗忘", "事实时间线", "非诱导"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 389, now()),
(100390, '有效学习不是多看几遍：间隔、意义化和自测更可靠', '核心观点：第8章不仅讲记忆模型，也给出学习策略。需要努力加工的信息，靠一次性猛背很容易快速遗忘；分散学习、间隔复述、过度学习、把新材料与已有知识连接、组织成意义结构、主动回忆和自我测试，更能提升长期保持。系列位置效应提醒我们，中间部分更容易被遗忘，学习计划要特别照顾这些“中段盲区”。

App落地：学习类功能可把建议做成流程：先浏览并发问，再阅读；读完马上合上资料复述；用自己的话解释；隔一段时间再测；把错题和卡住处作为下一轮学习入口。对“我看了很多遍还是忘”的用户，重点不是责备努力不足，而是把重复观看改成主动提取。

边界：记忆术、缩写词和图像联想适合陌生材料，但不能替代理解。系统可优先鼓励“能不能教给别人”作为检验，而不是只问“看起来熟不熟”。

后台提示：产品上可把“学习完成”从阅读时长改成提取证据：能否列出要点、能否解释给新人、能否隔天答对。对于焦虑型学习者，系统要强调短而分散的复习比长时间硬扛更有效，避免把学习建议变成新的自责来源。', '["学习方法", "间隔效应", "主动回忆", "自我测试", "意义编码", "SQ3R", "长期记忆"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 390, now()),
(100391, '思维捷径有用也危险：别让启发式替你做终审', '核心观点：第9章把人类思维写成理性与非理性的混合。概念、原型、算法、启发式和顿悟帮助我们快速解决问题；但代表性启发会让人忽视基础概率，易得性启发会让鲜活案例压过统计事实，过度自信会让人高估判断准确度，信念偏差和信念保持会让人更容易接受符合原有立场的“证据”。

App落地：在决策、关系判断、风险恐惧和自我评价中，可给用户一个“捷径复核”模板：我是不是被一个典型形象带走了？我是不是因为最近看到某个案例，就高估它的概率？有没有基础数据或长期模式？如果相反结论成立，我会找哪些理由？把这些问题做成轻量检查，比直接告诉用户“你有偏见”更容易被接受。

价值：启发式不是敌人，它是日常快速判断的工具。App要做的是在高代价决策、强情绪判断和长期关系结论前，提醒用户把捷径提交给证据复核。

后台提示：这条可接在“强判断”之后：一定、永远、所有人、肯定、没救了。系统检测到绝对化语言时，可启动概率化和反例搜索，而不是直接要求用户乐观。推荐输出是“这个判断可能在提醒风险，我们给它加一个概率和证据等级”。', '["思维与判断", "启发式", "代表性启发", "易得性启发", "过度自信", "信念保持", "决策校准"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 391, now()),
(100392, '动机不是单一意志：需要、诱因、唤醒和意义共同推动行动', '核心观点：第11章把动机定义为激发行为并使之指向目标的需要或欲望。人不是只靠“想不想努力”行动：生理需要会形成驱力，环境中的诱因会拉动行为，过低刺激会让人无聊，过高刺激会造成压力，人还会追求最佳唤醒、归属、尊重、自我实现和超越自我的意义。工作动机部分进一步说明，工作既满足生存，也提供身份、关系、能力感和意义感。

App落地：当用户说“我没有动力”时，不要只灌鸡汤。可分层排查：基础睡眠、饮食和安全是否被破坏？目标是否太远、诱因是否只奖励短期逃避？任务难度是否高到焦虑或低到无聊？是否缺少归属、被看见、成长或贡献感？

建议模板：把大目标改成能产生适度唤醒的小挑战；增加即时反馈；把行动连接到具体关系或价值；避免把所有低动力都解释成意志薄弱。

后台提示：动机模块可避免单点归因。若用户长期低动力，先检查身体资源和压力负荷；若只是某任务低动力，再看任务难度、反馈延迟和意义连接。系统可输出“动力处方”：降低启动门槛、增加即时反馈、安排同伴监督、连接长期价值。', '["动机", "需要层次", "驱力", "诱因", "最佳唤醒", "工作动机", "意义感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 392, now()),
(100393, '情绪有身体也有解释：先降唤醒，再看标签是否准确', '核心观点：第12章把情绪拆为三部分：生理唤醒、外显行为和意识体验。不同理论分别强调身体反应、同时发生的大脑加工，以及“唤醒+认知标签”。研究还提示情绪有双路径：某些恐惧和喜欢会经由快速低通道先于有意识解释出现；复杂情绪又深受评价、记忆和预期影响。

App落地：情绪支持不宜只问“你为什么这样想”，也不宜只让用户深呼吸。更好的顺序是：先识别身体唤醒（心跳、呼吸、肌肉、胃部、冲动）；用低刺激方式降唤醒；再检查标签——这是愤怒、害怕、羞耻、兴奋外溢，还是把运动/疲劳/争吵后的唤醒误标成了别的情绪？

边界：快速情绪不是“错误”，它常是保护系统；认知重评也不是万能，尤其对简单恐惧和强生理唤醒。App可把这条用于情绪命名、冲突暂停、考试焦虑和亲密关系误读。

后台提示：这条可作为情绪急救的顺序规则：高唤醒时先身体降温，低唤醒时先轻行动和唤醒，再进入认知整理。系统不应在用户心跳很快、想攻击或崩溃时立刻要求理性分析；等唤醒下降后，再帮助用户区分事实、解释、需要和请求。', '["情绪", "生理唤醒", "认知标签", "双因素理论", "情绪双通路", "情绪调节", "身体觉察"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 393, now()),
(100394, '压力应对先分两类：能改问题就改问题，不能改时先稳情绪', '核心观点：第12章把长期不可控压力与健康风险联系起来，同时给出两类应对：聚焦问题的应对，直接处理压力源；聚焦情绪的应对，在暂时无法改变环境时调节情绪和寻求支持。能否感到控制、解释方式是否乐观、是否有支持性关系，都会影响压力后的健康和恢复。

App落地：用户说“我压力很大”时，可先分流：这个压力源是否可改变？若可改变，生成下一步行动、沟通、资源和时间表；若短期不可改变，先做情绪稳定、距离调整、倾诉、睡眠和支持网络。不要把所有应对都变成“忍一忍”或“马上解决”。

补充策略：控制感可以从小选择开始恢复；社会支持不是泛泛求陪伴，而是找到能倾听、能协助、不会加重羞耻的人。表达性书写、适度运动、放松训练和规律生活可作为非诊断性的身心调节建议。

后台提示：压力问答可先让用户给压力源标注“可控、部分可控、暂不可控”。可控项生成行动清单，部分可控项生成边界和求助，暂不可控项生成恢复计划。这样能避免用户在不可控事件上耗尽意志，也避免把可解决问题全部情绪化处理。', '["压力", "应激", "聚焦问题应对", "聚焦情绪应对", "控制感", "社会支持", "健康心理学"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 394, now()),
(100395, '人格基础看大五，也看人与情境的交互', '核心观点：第13章将人格定义为思维、情感和行为的典型模式，并从精神分析、人本主义、特质和社会认知等视角介绍人格。对App端最稳妥的基础框架，是把“大五人格”作为描述语言，而不是命运标签：责任心、宜人性、神经质/情绪稳定性、开放性、外倾性。人格特质有稳定性和遗传基础，但具体行为仍受情境强烈影响。

App落地：用户问“我是不是某种人”时，系统可改问“你在哪些情境更容易表现出这种模式”。例如外向测验分数不能完全预测任何一次聚会表现；红绿灯前司机行为，情境线索比人格更能预测。人格建议应鼓励用户识别稳定倾向、触发环境和可训练反应，而不是贴固定标签。

避重方向：本条可作为九型人格、荣格类型之外的科学校准层。它不否定类型工具的自我反思价值，但提醒App不要用类型替代证据、情境和选择。

后台提示：测评结果进入知识库时，应默认加上“情境限定”。例如“高神经质”不等于脆弱，而是更容易觉察威胁和波动；“低外倾”不等于社交失败，而是能量恢复方式不同。系统应给用户更多选择，而不是把分数变成身份判词。', '["人格", "大五人格", "特质理论", "人情境交互", "社会认知观", "非标签化", "人格测评边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 395, now()),
(100396, '心理障碍非诊断理解：看痛苦、失能、文化和标签风险', '核心观点：第14章强调，心理障碍不是简单的“怪”或“坏”，通常指异常、令人痛苦、适应不良或不合理的思维、情感和行为的持续模式。判断正常与异常离不开文化、时代和功能损害：强烈恐惧若不影响生活，未必构成障碍；悲伤和抑郁也要看持续、痛苦和功能受损。现代观点采用生物—心理—社会框架，而不是只归因于性格缺陷。

App落地：App不做诊断，但可以做理解和分流。后台可先问四件事：痛苦强度、持续时间、功能受损、风险信号。对用户或他人贴标签时，提醒标签既能帮助描述和求助，也会引发偏见和自我实现。可把“他就是有病”改写为“TA表现出某些需要专业评估的持续困难”。

安全边界：涉及自杀想法、严重失眠、幻觉妄想、明显功能丧失、躁狂样高风险行为或伤人风险时，知识库应引导专业求助和现实支持，而不是提供诊断结论。

后台提示：这条可作为心理健康内容的安全边界。系统可以说“这听起来已经影响生活，值得寻求专业评估”，但不要说“你就是某某障碍”。对他人行为也一样：描述观察到的模式和影响，减少诊断化称呼，既保护被谈论者，也避免误导用户决策。', '["心理障碍", "非诊断", "生物心理社会", "功能损害", "标签风险", "专业求助", "心理健康"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 396, now()),
(100397, '有效帮助有共同因素：希望、新视角和可信关系', '核心观点：第15章梳理精神分析、人本、行为、认知、团体家庭治疗与生物医学治疗，并指出各种有效心理治疗常有共同因素：给受挫者希望，提供理解自我和世界的新观念，建立共情、信任、关怀的关系。治疗技术有差异，但治疗联盟、来访者的期待、具体问题匹配和持续练习，都会影响效果。

App落地：这能帮助后台设计“非治疗式支持”：先稳定希望感，再提供可理解的框架，最后给可执行练习。比如恐惧类问题可借鉴暴露和系统脱敏的逐步接近；抑郁和焦虑可借鉴认知疗法对自动想法的温和提问；行为问题可借鉴强化和替代行为。

边界：App不是治疗师，不能宣称治疗疾病。它可以做心理教育、练习提示、求助准备和复盘；一旦出现严重症状、药物问题、危机风险或复杂创伤，应鼓励线下专业支持。

后台提示：App对话也可借鉴共同因素：先让用户感到被理解，再给一个能解释困境的框架，最后提供小而可做的行动。若直接给技巧而没有关系承接，用户可能把建议体验成否定；若只有共情没有新视角，又容易停留在倾诉循环。', '["心理治疗", "共同因素", "治疗联盟", "希望感", "认知疗法", "行为疗法", "App支持边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 397, now()),
(100398, '心理健康也要上游预防：生活方式和环境同样是干预点', '核心观点：第15章后半部分强调，身心不是两套系统。规律有氧运动、充足睡眠、光照、社会接触、减少反复消极思考和营养支持等生活方式改变，可能帮助情绪恢复；更宏观地看，心理障碍预防不应只等症状出现后再“修理个体”，也要关注贫困、歧视、无意义工作、长期批评、孤立和缺少控制感等上游压力源。

App落地：知识库可把心理支持分成三层：当下稳定（睡眠、呼吸、运动、饮食、联系他人）、模式调整（想法、行为、关系、压力应对）、环境预防（减少长期压迫源、增加选择权和支持网络）。对用户而言，“先照顾身体和环境”不是肤浅建议，而是生物—心理—社会系统的一部分。

边界：生活方式建议不能替代药物或治疗；对严重抑郁、双相、精神病性症状或强迫症等，生活调整只能作为配合支持。App应避免制造“你只是没运动”的羞耻感。

后台提示：这条适合做长期维护计划。系统可把用户的工具箱分为“每天维护、早期信号、压力升级、危机求助”四层，并定期提醒复盘睡眠、运动、连接、光照、工作负荷和孤立程度。目标不是追求完美生活，而是降低复发和崩溃概率。', '["心理健康预防", "生活方式", "运动", "睡眠", "社会支持", "上游预防", "生物心理社会"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 398, now()),
(100399, '表达恐惧不是胆小：它是社会皮肤在提示“我可能被孤立”', '核心观点：诺尔-诺依曼把舆论理解为一种“社会皮肤”：人不是先天就能毫无代价地公开做自己，而是持续感知周围人会赞同、嘲笑、冷落还是排斥自己。当一个人明知某件事可能是对的，却预感“说出来会让我变成孤零零的那个”，沉默就不只是缺乏勇气，而是社会性本能在保护归属。App 端面对“不敢说”“不敢拒绝”“怕被群里的人觉得奇怪”的用户，不宜直接劝“真实一点”，而要先承认：你的身体正在评估关系风险。

应用方式：把表达恐惧拆成三层：一是观点本身，我真正想说什么；二是公共性，它会被谁看见、转发、记住；三是后果，我担心失去谁的认可或支持。只有把这三层分开，用户才不会把“我害怕被孤立”误解成“我这个人没主见”。

关系提醒：安全表达不是任何场合都全盘公开，而是在看见风险后仍保留选择权。可以从私下、一对一、可撤回的小表达开始，逐渐测试关系是否能承受真实差异。', '["沉默的螺旋", "表达恐惧", "孤立恐惧", "社会皮肤", "自我审查", "关系安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 399, now()),
(100400, '意见气候判断：人不只问“我怎么想”，还会问“大家怎么看”', '核心观点：沉默的螺旋的关键不在于某个观点实际有多少支持者，而在于人们如何估计“多数人站在哪边”“哪一边正在变强”。书中用大量民意测验说明，普通人会不断读取周围环境：哪些意见被提倡，哪些意见在退潮，哪些话题说出来会更安全。这个能力像一种准统计感官，并不总是准确，却会深刻影响一个人是否开口。

App 应用：当用户说“大家肯定都觉得我错”“这个群里没人会支持我”时，可以引导他分层核对意见气候：我亲眼看到的证据是什么？只是最吵的人在说，还是多数人都表态？沉默的人有没有可能只是怕麻烦、怕冲突、没有语言？趋势是在变强、变弱，还是我被单个强刺激吓到了？

沟通价值：这能帮助用户把“气氛压迫感”从事实中分离出来。很多社交压力来自对气候的快速判断，而不是明确的排斥。把气候说清楚，用户就能从自动沉默转向更有策略的表达。', '["意见气候", "社交压力", "气氛判断", "准统计感官", "关系误读", "表达决策"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 400, now()),
(100401, '沉默会制造强势幻觉：越少人说，越像没人支持', '核心观点：沉默的螺旋最适合解释关系和群体里的“强势幻觉”。当一方更愿意公开表达，徽章、谈话、转发和态度都更可见；另一方即使人数不少，只要更谨慎、更沉默，就会在公共图景里显得更弱。于是强势方因为被看见而更自信，弱势方因为看不见同伴而更退缩，循环就被启动。最终，群体里看似“大家都这么想”，可能只是“敢说的人都这么说”。

App 应用：当用户在家庭群、团队会议、伴侣冲突中觉得“我一定是少数”时，可以提醒他检查三件事：谁在高频发声？谁只是点头或沉默？有没有人私下表达过相近感受？在关系中，沉默不等于同意，也不等于没有人支持。

表达建议：不要一上来对抗整个气候，可以先释放低风险信号，例如“我有一点不同感受，想先确认大家是否愿意听另一种角度”。这句话既打破绝对沉默，又不会把自己立刻推到被围攻的位置。', '["舆论压力", "沉默效应", "强势幻觉", "少数意见", "群体关系", "低风险表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 401, now()),
(100402, '坐火车场景：用“小公共场合”评估自己能不能开口', '核心观点：书中的“坐火车测试”很适合转化为 App 里的表达自测。它模拟一个介于私人和公共之间的场景：你要和陌生人共处数小时，对方公开表达与你相反的观点，你会加入谈话，还是觉得没必要？这个场景的价值在于，它不问抽象的“你勇敢吗”，而是让用户感受具体压力：空间狭小、时间较长、对方已先开口、自己可能被注视。

App 应用：可把困难表达拆成场景梯度。最低风险是写下来不发送；第二层是一对一讲给可信任的人；第三层是在小群里提出“我有不同看法”；更高层才是公开发言或发帖。用户如果在“小火车包厢”级别都很紧张，就不必强迫自己直接上台，而应先增加支持线索和退出通道。

关系提示：很多人不是没有观点，而是无法承受特定场景的可见性。把表达能力从人格评价改成情境评估，能减少羞耻，也能帮助用户设计下一步练习。', '["坐火车测试", "表达练习", "公共场合", "社交暴露", "安全表达", "沟通梯度"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 402, now()),
(100403, '孤立恐惧不是软弱：独立意识和被接纳需要会同时存在', '核心观点：现代人常把“我会受别人影响”看成羞耻，因为我们崇尚独立、成熟、自主判断。但诺尔-诺依曼借奥许和米尔格兰姆等研究提醒：人确实会为了避免孤立而调整表达；这并不取消人的理性，只说明人还有社会性的一面。模仿也有两种来源：一种是学习别人怎么做，另一种是为了不被排除在共同体之外。关系成长需要同时承认这两面，而不是把从众全部骂成没骨气。

App 应用：当用户自责“我怎么总是看别人脸色”时，可以回应：你不是没有自我，而是在保护连接。接下来再问：这次顺从是在学习更好的做法，还是在躲避嘲笑和排斥？如果是学习，可以保留；如果是恐惧，可以寻找更安全的表达方式。

成长方向：真正的自主不是完全不在乎别人，而是能识别“我在乎谁、为什么在乎、是否值得为这份关系暂时妥协”。这比空喊“别管别人”更可执行。', '["从众", "孤立恐惧", "社会性本质", "自我接纳", "顺从", "关系成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 403, now()),
(100404, '威胁让人收声，支持让人开口：表达需要即时安全线索', '核心观点：书中关于吸烟者与不吸烟者的实地实验很适合解释关系里的自我审查。轻微的语言威胁、批评性语境和不友好的同行者，会让原本愿意捍卫自己观点的人降低交谈意愿；相反，当较胆怯的一方看到有人替自己说出相近立场时，开口意愿会增强。表达不是只靠内在勇气，外部安全线索会直接改变一个人能否说话。

App 应用：在伴侣、亲子、团队反馈中，先创造安全线索，再邀请真实表达。比如“你可以不同意，我不会马上反驳”“我们先听完，不做评价”“你不需要一次说完整”。这些话不是客套，而是在降低被孤立的预期。

自助练习：用户准备表达前，可以先找一个支持性线索：一个同伴、一句预告、一段文字草稿、一次可暂停的对话规则。若环境已经充满嘲笑、贴标签和道德压迫，暂缓公开表达并不等于失败，而是对风险的准确判断。', '["安全感", "自我审查", "支持线索", "表达意愿", "关系沟通", "反馈文化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 404, now()),
(100405, '可见符号也是表达：徽章、贴纸、转发和服饰都会暴露立场', '核心观点：表达不只发生在“我说了一句话”的时刻。书中把徽章、汽车贴纸、报纸是否公开阅读、发型、服饰、海报等都视为公共表达；相应地，把报纸卷起来、摘下徽章、不贴海报，也是一种沉默。对 App 端关系场景来说，用户在朋友圈点赞、群里不回应、穿某种衣服、在办公室关门，都可能被他人读取为立场信号。

App 应用：当用户困惑“我明明没说什么，为什么别人反应这么大”，可以帮助他盘点可见符号：我展示了什么？隐藏了什么？别人可能把哪个动作读成支持、反对、疏离或结盟？这不是让用户迎合所有解读，而是让他更清楚自己暴露在怎样的公共视线中。

表达策略：把立场可见度分级。低可见是写私密日记；中可见是给可信的人发消息；高可见是公开发帖、贴标签、在群里站队。很多社交压力可以通过调节可见度降低，而不是只能在“全说”与“全忍”之间二选一。', '["非语言表达", "可见性", "立场信号", "社交压力", "沉默", "公共场合"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 405, now()),
(100406, '舆论压力最强时，通常已经带上“好坏对错”的道德审判', '核心观点：沉默的螺旋并不会在所有差异里同等强烈地出现。书中特别指出，只有话题被情绪化、道德化，公共压力才会真正形成。因为此时人们不再只是说“我不喜欢这个观点”，而是在暗示“持这种观点的人不体面、不善良、不属于我们”。关系中的很多僵局也是如此：伴侣争论家务、父母争论教育、团队争论方案，一旦升级为“你就是自私/不负责/没良心”，表达风险就大幅上升。

App 应用：可引导用户识别三种层级：偏好差异、利益冲突、道德定罪。偏好差异可以协商，利益冲突需要谈边界和资源，道德定罪则需要先降温，否则对话会变成自我辩护和羞辱互投。

安全表达模板：把“你怎么能这样”改成“这件事触碰了我对公平/安全/尊重的需要，我想谈具体做法”。这样既不抹掉价值，也避免把对方整个人驱逐到关系外。', '["道德压力", "舆论压力", "价值冲突", "冲突降温", "关系修复", "安全表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 406, now()),
(100407, '嘲笑、嘘声和背后议论：微小排斥信号会启动自我审查', '核心观点：孤立威胁不一定表现为正式惩罚，很多时候只是嘲笑、嘘声、冷脸、背后议论或“不坐在你旁边”。书中把这些声音和姿态视为公共场合中的排斥符号：它们让人迅速意识到，某种表达会让自己成为被围观、被轻视、被谈论的人。关系中也是如此，一句阴阳怪气、一次集体沉默、一个群聊里的表情包，都可能让人学会以后少说。

App 应用：当用户描述“我后来就不想讲了”，不要只追问观点内容，也要问：当时出现了哪些排斥信号？是明确反对，还是嘲弄式反应？有没有人提供修复信号？这样能把沉默从“我太敏感”还原为对环境线索的反应。

应对建议：如果信号轻微，可用核对式表达：“我刚刚听到笑声，有点担心自己被嘲笑，能确认一下你们的意思吗？”如果信号持续且带羞辱，就优先离开或寻求同伴支持，而不是强迫自己在不安全场中证明观点。', '["排斥信号", "嘲笑", "背后议论", "自我审查", "社交安全", "群体关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 407, now()),
(100408, '找不到说法的人更容易沉默：安全表达需要可用的话语脚本', '核心观点：书中对大众传媒的一个重要洞察是：传媒不只告诉人们“哪边更强”，还提供表达某种立场的词汇、框架和刻板印象。如果一个人的观点在公共语言里没有现成说法，他即使知道很多人和自己想法相近，也可能“理屈词穷”而沉默。放到 App 场景里，许多用户不是没有需要，而是不知道怎样把需要说得既清楚又不自我暴露过度。

App 应用：知识库应能把模糊压力翻译成可说出口的脚本。例如把“我不想再忍了”翻译成“我愿意继续合作，但我不能接受被当众讽刺”；把“我怕群里攻击我”翻译成“我只补充一个不同经验，不代表否定大家”。脚本的价值不是替用户站队，而是给他一套不羞辱自己、不攻击他人的表达工具。

风险提醒：平台热词和群体口号也可能替人思考。安全表达应帮助用户生成“自己的话”，而不是把另一套舆论直接塞进他的嘴里。', '["表达脚本", "话语资源", "媒体影响", "刻板印象", "沟通模板", "自我表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 408, now()),
(100409, '双重意见气候：亲身经验与平台气氛冲突时，要分层判断', '核心观点：书中提出“双重意见气候”：人一方面从身边真实互动中观察气氛，另一方面通过电视、报纸等媒介的“眼睛”观察世界；两者可能不一致。今天的 App 用户同样会同时生活在家庭、公司、朋友圈、短视频平台和社群评论区里。一个平台上声量很大的观点，可能并不等于身边所有人都这样想；一个群里的沉默，也可能被外部热搜放大成“全世界都在反对我”。

App 应用：当用户被舆论压得喘不过气，可以做“气候分层表”：亲眼接触的人怎么说？我信任的人怎么说？平台推荐让我看见了什么？最极端的评论占多大比例？我有没有把媒介看到的气氛投射到亲密关系里？

沟通价值：分层不是否认社会压力，而是避免把所有气候合并成一个巨大的审判者。用户一旦看到不同场域的气候并不完全相同，就更容易找到可以开口的小空间。', '["双重意见气候", "平台压力", "媒介影响", "群聊气氛", "社交判断", "信息分层"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 409, now()),
(100410, '坚实核心不是人人都要当：少数声音需要同伴、身份和退路', '核心观点：沉默的螺旋并不意味着所有少数派都会沉默。书中提到“坚实的核心”：在漫长压力中留下来的一小群人，愿意承受孤立，并可能把自己看作先锋。但这也提醒 App 端，不应把每个用户都推向“勇敢发声”的英雄叙事。能成为坚实核心的人，往往有身份认同、同伴支持、意义感或对未来变化的期待；缺少这些条件时，硬扛孤立会变成消耗。

App 应用：帮助用户评估自己此刻更适合哪种策略：沉淀观点、寻找同伴、私下表达、半公开表达，还是公开站出来。对创作者、团队成员、家庭中的少数意见者来说，最重要的不是一次性爆发，而是建立可持续的支持系统。

安全提醒：少数声音有价值，但用户的身心安全也有价值。好的知识库应同时提供勇气和退路：怎样说、对谁说、说到什么程度、被围攻时如何暂停、找谁复盘。', '["少数意见", "坚实核心", "勇气边界", "同伴支持", "心理安全", "可持续表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 410, now()),
(100411, '社会事实：既要承认主观感受，也要核对外部关系', '核心观点：书中讨论托马斯“定理”时提醒我们，人常常不是直接对事实本身行动，而是对自己理解到的事实行动；但这并不等于社会事实只存在于脑中。关系规则、组织位置、制度后果和他人的真实行为仍然存在，只是它们会经过每个人的信息、信念和利益被感知、解释，再变成行动。

App 应用：当用户说“他们都讨厌我”“这个家就是不允许我做自己”时，不要急着否定感受，也不要把感受当成全部事实。更稳妥的路径是三分法：第一，先承认主观经验——你确实感到被排斥；第二，收集外部线索——发生了哪些可观察行为、规则或后果；第三，寻找关系验证——有没有可以低风险核对的对象或场景。

关系成长提醒：痛苦既可能来自误读，也可能来自真实结构压力。成熟的自助不是“相信感觉”或“只信证据”二选一，而是把感觉当信号，把事实核对当方向盘。这样既保护用户的内在经验，也避免把暂时解释固化成自我标签或关系判决。

适合场景：用户在关系中反复把一句话、一个眼神或一次拒绝解释成全局结论时，可以用这条作为澄清模板。系统可先问“你感到什么”，再问“你看到了什么”，最后问“还有哪一种解释也能解释这些证据”。这不是让用户怀疑自己，而是把情绪、证据和关系行动放到同一张桌上。', '["社会事实", "托马斯定理", "事实核对", "感受与解释", "关系误读", "非标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 411, now()),
(100412, '把困扰放回系统：人不是孤立节点，也不是系统玩具', '核心观点：书中反复反对两个极端：只看个人选择的个体主义，和只看整体压力、把人当棋子的整体主义。系统主义的中间路是：每个人都在家庭、学校、公司、社群、制度等多个系统里行动；系统影响个体，个体也通过行动维持或改变系统。因此，一个人的困扰很少只是“性格差”，也不必被解释成“我完全没有办法”。

App 应用：遇到“我为什么总是这样”“是不是我太敏感”这类问题，可以把分析框架从人格审判改成系统地图：我在哪个系统里出现这个反应？这个系统的规则、资源、惩罚和期待是什么？我的行动又怎样影响别人继续这样对我？

练习提示：请用户列出三个圈子——亲密关系、工作/学习、家庭/社群——分别写下“我被期待做什么”“我能影响什么”“我暂时影响不了什么”。这样既去羞耻，也保留行动感：人不是系统外的孤岛，也不是系统里的木偶。

适合场景：自责、羞耻和无力感同时出现时尤其适用。系统可以把问题从“我怎么这么差”改写成“我所在的系统如何奖励或惩罚这种反应”。如果用户仍有改变空间，再引导他选择最小可行动作；如果系统存在明显不公或危险，则优先寻找外部资源，而不是继续要求自我优化。', '["系统主义", "结构性压力", "行动感", "去羞耻", "家庭系统", "职场关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 412, now()),
(100413, '社会结构就是纽带：关系会改变人，不只是背景', '核心观点：书中把社会结构理解为系统中各成分之间的关系集合，并特别区分“会影响关系项的关系”与普通并列关系。婚姻、就业、贸易、教育、政治忠诚等不是静态背景，而是会改变当事人的纽带：它们规定可接近的资源、可说的话、需要承担的责任和违背规则的代价。

App 应用：关系问题常被说成“我不够好”“他性格冷”“我们沟通差”。系统视角会继续追问：你们之间有哪些纽带？这些纽带带来的是照顾、依赖、考核、经济交换、身份义务，还是公开承诺？同一句话在朋友、上下级、伴侣、亲子之间意义不同，因为纽带不同。

关系成长提醒：改变关系不能只改情绪表达，还要识别纽带本身。比如伴侣冲突可能同时包含亲密纽带、家务分工、经济依赖和双方家庭期待；职场委屈可能包含任务关系、评价权和晋升资源。把纽带画出来，用户更容易看见：哪些是沟通可修复的，哪些需要边界、资源或制度性调整。

适合场景：适合处理伴侣分工、职场委屈、亲子义务和朋友间金钱往来。系统可提示用户不要只描述情绪，还要描述纽带：谁依赖谁，谁评价谁，谁掌握资源，谁承担后果。许多所谓“沟通问题”其实是纽带不清或权责不对等；把它命名出来，才知道该谈感受、谈规则，还是谈退出方案。', '["社会结构", "纽带", "关系地图", "制度关系", "边界", "资源分配"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 413, now()),
(100414, '角色不是性格：同一个人在不同位置会做出不同反应', '核心观点：书中指出，同一个体在不同社会系统中，或在同一系统里升职、降职、换位置时，可能出现不同行动；“角色”必须参照同一系统中的其他人才能说清。一个经理、下属、照顾者、孩子、伴侣并不是几套内在人格，而是在不同关系位置上承接不同任务、权力、期待和风险。

App 应用：当用户困惑“我在外面很能干，回家就像小孩”“我明明温和，却在团队里变得控制”时，可以先用角色视角降羞耻：这可能不是你人格分裂，而是不同系统正在调用不同角色脚本。接着追问：这个角色被要求完成什么？它拥有哪些权力？承担哪些责任？最害怕失去什么？

关系提醒：角色冲突常来自多个期待同时挤压，例如既要做孝顺子女，又要做独立伴侣；既要做高绩效员工，又要做稳定父母。成长不是消灭某个角色，而是给角色排序、协商边界，并把“我这个人不行”改写为“我正在处理多个系统给我的任务冲突”。

适合场景：用户在不同关系中表现反差很大，并因此自责“我是不是很假”时，可用角色框架帮助整合。系统可询问：这个角色从什么时候开始？谁最在意你扮演好它？如果你退出这个角色，会影响谁的利益或安全感？这些问题能把角色脚本从身份里拆出来，让用户有机会重新谈判。', '["社会角色", "角色冲突", "身份压力", "家庭关系", "职场压力", "去人格化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 414, now()),
(100415, '机制解释：别只问发生了什么，要问它如何运转', '核心观点：书中把“机制”放在解释的中心：真正理解一个过程，不只是看到两个现象一起出现，而是知道中间如何连接、靠什么力量维持、在哪些条件下会改变。作者用黑箱、灰箱、透光箱区分解释深度：黑箱只说输入输出，灰箱只给粗略中介，透光箱才尽量说明“它如何运行”。

App 应用：心理教育内容可以少做简单归因，多做机制拆解。例如“冷战伤关系”不是因为冷战这个词不好听，而是因为回避—猜测—威胁感—更回避的回路会不断强化；“讨好很累”不是因为讨好者软弱，而是认可奖励、冲突恐惧、短期安全感共同维持了行为。

用户练习：把一个困扰写成四格：触发条件、自动反应、短期收益、长期代价。再问：谁在奖励这个模式？什么环境让它更容易发生？哪个小环节最能被改变？这样能把“我就是这样”转成“这个机制正在这样运转”。

适合场景：适合把抽象建议转成可操作方案。系统若只说“多沟通”“要自信”，用户很难行动；若能指出维持机制，就能设计干预点。比如先改变触发条件，或改变短期奖励，或增加新的支持者。机制解释也能减少互相指责：我们不是在找坏人，而是在找让坏模式持续运转的零件。', '["机制解释", "行为回路", "黑箱灰箱透光箱", "心理教育", "模式识别", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 415, now()),
(100416, '微观—宏观双层图：个人行动与制度环境互相接力', '核心观点：书中批评只从个人偏好解释社会现象，也批评只从宏观结构压下来的解释。更好的系统解释要同时看自下而上的个人行动和自上而下的环境约束：社会关系经过人的头脑，最终由个体行动承接；但个体意图、期望和选择又被资源、阶层、教育、政策、组织规则塑造。

App 应用：面对“我为什么不离开这段关系/这份工作/这个家庭模式”，不要只问意志力，也不要只说环境太强。可以画双层图：宏观层写制度、经济、家庭规则、群体舆论；微观层写感受、信念、选择、身体反应；中间写它们如何互相影响。

关系成长提醒：许多痛苦不是“想通就能改”，因为微观选择需要宏观条件支持；但宏观条件也常通过微小行动被重新组织。比如争取支持者、保存证据、学习技能、调整沟通脚本，都是让个体行动接上结构改变的桥。

适合场景：用户把问题全部归因于自己不够坚定，或全部归因于社会/家庭不给机会时，都可用这条拉回双层分析。系统可以分别生成“个人层可做的三件小事”和“环境层需要争取的三种资源”。这能避免鸡汤式行动主义，也避免结构决定论，让用户在现实限制内看见可移动的边界。', '["微观宏观", "能动性与结构", "制度环境", "选择受限", "系统图", "社会支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 416, now()),
(100417, '价值与事实分开看：客观不等于没有立场', '核心观点：书中反对把客观性误解成“不能作价值判断”。客观性要求我们尽量准确描述事实、证据和机制；但当事实涉及压迫、伤害、剥夺或不平等时，研究者和助人者仍可以有清楚的伦理立场。换句话说，区分事实与价值，不是把价值赶出讨论，而是让价值判断建立在更可靠的事实理解上。

App 应用：关系成长中常见两种偏差：一种是只讲价值，“你必须原谅/必须独立/必须孝顺”；另一种是假装中立，“谁对谁错我不评价”，结果让受伤者继续自责。更好的回答可以分两步：先核对事实——发生了什么、频率如何、影响是什么；再说明价值——尊重、自主、安全、平等为什么在这里重要。

提示语：可以对用户说：“我们先把事实讲清楚，再看哪些底线被触碰。”这能避免道德说教，也避免把伤害稀释成单纯观点差异。

适合场景：适合处理家暴、语言贬低、职场不公、亲子控制等容易被“各有各的立场”稀释的问题。系统应避免替用户武断定罪，但也不能把伤害包装成中立分歧。事实核对越清楚，价值判断越有力量：频率、影响、权力差和可拒绝性，都是判断边界是否被侵犯的重要线索。', '["事实价值区分", "客观性", "伦理立场", "关系边界", "安全底线", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 417, now()),
(100418, '关系改变要系统化：只改一个环节容易产生反作用', '核心观点：书中讨论社会改革时指出，系统不能像死物一样被随意切开修理；改变一个成分会影响其他成分，有时还会带来不可预见的反作用。对家庭、亲密关系和团队也是如此：只要求一个人改变说话方式，却不改变权力、分工、奖惩和支持条件，常会让旧模式换个形式回来。

App 应用：当用户想“只要我不发脾气/只要我更温柔/只要我更努力，关系就会好”时，可以提醒做系统化改变：一看触发源，二看互动回路，三看资源支持，四看对方是否参与，五看改变后谁会失去既得好处。关系中的新行为需要新环境托住，否则容易被旧规则拉回。

小练习：为一个目标列出相关部门——情绪调节、沟通脚本、时间安排、经济资源、同伴支持、边界后果。每个部门设一个小调整，而不是把全部责任压在“我要更强大”上。

适合场景：用户已经做过多次个人努力却总是复发时，可以用来检查系统条件。系统可问：你的新做法会让谁不适？旧模式给谁带来好处？有没有共同规则来保护新模式？如果没有，改变就会变成单人硬扛。系统化改变不一定宏大，它可以是一次家庭会议、一份分工表、一个冷静期协议或一个外部支持网络。', '["系统性改变", "反作用", "关系修复", "家庭系统", "分工权力", "支持条件"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 418, now()),
(100419, '真实的人不是冷酷计算器：情绪、地位和关系会进入选择', '核心观点：书中批评把人想象成只计算收益的“经济人”。真实的人会算错，甚至根本不计算；会受情绪、关系、地位、宣传和群体氛围影响。这不是说人没有理性，而是说人的理性总在身体、身份、资源和关系网络中运行。

App 应用：当用户自责“我明知道不该这样，为什么还会选错”“我为什么总被认可牵着走”时，回答不宜停在“你要理性一点”。更有帮助的是识别选择现场：当时有什么情绪唤醒？谁在场？我在保住什么身份？我担心失去什么关系？这个决定短期给了我什么安全感或地位感？

关系成长提醒：改变选择要改变选择环境。比如在冲突前约定暂停协议，在消费或复合前设置等待期，在群体压力前准备支持者，在高唤醒时先降温。理性不是压倒情绪，而是为情绪、关系和地位压力预先设计缓冲。

适合场景：冲动复合、讨好答应、群体压力下附和、被营销或权威影响时都适用。系统可以把“选择错误”翻译成“选择环境设计不足”：当用户处于疲惫、孤独、羞耻或急需认可的状态时，最聪明的策略不是当场变理性，而是提前设置延迟、同伴确认、书面清单和离场脚本。这样既减少自责，也提高下一次选择质量。', '["理性选择批评", "情绪决策", "地位焦虑", "社会影响", "选择环境", "自责松动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 419, now()),
(100420, '场域：关系不是空地，而是有规则的游戏现场', '【核心理解】布尔迪厄提醒我们：一个人进入家庭、职场、亲密关系、学校或社群时，并不是走进一片中性的空地，而是进入一个已经有排序、有奖励、有禁忌、有“什么才算有价值”的场域。很多关系冲突表面上是性格不合，实际是在争夺谁的规则算数、谁的话更有分量、什么资源会被承认。
【关系应用】当用户说“我是不是太不会做人”“为什么我总被边缘化”，App 可先帮助他识别当前场域：这里看重钱、学历、人脉、资历、情绪劳动、性别角色，还是某种体面感？谁有权定义对错？哪些行为被奖励，哪些会被惩罚？
【成长方向】看见场域不是鼓励圆滑，而是把自责改成定位。用户可以选择学习规则、协商规则、寻找盟友，或离开不适合自己的场域。真正的关系成长，不只是把话说得更好听，也包括弄清自己正在参与什么游戏，以及是否愿意继续玩。
【后台落点】可做成“场域定位卡”：1）我在哪个关系场域；2）这里默认奖励什么；3）我缺的不是哪种性格，而是哪类资源、资格或支持；4）我愿意遵守、协商还是退出哪些规则。这样能避免把所有不适都解释为沟通能力差，也能避免把适应误读为讨好。', '["场域", "关系规则", "无形规则", "权力关系", "自我定位", "关系成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 420, now()),
(100421, '资本不只是钱：看见关系里的文化、社会与象征资源', '【核心理解】布尔迪厄把资本从“钱”扩展到多种能影响关系位置的资源：经济资本是财产和收入，文化资本是语言能力、教育经历、审美与信息，社会资本是关系网络与熟人资源，象征资本则是名声、资格、体面和被承认的合法性。很多关系里的不平等，不是因为某个人天生更值得被听见，而是他带着更多被场域承认的资本。
【关系应用】当用户在伴侣、婆媳、同事或同学关系中觉得“我说什么都没用”，App 可引导他画一张资本地图：谁掌握经济资源？谁更懂规则和话语？谁有支持网络？谁的身份更容易被相信？
【成长方向】资本地图不是给人贴阶层标签，而是帮用户少一点羞耻、多一点策略。缺信息就补信息，缺支持就建网络，缺表达资格就寻找能被承认的渠道。关系中的自尊不只来自内心强大，也来自现实资源被一点点补足。
【后台落点】这条适合接在自卑、配得感、职场弱势和亲密关系权力差内容后。系统不只给“提升自信”的建议，而要把问题拆为可补足的资源：需要钱、时间、知识、证书、见证人、可信推荐，还是一个能帮你翻译规则的人。把资本具体化，用户才不会把资源不足误会成自己不值得。', '["资本", "文化资本", "社会资本", "象征资本", "资源地图", "关系不平等"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 421, now()),
(100422, '习性：那些“不用想就会这样”的反应，常是社会经验进了身体', '【核心理解】习性不是简单的习惯，也不是固定人格，而是长期生活条件进入身体和判断后的倾向系统。它让人不用计算就知道“该怎么坐、怎么说、该不该争取、什么人适合我、什么东西不是给我准备的”。因此，一个人回避表达、过度证明、天然自信、害怕被看见，可能都不只是心理问题，也可能是过去家庭、阶层、学校和关系经验在身体里留下的方向感。
【关系应用】App 面对“我为什么总忍不住讨好/退缩/逞强”的用户，可以先不急着纠正，而是追问：这种反应最早在哪些场景有用？它曾经保护过你什么？它对应的是怎样的家庭位置、性别期待、经济压力或学校评价？
【成长方向】改变习性不能只靠讲道理，需要新的场域、新的身体经验和小步实验。用户可以从低风险表达、被支持地拒绝、在安全关系里练习不同姿态开始，让身体慢慢学会：过去的规则不必永远支配现在。
【后台落点】可设计“习性追踪练习”：写下一个自动反应，标出触发场景、身体感觉、脑中规则、最早学会它的关系，以及一个更小的新动作。比如从“我必须马上道歉”改为“我先确认事实”；从“我不能麻烦别人”改为“我提出一个可拒绝的请求”。', '["习性", "惯习", "身体化经验", "社会化", "自动反应", "自我理解", "行为改变"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 422, now()),
(100423, '“这不是给我准备的”：限制感如何变成内心边界', '【核心理解】布尔迪厄特别敏锐地指出，社会限制最隐蔽的地方，是它会被人体验成“我自己不想要”“我本来就不适合”。当资源和机会长期有限，人会发展出一种限制感，把外在边界变成内心边界：不敢申请、不敢亲近、不敢进入某些圈子，甚至把退缩解释成理性、懂事或不贪心。
【心理教育应用】当用户说“那种生活不是给我这种人的”“我不该有更高期待”，App 可以把这句话当作线索，而不是结论。继续问：这是你的真实愿望，还是你对失败概率、羞辱风险、家庭评价、阶层距离的提前适应？如果没有惩罚和羞耻，你还会这样选择吗？
【成长方向】看见限制感，不等于否认现实差距。它意味着用户可以把目标拆成试探：先获得信息、找到同伴、体验一次安全进入，再决定是否继续。不是每个门都必须推开，但至少要分清：这是我的选择，还是过去的社会位置替我做出的选择。
【后台落点】这条适合用于羞耻、阶层流动、择偶、职业申请和学习焦虑场景。系统要区分“我经过评估后不选择”和“我一想到就觉得自己没资格”。前者是边界，后者可能是内化限制。引导用户做一次低成本试探，比直接喊“你要相信自己”更有效。', '["限制感", "社会位置", "自我设限", "阶层感", "可能性", "羞耻修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 423, now()),
(100424, '象征权力：最深的控制，是让评价标准看起来天然正确', '【核心理解】象征权力不是简单命令别人，而是让某套分类、语言和评价标准显得自然、体面、正确。比如“有教养/没档次”“懂事/不识大体”“成功/失败”“正常/丢人”，这些词一旦被接受，就会让人用别人的尺子衡量自己。它的力量在于，被支配者也可能承认这套标准，从而把不平等误认为个人不够好。
【关系应用】在亲密关系和家庭里，象征权力常表现为一方不断定义现实：谁是理性的一方，谁是情绪化；谁叫牺牲，谁叫自私；谁的工作体面，谁的付出不算数。App 可引导用户问三句：这个词是谁发明和反复使用的？它让谁获得合法性？它让我失去了哪些表达自己的语言？
【成长方向】反抗象征权力的第一步，是重新命名。把“我太敏感”改成“我对不尊重有反应”，把“我没出息”改成“我缺少被承认的资源和路径”。新的语言会帮助用户恢复现实感，也为关系协商创造空间。
【后台落点】这条可作为关系风险和自我怀疑内容的上位解释。系统不必把每次分歧都说成符号暴力，而要看是否长期由一方垄断命名权：TA 总能定义你是什么人、你的感受算不算数、什么才叫正常。若是，就先恢复自己的词典，再讨论沟通技巧。', '["象征权力", "符号暴力", "现实感", "评价标准", "语言控制", "关系权力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 424, now()),
(100425, '文化差异不是品味高低：别把生活条件误读成个人价值', '【核心理解】布尔迪厄在《区隔》相关讨论中说明，品味并非单纯的个人审美，也常是生活机会、经济距离和文化资本的结果。有些人重形式、风格和仪式，是因为他们离生存压力更远；有些人重实用、饱足和耐用，是因为他们长期与必需品更近。把两者简单翻译成“高级/低级”“有趣/土气”，就是把社会差异道德化。
【关系应用】伴侣、亲子、朋友之间常因吃什么、穿什么、送什么礼物、怎么旅行、怎样教育孩子而互相评判。App 可提示：先不要急着判断对方“没品味”或“太装”，而要理解这背后的资源经验、家庭训练和安全感来源。
【成长方向】尊重文化差异不是放弃审美，而是把审美从攻击工具变成沟通材料。可以说“这对我代表体面/安全/放松”，而不是“你这样很低级”。当双方能讲出品味背后的生活史，关系就有机会从互相羞辱转向互相翻译。
【后台落点】适合做“品味翻译器”：把评价性语言改成需求语言。比如“你太土”可转成“我在意公共场合的体面”；“你太装”可转成“我担心自己被比较和否定”；“你太小气”可转成“我需要被重视的仪式感”。这样既保留差异，也减少羞辱。', '["文化差异", "品味", "阶层感", "生活方式", "非评判", "关系沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 425, now()),
(100426, '中间位置的紧张：过度用力、不敢松弛，也可能是位置焦虑', '【核心理解】布尔迪厄写到中间阶层时，捕捉到一种很像现代人的紧张：想摆脱旧位置，又还没有足够资源稳稳进入新位置，于是容易过度努力、过度纠错、过度证明自己“够格”。这种状态不必被羞辱为虚荣或做作，它常是处在两个评价系统之间的人，为了获得承认而发展出的生存姿态。
【关系应用】用户若总是害怕说错话、穿错衣服、用错词，或在关系里不断证明自己有价值，App 可以帮助他识别：我是在表达真实需要，还是在向某个想象的评委证明我不低级、不失败、不该被抛下？
【成长方向】缓解位置焦虑，需要从“表现正确”转向“关系真实”。可练习在安全关系中承认不知道、承认普通、承认需要帮助；也可把外部标准分层：哪些标准能帮助我成长，哪些只是让我长期羞耻。真正的从容不是学会所有上层规则，而是不再让单一评价系统决定自己的存在价值。
【后台落点】可用于完美主义、社交焦虑、阶层羞耻和职场新人内容。系统可提醒：过度用力不等于虚伪，它可能说明你正在缺少安全的承认。练习重点不是立刻“松弛感”，而是找到不需要表演也能被接住的关系，并把外部评价从“生死判决”降级为“部分参考”。', '["位置焦虑", "中间阶层", "过度证明", "羞耻", "自我价值", "关系真实"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 426, now()),
(100427, '教育不只是努力赛道：文凭会把家庭资本包装成个人能力', '【核心理解】布尔迪厄对教育的分析适合提醒 App 用户：学校并不只是公平筛选努力者的机器，它也会保存、灌输并神圣化某种文化遗产。那些从小熟悉学校语言、审美、表达方式和升学路径的孩子，更容易把家庭资本转化为成绩和文凭；而缺少这类资本的人，常把不适应误解为自己笨、不努力或没天赋。
【关系与亲子应用】当用户因学历、孩子成绩、择校或职业资格而自责时，App 可引导他同时看四层：个人努力、家庭可提供的信息和时间、学校默认的文化规则、文凭在劳动力市场里的兑换价值。这样既不否认努力，也不把所有结果压回个人。
【成长方向】教育资本可以被补建：找懂规则的人、获得信息、练习表达、认识隐性评价、争取支持网络。对父母而言，重要的不只是催孩子努力，还包括帮助孩子理解游戏规则，并减少“输不起”的羞耻。
【后台落点】这条适合亲子教育、学历羞耻和职业选择模块。回应用户时要同时保留两句话：努力有意义，但努力发生在不平等的资源结构中；文凭有现实价值，但文凭不能决定人的全部价值。这样既不犬儒，也不把教育压力继续转嫁给孩子和个体。', '["教育", "文化资本", "家庭资源", "文凭", "亲子压力", "社会不平等"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 427, now()),
(100428, '关系中的准入费：进入一个圈子前，先看它要你交什么', '【核心理解】每个场域都有准入费。它不一定是金钱，也可能是学会某种说话方式、接受某种情绪劳动、认同某些价值、维护某些面子，或默认某些人拥有更高解释权。进入职场、伴侣家庭、朋友圈、社群、精英学校和专业圈子时，人往往先被要求证明“你知道怎么玩”。
【关系应用】当用户在新关系里感到累、格格不入或总被暗示“不懂规矩”，App 可帮他列出准入费清单：我要付出时间、金钱、形象管理、服从、沉默、礼物、人情，还是自我否定？这些成本是否合理？它们换来的归属是否真实？
【成长方向】成熟的关系不是没有规则，而是规则可以被说明、协商、修正。若一个圈子的准入费是长期牺牲尊严、现实感和边界，就不只是适应问题，而是场域本身在消耗你。用户可以学习必要规则，也可以保留退出权。
【后台落点】可做成“准入费评估表”：规则是否公开、成本是否可承受、是否允许拒绝、是否有退出惩罚、是否要求你否认自我。健康圈层会让新人学习规则，但不会把羞辱当筛选；不健康圈层会不断移动门槛，让你永远觉得自己还不够格。 若用户总觉得“我已经很努力讨好了，为什么还不被接纳”，系统可进一步区分：这是学习成本，还是关系在借规则维持不平等。', '["准入费", "圈层", "关系边界", "隐性规则", "归属感", "场域适应"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 428, now()),
(100429, '错位感：旧习性遇到新场域时，焦虑可能是转型信号', '【核心理解】人会带着过去形成的习性进入新的场域。若新场域的机会、奖励和规则与旧经验相近，人会觉得自然；若差距很大，就会出现错位感：明明已经换了环境，却还用旧方式判断安全、价值和可能性。初代大学生、跨阶层伴侣、转行者、移居者、进入新家庭的人，都可能体验到这种“我好像不属于这里”。
【心理教育应用】App 可把这类焦虑从“我有问题”改写成“旧地图遇到新地形”。可以引导用户区分：旧场域教会我的规则是什么？新场域奖励什么？哪些旧能力仍有用，哪些会造成误会？我需要补的是知识、关系、语言，还是身体上的安全感？
【成长方向】错位不一定要立刻消除。它可能是身份转换的过渡期，需要哀悼旧熟练感，也需要练习新规则。与其逼自己马上自信，不如找一个可解释规则的人、一个允许犯错的小空间，以及一套逐步更新习性的练习。
【后台落点】适合新城市、新学校、新职业、跨阶层亲密关系和家庭重组场景。系统可以先验证用户的错位感，再帮他分别列出旧规则与新规则。目标不是立刻融入，而是保留旧经验中有力量的部分，同时补上新场域需要的语言、节奏和支持。', '["错位感", "惯习", "习性滞后", "身份转换", "跨阶层关系", "焦虑", "适应"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 429, now()),
(100430, '承认也是资本：被看见、被相信，会改变一个人的关系位置', '【核心理解】象征资本可以理解为被承认的资本：名声、信誉、资格、体面、可信度和“这个人说话算数”的位置。它常和社会资本交织在一起，使某些人的表达更容易被相信，某些人的痛苦更容易被轻视。关系里的很多不平等，并非只发生在钱和权上，也发生在谁被承认、谁被默认无理、谁必须反复自证。
【关系应用】当用户抱怨“为什么同样的话别人说就有用，我说就被当成闹情绪”，App 可以引导他观察承认结构：在这个家庭或团队里，谁天然可信？谁的学历、年龄、性别、职位或收入给了他说话权？谁的贡献被当成应该？
【成长方向】争取承认不是乞求认可，而是建设更公平的见证系统。用户可以记录事实、寻找第三方支持、把贡献具体化、避免只在否认自己的人面前证明自己。健康关系会扩大彼此的象征资本：让对方的感受、劳动和边界都能被看见。
【后台落点】这条适合处理“我怎么说都没人信”“我总要证明自己”的自证疲劳。系统可以建议用户减少在否认者面前耗尽自己，转而建立见证系统：书面记录、可信朋友、专业支持、共同规则、可验证事实。被承认不是虚荣需求，而是关系公平的一部分。', '["象征资本", "承认", "可信度", "关系位置", "被看见", "自证疲劳"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 430, now()),
(100431, '社会学想象力：把“我怎么了”改问“什么情境在影响我”', '【核心观点】社会学想象力不是把责任都推给社会，也不是否认个人选择，而是把一个人的困扰放回其生活情境中理解：家庭、邻里、学校、组织、工作市场、历史时代和制度规则，都可能在塑造“我能做什么、我为什么这么难”。当很多人遭遇相似困境时，它往往不只是某个人不够努力，而是某种结构正在反复制造同类结果。
【App落地】用户说“我太失败了、我怎么总是做不到”时，先做双层提问：1）个人层：这件事中我能调整的行为、技能、边界是什么？2）情境层：哪些规则、资源差距、角色期待、时间压力或组织安排在推着我走？3）连接层：谁能提供信息、陪伴、制度资源或专业支持？
【关系成长】这种视角能减少羞耻和互相归罪。伴侣争吵、亲子冲突、职场挫败，都可同时看见人的选择与局面的力量。最后再回到行动：在不能立刻改变大结构时，先找一个可移动的小杠杆；在确实涉及公共议题时，允许自己寻求社群、机构或政策层面的帮助。
【可用提问】如果把这件事拍成一张社会地图，地图上除了“我”还会出现谁、哪些机构、哪些规则、哪些资源缺口？哪些因素我能今天处理，哪些只能先命名、寻找同伴或等待更大的支持？', '["社会学想象力", "个体困扰", "公共议题", "情境", "去自责", "心理教育", "关系成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 431, now()),
(100432, '常识和刻板印象都要追问：它在什么情境下成立', '【核心观点】人会用常识和刻板印象快速解释世界，例如把贫穷归因于懒惰，把某类亲密关系看成“不自然”，或把年龄、体重、性别、族群当成能力和品格的证据。社会学训练提醒我们：常识并非总错，但它通常只在特定情境下成立；刻板印象更危险，因为它把群体标签直接套到具体个人身上，遮住了制度、资源和历史原因。
【App落地】当用户用“他这种人都……”“我这种家庭出来的人注定……”来解释关系时，可引导四问：这个判断从哪里来？有没有反例？谁会因这种说法受益或受伤？如果把具体行为、处境和资源分开看，会得到什么新解释？
【关系成长】这不是要求用户“不要评价”，而是把粗暴归类转化为可核对的事实、具体影响和可协商的需要。尤其在冲突中，少用“你们男人/女人/年轻人/外地人都这样”，多说“我在这件具体事里感到什么、需要什么”。这样既能保留判断力，也能减少羞辱和防御。
【可用提问】这句话是在描述事实，还是在替一个群体下判决？如果我把“总是、都、天生”换成“在某些条件下更可能”，我会看见哪些被忽略的处境和选择？ 这能让解释更慢，也更准确。', '["刻板印象", "常识批判", "归因", "偏见", "群体标签", "沟通", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 432, now()),
(100433, '镜中我：自我感是在重要他人的目光中长出来的', '【核心观点】自我不是孤立的内在物，而是在互动中形成的过程。人会从父母、朋友、老师、伴侣、同事、网络群体等“镜子”里理解自己：我是否聪明、可爱、体面、值得被接纳。重要他人、参照群体和概化他人共同塑造我们在意谁的评价、模仿谁的行为、遵守哪些不成文期待。
【App落地】用户说“我太在意别人眼光”时，不必简单劝他“别管别人”。可以先承认：在意评价是人类维持归属的社会能力。随后做“镜子盘点”：哪些评价来自亲密且可信的人？哪些来自不熟悉但强势的群体？哪些只是想象中的大众审判？哪些镜子长期只反馈羞耻，而不反馈真实与成长？
【成长方向】支持用户寻找更健康的参照群体，让自我感从一个严苛镜子，扩展为多面、稳定、可修正的社会支持系统。练习上，可以把“别人怎么看我”改成“哪些人的反馈值得进入我的自我定义，哪些只适合当作情境信息”。
【可用提问】我现在最怕失去谁的认可？这个人或群体是否真正了解我？我有没有把一次表情、一次沉默、一个点赞数量，误读成对整个人的判决？我还可以把自己交给哪些更温和的镜子？ 这一步能把羞耻还原成信息。', '["镜中我", "社会互动", "重要他人", "参照群体", "自我感", "归属", "自尊"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 433, now()),
(100434, '角色冲突：你不是矛盾的人，而是同时被多个期待拉扯', '【核心观点】人在一天中会切换许多角色：子女、父母、伴侣、学生、员工、朋友、照顾者、领导者。每个角色都带着一套期待和“应该”：学生要跟上课业，朋友要帮忙，子女要回家，员工要服从流程，父母要照顾孩子。当两个角色的要求同时出现且互相冲突，痛苦并不说明这个人虚伪或没原则，而是社会位置之间发生了拉扯。
【App落地】处理内疚和两难时，可用角色冲突表：1）我现在被哪些角色要求？2）每个角色背后的具体期待是什么？3）如果满足A，会牺牲B的什么？4）有没有边界、协商、延期、部分满足或求助的空间？5）这次选择是在照顾长期价值，还是只是在躲避眼前评价？
【关系成长】把“你怎么这么自私/不孝/不负责”改成“我们各自被哪些角色期待拉住”，能降低道德攻击，让双方讨论真实限制和优先级。角色冲突无法靠讨好所有人解决，成熟的目标是有意识地排序、解释和承担后果。
【可用提问】此刻最强的内疚来自哪个角色？这个角色的期待是否合理、是否过时、是否由我一个人承担？如果我只能诚实满足一部分，我要怎样说明边界并保留关系？ 这一步能让选择更诚实。', '["角色冲突", "社会角色", "内疚", "边界", "家庭关系", "职场压力", "协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 434, now()),
(100435, '规范和制度：看不见的脚本让人感觉“不得不”', '【核心观点】很多压力来自看不见的脚本。规范是不成文的“这样才合适”，规则是更正式的准则，制度则把规则和惯例固定进学校、家庭、婚姻、法律、公司、医疗等组织里。人往往觉得自己在自由选择，实际已经被“好孩子该怎样、合格员工该怎样、体面家庭该怎样”的脚本牵引。违背脚本不一定违法，却可能招来尴尬、排斥、惩罚或羞耻。
【App落地】当用户说“我必须这样做，不然大家会觉得我很糟”时，可追问：这是明文规则，还是默认规范？谁在执行它？违反后真实代价是什么，想象代价是什么？它保护了谁，又压住了谁？哪些部分能协商，哪些需要外部资源或集体支持？
【关系成长】看见规范不是为了鼓励任性，而是让用户从自动服从变成有意识选择：我愿意遵守哪些规则，又要在哪些规则前建立边界。对亲密关系尤其重要：很多争执表面是性格不合，底层其实是双方带着不同家庭、阶层或性别脚本进入同一段关系。
【可用提问】这条脚本是我真正认同的价值，还是害怕被排斥而服从的惯例？如果我要微调它，最小、最低风险的实验是什么？谁能见证我不是在破坏关系，而是在创造更健康的规则？', '["社会规范", "制度", "规则", "社会事实", "边界", "家庭脚本", "职场脚本"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 435, now()),
(100436, '标签会变成现实：从污名到自我实现预言', '【核心观点】标签不是中性的描述。一个人或群体被贴上“坏孩子、疯子、失败者、越轨者、不正常”的标签后，周围人的期待、机构的处理方式和同伴网络都会随之改变；久而久之，被贴标签的人可能被迫进入标签所规定的位置，形成自我实现预言。污名的伤害不只在于难听，而在于它会减少机会、改变互动、制造隔离，并让人把外界判断误认为自我本质。
【App落地】面对用户自称“我就是有问题的人”时，先把标签拆开：具体发生了什么行为？谁给出了这个名称？这个名称带来哪些后果？有没有更准确、更少伤害的描述？如果确有行为需要承担责任，也应落在行为修复、支持和新选择上，而不是把整个人判死刑。
【关系成长】亲密关系和亲子沟通中，少用身份判词，多说具体事件、影响、需要和下一步。例如把“你就是废物/疯了/坏孩子”改成“这件事造成了什么影响，我们需要怎样修复”。这样既保留边界，也减少污名进入自我概念。
【可用提问】这个标签让我失去了哪些具体机会？它让我开始用什么方式看自己？有没有一个更贴近事实、也更有行动空间的新名称？我能否把“我是这种人”改成“我曾经有这种行为/处境/反应”？', '["标签理论", "污名", "自我实现预言", "越轨", "身份羞耻", "去标签化", "行为修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 436, now()),
(100437, '身份不是本质：分类会被建构，却会产生真实后果', '【核心观点】性别、种族、族群、身体特征、残疾、宗教等身份，经常被人当作个人本质，但社会学更关注这些分类如何被社会赋予意义，以及它们如何影响机会和待遇。某些分类并非天然固定，却因为法律、学校、雇主、家庭和日常互动的反复使用而变得“真实”：它会决定别人如何看你、你能进入哪些空间、你是否更容易被怀疑、奖励或排斥。
【App落地】当用户遭遇性别偏见、地域标签、身材羞辱或族群歧视时，不宜只说“别在意”。更有帮助的是：承认这不是单纯敏感；区分生理事实、社会意义和具体待遇；记录发生过的行为；寻找制度性申诉、同伴支持和心理修复。
【关系成长】身份理解要避免两种极端：既不把人简化为标签，也不否认标签在现实中造成的机会差异和心理负担。App可提醒用户：我不是标签本身，但我确实可能生活在某些标签带来的现实后果里；成长既包括自我接纳，也包括为自己争取更公平的互动条件。
【可用提问】这个身份在我的生活里带来哪些优势、限制、误解或危险？我希望别人看见我的哪些复杂性？在争取被理解之前，我需要先为自己建立什么安全边界和支持网络？', '["身份", "社会建构", "性别", "种族", "歧视", "身份安全", "社会分类"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 437, now()),
(100438, '阶层不是努力排行榜：资源、压力和机会会代际累积', '【核心观点】阶层不只是收入高低，也包括教育机会、家庭资源、社会关系、健康风险、居住环境和未来想象。贫困的影响不止是“钱少”，还会带来长期压力、发展机会不足和选择范围缩小。社会流动研究提醒我们：一个人的出身资源与成年后的机会往往有关；向上流动的故事真实存在，但不能因此把未能流动的人解释成不够努力。
【App落地】当用户因家庭条件、学历、职业起点而羞耻时，可把问题改成资源地图：我目前缺的是钱、时间、证书、关系、信息、健康、照顾支持，还是安全环境？哪些资源能通过小步积累获得，哪些需要政策、机构、社群或专业支持？
【关系成长】阶层视角能减少伴侣、亲子之间的互相轻视：不同起点会塑造不同习惯和风险感，理解差异后再谈责任与计划。它也能提醒用户不要用单一成功标准评价自己：真正的问题不是“我为什么不像别人一样轻松”，而是“我在现有资源下如何获得下一份支持”。
【可用提问】我现在羡慕或责备的人，拥有哪些我没有看见的起点资源？我拥有哪些别人可能看不见的能力和支持？下一步是补资源、换环境、找导师，还是先停止把结构压力翻译成自我攻击？', '["社会分层", "阶层", "贫困", "机会不平等", "社会流动", "资源地图", "去羞耻"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 438, now()),
(100439, '文化资本与品味：别把“没见识/不高级”当成人格评价', '【核心观点】人们常以为品味只是个人喜好，其实谈吐、穿着、爱好、审美、教育经历和“知道什么”都会成为文化资本，影响别人如何判断一个人的地位和是否“合群”。所谓有品味，常常不是天生高级，而是某些家庭、学校和圈层更早、更自然地传递了特定规则。文化资本会帮助人进入机会场，也会把没有相同背景的人挡在门外。
【App落地】用户在社交、面试、亲密关系里因“我不够体面、不懂规矩、融不进去”而自卑时，不要把这解释成低价值。可以把隐藏规则显性化：这个场域看重什么语言、礼仪、知识和关系方式？哪些可以学习，哪些不必迎合？我能否在掌握规则的同时保留自己的出身经验和真实喜好？
【关系成长】学习文化规则是扩展选择，不是羞辱原来的自己。对App知识库而言，这一条可用于解释“社交自卑、阶层羞耻、伴侣消费观差异、见家长焦虑”等问题：冲突常常不是谁更高级，而是谁熟悉哪套文化密码。
【可用提问】我进入的这个圈层默认哪些知识是“大家都懂”的？我不懂时，是能力不足，还是没有被提前教过？我可以把哪些规则当作工具学习，又把哪些评价还给评判者？', '["文化资本", "品味", "阶层复制", "社交自卑", "场域规则", "身份认同", "职场成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 439, now()),
(100440, '工作压力不只是抗压差：好工作需要自主、信任、技能和稳定', '【核心观点】工作不只是换工资的地方，也提供日常结构、身份、关系、技能成长和未来机会。判断一份工作好不好，不能只看薪水，还要看自主权、被信任程度、社会地位、技能是否被使用、上升空间和稳定性。低控制、高监控、日程不稳定、福利缺失和随时可替代，会让人长期处在不安全感中；这类痛苦不是简单的“玻璃心”或“不会时间管理”。
【App落地】用户说“我上班很崩溃”时，可从工作结构评估：我能控制节奏吗？是否被严密监控？任务是否有意义或能成长？岗位是否稳定？组织是否把风险转嫁给个人？我需要的是情绪调节、边界谈判、技能转型、求职准备，还是外部保障？
【关系成长】把职场压力带回家庭时，伴侣双方可讨论制度压力如何进入关系，而不是只互相指责脾气差。对个体而言，也要把“工作表现”与“人格价值”分开：一份坏工作可以消耗人，但不等于这个人没有能力或没有价值。
【可用提问】这份工作最消耗我的，是任务量、关系、监控、低自主、低回报，还是未来不确定？如果我暂时不能离开，能否先增加一点控制感、恢复资源，并为下一次选择积累筹码？ 先稳住身心，再做职业判断。', '["工作", "组织", "自主权", "工作满意度", "职业压力", "稳定性", "职场心理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 440, now()),
(100441, '家庭是电影不是照片：亲密关系要看过程、资源和支持', '【核心观点】家庭不是一种固定类型，而是一条不断展开的路径。外人看到的“完整家庭、单亲家庭、再婚家庭、双职工家庭、同性伴侣家庭”只是某一刻的照片；真正影响成员福祉的，是家庭过程：是否有安全、照顾、经济稳定、情感支持、灵活分工和应对变化的能力。现代家庭变化与经济重构、女性教育和就业、工作—照顾冲突、婚姻制度变化相连，不能简单归咎于“家庭价值崩坏”。
【App落地】处理家庭议题时，少问“这是不是标准家庭”，多问：谁在照顾谁？资源够不够？冲突是否安全？角色能否调整？有没有外部托育、亲友、社区、工作弹性或法律支持？
【关系成长】家庭压力往往来自旧制度脚本和新现实不匹配。帮助家庭创造更灵活的安排，比评判哪种家庭形式更高级更有效。对用户来说，重要的不是把家庭修成某张理想照片，而是在变化中持续增加安全、合作和可获得的支持。
【可用提问】家里真正需要被照顾的是什么：钱、时间、老人孩子、情绪、尊严，还是安全？现在的分工是因为大家都认可，还是因为旧脚本惯性运转？有没有一项任务可以重新分配或外包？ 重点是支持真实生活，而非维护面子。', '["家庭", "亲密关系", "工作家庭冲突", "照顾", "家庭过程", "多样化家庭", "社会支持"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 441, now()),
(100442, '谁在定义“正常”：越轨、道德和社会控制的关系视角', '【核心观点】越轨并不等于少见，也不等于天然坏。某行为是否被看成越轨，取决于群体规范、历史语境、权力关系和社会控制方式。穿什么、爱谁、喝酒、用药、离婚、未婚生育、精神疾病、犯罪等，都曾在不同时间被不同制度以不同方式定义和惩罚。真正需要追问的是：谁有权定义正常？谁承担污名和惩罚？这种定义保护了安全，还是维护了某种不平等？
【App落地】当用户因“不像别人”而羞耻，或被家人/团队说成“有问题”时，可先区分三层：1）是否存在实际伤害或安全风险；2）是否只是违反了某个群体的习惯；3）是否被权力较强的一方道德化。若有伤害，做修复；若主要是规范压力，就需要边界、同伴支持和低风险表达。
【关系成长】把“正常/不正常”的争吵改成“影响、风险、规则来源和选择空间”的讨论。这样既不浪漫化所有越界，也不把差异自动病理化，适合用于家庭冲突、性/亲密议题、社群排斥和自我接纳场景。
【可用提问】我被说成“不正常”时，对方具体担心的风险是什么？这个风险有没有证据？如果只是不同价值观的冲突，我可以用什么低风险方式表达自己，同时保护安全和退路？', '["越轨", "社会控制", "正常性", "道德化", "污名", "边界", "非病理化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 442, now()),
(100443, '把关系问题放回资源和规则中看', '当一个人反复在关系里感到“我说了也没用”“我总是要让步”，不必急着把答案归结为性格软弱、沟通技巧差或原生家庭创伤。伦斯基提醒我们：社会关系会进入人的自我意识，关系也不只是情感交换，还包含资源、规则和位置。App 端可把这个视角转成温和的自查：谁掌握时间、金钱、信息、评价权和退出权？谁能说“不”而代价较小？谁的情绪会被优先照顾，谁的需要常被推迟？这些问题不是为了制造阵营，而是为了减少无谓自责。适用场景包括伴侣中一方长期解释、家庭中某个孩子总被要求懂事、团队里新人没有发言权。更完整的关系成长问题是：在承认个人责任的同时，能否把隐形规则说出来，把“我是不是太敏感”改成“这个互动结构让谁更有余地，谁更容易失声”。接下来的行动可以很小：澄清一条规则、要求一次平等反馈、把资源信息透明化、为拒绝设置可承受的后果、找一个见证者陪自己复盘。如果关系已经存在明显威胁，优先考虑安全和支持网络，而不是继续证明自己讲得有道理。这样，改变不只是调整心态，也是在重建更安全的互动条件。用于知识库问答时，可把它放在“关系中总觉得低人一等”“为什么我总是解释不清”“我是不是太敏感”等问题下，作为从自责转向结构觉察的入口。', '["权力结构", "关系成长", "资源差异", "自我责备", "边界", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 443, now()),
(100444, '需要与权力：冲突背后常有两套分配逻辑', '书中把分配过程概括为两条看似矛盾的原则：需要和权力。为了让合作继续，成员的基本生存和生产能力要被维持；但一旦出现“剩余”——额外机会、荣誉、金钱、关注、时间、晋升名额，谁能拿到更多，往往取决于权力如何分布。关系里的很多冲突也可以这样看：一方在说“我有基本需要，希望被听见、被照顾、被公平对待”，另一方却在用权力逻辑回应：“资源由我安排，规则由我解释，你要适应”。App 可引导用户把冲突拆开：这是基本需要没有被承认，还是额外资源的分配没有规则？谁拥有决定权？有没有申诉、协商、暂停和复盘机制？例如伴侣争吵中，“请你不要羞辱我”属于基本尊严需要；“周末更多时间按谁的偏好安排”则是可协商资源。亲子关系中，安全和照料是基本需要，零花钱、屏幕时间、课外选择则需要透明规则。内容落地时可用三问：我真正要保护的需要是什么？对方手里有什么决定权？是否能把决定权变成双方都看得见的流程？这样做能避免把所有矛盾都道德化，也能避免只讲爱与理解而忽略现实差异。真正可持续的亲密或合作，不是取消所有差异，而是让基本需要有保障，让额外资源的分配可以被讨论、被解释、被修正。', '["需要", "权力", "冲突理解", "资源分配", "亲密关系", "协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 444, now()),
(100445, '特权是行动余地，不是给人的总评', '“特权”在心理教育中容易被听成指责，好像某个人有特权就等于他没有痛苦、没有努力、道德上低人一等。书中的用法更适合被转译为“行动余地”：谁能控制更多剩余资源，谁就更容易拥有选择、缓冲和被原谅的空间。一个人可能在某些维度有优势，在另一些维度受限；同一个人也可能因财产、职业、教育、性别、年龄、户籍、家庭关系等不同角色，被放进不同的阶级系统。App 可以用非羞辱的方式帮助用户识别：我有哪些别人没有的支持？我在哪些地方比别人少了选择？哪些失败不是能力差，而是起点、规则和缓冲垫不同？例如“父母能托底”会让试错成本更低，“熟悉面试语言”会让能力更容易被看见，“有安全住房”会让人更能专注学习。识别特权的目的不是互相扣帽子，而是把现实说清楚：优势方可以更少防御、更愿意透明和让利；弱势方可以减少“都是我不够好”的自责，转而寻找资源、联盟和规则修正。它也适合亲密关系中的修复：拥有更多余地的一方可以先承担解释、等待和补偿成本。提醒用户也要避免反向简化：有优势的人仍可能受伤，有劣势的人也仍有行动力。特权是一张现实地图，不是给人盖棺定论。', '["特权", "行动余地", "自我评价", "多重身份", "资源地图", "去羞辱"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 445, now()),
(100446, '隐性门槛：教育、语言和家庭资源会变成机会差', '现代社会常把教育和证书包装成“客观标准”，这比赤裸裸的世袭更容易被接受，也确实扩大了很多人的机会。但 OCR 文本提醒：教育机会并不等于真正平等。家庭背景会通过财力、语言技能、动机、私人学习条件、信息和期待进入孩子的竞争过程；组织越科层化，学历越容易成为雇用和晋升的前提，于是教育地位本身就变成争夺权力和特权的资源。App 端可以把这条知识用于缓解隐性羞耻：用户如果因为学历、表达、面试、职场晋升受挫而自我否定，先不要只问“我是不是不够聪明”，也要问“我缺的是知识、证书、语言环境、作品机会、导师推荐，还是熟悉规则的人”。这不是否认努力，而是让努力更精确。适用场景包括第一代大学生不懂实习路径、职场新人不会包装项目、转行者缺少证书和行业暗语、来自低资源家庭的人不敢谈判薪资。成长建议可以从补齐门槛开始：拆出可学习的技能、寻找低成本训练、建立信息来源、请求反馈、用阶段性目标替代和高资源者的一次性比较。对于咨询话术，可把“你要更自信”改成“我们一起找出哪条规则还没人教过你”。对用户的核心安抚是：卡住不一定说明你差，也可能说明你正在碰到过去没人帮你翻译的门槛。', '["隐性门槛", "教育资源", "家庭背景", "机会差异", "职场成长", "羞耻修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 446, now()),
(100447, '地位不一致：同一个人会在不同场域被高看或低看', '一个人并不只有一个身份。有人在职业上很受尊重，却因性别、年龄、地域、种族、家庭出身或经济条件被轻视；也有人在家庭中被要求服从，在工作中却承担重要责任。书中把这种现象称为地位不一致，并指出它会带来紧张：当事人自然倾向于按自己最高的地位来理解自己，也期待别人如此对待；而互动中的另一方可能出于利益或习惯，按其最低位置来对待他。App 可把这转化为关系觉察工具：当你突然感到羞辱、愤怒或“我被看扁了”，先问：对方激活了我的哪一重身份？我希望被按哪条规则对待？对方坚持的是哪条排序？这能帮助用户把痛苦从“我不值得”改写为“我的多重身份被不公平地压低了”。应对上，不一定要立刻证明自己全部价值，而是选择适当场域主张规则：在专业场景回到专业标准，在亲密关系表达尊重需求，在家庭场景说明成年人边界，在不安全环境保留能量并寻找承认自己完整身份的支持群体。它也适合解释一些“明明我做得很好，却仍感到被羞辱”的体验：受伤点不在能力本身，而在对方拒绝承认你的完整位置。也要提醒用户：别人偶尔误读不等于你必须耗尽自己纠正；持续的地位压低才需要明确边界、减少暴露或更换环境。', '["地位不一致", "多重身份", "羞耻", "尊严", "关系误读", "社会分层"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 447, now()),
(100448, '自尊与地位：被尊重是心理需要，但排序不是全部价值', '书中关于地位和声望的段落很适合进入心理教育：人们常否认自己在意地位，但许多选择都会受它影响。更深层的原因是，自尊在很大程度上依赖重要他人的尊重；一个人在家人、朋友、同事或所属群体中被如何看见，会影响自我形象和心理健康。App 需要同时传递两点：第一，想被尊重不是虚荣，而是正常的心理需要；第二，把自我价值完全押在外部排序上，会让人陷入无止境比较，因为地位欲望很容易变成“再多一点才够”。可设计练习：列出真正重要的三个评价共同体，而不是让所有人都认可自己；区分“尊严”与“排名”——尊严是基本被当人对待，排名是某个场域里的相对位置；在受挫后寻找具体反馈，而不是把一次低评价扩展为“我整个人不行”。在关系中，也可以把“你不尊重我”翻译得更具体：是没有听完、公开贬低、忽视贡献，还是把你排除在决定之外？越具体，越容易修复。对于比较焦虑强的用户，可引导他建立多来源自尊：能力、关系、身体照顾、价值实践、创造和贡献都能提供稳定感。若用户把所有精力都投入赢得某个圈层认可，App 可提示他检查代价：我是在追求被看见，还是在用排名逃离羞耻？这样既承认社会评价的力量，又不让它垄断内在价值。', '["自尊", "地位", "声望", "尊严", "比较焦虑", "自我价值"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 448, now()),
(100449, '从强力到规则：安全关系需要可预期的权利', '书中讨论权力时指出，强力或威胁是最直接的控制方式，但单靠强力代价高，也难以形成稳定秩序；当权力转向被承认的规则和权利时，虽然仍不完美，却会带来细微而深远的改变。关系成长可以借用这个逻辑：如果家庭、伴侣或团队里的每次冲突都由“谁声音大、谁掌钱、谁能惩罚、谁能冷暴力”决定，弱势一方会越来越沉默，表面平静却没有安全。更健康的关系需要可预期的权利：每个人都有表达、拒绝、解释、暂停、保留隐私、使用共同资源和寻求外部支持的空间。App 可建议用户把抽象公平落成规则：争吵时不威胁分手或断供；重大花费有共同知情权；拒绝亲密接触不被惩罚；复盘时先说影响再说动机；任何一方都可以提出暂停但必须约定回来讨论的时间。规则不是为了让关系变冷，而是让爱不必依赖谁更强。若用户总在问“我怎样才能让他别生气”，可以转问“我们有没有一套不靠恐惧维持的规则”。若规则被反复破坏，重点就不再是把话说得更漂亮，而是评估边界、支持和退出成本。真正的安全感来自“我即使不同意，也不会被剥夺基本尊严”。对关系训练而言，规则还要定期复盘：哪些规则真的保护了双方，哪些规则只是在维护某一方的方便或面子。', '["安全感", "规则", "权利", "关系边界", "控制关系", "尊严"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 449, now()),
(100450, '公民权思维：把被动忍耐转化为可表达的共同权利', '书中把公民权视为一种资源：它不像财产那样只属于少数人，而是在现代社会中逐渐成为更普遍的权利基础。转译到 App 端，不需要做政治动员，而是帮助用户建立“共同权利”的关系语言。很多人在弱势关系里只会忍、讨好或爆发，因为他觉得自己没有资格要求；公民权思维提醒他：有些东西不是奖励，而是基本权利，例如被倾听、不被羞辱、获得必要信息、休息、拒绝、申诉、求助和参与与自己有关的决定。它也提醒优势方：共享规则不是失去权威，而是让关系更可持续。练习上，可以把抱怨改写成权利和请求：“我不是要赢你，而是希望我们都能在争执中不被辱骂”；“我需要知道这笔共同开支的去向”；“我希望有一个可以暂停对话的规则”。当个人资源不足时，用户也可以寻找同伴、制度、专业支持或第三方协助。适用场景包括家庭照护分工、伴侣财务透明、职场加班边界、社群发言规则。在群体关系里，它还可以帮助用户从“求某个人开恩”转向“让规则对所有人一致”。提醒：权利语言不是任性索取，它总是和同等尊重、事实核对、愿意协商相配套。共同权利让人从孤立忍耐走向有边界的表达。', '["公民权", "共同权利", "表达", "边界", "关系协商", "赋权"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 450, now()),
(100451, '冲突不是人格失败：通道不足时，人会寻找制度化行动', '用户常把冲突理解为“我情绪管理差”“我不够成熟”。书中提供了另一种视角：当个人流动机会不足、单靠个人努力拿不到应得报酬时，人们常会转向集体行动；在现代社会，冲突也不必总是暴力，它可以通过合法、非暴力、制度化的方式表达。放到关系和职场中，这意味着反复出现的问题不一定靠更温柔的语气就能解决。若资源、职责、晋升、家务、照护或话语权长期没有通道，冲突会不断回流。App 可引导用户区分三种层次：情绪层——我被触发了什么；关系层——我们如何沟通和修复；制度层——有没有清晰流程、分工、反馈和申诉。成熟不是永远不冲突，而是把冲突从攻击人格转成修正规则：记录事实、提出可验证请求、寻找共同目标、引入第三方、设定复盘时间。也要承认，同一个人可能在冷淡、个人奋斗、合作和抗议之间摇摆；这种复杂反应不等于虚伪，而是人在有限通道中寻找出路。对 App 提示语来说，可以从“别想太多”改成“你想改变的是情绪强度、互动方式，还是资源规则”。如果用户已经多次温和表达无效，下一步也许不是更压抑，而是升级为书面确认、共同会议或外部支持。这会让用户更容易选择合适行动，而不是把所有责任压回自己身上。', '["冲突", "制度化表达", "职场关系", "家务分工", "申诉", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 451, now()),
(100452, '避免单一解释：把阶层和权力拆成可观察变量', '书中反复提醒，传统争论容易被“非此即彼”的概念困住：不平等到底合理还是不合理、社会到底是合作系统还是斗争舞台、某人到底是强者还是弱者。更有用的方法，是把绝对概念改成变量，把复合概念拆成组成部分。App 端可把它做成提问模板：这里涉及哪种资源——金钱、教育、职业、职位、年龄、性别、身份、家庭网络、信息还是身体安全？它的强度有多大？能不能流动？是法律支持、习俗支持，还是靠情绪压力维持？当事人是否在不同系统里位置不一致？这样做能避免两种极端：一种是把所有痛苦都归咎于个人不努力，另一种是把所有选择都交给抽象结构。拆成变量后，用户更容易找到可行动的点：补资源、改规则、换场域、找盟友、练表达、降低不必要比较。举例说，“我在公司被压制”可以拆成岗位权责、绩效标准、上级评价权、同事联盟、行业证书和个人表达策略；“我在家庭里没地位”可以拆成经济依赖、照护贡献是否被看见、长幼规则、房屋所有权和情感威胁。输出时要避免给用户一个宏大标签，而是给他一张小地图：哪一块能改，哪一块要借力，哪一块暂时只能保护自己。复杂化不是为了让人无力，而是为了把模糊压迫感变成可观察、可讨论、可调整的现实。', '["社会分层", "变量思维", "复杂问题", "结构性压力", "行动方案", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 452, now()),
(100453, '社会学视野：把个体困扰放回社会情境', '核心观点：社会学视野不是替个人找借口，而是把“我怎么会这样”扩展为“我处在什么关系、类别和制度中”。书中反复说明，婚恋、生育、职业、失业，甚至看似最私人的自我感受，都有社会模式在背后参与：性别、年龄、阶层、教育、种族、时代变迁和全球经济，会影响一个人能看见什么选择、能承担什么风险、会被怎样评价。
App 端可用法：当用户陷入强烈自责时，先做三步重构。第一，把问题从人格判决改成情境描述：不是“我无能”，而是“我正在面对某个就业、家庭或关系结构”。第二，区分个人可行动部分与结构限制：能调整的是技能、求助、沟通和边界；不能独自承担的是行业收缩、家庭资源差异、社会偏见。第三，把孤立感转成共同经验：许多人不是因为“不够努力”才受困，而是在同一种制度压力下出现类似反应。
关系成长提示：社会学视野能降低羞耻，却不取消行动。它帮助用户少一点自责，多一点观察；少问“我是不是坏了”，多问“哪些关系和规则正在塑造我，我可以从哪里重新选择”。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["社会学视野", "社会情境", "去自责", "结构性压力", "关系成长", "心理教育"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 453, now()),
(100454, '文化与规范：误解常来自不同的符号系统', '核心观点：文化并不只是“风俗习惯”，而是由符号、语言、价值观和规范组成的意义系统。一个眼神、一句玩笑、一种穿着、一顿饭的礼仪，在不同群体里可能完全不是同一件事。文化震惊之所以让人迷失、孤独甚至害怕，是因为原来能自动指导行动的符号突然失效了；人不知道该怎样解释别人，也不知道自己怎样做才合适。
App 端可用法：处理亲密关系、代际沟通、跨地域或职场冲突时，不要急着判断“对方没礼貌”“我不被尊重”。可以先问四个问题：我们对同一个动作赋予的意义一样吗？这条规则是家庭规则、地方文化、阶层习惯，还是组织规范？我是在用自己的标准评价对方，还是愿意先理解对方文化内部的逻辑？哪些规范必须尊重，哪些规范可以协商更新？
成长方向：文化相对主义不是无限纵容，而是先暂停“我的方式才自然”的反射。它让用户在差异中保持好奇：先翻译，再表达；先核对意义，再处理边界。这样能减少关系中的误读，也能帮助用户在新环境里建立安全感。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["文化", "规范", "文化震惊", "跨文化沟通", "关系误读", "边界协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 454, now()),
(100455, '社会化：人格不是孤岛，而是长期关系训练', '核心观点：社会化是一生都在发生的过程。家庭、学校、同辈群体和大众传媒不断教人“我是谁”“什么值得追求”“怎样才算合格”。早期照料会影响信任感和安全感；家庭的阶层、种族和资源会影响孩子的自我定位；学校会扩大儿童的社会世界，也会通过隐性课程教会竞争、服从、时间表和官僚规则；同辈群体影响青春期的归属与风格；媒介则把远方的图像、欲望和标准带进日常生活。
App 端可用法：当用户把性格完全归因于“我天生如此”时，可以引导他做社会化地图：我从家庭学会了什么情绪规则？学校奖励过我哪种表现？同辈群体让我害怕哪种“不合群”？媒体让我把怎样的身体、成功、恋爱当成标准？这些规则哪些曾经保护过我，哪些现在让我受限？
关系成长提示：看见社会化，不是为了怪父母、学校或社会，而是为了把自动反应变成可选择的反应。一个人可以承认过去塑造了自己，同时通过新的关系、新的学习和新的社群经验，继续再社会化。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["社会化", "家庭影响", "同辈群体", "大众传媒", "生命历程", "自我理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 455, now()),
(100456, '地位与角色冲突：压力常是多个身份同时要你负责', '核心观点：每个人都同时拥有多个地位：子女、伴侣、父母、学生、员工、朋友、照料者、领导者。每个地位都带来一组角色期待。压力不一定来自“内心不够强大”，也可能来自多个角色同时索要时间、情绪和责任：一边要做可靠员工，一边要做在场父母；一边要做孝顺子女，一边要维护伴侣边界；一边想亲近学生或下属，一边又要保持公平与专业距离。
App 端可用法：用户说“我什么都做不好”时，可以改问：“现在有哪些角色同时在要求你？”把冲突拆成角色清单：哪些期待来自制度，哪些来自家庭文化，哪些是自己内化的完美标准？哪些角色必须同一时间完成，哪些可以分区、排程、委托或重新谈判？
关系成长提示：角色冲突的解决不只是情绪管理，也需要结构设计。可建议用户建立“角色边界”：工作时间不默认随时回应家庭事务，家庭时间不默认被工作侵入；照料别人时保留个人恢复时间；向重要他人说明自己不是拒绝关系，而是在分配有限能量。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["角色冲突", "角色紧张", "身份压力", "工作家庭平衡", "边界", "责任分配"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 456, now()),
(100457, '性别角色：把“天生应该”还原成社会期待', '核心观点：性别不只是生物差异，更是社会赋予“女性/男性”的意义、资源和限制。书中用跨文化研究说明，不同社会对“男子气质”“女子气质”的定义差异很大，很多被说成天生的分工，其实是文化和制度长期训练的结果。性别分层还会进入家庭、学校、职场和政治：女性常被期待承担更多照料和家务，男性则被期待竞争、坚强、少表达脆弱。
App 端可用法：当用户因“不够像男人/女人”而羞耻，或因家务、育儿、职业选择发生冲突时，可以帮助他把问题从人格评价转成规则识别：谁规定这件事必须由某个性别承担？这条规则对谁有利、让谁疲惫？我真正认同它，还是害怕不遵守会被否定？
关系成长提示：性别平等不是把所有人变得一样，而是让每个人都能协商适合自己的责任和表达方式。伴侣或家庭可以把“你本来就该做”改成“这件事需要谁做、怎样分担才公平”；个人也可以允许自己发展被性别脚本压下去的能力，比如男性练习求助，女性练习主张。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["性别角色", "性别分层", "家务分工", "父权制", "关系协商", "去标签化"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 457, now()),
(100458, '家庭不是纯私域：爱也被资源、权力和制度塑形', '核心观点：家庭既是亲密关系，也是社会制度。它把人们组织起来相互照料、养育子女、传递身份、资源和规则。家庭可以提供情感支持和经济保护，也可能复制不平等：财产继承、父权制、种族与阶层内婚、家务分工和家庭暴力，都说明“家里的事”并不只是私人性格问题。现代家庭形式不断变化，核心家庭、扩大家庭、单亲、再婚和混合家庭，都需要重新定义责任和归属。
App 端可用法：当用户谈原生家庭、婚姻、离婚、育儿或照料老人时，可以同时看三层：情感层，我是否被看见、被支持；资源层，钱、时间、住房、教育机会如何分配；权力层，谁有决定权，谁承担无偿劳动，谁的需求被默认牺牲。
关系成长提示：家庭修复不是回到某个想象中的“传统正确家庭”，而是建立更清楚的照料契约。可引导用户把模糊期待写成可讨论的问题：谁负责什么，边界在哪里，冲突如何处理，孩子和老人需要哪些支持，哪些责任不能只压在一个人身上。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["家庭制度", "亲密关系", "照料劳动", "家庭权力", "混合家庭", "原生家庭"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 458, now()),
(100459, '教育与自我预言：学校既打开机会也复制差距', '核心观点：教育一方面传授知识、社会化年轻人、整合多样人口、分配社会位置；另一方面也可能把家庭资源差异包装成个人能力差异。学校里的标签会变成自我实现预言：当老师、制度或同伴把某些学生看成“聪明”“不行”“适合普通轨道”，学生可能在互动中逐渐活成这些期待。标准化考试、教育分流、学区资源差异和家庭文化资本，会让本来就有优势的孩子继续获得更好的机会。
App 端可用法：面对学习挫败、考试焦虑、学历自卑或亲子教育问题时，不要只问“孩子够不够努力”。也要问：学校给了什么标签？班级和老师如何回应？家庭能否提供安静空间、阅读支持、补习资源和稳定期待？孩子是在学习困难，还是在被长期低期待训练？
成长提示：教育仍然是流动通道，但需要反标签使用。对孩子和成人学习者，都要把评价从身份层拉回策略层：不是“我笨”，而是“我缺少某种训练、资源或反馈”。高期待要配高支持，才不会变成新的压力。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["教育", "自我实现预言", "教育分流", "文化资本", "学习焦虑", "机会不平等"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 459, now()),
(100460, '工作与后工业压力：职业焦虑背后有技术、全球化和组织结构', '核心观点：现代工作不只是个人职业选择，而是经济制度、技术变迁和全球分工共同塑造的结果。后工业经济把重心从制造业转向服务、信息和符号劳动；电脑和网络让“虚拟办公室”随处存在，也模糊了工作与生活边界。失业并不只是个人能力不足，岗位会因公司重组、行业老化、外包、经济衰退和技术替代而消失；即使有工作，很多人也面临低薪、福利减少、兼职化和被持续监控的压力。
App 端可用法：当用户因失业、转行、职业倦怠或被算法管理而自责时，可做结构化复盘：我的行业处在扩张还是收缩？技能是否被新技术替代？公司是否在全球范围寻找更低成本劳动力？我承受的是个人绩效问题，还是组织把风险转嫁给个人？
成长提示：职业韧性不是无限加班，而是提高可迁移能力、维护支持网络、谈判边界和识别结构风险。用户可以为自己保留恢复时间，减少把工作成败等同于人格价值；同时把求职和学习看成对环境变化的适应，而不是对“失败自我”的补救。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["工作压力", "后工业经济", "失业", "技术变迁", "全球化", "职业倦怠"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 460, now()),
(100461, '越轨与标签：不要让一次行为变成整个人的判决', '核心观点：越轨不是某些“坏人”的固定属性，而是社会如何定义规范、发现偏离并做出反应的过程。同一个行为可能被看成粗心、借用、叛逆、疾病或犯罪，取决于情境、权力和他人的解释。标签理论提醒我们：一次轻微偏离如果引发强烈排斥，可能改变一个人的自我概念，使他被迫进入“越轨者”身份；污名一旦成为主要身份，其他品质就容易被遮蔽。
App 端可用法：在亲子、伴侣、学校和社群中，慎用“你就是懒、坏、疯、没救”这类身份标签。更好的做法是区分行为、需要和影响：你做了什么？伤害了谁？背后可能有什么压力或需求？下一步如何修复？对于成瘾、心理困扰、肥胖、创伤反应等议题，既不要道德审判，也不要随意诊断，而是看功能损害、支持资源和专业帮助。
成长提示：去标签化不是否认责任，而是保留改变空间。让人对具体行为负责，同时不把他锁死在一个负面身份里，关系才可能修复，个人也更可能重新选择。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["越轨", "标签理论", "污名", "去标签化", "修复责任", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 461, now()),
(100462, '群体与组织：归属感、参照群体与科层效率的两面', '核心观点：人需要群体归属，但群体也会塑造比较、从众和自我评价。初级群体如家庭和亲密朋友提供情感连接，让人感到“我们”；次级群体如学校、公司和机构更目标导向、非个人化。人还会用参照群体衡量自己：想进入某个圈子时，会提前模仿其穿着、语言、价值和行为。现代社会越来越依赖正式组织和科层制，它们通过分工、层级、规则、绩效和档案提升效率，却也可能带来去人情化、仪式主义和异化。
App 端可用法：用户在团队、社群或职场中受困时，可区分三类压力：归属压力，我害怕被排除；参照压力，我用谁的标准评价自己；组织压力，我被哪些流程、KPI、规则和层级影响。这样能避免把所有问题都解释成“我不会社交”。
成长提示：健康的群体既要有情感连接，也要有清楚规则；健康的组织既要有效率，也要保留人的弹性。个人可练习选择参照群体、建立小型支持关系，并在大型组织中为自己争取可理解、可协商的空间。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["群体", "组织", "参照群体", "科层制", "归属感", "职场关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 462, now()),
(100463, '阶层与社会流动：努力有用，但起点与机会结构也在场', '核心观点：社会分层是把人们按等级组织起来的制度，不只是个人天赋和努力的差别。泰坦尼克号案例显示，阶级位置甚至会影响生死机会；现实中，家庭出身会影响健康、教育、职业、收入、寿命和社会网络。社会流动确实存在，但并不对所有人同样开放。阶层还需要意识形态维持：例如把富有解释为聪明勤奋，把贫困解释为懒惰，就会让不平等显得“公平”。
App 端可用法：当用户因收入、学历、住房、婚恋门槛或职业发展而自卑时，可以把“我差”拆成资源地图：我继承了哪些资源或缺口？教育、家庭、地域、性别、种族/族群、健康如何影响机会？我有哪些可动用的桥接资源，如培训、导师、同伴、制度福利和长期储蓄？
成长提示：承认结构不等于放弃努力，而是让努力更准确。对处在劣势的人，重点不是羞辱式鸡血，而是降低孤立、找到现实通道、积累可迁移资本；对处在优势的人，则要发展阶层觉察，避免把他人的困难简单归因为“不努力”。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["社会分层", "社会流动", "阶层", "贫困羞耻", "机会结构", "资源地图"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 463, now()),
(100464, '现实是互动中建构的：关系修复从改写情境定义开始', '核心观点：日常关系不是简单地“发生”，而是在互动中被共同定义出来的。一个眼神被理解成关心还是嘲讽，一次沉默被理解成冷暴力还是需要空间，都会影响后续反应。书中“现实的社会建构”和托马斯定律提醒我们：如果人们把某个情境当成真实，它就会产生真实后果。学校里的自我实现预言也是同样机制：被期待优秀或失败的人，可能在互动中逐渐表现出相应样子。
App 端可用法：处理冲突时，可引导用户做“情境定义复盘”：我当时把对方的行为定义成什么？对方可能怎样定义我的行为？我们的定义是否被旧伤、阶层、性别、权力或文化差异放大？如果换一个可检验的定义，我会怎样回应？例如把“他故意不回”暂时改成“我还不知道原因，需要核对”，就能为关系留下空间。
成长提示：改写情境定义不是自我欺骗，而是停止把猜测当事实。先核对、再表达影响、再提出请求，可以让互动从敌意循环回到共同解决。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["现实建构", "托马斯定律", "自我实现预言", "冲突复盘", "关系修复", "沟通核对"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 464, now()),
(100465, '社会变迁：焦虑来自变化太快，不只是个人不适应', '核心观点：社会变迁一直在发生，但现代和后现代社会的变化速度特别快。技术、人口、冲突、观念传播和全球扩散会改变家庭、工作、城市、身份和价值。变化不总是进步：汽车、电视、电脑和网络带来便利，也带来环境压力、隐私风险、旧职业消失、社区疏离和身份摇摆。现代性给人更多自由和选择，却也让传统标准松动，许多人在“我是谁”“该怎样生活”上感到不稳定。
App 端可用法：当用户说“我跟不上时代”“我总在比较”“我不知道自己是谁”时，可以把焦虑放回社会变迁：平台和技术是否改变了工作节奏？家庭模式是否比上一代更多样？价值标准是否同时来自传统、消费文化、同辈和全球媒体？用户的困惑也许不是个人失败，而是多套规则并存造成的适应成本。
成长提示：面对变迁，目标不是追上所有变化，而是建立自己的稳定锚点：可靠关系、身体节律、核心价值、可学习能力和有限信息边界。允许自己在变化中慢慢重组身份。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["社会变迁", "现代性", "后现代性", "身份焦虑", "技术影响", "适应压力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 465, now()),
(100466, '社会学式助人：从责怪个人到调整关系和制度场域', '核心观点：这本书的许多主题可以合成一个 App 端底层原则：个体痛苦常常同时发生在身体、关系、组织和制度场域中。一个人的“问题行为”可能连着家庭社会化、学校标签、阶层资源、性别分工、工作制度、群体归属和文化规范。只做心理内部解释，容易把结构压力变成羞耻；只做社会批判，又可能让人失去行动感。社会学式助人要同时保留两者：看见结构，也寻找可操作的小改变。
App 端可用法：面对任何用户困扰，都可以用“五问”快速定位：第一，我把自己放进了哪些身份和角色？第二，谁的规范正在评价我？第三，我所在的家庭、学校、职场或社群怎样分配资源和权力？第四，有没有标签或污名正在缩小我的选择？第五，在现有结构里，我能争取什么支持、调整什么边界、改变什么互动？
成长提示：把问题放回场域，会让助人语言更温和也更有力量。它不说“都是你的错”，也不说“你什么都不能做”，而是帮助用户从孤立个体回到关系网络，再从关系网络中找到下一步。 使用提醒：用于App问答时，先共情用户的现实感受，再把问题放回关系、规范、资源和制度条件中，最后给出一两个可执行的小步骤。', '["社会学助人", "场域视角", "关系制度", "去羞耻", "App问答框架", "结构与行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 466, now()),
(100467, '把个人困境放回结构中看：少一点自责，多一点可行动的理解', '核心理解：社会分层不是简单的“有人富、有人穷”，而是资源、声望、权力和机会被制度化地分配到不同位置。一个人的心理压力、健康、寿命、受教育机会和可选择的生活方式，都会受到这种位置影响。
关系启发：当自己或伴侣陷入失业、债务、低收入、住房不稳、教育受限等处境时，如果只用“你不够努力”“我太差劲”解释，很容易制造羞耻、怨怼和防御。更成熟的看法是同时看三层：我能做什么、身边有哪些资源、外部结构正在给我什么限制。
练习提示：把困扰写成三栏：结构压力（收入、时间、家庭责任、地域、健康）、可控小步（今天能完成的一个动作）、可调用支持（朋友、机构、专业服务、社区资源）。这样既不否认个人责任，也不把全部重量压在自尊上。
App端使用：这条适合放在“停止过度自责”“理解伴侣压力”的场景。它要传达的不是受害者身份，而是一种双焦点能力：既看见结构限制，也保留下一步行动。用户可以被邀请写下：哪些困难不是我一个人造成的，哪些部分仍可由我今天启动。
适用边界：条目不鼓励把所有问题外包给社会，也不鼓励对立；它强调把责任放回合适层级，让用户既能保护自尊，也能恢复行动感。', '["社会分层", "结构压力", "自责", "自尊", "心理教育", "生活机会"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 467, now()),
(100468, '不平等不只收入：基本生活、健康和公共声音都会进入情绪', '核心理解：收入和财富只是可见部分，真正进入日常心理的，还包括食物、住房、医疗保健、安全环境、交通、教育、公共服务和表达利益的机会。基本必需品价格、补贴制度和医疗分配方式不同，会让同样收入的人承受完全不同的压力。
关系启发：很多焦虑、易怒、拖延和亲密关系冲突，并不是单纯情绪管理差，而是长期资源紧张造成的心理带宽不足。一个家庭若总在为房租、看病、孩子教育或父母照护作选择，伴侣之间容易把资源不足误读为“不在乎我”“不负责任”。
练习提示：讨论冲突前先问：这件事背后有没有基本需求没有被满足？是钱不够、时间不够、健康资源不够，还是信息和公共支持不够？先承认现实压力，再谈分工与沟通，能显著降低互相指责。
App端使用：可用于金钱焦虑、伴侣财务争吵、照护压力和健康焦虑模块。引导语可以是：先确认基本需求有没有缺口，再谈情绪技巧。若底层需求持续未满足，冥想、沟通话术和时间管理只能缓解表层，仍需要实际资源、制度信息和社会支持介入。
适用边界：若用户处在急性危机，如断供、无家可归、医疗中断，应优先链接现实援助；心理教育只作为稳定情绪和组织求助的辅助。', '["不平等", "基本需求", "健康资源", "安全感", "情绪压力", "关系冲突"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 468, now()),
(100469, '先赋与自致：努力有价值，但起点并不相同', '核心理解：书中区分“先赋”和“自致”。先赋是出生阶级、性别、族群、家庭资源等个人无法选择的条件；自致是能力、学习、勤奋、选择和成就。现代社会常强调自致，但多数人的位置其实由两者共同塑造。
心理启发：理解先赋，不是为放弃找理由，而是减少有毒比较。一个人在更少安全感、更少教育支持、更少人脉和更高家庭责任下前进，本来就需要消耗更多能量。把自己和资源条件完全不同的人比较，容易损伤自尊，也容易把愤怒投向家人或伴侣。
练习提示：评估目标时同时写下“我能训练的能力”和“我需要补齐的条件”。把努力从证明自我价值，转向建设条件：补证书、找导师、扩大信息源、降低不必要消耗。努力仍然重要，但它需要被放在真实起点上设计。
App端使用：适合在比较心、成就焦虑和亲子期待主题中使用。它帮助用户把“别人能做到为什么我不能”改写为“我的起点、负担和资源组合是什么”。这会让目标更公平，也让亲密关系中的鼓励从施压变成共同建设条件。
适用边界：它不是否定努力，而是帮助用户选择更聪明的努力顺序：先补关键条件，再提高执行强度，避免用意志力硬扛结构差距。', '["先赋", "自致", "机会", "自我评价", "成长", "公平感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 469, now()),
(100470, '社会流动：向上不是个人意志的直线，而是教育、职业结构与支持网络的合力', '核心理解：社会流动研究关心一个人相对父母位置是上升、下降还是停留原位；地位获得研究进一步追问为什么会这样。书中梳理的模型显示，父母教育、父母职业、家庭社会经济地位，会通过教育机会、抱负、同辈关系和初职影响后来的职业位置；同时，职业结构本身也会改变流动空间。
关系启发：当家庭成员期待孩子“必须翻身”、伴侣期待对方“赶快成功”时，若忽略教育、行业、地域和中等收入岗位变化，就容易把结构性困难变成羞辱。更好的方式是一起画机会地图：现在有哪些门槛、哪些证书有用、哪些行业在扩张、谁能提供信息。
练习提示：把目标拆成四类资源：技能、证书、信息、人际支持。每类只选一个最小行动，而不是用一句“我要逆袭”承担全部压力。
App端使用：可设计为“机会地图”工具。用户选择一个目标后，系统提示其填写教育门槛、行业门槛、经济缓冲、推荐关系和可替代路径。这样能把抽象成功学转成路径规划，也帮助家庭成员从催促结果转向支持过程。
适用边界：不要把流动困难解释成命运注定。即使大结构有限，具体行业、城市、证书、人脉和时间窗口仍会形成可操作的微机会。', '["社会流动", "地位获得", "教育", "职业", "家庭背景", "支持网络"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 470, now()),
(100471, '阶级经验会进入自尊、品味和亲密关系：差异不等于高低', '核心理解：阶级地位不只影响收入，也会影响幸福感、自尊、工作满意度、说话方式、衣着品味、居住区、休闲方式和对教育的熟悉程度。书中把这些称为阶级亚文化和生活方式：它们多是不同资源与经历长期形成的差异，不应被简单评判为谁更高级。
关系启发：伴侣或姻亲之间常因消费观、礼仪、表达方式、孩子教育、职业选择发生摩擦。表面上是在争“你懂不懂规矩”“你太虚荣/太寒酸”，底层可能是不同阶级经验对安全感的理解不同：有人用储蓄抵御风险，有人用体面避免被轻视，有人用教育投资换未来机会。
练习提示：遇到差异先翻译成经历问题：这个习惯曾经保护过对方什么？它满足的是尊严、安全、归属还是未来感？先理解功能，再协商边界。
App端使用：适合跨阶层伴侣、婆媳/姻亲冲突、消费观差异和羞耻感主题。提醒用户：对方的品味和表达方式不是人格高低，而是生活史的痕迹。真正要协商的是共同生活的预算、尊重、边界和孩子教育，而不是赢得谁更“正确”。
适用边界：理解差异不等于纵容伤害。如果品味差异演变为羞辱、控制或经济压迫，仍需要清晰边界和具体协议来保护双方尊严。', '["阶级亚文化", "自尊", "生活方式", "关系冲突", "尊重", "家庭沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 471, now()),
(100472, '资源集中与社交网络：机会常在关系网络中流动', '核心理解：位于分层体系顶端的人并不只是个人收入高，他们常通过学校、俱乐部、董事会、政策机构、投资机构和社会纽带形成信息与机会网络。书中并不把这解释成简单阴谋，而是强调社会结构会让某些群体更容易共享信息、形成共识并影响重要决策。
成长启发：对普通个体来说，这个视角提醒我们：机会往往不仅来自“我足够好”，也来自谁知道机会、谁愿意推荐、谁能解释规则。缺少网络并不说明你能力差，只说明你需要把“建立社会资本”当作真实任务。
练习提示：每月维护三类弱连接：一个行业信息源、一个可请教的前辈、一个能互相支持的同伴。关系不是攀附，而是稳定、互惠、可信的连接。看见网络的力量，可以减少孤军奋战式自责。
App端使用：可用于职业成长、人脉焦虑和自我价值感模块。它让用户把建立连接看作技能，而非讨好。建议从低压力连接开始：请教一个问题、分享一条有用信息、参加一次同业活动、维护一次旧关系。长期看，稳定可信比短期套近乎更能转化为机会。
适用边界：建立网络应避免功利操控。App可强调互惠、透明、守信和长期贡献，帮助用户在尊重他人自主性的基础上扩展机会。', '["资源网络", "社会资本", "权力", "机会", "职业成长", "信息差"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 472, now()),
(100473, '贫困不是人格缺陷：环境压力会塑造选择', '核心理解：书中梳理多种贫困理论，特别批评把贫困简单归咎于懒惰、低自控或道德失败的看法。贫困环境论提醒我们，许多看似“短视”的选择，是人在不稳定工作、住房、治安、家庭支持和福利不足中形成的现实适应；结构论进一步强调政治经济力量会制造并维持贫困。
心理启发：当一个人长期处于危机中，延迟满足未必带来回报，计划未来也会变得困难。此时最需要的不是训诫，而是降低危机密度：稳定住所、食物、医疗、照护、收入和可预期的日程。
关系启发：家庭里若有人反复借钱、失业或无法规划，先区分“能力问题、资源问题、创伤问题、环境问题”。道德审判通常只会加深羞耻；更有效的是共同设立小边界、小支持和可验证的下一步。
App端使用：适合低谷期、债务压力、求职挫败和家庭反复冲突。系统可引导用户先做“危机降噪”：今天先保障睡眠、食物、账单优先级、必要求助和安全边界。只有当生活稍微稳定，反思、规划和习惯改变才更可能真正发生。
适用边界：理解贫困压力不等于取消边界。亲友提供支持时也应设置金额、期限和责任分工，以免救助关系变成新的消耗。', '["贫困", "环境压力", "结构因素", "羞耻", "自我同情", "行为理解"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 473, now()),
(100474, '家庭压力的交叉叠加：阶级、性别和族群位置会一起作用', '核心理解：家庭压力往往不是单一来源。第10章提醒我们，许多服务家庭、照顾亲属、维系亲友网络的情感工作和亲情工作长期不被当作生产性工作，却深刻影响女性的财富和地位。第11章进一步显示，族群、性别、阶级、家庭结构和福利制度会叠加影响收入与教育机会。
关系启发：伴侣冲突中常见一句话是“你怎么什么都做不好”。但如果一个人同时承担赚钱、育儿、老人照护、亲戚协调、情绪安抚和身份歧视压力，问题就不只是态度。看见交叉压力，可以把攻击改成盘点：哪些劳动被看见了，哪些责任可以重分配，哪些外部支持可以引入。
练习提示：做一张家庭劳动清单，包含有偿劳动、家务、照护、情绪安抚、亲属联络、风险管理。先让隐形劳动可见，再谈公平。
App端使用：可在伴侣分工、女性压力、单亲家庭和照护者疲惫主题中使用。用户可被邀请区分三种劳动：赚钱的劳动、维持家庭运转的劳动、稳定关系气氛的劳动。很多冲突降温的第一步，不是讲道理，而是让长期被默认的劳动获得命名和感谢。
适用边界：看见交叉压力不是为了比较谁更苦，而是为了找到更公平的分工和更准确的支持，让家庭从互相指责转向共同承压。', '["家庭压力", "交叉压力", "性别分层", "族群不平等", "照护", "隐形劳动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 474, now()),
(100475, '冲突的合法化：人会把不公平解释成“本来如此”', '核心理解：合法化过程解释的是：为什么人们会接受自己得到更少资源、较低地位或不对等权威。书中从微观层面讨论行为、自我概念、信念体系如何被群体力量塑造，也讨论分配正义准则：人们常用贡献、需要、资格、传统或机会平等来判断谁该得到什么。
心理启发：合法化会进入自我评价。一个人可能把长期低回报解释成“我不配”，把不合理分工解释成“我天生就该忍”，把关系里的控制解释成“对方更懂”。这会削弱愤怒的边界功能，也会让冲突长期潜伏。
练习提示：遇到不公平感时，不急着判定谁坏，先问四个问题：分配规则是什么？它服务于需要、贡献、权力还是习惯？谁参与制定？有没有重新协商的空间？这样能把抱怨变成可谈判的规则。
App端使用：适合公平感受伤、职场委屈和家庭权力不对等场景。它可以帮助用户把“我是不是太敏感”改为“现在运行的是哪套规则”。若规则不可谈，重点是保护边界；若规则可谈，重点是把需要和贡献说清楚，并提出可执行的替代安排。
适用边界：识别合法化不等于鼓动对抗。很多场景可以通过澄清规则、重新约定和第三方协助解决；只有持续压迫时才需要更强边界。', '["合法化", "公平感", "自责", "认知框架", "边界", "冲突降温"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 475, now()),
(100476, '比较视角：制度不同，压力和关系也会不同', '核心理解：同样是工业社会，不同制度会给普通人完全不同的安全感。书中比较美国、日本和德国：日本的年龄排序、群体关系和企业安排影响晋升与退休；德国的工会、监事会和工作委员会让工人在裁员、培训、工时、工资等事项上拥有更多协商位置；美国则更强调市场竞争和个人责任。
心理启发：如果只用一种社会的成功叙事解释所有人，就会把制度差异变成个人羞耻。工作安全、福利、医疗、工时和工人发言权不同，会直接影响家庭时间、亲密关系耐心、育儿压力和未来感。
练习提示：面对职业焦虑时，除了问“我够不够强”，也问“我的行业规则是什么、组织有没有协商渠道、我能否和同事共同提出可行方案”。制度视角不是抱怨，而是帮助你找到更现实的杠杆。
App端使用：可用于职场压力、加班争吵和安全感主题。它提醒用户把个人困境与组织规则相连：有没有申诉渠道、协商空间、同伴支持、福利政策和法律信息。亲密关系中也可借鉴“共同协商”思路，把伴侣视为同队，而不是彼此审判的管理者。
适用边界：制度比较不是照搬他国经验，而是训练用户看见规则可以被设计。这个视角能降低自责，并启发更现实的组织沟通。', '["比较视角", "制度安排", "工作安全", "福利", "家庭关系", "协商"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 476, now()),
(100477, '全球分层：个人选择常被国家与产业位置限定', '核心理解：世界体系视角提醒我们，贫穷国家与富裕国家的差距不是简单由个人勤奋解释，也不总能靠经济增长自动解决。书中指出，增长是否均衡、土地和收入分配、跨国公司投资方式、国家在全球产业链中的位置，都会决定普通人的工作选择和生活风险。
心理启发：当我们看见全球贫困、血汗工厂或移民劳动时，容易在同情、内疚、愤怒和无力之间摇摆。更有帮助的态度是现实感：承认很多人的选择空间很窄，同时避免用舒适位置上的道德想象替他们下判断。
练习提示：把全球议题转化为可承受行动：了解商品来源、支持更公平的劳动标准、在消费中做小比例调整、对移民和低薪劳动者保持尊重。结构很大，但个人仍可选择不把贫困解释成低价值。
App端使用：适合社会议题带来的无力感、消费内疚和移民/低薪劳动者理解模块。它鼓励用户在现实范围内行动：尊重服务者、减少刻板评价、支持可信公益或劳工信息、做可持续消费选择。重点不是用宏大问题压垮自己，而是练习有边界的责任感。
适用边界：全球视角容易带来宏大无力感，因此条目应始终落回可做的小选择和尊重他人的态度，避免把用户推向愤怒或道德疲劳。', '["全球化", "世界体系", "贫困", "产业链", "现实感", "消费伦理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 477, now()),
(100478, '成人自我不是冷静人设，而是现场数据处理', '伯恩的“成人自我”不是年龄标签，也不是没有情绪，而是把当下事实、可能性和后果重新放到桌面上的功能。父母自我负责内化规则与自动反应，儿童自我带来自发、创造和乐趣；沟通卡住时，目标不是消灭父母/儿童，而是让成人自我重新协调：现在发生了什么？证据是什么？我有哪些选择？', '["沟通分析", "成人自我", "父母自我", "儿童自我", "事实核对", "冲突降温"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 478, now()),
(100479, '交错沟通：小事谈崩，是回应了对方没发出的那句话', '许多争吵不是因为问题本身，而是刺激和回应来自不同自我状态：一句成人式询问，被对方听成父母式指责，于是儿童自我反击。App 可引导用户分两层复盘：原话在问什么？我实际回应的是哪种旧感受或权威形象？修复方式是先承认被触发，再把话题拉回成人-成人的事实与请求。', '["沟通分析", "交错沟通", "成人状态", "触发反应", "关系修复", "事实请求"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 479, now()),
(100480, '隐蔽沟通：表面在谈事，底层在发出角色邀请', '隐蔽沟通同时跑两个频道：社会层面像理性谈事，心理层面却在邀请对方证明、屈从、反抗、被照顾或被诱惑。识别游戏时不要只看句子字面，要问“这句话想让对方扮演什么角色”。当底层邀请决定结局时，表面合约再合理也会走向可预测冲突。', '["隐蔽沟通", "社会层面", "心理层面", "角色邀请", "人际游戏", "沟通分析"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 480, now()),
(100481, '六种获益：游戏不只让人吵赢，还帮人维持旧平衡', '人际游戏顽固，是因为它一次性提供多种收益：缓解内在紧张、避开焦虑或亲密、在伴侣间固定一句台词、在外部圈子获得谈资、获得强烈安抚，以及再次确认“我/你/世界就是这样”的存在立场。做关系复盘时，与其只问“谁错了”，不如问“这场戏替我们保住了什么”。', '["隐藏收益", "六种获益", "心理地位", "安抚", "亲密回避", "关系复盘"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 481, now()),
(100482, '“要不是因为你”：抱怨有时是在外包自己的恐惧', '这个游戏里，限制者表面上是压迫者，抱怨者表面上是受害者；但限制也可能替抱怨者挡住自己害怕面对的场景。真正的退出不是继续辩谁阻碍谁，而是把“都是你不让我”改成“如果没人拦我，我其实怕什么”。对方若给出许可，隐藏恐惧会浮出来，游戏也失去燃料。', '["要不是因为你", "IWFY", "恐惧回避", "婚姻互动", "受害者位置", "退出游戏"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 482, now()),
(100483, '“看你都让我做了什么”：把过激反应包装成被迫', '当一个人把摔东西、失误、糟糕决策归咎于“你打扰我/你让我这样”，他可能正在用别人的靠近来保护自己的孤立，或把责任推给代做决定的人。App 可提示：对方确实打断了你，但反应仍属于你；下一步不是追责，而是明确空间、权限和谁来承担决定。', '["看你都让我做了什么", "SWYMD", "责任边界", "孤立防御", "婚姻游戏", "职场沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 483, now()),
(100484, '“可逮着你了”：用小错误兑换正当愤怒', '有些人会长时间等待他人犯错，一旦抓到细节，就把局部失误扩大成对整个人的审判。表面是维权或讲原则，底层收益是获得“我有理由发怒”的许可。应对这类游戏，要把规则、费用、边界和例外提前写清；真有误差时只处理误差，不进入人格清算。', '["可逮着你了", "NIGYSOB", "正当愤怒", "人格审判", "契约边界", "冲突降温"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 484, now()),
(100485, '“踢我吧”：不断招来惩罚，以证明命运总会如此', '“踢我吧”不是单纯倒霉，而是用挑衅、越界或自我破坏把别人推到不得不拒绝、驱逐或惩罚的位置，然后再说“为什么总是我”。识别点是结局反复相似：被赶走、被抛弃、被解雇。退出时要少接“踢人”的角色，改用清晰后果、有限帮助和可执行边界。', '["踢我吧", "Kick Me", "自我破坏", "惩罚循环", "边界", "为什么总是我"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 485, now()),
(100486, '“你为什么不——是的，但是”：求建议有时是在赢得无解', '当用户不断索要建议又逐条否定时，核心未必是找方法，而是证明“没有任何办法能帮我”。这种游戏用理性讨论填满无结构时间，也避免屈从和暴露无助。回应时不要急着提供第十个方案，可转向：“你已经试过/否定了哪些？如果暂时没有方案，你想让我陪你确认什么？”', '["你为什么不", "是的但是", "YDYB", "建议拒绝", "助人边界", "无解证明"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 486, now()),
(100487, '“我只是想帮你”：助人若带隐蔽动机会让对方必须失败', '真正的帮助会公开说明能力、边界、费用和合作方式；“我只是想帮你”的游戏则需要对方不领情，以证明“人都忘恩负义”。助人者越急着给建议、越不能承受对方没照做，越容易把对方固定成失败者。App 在助人场景中应提醒：先问对方要什么帮助，避免用建议换控制感。', '["我只是想帮你", "ITHY", "助人边界", "控制感", "来访者自主", "职业助人"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 487, now()),
(100488, '关系脚本：重复游戏会把偶发冲突排练成命运', '书中把常玩游戏放进“人生脚本”框架：孩子不仅学会礼貌、程序和消遣，也从家庭情感动力中学会怎样获得关注、怎样失败、怎样证明世界。一个人最熟悉的游戏，会影响他如何使用机会，并把婚姻、事业甚至结局推向熟悉方向。识别脚本的入口，是追问“这场戏最早像谁教会我的？”', '["关系脚本", "人生脚本", "家庭动力", "儿童原型", "重复冲突", "命运感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 488, now()),
(100489, '自主的三件事：看见此刻、自由选择、无游戏地坦率', '超越游戏不是永远理智，而是恢复三种能力：觉察让人回到此时此地，不只按旧教条看世界；自发性让人能选择表达父母、成人或儿童自我的感受；亲密则是没有隐藏交易的坦率接触。关系修复可据此设计三问：我现在看见了什么？我真正想表达什么？我能否不测试、不讽刺地说出来？', '["自主性", "觉察", "自发性", "亲密", "退出游戏", "真实表达"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 489, now()),
(100490, 'READ 四步：先把线索变成问题，再沟通核对', '线索假设：非语言观察不是“瞬间看穿”，而是把看见的表情、姿态、距离、声音和场景整理成可检验的问题。可以按 READ 四步使用：R 先像孩子一样审视事实，记录眉眼、手脚、语调、空间与时机；E 再看整体组合，哪些线索比其他线索更重要；A 回到基线、文化和自己的偏见，分析是否有误读；D 最后决定是记下、放慢、退出，还是开口询问。
核对沟通：把结论写成低确定性句子，例如“我注意到说到这里时，你声音变小、身体往后退，我不确定是累了、需要时间，还是这个话题有压力。我们要不要暂停一下，或换个方式谈？”这样既使用线索，也把解释权留给对方。', '["READ", "非语言线索", "核对沟通", "避免读心", "情境判断", "观察伦理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 490, now()),
(100491, '整体心情三维：能量、方向、焦点要一起看', '线索假设：一个动作本身很少足够，真正有用的是全身状态的组合。可以先问三件事：这个人整体能量是高还是低？能量有没有指向明确对象，还是分散漂移？焦点是在外部互动上，还是退回内在思绪里？高能量、方向集中、焦点向外，可能提示愤怒、兴奋或强烈推动；低能量、方向分散、焦点向内，可能提示困惑、疲惫或被某个念头困住。
核对沟通：不要说“你就是生气/心虚”，可以说“我感觉你现在整个人很用力，注意力好像都集中在这件事上。我理解成你很在意它，对吗？还是我误读了？”先核对情绪强度和关注点，再谈具体内容。', '["整体观察", "心情系统", "能量方向焦点", "情绪线索", "核对沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 491, now()),
(100492, '眉毛和前额：确认需求不等于撒谎证据', '线索假设：眉毛、前额常在认出别人、强调意思、寻求理解或请求认可时快速变化。挑眉可能是在说“我懂了”“你懂吗”，也可能是熟人相认的瞬间反应；缺少挑眉也未必是冷漠，可能是没认出、疲劳、文化习惯或刻意控制。把眉毛变化当作“对方可能在确认关系或确认理解”的线索，比把它当成心虚证据更稳妥。
核对沟通：适合用轻量确认句承接，例如“我看到你刚才好像在确认我有没有听懂。我的理解是……对吗？”或“我们是不是以前见过？我有点不确定。”这样让表情线索转成互相校准，而不是审问。', '["面部表情", "眉毛线索", "确认需求", "关系识别", "避免读心", "核对沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 492, now()),
(100493, '声音基线：语调变化提示压力，含义仍需确认', '线索假设：声音也是非语言信息。叹气、停顿、填补空白的口头声音、音调变尖、节奏加快或变慢，都可能提示压力、困惑、厌恶、悲伤、怀疑或努力维持礼貌。但声音变化只有在知道对方平时怎么说话时才更有价值；有人平常就语速快、声调高，也有人在低压力聊天里就常叹气。
核对沟通：先建立低压力基线，再谈敏感话题。可说“我不确定是不是听错了，刚才谈到这个请求时，你声音突然紧了一点。这个话题对你有压力吗？需要我说慢一点，还是你想先整理一下？”把语调当作照顾节奏的提醒，而不是“你说谎”的证据。', '["语调", "声音基线", "口头声音", "压力线索", "沟通节奏", "核对沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 493, now()),
(100494, '调适姿势：身体可能在释放压力，先给缓冲', '线索假设：搓手、揉脖子、抖腿、抓挠、打理自己、撕手皮、反复摸物品等，可能是调适姿势，也就是身体在转移能量、安抚压力或处理无聊。它们不自动等于欺骗、抗拒或不尊重；同一个动作也可能只是习惯、环境不适、身体瘙痒或等待太久。
核对沟通：看到调适姿势时，优先降低压力而不是提高质问强度。可以说“我注意到这个话题好像让人有点紧，我们要不要喝口水、放慢一点，或者先谈你最在意的部分？”如果对方说只是习惯，就尊重其解释；只有在同类场景反复出现时，再把它作为压力模式继续观察。', '["调适姿势", "压力释放", "身体安抚", "姿态观察", "低压力沟通", "情境核对"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 494, now()),
(100495, '阻隔与距离：先处理安全感，再处理观点', '线索假设：交叉手臂、半转身体、站到桌后、把包或文件放在中间、降低视线、后退、寻找出口，都可能是在建立安全距离。它们不一定表示讨厌你，也可能是空间太近、权力差距大、话题太私密、现场有旁人，或对方需要一点控制感。
核对沟通：不要逼近或追问“你为什么防备我”。先撤一点压力：“我们这个距离会不会太近？要不要坐远一点、把门打开，或晚点再谈？”当对方的身体不再忙着保护自己，语言沟通才更可能进入事实和需求。若你自己出现阻隔姿势，也可直接说明：“我抱臂是因为有点紧张，不是要拒绝你。”', '["阻隔姿势", "个人空间", "距离线索", "安全感", "冲突降温", "核对沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 495, now()),
(100496, '文化与微文化：先问这套关系规则是什么', '线索假设：同一个手势、距离、致意、眼神或拥抱，在不同文化、职业、家庭、伴侣关系中可能含义不同。长期关系本身也会形成微文化：伴侣间一个扬眉、朋友间一个玩笑、团队里一个沉默，可能有他们内部的历史和禁忌。外人若只按自己的规则翻译，很容易把礼貌看成疏离，或把习惯看成挑衅。
核对沟通：遇到不确定的动作，可直接把文化差异放到台面：“我可能按自己的习惯理解了。你们这里这样做通常代表什么？”在亲密关系里可问：“以前你这个表情我会理解成开玩笑，但今天我不确定。它现在代表什么？”先校准规则，再解释情绪。', '["文化差异", "微文化", "关系规则", "情境核对", "避免误读", "跨文化沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 496, now()),
(100497, '投射过滤：服饰、文身和步态先标记为未知', '线索假设：观察者很容易把自己的故事贴到别人身上。文身、衣着、妆容、步态、性别、年龄、职业或场所，都可能触发投射，让人以为“已经看清这个人”。更稳妥的做法是把第一反应降级为假设：我看见了什么事实？我自动补了什么剧情？还有哪些无害解释？
核对沟通：如果线索影响了互动，先承认不确定：“我可能有点按外表猜测你了，想确认一下……”或“我刚才看到你沉默，就脑补成不赞同；其实你当时是在想什么？”把投射说成自己的解释，而不是对方的问题，能减少羞辱和防御。', '["投射", "偏见校准", "服饰线索", "身体装饰", "避免读心", "事实解释分离"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 497, now()),
(100498, '公开冲突降温：保全面子比当场赢更重要', '线索假设：公开场合的争论会放大羞辱、地位威胁和旁观者压力。对方下巴抬高、声音变硬、动作更大、寻求同盟或盯住观众，可能不是单纯不讲理，而是在维护面子和群体位置。此时继续公开压迫，常会把分歧推向战斗姿态。
核对沟通：能私下谈就私下谈；必须当场回应时，先承认共同目标，再把分歧从人格降到事实：“这个点我们可能有不同资料，我不想让你在公开场合难堪。我们先确认目标，细节会后一起核对，可以吗？”冲突线索的用途是降温和保留退路，而不是当众拆穿。', '["冲突降温", "公开争论", "面子需求", "职场沟通", "群体压力", "核对沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 498, now()),
(100499, '高压请求：相似感和情绪诉求要先放慢', '线索假设：推销、募款、传教、亲友求助或恋爱追求都可能使用高压策略：先制造“我们是一边的”相似感，再把话题推到难以拒绝的道德或情感位置。你若感觉身体被卷入、来不及思考、很难说不，这本身就是压力线索；对方热情不必然是恶意，但需要核对真实需要和你的边界。
核对沟通：先问无压力问题，观察对方平常怎么说话、看哪里、如何回应，再决定。可以说“我愿意了解，但我需要慢一点。你具体希望我做什么？今天必须决定吗？如果我不答应，会有什么影响？”把模糊情绪诉求拆成事实、时间、选择和可拒绝请求。', '["高压沟通", "边界", "说不", "请求核对", "压力线索", "关系安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 499, now()),
(100500, '关系观察：长期关心比一次拥抱更有说明力', '线索假设：朋友还是泛泛之交，不能只看一次拥抱、一次热情或一次冷淡。有人把拥抱当亲近，有人觉得拥抱很怪；不同成长经历和微文化会让同一动作有不同意义。更值得观察的是长期稳定性：对方是否关心你过得好不好，是否记得重要处境，久别重逢后对待你的方式是否明显变化。
核对沟通：把关系判断变成可谈的期待：“我发现我们见面时很热络，但平时很少真正聊近况。我有点不确定我们对这段关系的期待是否一致。你怎么看？”这样既不因一个非语言动作定性关系，也给对方说明亲近方式的机会。', '["关系观察", "朋友关系", "微文化", "长期模式", "亲密距离", "核对沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 500, now()),
(100501, '亲密关系线索：用担忧核对期待，不用侦查定罪', '线索假设：承诺关系中的争吵常来自未说清的期待和权利。伴侣在敏感话题上眼神、声调、节奏、姿态或阻隔姿势改变，可能提示压力、隐瞒、羞耻、害怕冲突，也可能只是旧伤被触发。越亲近，越容易把过去经验投射到当下；因此线索只适合提醒你“这里需要温柔核对”，不适合变成侦查游戏。
核对沟通：用发自内心的担忧表达影响：“当我问到这件事时，我感觉我们都紧了。我不是想审你，而是这会影响我在关系里的安全感。你愿意告诉我发生了什么，或者我们先把彼此期待讲清楚吗？”目标是弄清期待、修复信任和决定下一步，而不是证明自己看穿了对方。', '["亲密关系", "期待核对", "信任修复", "语调姿态", "避免侦查", "冲突降温"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 501, now()),
(100502, '情绪不只在心里，也在关系场里', '当一个人说“我很难受”时，不要只问“我怎么了”，也要问：这个情绪指向谁、哪段关系、哪个群体位置或哪条规则？情绪常在社会结构中被点燃，也会反过来改变人对关系和环境的选择。', '["情绪社会学", "社会结构", "关系场", "情绪觉察", "归因"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 502, now()),
(100503, '被认可，才更容易对群体有归属感', '一个人对家庭、团队或组织的承诺，往往不是靠道理说服出来的，而是来自一次次“我在这里被看见、被奖励、能做好自己”的正性体验。反复被肯定，情绪会从具体关系扩展到对群体和制度的信任。', '["归属感", "社会承诺", "正性情感", "组织关系", "身份确认"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 503, now()),
(100504, '身份被否定时，情绪会比事情本身更大', '有些冲突看似只是一次批评、拒绝或误解，实际碰到的是“我是谁”。越接近核心自我或重要身份，没被承认时情绪越强；这时先处理身份受伤，再讨论事情对错，关系更容易降温。', '["身份评价", "自我证明", "核心自我", "冲突降温", "关系沟通"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 504, now()),
(100505, '羞愧是社会警报，不是整个人的判决', '羞愧常在“我没有达到规则、角色或期待”时出现，它能提醒人修正行为、修复关系。但如果把羞愧理解成“我整个人都不行”，痛苦会过强，反而更容易逃避、压抑或攻击。', '["羞愧", "羞耻", "社会规范", "自我价值", "关系修复"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 505, now()),
(100506, '愤怒有时是被压住的羞愧在找出口', '有些愤怒不是事件刚发生时的第一情绪，而是长期羞愧、失败感或不公平感被压下后的出口。若只处理“别发火”，会漏掉底层的“我没被尊重、没被承认、没被公平对待”。', '["愤怒", "羞愧", "防御机制", "外部归因", "不公平感"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 506, now()),
(100507, '亲密需要可预测的节奏和尊重', '亲密不是一直热烈，而是能预测对方、跟上彼此节奏，并感到对方忠诚、诚实、尊重自己。信任一旦缺位，恐惧和愤怒会升高，互动会变得躲闪、公式化甚至虚伪。', '["亲密关系", "信任", "节奏同步", "安全感", "关系互动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 507, now()),
(100508, '情绪劳动：被规则要求管理感受', '情绪劳动不是简单“忍一忍”，而是在角色、地位或关系规则要求下，努力表现出该有的感受、藏起不该有的感受。长期隐藏真实情绪会积累紧张，最终可能以爆发、羞愧或内疚回到关系里。', '["情绪劳动", "感受规则", "表达规则", "角色压力", "情绪压抑"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 508, now()),
(100509, '规范和权力会分配“谁可以怎样感觉”', '每个环境都在暗中规定：谁该自豪、谁该难过、谁能生气、谁不能挑战。当地位和权力不平等被包装成“应该如此”，低位者的悲伤、羞愧和愤怒就不只是个人情绪，也是位置带来的情绪负担。', '["规范与权力", "地位", "分层", "情绪规则", "社会评价"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 509, now()),
(100510, '关系交换不只算资源，也在交换情绪', '关系里交换的不只是钱、时间和帮助，也有被感谢、被公平对待、被尊重的情绪回报。一个人觉得“投入大于回报”时，愤怒和疏离会增加；当正性情绪被相对平等地分配，关系更容易形成团结。', '["情绪交换", "公平感", "互惠", "关系承诺", "资源分配"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 510, now()),
(100511, '修复仪式让关系从羞愧回到连接', '关系破裂后，承认尴尬或羞愧、道歉、重新定义情境，并不是客套，而是在重建互动规则。能承认羞愧时，关系有机会回到正性情绪；若继续压抑，羞愧更容易变成愤怒循环。', '["修复仪式", "关系修复", "羞愧", "愤怒循环", "互动规则"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 511, now()),
(100512, '角色转换：先借一个位置理解关系，不替对方下结论', '【核心观点】心理剧中的角色转换，不是让人“猜中”对方，而是暂时换一个观察位置，看见关系里还有哪些被自己忽略的感受、限制和需要。它的价值在于扩大角色目录：一个人不只被固定在受伤、指责、讨好或防御的位置上，也能试着理解另一端的经验。
【App 转化】适合做成低强度反思提示：如果我站到对方的位置，可能会看见什么？如果我再回到自己这里，我想保留什么边界、改变什么回应？
【边界提醒】不要要求用户代入强刺激人物或重演创伤场景；更适合用于日常误会、亲密关系沟通、团队协作等可承载情境。', '["心理剧", "角色转换", "换位理解", "关系视角", "边界感", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 512, now()),
(100513, '替身：把说不出口的内在声音变成可核对的句子', '【核心观点】替身的重点不是替用户解释人生，而是把可能被压住、说不清或只停留在身体里的内容，先试探性地翻译成一句话，再交还给本人确认、修改或拒绝。好的替身像温和的“可能性草稿”，不是权威判决。
【App 转化】可设计为“我心里可能有一部分在说……”的自我核对句，帮助用户从混乱情绪中分辨多个声音：想靠近的一部分、想逃开的一部分、想保护边界的一部分。
【边界提醒】替身提示应保持低确定性，避免给用户灌输结论；尤其不要把复杂关系直接解释成单一创伤或病理原因。', '["心理剧", "替身", "内在声音", "情绪命名", "自我核对", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 513, now()),
(100514, '镜映：从旁边看见自己的姿态、语气和关系信号', '【核心观点】镜映让人暂时离开“我正在经历”的位置，改用旁观角度看见自己的表情、姿态、语气、距离和重复模式。它不是羞辱性的曝光，而是把自动反应变成可观察、可调整的材料。
【App 转化】可转成轻量问题：如果有一位友善观察者看见刚才的我，他会注意到什么？我的身体在说“靠近”“防御”“求助”还是“不要碰我”？
【边界提醒】镜映不应制造审判感。App 文案要强调“观察不是定罪”，并邀请用户核对而不是贴标签。', '["心理剧", "镜映", "身体觉察", "非语言沟通", "自我观察", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 514, now()),
(100515, '此时此地：把探索落在现在能承载的一小步', '【核心观点】心理剧重视此时此地，因为改变不是只在解释过去，而是在当下看见身体、关系和选择如何发生。过去、未来和想象都可以被带入，但最后需要回到现在：我此刻在哪里？我能做一个什么小回应？
【App 转化】适合用于对话收束：现在我身体最明显的感觉是什么？我和这件事之间需要多大距离？接下来一天里，一个低风险、可执行的小行动是什么？
【边界提醒】不要把用户一路带向深层回忆却不收束；每次内容都应有回到现实、回到身体、回到当下生活的落点。', '["心理剧", "此时此地", "当下觉察", "现实落地", "小行动", "情绪安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 515, now()),
(100516, '行动化表达：让内在经验可见，但在 App 里要轻量化', '【核心观点】心理剧把许多说不清的经验转成行动语言：站远一点、转向、放一个物件、说一句未说完的话，都会让内在关系变得可见。行动化表达的价值，是让人从“脑中反复想”进入“我看见它如何发生”。
【App 转化】更适合做成低刺激练习：用一个词、一个姿势、一个安全物件或一张纸的位置，标记“我”和“这件事”的距离。重点是观察，不是强迫情绪爆发。
【边界提醒】不要设计高强度重演、喊叫、对抗或身体接触任务；线上产品应优先采用象征、书写、想象距离等温和形式。', '["心理剧", "行动化表达", "行动外化", "象征表达", "身心连接", "练习边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 516, now()),
(100517, '行动领悟：不是想明白才改变，而是在小体验后再理解', '【核心观点】行动领悟强调“从做中学”：当一个人亲身体验不同角色、距离或回应方式，理解会带有身体感和关系感，比单纯听道理更容易转化为生活中的选择。领悟不是终点，能否回到现实中试一小步，才是关键。
【App 转化】适合在练习后追加三问：刚才我看见了什么？这和我平常的模式有什么不同？我愿意在真实生活中尝试哪一个很小、很安全的回应？
【边界提醒】不要把体验包装成顿悟承诺；App 只提供反思与微行动提示，复杂关系仍需要现实沟通与持续练习。', '["心理剧", "行动领悟", "体验式学习", "从做中学", "微行动", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 517, now()),
(100518, '共创与关系修复：心理剧不是独白，而是关系中的新回应', '【核心观点】心理剧的关系观强调共创：主角、带领者、团体和辅助角色共同生成一个可探索的场。关系修复也不是只把话说漂亮，而是在安全互动中看见自己如何影响他人、如何被他人回应，并把新经验带回生活。
【App 转化】可用于设计关系类知识：冲突不是单人故障，而是互动模式；修复可以从承认影响、听见对方位置、选择新的回应动作开始。
【边界提醒】不要让用户在 App 内单方面“完成和解”。真正的关系修复需要对方同意、现实边界和可持续行动。', '["心理剧", "共创", "会心", "关系修复", "互动模式", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 518, now()),
(100519, '情绪安全：接纳、支持和面质要同时被看见', '【核心观点】心理剧可以触及强情绪，但安全不是靠推动，而是靠接纳、支持、清楚节奏和非评断氛围。面质只有在足够安全时才有意义；没有支持的面质容易变成压力，没有面质的支持也可能停在安慰。
【App 转化】后台知识可提醒：所有情绪类内容先给容纳，再给观察，最后才给选择。用户可以被邀请命名感受、确认需要、暂停或求助，而不是被催促“释放出来”。
【边界提醒】不要把哭、崩溃、宣泄当成进步指标；App 端应优先提供稳定化、节奏调节和退出选项。', '["心理剧", "情绪安全", "接纳", "支持与面质", "节奏调节", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 519, now()),
(100520, '练习边界：保密、同意、身体距离和伦理先于技巧', '【核心观点】心理剧不是“有技巧就能做”，而是先有场域边界：空间是否私密、规则是否清楚、身体距离是否被尊重、参与者是否知道可以拒绝或暂停。边界越清楚，行动表达才越可能安全。
【App 转化】任何心理剧元素进入产品，都应改写为低风险、可退出、无需身体接触的版本；涉及他人关系时，强调现实同意与隐私，不鼓励录音、曝光或逼迫对话。
【边界提醒】线上知识库不应提供治疗型导剧脚本，只保留心理教育、观察问题和温和自助提示。', '["心理剧", "练习边界", "保密", "身体距离", "同意", "伦理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 520, now()),
(100521, '结束与回到自己：每次探索都要有收束和整合', '【核心观点】心理剧不是把人带进角色就结束，而是需要从角色、场景和情绪中回到自己。好的结束会帮助人确认：我现在是我，不是刚才那个角色；我回到现实；我知道接下来怎么照顾自己。
【App 转化】所有练习都应有收束段：看见周围三样东西，感受脚踩地面，写下一个此刻能做的普通行动，或给自己一句回到现实的话。
【边界提醒】不要在用户高情绪处突然结束内容，也不要把复杂体验留给用户独自消化；收束、整合、回到日常是必要组成部分。', '["心理剧", "结束", "整合", "回到自己", "落地练习", "情绪安全"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 521, now()),
(100522, '暖身：轻度、游戏性和信任感是进入探索的缓冲区', '【核心观点】暖身不是无关紧要的开场游戏，而是让身体、注意力和关系慢慢进入状态。对很多人来说，刚开始的不愿意、不确定或想退后，不一定是问题，而可能是安全系统在观察环境。
【App 转化】心理剧式内容前可以先给低门槛过渡：选择一个今天的情绪词、给当前能量打分、决定本次只做观察还是做一点表达。让用户有选择权，本身就是安全感的一部分。
【边界提醒】不要用“突破”“挑战”“立刻进入深处”作为引导语；温和、可停、可选择，比强行打开更适合 App 场景。', '["心理剧", "暖身", "信任感", "游戏性", "选择权", "低刺激练习"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 522, now()),
(100523, '象征与物件：用距离感承载内容，而不是直接冲进情绪', '【核心观点】心理剧不一定要直接说出最痛的部分，也可以让物件、椅子、纸张或象征角色先承载一部分内容。象征的好处是保留距离：用户既能看见内在关系，又不必一次性完全暴露自己。
【App 转化】可设计“把这件事放在纸上/屏幕外一个位置”的提示，让用户调节距离：太近就移远一点，太远就只观察轮廓。目标是建立可承载的关系，而不是制造强烈情绪。
【边界提醒】避免要求用户破坏真实物品、进行仪式化告别或重演高压情境；App 内只使用温和、可撤回、无损害的象征动作。', '["心理剧", "象征表达", "物件外化", "距离感", "情绪安全", "练习边界"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 523, now()),
(100524, '实用乐观主义八支柱：把高能量状态拆成可练习的系统', '高能量状态不是持续兴奋，也不是用积极想法覆盖现实，而是把心态、技能和行动组合成可练习的系统。App 端可把“我没状态”拆成八个可调节入口：人生目标、处理情绪、解决问题、自我价值感、自我效能感、活在当下、人际关系、健康习惯。每次只问“现在最缺哪一根支柱”，再给一个小练习，而不是直接鼓励用户硬撑。', '["高能量状态", "实用乐观主义", "状态管理", "行动框架"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 524, now()),
(100525, '高能量状态自检：先定位哪根支柱最需要补强', '状态评估适合做成低压力“生活自拍照”，目的不是诊断，而是发现精力应该集中在哪里。书中的 40 项自检分别映射八支柱：1-5 看目标，6-10 看情绪，11-15 看问题解决，16-20 看自我价值，21-25 看自我效能，26-30 看当下注意力，31-35 看关系，36-40 看健康习惯。App 可用“是/否/最近不确定”快速筛出当前最该补强的 1-2 个领域。', '["状态自检", "能量评估", "八支柱", "App问诊"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 525, now()),
(100526, '目标加快乐：用 AIM 把愿景变成行动路线', '目标感需要和快乐、心流一起设计；只追求有意义但长期牺牲快乐，容易耗竭。AIM 路线可用于目标澄清：承认自己如何走到现在，识别哪些事有效、哪些带来意义和快乐，再采取小步前进。App 可引导用户写下“我想去哪里、为什么值得、这周 15 分钟能做什么”，并提醒目标可以坚定，路径要允许调整。', '["人生目标", "目标行动", "心流", "行动闭环"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 526, now()),
(100527, '情绪四步法：命名、认领、驯服、重构', '情绪处理不是压下去，也不是立刻发泄，而是先给情绪留出可观察空间。可执行流程是：命名具体情绪，认领触发情境与身体反应，驯服情绪（用同情、矫正、平静、连接的应对方式，或呼吸、身体扫描、担忧日记），最后重构视角，寻找更真实、更有帮助的解释。适合 App 在用户焦虑、愤怒、委屈时提供分步卡片。', '["情绪处理", "情绪调节", "压力恢复", "认知重构"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 527, now()),
(100528, '压力恢复的 5R：先评估参与方式，再补给和求助', '遇到高情绪张力的问题时，不必默认硬扛或逃避。5R 可作为压力恢复与问题解决流程：重新评估是否参与、如何参与；给身体和情感储备加油；向可靠对象寻求信息或情绪支持；提醒自己已有能力和过往经验；在无法改变事实时重新评价与它的关系。必要时可短暂转移注意力，但不能把转移当成长期逃避。', '["问题解决", "5R策略", "恢复力", "压力管理"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 528, now()),
(100529, '身体信号也是状态数据：把症状纳入压力恢复，而非只靠意志硬撑', '身体状态可以反映心理负荷：睡眠不足、紧张性头痛、胃部不适、心跳加速、下巴紧绷、腿软或持续疲惫，都可能提示压力已超过恢复能力。App 不应把这些当作“意志力差”，而应引导用户记录睡眠、饮食、情绪、工作负荷和身体感受的关联；先排除必要的健康问题，再用休息、情绪处理、求助和任务降载恢复基线。', '["身体状态", "压力信号", "恢复基线", "身心连接"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 529, now()),
(100530, '稳定自我价值：GRACE 不是自夸，而是现实而友善地校准自己', '稳定自我价值不是夸大自己，而是对自己保持内在、准确、友善且鼓励成长的认识。GRACE 可做成自我校准练习：感恩美好，承认现实，接受不完美，自我关怀，共情他人。它帮助用户把“我做错了”与“我很糟糕”分开，既能承担责任，也能休息、求助、继续尝试。', '["自我价值感", "GRACE", "自我关怀", "恢复力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 530, now()),
(100531, '自我效能循环：小经验、正向设想和反馈让“我能做”变可靠', '自我效能感来自可重复的小成功，而不是空喊自信。做法是先设计低风险、小步的亲身经验，再用正向设想、导师反馈和进展记录强化“我能学会”。当用户拖延或焦虑时，App 可提示“行动先于动机”：先做 5-15 分钟可完成版本，再记录完成后的情绪、能力证据和下一步。', '["自我效能感", "小步行动", "正向反馈", "行为激活"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 531, now()),
(100532, '注意力主权：识别过去、未来和比较三种认知陷阱', '时间和注意力是有限资源，需要被保护。注意力被劫持时，常落入三类陷阱：困于过去的反刍和后悔，困于未来的灾难化和不确定焦虑，困于比较的自卑、追赶和错失恐惧。App 可先标记用户属于哪一类，再给当下觉知、品味练习、社交媒体边界或纸笔记录，把注意力从自动滚动中拿回来。', '["注意力", "当下觉知", "反刍", "FOMO"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 532, now()),
(100533, '克服心理疲劳：休息要分身体、感官和社交情绪三类', '心理疲劳不一定靠睡一觉就解决，可能来自选择过载、睡眠不足、噪声、屏幕刺激或关系消耗。恢复时可分三类安排：身体休息（睡眠、小睡、伸展、按摩），精神/感官休息（关掉噪声、减少通知、绿洲时刻），社交情绪休息（独处和滋养性关系之间取得平衡）。App 可根据用户疲劳来源推荐对应休息，而不是笼统建议“早点睡”。', '["心理疲劳", "休息类型", "注意力恢复", "可持续行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 533, now()),
(100534, '从意图到自动化：让好习惯低门槛、坏习惯高门槛', '可持续行动依赖环境设计，而不是单靠意志力。习惯更容易坚持，通常因为它便利、有趣、可得、愉快。做法是明确意图，细化目标，制定活动计划，安排高能时间，从小事做起，设置问责与奖励；同时让不想要的行为更难接近、更少提示。遇到挫折时暂停、复盘触发因素、减少伤害，再恢复下一小步。', '["习惯养成", "自动化", "环境设计", "行动闭环"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 534, now()),
(100535, '心理健康 4M：把基础处方做成每周最低配', '4M 可作为 App 的基础能量处方：掌控（持续学习或精进一件事）、运动（让身体活动支持情绪和大脑）、有意义的接触（与人真实连接并贡献存在感）、正念（温和引导注意力）。每周最低配可以是：15 分钟学习、一次低强度运动、一次主动联系或共同活动、一次呼吸/冥想/正念停顿。重点是稳定重复，而不是一次做到完美。', '["心理健康4M", "健康习惯", "身体状态", "可持续行动"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 535, now()),
(100536, '生命周期不是闯关清单：每个阶段都在继续参与人生', '埃里克森的阶段观适合被理解为“发展中的关键课题”，而不是一次完成、永不回头的闯关表。信任、自主、主动、勤奋、身份、亲密等力量会在不同年龄以新的形式继续出现；每一阶段的积极力量也始终伴随相反感受。用于 App 回答时，可提醒用户：某个阶段的困难并不等于人格定型，而是当前生活正在重新激活某种发展任务；可从关系、身体、角色和社会支持一起寻找可调整的入口。', '["埃里克森", "发展阶段", "生命周期", "心理社会发展", "非诊断", "成长任务"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 536, now()),
(100537, '基本信任：安全感来自稳定可预见的关系品质', '婴儿期的信任不是被喂多少、被爱多少的简单总和，而是照料者能否稳定、敏锐、可预见地回应需要。孩子逐渐把照料者体验为“即使暂时不在眼前，也仍然可靠”的存在，同时也学会相信自己的身体和需求可以被承接。面向亲子或亲密关系的问答，可把“信任”解释为长期关系中的一致性：允许有挫折，但关系要有可理解的意义、可修复的节奏和足够稳定的回应。', '["基本信任", "安全感", "亲子关系", "照料回应", "关系品质", "希望"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 537, now()),
(100538, '自主感：边界的目的不是控制孩子，而是让孩子敢于自控', '自主阶段的核心不是“孩子想怎样就怎样”，也不是成人用羞辱换服从，而是在保持与放手之间建立可安心的外在控制。孩子需要在安全边界里练习选择、拒绝、坚持和放手，从自控与自尊中发展意志感。若成人的规则反复无常、过度羞辱，孩子更容易把探索体验成暴露、怀疑或丢脸。App 可以建议家长把规则说清楚、保持一致，并把错误当成练习自控的材料。', '["自主", "羞愧与怀疑", "边界", "自控", "亲子教育", "意志"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 538, now()),
(100539, '主动感：把“我想做”引向计划、责任和可承受的后果', '主动阶段的孩子开始更有能量，想靠近目标、提出计划、模仿大人、照顾更小的人。这个阶段需要的不是简单压下冲动，而是把“想做”转化为可执行、可负责、可合作的行动。过度禁止会让主动性和内疚感纠缠；缺少指引又会让孩子难以理解边界。适合 App 场景的表达是：给孩子小任务、可见角色和现实反馈，让他们在被允许尝试中学习责任，而不是只在犯错后被评价。', '["主动", "内疚", "责任感", "儿童发展", "角色模仿", "行动力"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 539, now()),
(100540, '勤奋感：孩子需要在工具世界里体验“我能学会”', '进入学校或类似学习环境后，孩子的发展重点从想象和游戏逐渐转向技能、工具、任务和同伴合作。勤奋感不是单纯“努力”，而是孩子能在真实任务中看到自己掌握了方法，并被所属文化承认为有能力的参与者。若家庭没有为学习做准备，或学校无法兑现早期成长的期待，孩子容易把困难理解成“我不行”。App 回答可强调：把任务拆小、让进步可见、减少比较羞辱，比空泛鼓励更能保护勤奋感。', '["勤奋", "自卑", "学习动力", "学校适应", "能力感", "儿童发展"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 540, now()),
(100541, '身份发展：青春期是在身体、角色和未来之间寻找连续感', '青春期的“我是谁”不是单靠兴趣标签回答的，而是要把身体变化、早年形成的自我感、同伴评价、技能、价值和未来职业可能整合起来。身份感大于童年身份的相加，它需要内在连续感与他人眼中的一致性相互印证。青少年对偶像、群体、风格和恋爱对话的投入，常是在试着看清自己。App 端可避免把探索贴成叛逆，转而帮助用户辨认：哪些角色让我更像自己，哪些只是为了被接纳。', '["身份发展", "自我同一性", "青春期", "角色探索", "同伴关系", "价值澄清"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 541, now()),
(100542, '青年之爱常在回答身份问题：我在你眼中是谁', '埃里克森把青年期的爱理解为身份澄清的重要场域：年轻人会把尚未稳定的自我意象投向对方，再从对方回应中看见和整理自己。因此，早期恋爱常常有大量谈话、确认、理想化和群体边界。App 回答亲密困惑时，可把一部分“反复确认关系”理解为身份探索，而不是急着判断成熟或幼稚；更有帮助的问题是：这段关系是否帮助双方更清楚地成为自己，还是只让彼此陷入排外、比较和自我丧失。', '["青年之爱", "身份澄清", "亲密关系", "青春期", "自我意象", "关系成长"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 542, now()),
(100543, '亲密不是吞没：清晰的自我更能承担承诺', '亲密阶段建立在相对清晰的身份感之上。一个人越能知道自己是谁，越可能与他人建立具体的依附、伙伴关系和承诺，并在必要的牺牲与妥协中不完全失去自己。相反，如果靠近总被体验成自我受损，人就可能用距离、防御或孤立保护自己。App 端可把亲密关系建议落在两个问题上：我能否在关系中保持自我连续感？我是否愿意为重要关系承担可协商的承诺？', '["亲密", "孤独", "承诺", "自我边界", "成年早期", "伴侣关系"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 543, now()),
(100544, '童年经验会进入成人关系，但不等于成人只能重复过去', '《童年与社会》反复把童年与成人生活连在一起：早期的信任、羞愧、主动、能力和身份经验，会在成年后的爱、忠诚、工作、权威和亲密中被重新激活。重要的是，这种影响不是命运判决，而是理解当下反应的线索。App 可用非诊断语言引导用户回看：某个关系触发点像不像早年熟悉的处境？现在的我是否可以用新的支持、解释和行动来回应，而不只是沿用旧的防御。', '["童年经验", "成人关系", "早年模式", "关系触发", "自我理解", "非诊断"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 544, now()),
(100545, '社会化：孩子不是被家庭单独塑造，而是在文化中学习成为人', '儿童训练并非只发生在家庭内部，也不是把成人规矩机械塞给孩子。人类漫长童年中的训练和教育，会把身体需要、情绪能量、家庭习惯、社会传统和文化理想组织起来，使孩子同时成为有机体、社会成员和独立个体。不同文化会用不同方式安排儿童训练，因此 App 在回答亲子问题时，可少用“唯一正确养法”，多问：这个家庭和文化期待孩子学会什么？这些期待是否仍能支持孩子的安全、能力和归属。', '["社会化", "儿童训练", "文化影响", "亲子关系", "家庭与社会", "成长环境"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 545, now()),
(100546, '亲子挫折需要意义：孩子承受的不是限制本身，而是无意义的中断', '埃里克森提醒，儿童并不是因为所有挫折而受伤；更关键的是挫折是否被放在可理解、可修复、与群体意义相连的框架里。父母不能只靠禁止和允许来带孩子，还需要说明事情的意义，让孩子知道规则如何服务于安全、合作和成长。当家庭或学校的要求突然、粗暴、缺少解释，孩子更容易体验到不连续和不归属。App 可建议成人先连接、再设限、再解释，帮助孩子把限制转化为可学习的经验。', '["亲子关系", "挫折意义", "规则解释", "安全感", "家庭教育", "连接与设限"]'::jsonb, 'enabled', 'seed:xinzhili-essence-v15-20260705', 546, now())
ON CONFLICT (id) DO UPDATE SET
  title = EXCLUDED.title,
  content = EXCLUDED.content,
  tags = EXCLUDED.tags,
  status = EXCLUDED.status,
  source = EXCLUDED.source,
  sort = EXCLUDED.sort,
  update_time = now();

SELECT setval(pg_get_serial_sequence('rag_documents','id'), GREATEST((SELECT max(id) FROM rag_documents), 1));

COMMIT;
